/* ── Advance Request panel ───────────────────────── */
function loadAdvReqPanel() {
  reloadAdvHistory();
}

function reloadAdvHistory() {
  api("get_requests_history", {}, function(h) {
    renderReqHistory("adv-history", h.advances, "No advance requests submitted yet.", function(r) {
      const statusMap = {Paid:"badge-green",Claimed:"badge-blue",Paid:"badge-green"};
      const cls = statusMap[r.status] || "badge-amber";
      return '<div class="req-item"><div class="req-icon"><i class=ic-cash-out></i></div><div class="req-body"><div class="req-title">' + (r.purpose||"Advance Request").substring(0,70) + '</div><div class="req-meta">' + fmtDate(r.posting_date) + ' · ' + fmtMoney(r.advance_amount) + '</div></div><div class="req-status"><span class="badge ' + cls + '">' + (r.status||"Pending") + '</span></div></div>';
    });
  }, function(e) { failBox("adv-history", e, reloadAdvHistory); });
}

function submitAdvanceRequest() {
  const purpose = document.getElementById("adv-purpose").value.trim();
  const amount  = parseFloat(document.getElementById("adv-amount").value);
  let ok = true;
  if (!purpose)          { showErr("adv-purpose-err"); ok=false; } else hideErr("adv-purpose-err");
  if (!amount||amount<=0){ showErr("adv-amount-err");  ok=false; } else hideErr("adv-amount-err");
  if (!ok) return;
  /* Slice 070 (D2, SEC-2, OPS-R4): as the expense claim - no server guard,
     so no resend after a lost answer; Submit stays off until Close. */
  var btn = document.getElementById("adv-submit-btn");
  if (btn.disabled) return;
  btn.disabled = true;
  btn.textContent = drT("Sending…");
  sendSay("adv-send-fail", null);
  var gen = ++ADV_GEN;
  function unlock(words) { btn.disabled = false; btn.textContent = drT(words || "Submit Request"); }
  function done(d) {
    if (gen !== ADV_GEN) return;
    ADV_GEN++;
    sendSay("adv-send-fail", null);
    unlock();
    toast(drT("Advance request submitted: {0}", [(d && d.name) || ""]), "ok");
    clearForm(["adv-purpose","adv-amount"]);
    loadedPanels.delete("adv-req"); reloadAdvHistory();
  }
  gpFetch("alvoraa_portal.hr_api.submit_advance_request", {purpose: purpose, amount: amount},
          {lostAnswerHandled: true}).then(done, function(e) {
    if (gen !== ADV_GEN) return;
    if (e.late) e.late.then(done, function() {});
    if (e.kind === "refused") { unlock(); toast(e.message, "err"); return; }
    if (e.kind === "offline") {
      sendSay("adv-send-fail", "We could not reach the office. Nothing was sent.",
              "Your details are still here. When you have signal, tap Try again.");
      unlock("Try again");
      return;
    }
    sendSay("adv-send-fail", "No answer from the office. It may have gone through.",
            "Look in your list before you send it again.", function() {
      ADV_GEN++;
      sendSay("adv-send-fail", null);
      unlock();
      reloadAdvHistory();
    });
  });
}

/* ── Employee detail drawer ──────────────────────── */
function openEmpDrawer(empId, color) {
  const overlay = document.getElementById("emp-drawer-overlay");
  const drawer  = document.getElementById("emp-drawer");
  overlay.classList.add("open");
  drawer.classList.add("open");
  document.body.style.overflow = "hidden";
  document.getElementById("ed-body").innerHTML = '<div style="padding:40px;text-align:center;color:var(--text3)"><div class="spinner" style="margin:0 auto 12px;border-color:var(--border);border-top-color:var(--primary)"></div>Loading...</div>';

  api("get_employee_detail_for_manager", {employee_id: empId}, function(d) {
    renderEmpDrawer(d, color);
    api("get_employee_goals_for_manager", {employee_id: empId}, function(gd) {
      if (gd.available) renderDrawerGoals(gd.goals, empId);
    });
    renderDrawerNotes(empId, d.employee.employee_name || empId);
  }, function(e) {
    document.getElementById("ed-body").innerHTML =
      '<div style="padding:40px;text-align:center;color:var(--danger)">' +
      esc(e.message || "Failed to load employee details") + '</div>';
  });
}

function closeEmpDrawer() {
  document.getElementById("emp-drawer-overlay").classList.remove("open");
  document.getElementById("emp-drawer").classList.remove("open");
  document.body.style.overflow = "";
}

/* ── Employee Scorecard ──────────────────────────── */
var _scBackPanel = "team";
var _scBackNavEl = null;

function openEmpScorecard(empId, color) {
  _scBackPanel = document.querySelector(".panel.active") ? (document.querySelector(".panel.active").id || "team").replace("panel-", "") : "team";
  _scBackNavEl = document.querySelector(".nav-item.active");
  switchPanel("scorecard");
  var av = document.getElementById("sc-avatar");
  av.style.background = color || "var(--primary)";
  av.textContent = "…";
  document.getElementById("sc-emp-name").textContent = "Loading…";
  document.getElementById("sc-emp-role").textContent = "";
  document.getElementById("sc-join-badge").textContent = "";
  var _scBodyEl = document.getElementById("sc-body");
  _scBodyEl.scrollTop = 0;
  _scBodyEl.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text3)"><div class="spinner" style="margin:0 auto 12px;border-color:var(--border);border-top-color:var(--primary)"></div>Loading scorecard…</div>';
  api("get_employee_scorecard", {employee_id: empId}, function(d) {
    renderScorecard(d, color);
  }, function(e) {
    document.getElementById("sc-body").innerHTML = '<div style="color:var(--danger);padding:40px;text-align:center">' + (e.message || "Failed to load scorecard") + '</div>';
  });
}

function scGoBack() {
  switchPanel(_scBackPanel || "team", _scBackNavEl);
}

function renderScorecard(d, color) {
  var emp = d.employee || {};
  var av  = document.getElementById("sc-avatar");
  av.style.background = color || "var(--primary)";
  av.textContent = initials(emp.employee_name || "?");
  document.getElementById("sc-emp-name").textContent = emp.employee_name || "";
  document.getElementById("sc-emp-role").textContent = [emp.designation, emp.department].filter(Boolean).join(" • ");
  document.getElementById("sc-join-badge").textContent = emp.date_of_joining ? "Joined " + fmtDate(emp.date_of_joining) : "";

  var att     = d.month_att_summary || {};
  var present = (att["Present"] || 0) + Math.round((att["Half Day"] || 0) * 0.5);
  var absent  = att["Absent"] || 0;
  var onLeave = att["On Leave"] || 0;
  var avgHrs  = d.avg_hours || 0;

  // Stat row
  var statsHtml = '<div class="sc-stat-row">' +
    '<div class="sc-stat"><div class="sc-stat-val" style="color:var(--green,var(--green))">' + present + '</div><div class="sc-stat-lbl">Present</div></div>' +
    '<div class="sc-stat"><div class="sc-stat-val" style="color:var(--red,var(--red))">' + absent + '</div><div class="sc-stat-lbl">Absent</div></div>' +
    '<div class="sc-stat"><div class="sc-stat-val" style="color:var(--amber,var(--amber))">' + onLeave + '</div><div class="sc-stat-lbl">On Leave</div></div>' +
    '<div class="sc-stat"><div class="sc-stat-val" style="color:var(--primary)">' + avgHrs + 'h</div><div class="sc-stat-lbl">Avg Hours/Day</div></div>' +
  '</div>';

  // 6-month attendance bars
  var monthly = d.monthly_att || [];
  var barsHtml = '<div class="sc-month-bars">' +
    monthly.map(function(m) {
      var total = m.present + m.absent + m.on_leave + (m.wfh || 0);
      if (!total) {
        return '<div class="sc-mb-col"><div class="sc-mb-bar-wrap"><div class="sc-mb-seg" style="height:4px;background:var(--border)"></div></div><div class="sc-mb-lbl">' + m.month_label + '</div></div>';
      }
      var pH = Math.round(m.present  / total * 70);
      var aH = Math.round(m.absent   / total * 70);
      var lH = Math.round(m.on_leave / total * 70);
      var wH = Math.round((m.wfh||0) / total * 70);
      return '<div class="sc-mb-col" title="' + m.month_label + ': ' + m.present + 'P ' + m.absent + 'A ' + m.on_leave + 'L">' +
        '<div class="sc-mb-bar-wrap">' +
          (wH ? '<div class="sc-mb-seg" style="height:' + wH + 'px;background:var(--primary-lt,var(--primary-lt))"></div>' : '') +
          (lH ? '<div class="sc-mb-seg" style="height:' + lH + 'px;background:var(--amber-lt,var(--amber-lt));border:1px solid var(--amber,var(--amber))"></div>' : '') +
          (aH ? '<div class="sc-mb-seg" style="height:' + aH + 'px;background:var(--red-lt,var(--red-lt));border:1px solid var(--red,var(--red))"></div>' : '') +
          (pH ? '<div class="sc-mb-seg" style="height:' + pH + 'px;background:var(--green,var(--green))"></div>' : '') +
        '</div><div class="sc-mb-lbl">' + m.month_label + '</div>' +
      '</div>';
    }).join("") +
  '</div>' +
  '<div style="display:flex;gap:12px;flex-wrap:wrap;font-size:var(--fs-xs);color:var(--text3);margin-top:4px">' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--green,var(--green));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>Present</span>' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--red-lt,var(--red-lt));border:1px solid var(--red,var(--red));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>Absent</span>' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--amber-lt,var(--amber-lt));border:1px solid var(--amber,var(--amber));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>On Leave</span>' +
  '</div>';

  // Leave balance bars
  var balances = d.leave_balances || [];
  var leaveHtml = balances.length
    ? balances.map(function(b) {
        var pct = b.allocated ? Math.round(b.taken / b.allocated * 100) : 0;
        return '<div class="sc-lb-row">' +
          '<div class="sc-lb-lbl" title="' + b.leave_type + '">' + b.leave_type + '</div>' +
          '<div class="sc-lb-track"><div class="sc-lb-fill" style="width:' + pct + '%;background:var(--primary)"></div></div>' +
          '<div class="sc-lb-counts">' + b.taken + '&thinsp;/&thinsp;' + b.allocated + 'd</div>' +
        '</div>';
      }).join("")
    : '<div class="empty-state" style="padding:12px 0"><div class="empty-state-text">No leave allocations found</div></div>';

  // Goals
  var goals = d.goals || [];
  var TRAJ = {"Completed":"var(--green,var(--green))","On Track":"var(--primary)","At Risk":"var(--amber,var(--amber))","Needs Attention":"var(--red,var(--red))"};
  var goalsHtml = !d.goals_available
    ? '<div class="empty-state" style="padding:12px 0"><div class="empty-state-text">Goals module not active</div></div>'
    : !goals.length
      ? '<div class="empty-state" style="padding:12px 0"><div class="empty-state-text">No goals set</div></div>'
      : goals.map(function(g) {
          var pct = Math.min(100, Math.round(parseFloat(g.progress_pct) || 0));
          var col = TRAJ[g.status] || TRAJ[g.trajectory] || "var(--primary)";
          return '<div class="sc-goal-item" onclick="openTeamGoalDrawer(\'' + g.name + '\')" style="cursor:pointer">' +
            '<div class="sc-goal-name" title="' + esc(g.goal_name||"") + '">' + esc(g.goal_name || "—") + '</div>' +
            '<div class="sc-goal-bar-wrap"><div class="sc-goal-bar" style="width:' + pct + '%;background:' + col + '"></div></div>' +
            '<div class="sc-goal-pct">' + pct + '%</div>' +
            '<div style="font-size:var(--fs-base);color:var(--text3);flex-shrink:0;margin-left:4px">›</div>' +
          '</div>';
        }).join("");

  // Appraisal history (sparkline + cards)
  var appraisals = d.appraisal_history || [];
  var RCOLOR = {"Exceptional":"var(--green,var(--green))","Exceeds Expectations":"var(--primary)","Meets Expectations":"var(--amber,var(--amber))","Needs Improvement":"var(--red,var(--red))","Unsatisfactory":"var(--red,var(--red))"};
  var apprHtml;
  if (!appraisals.length) {
    apprHtml = '<div class="empty-state" style="padding:12px 0"><div class="empty-state-text">No appraisal records</div></div>';
  } else {
    var scores = appraisals.map(function(a) { return a.score || 0; });
    var maxSc = Math.max.apply(null, scores.concat([5]));
    var sparkPts = scores.length > 1
      ? scores.map(function(s, i) {
          var x = Math.round(i / (scores.length - 1) * 200);
          var y = Math.round(50 - (maxSc ? s / maxSc : 0) * 40);
          return x + "," + y;
        }).join(" ")
      : null;
    var sparkHtml = sparkPts
      ? '<svg width="100%" viewBox="0 0 200 60" preserveAspectRatio="none" style="display:block;margin-bottom:10px;overflow:visible;height:50px">' +
          '<polyline points="' + sparkPts + '" fill="none" stroke="var(--primary)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>' +
          scores.map(function(s, i) {
            var x = Math.round(i / (scores.length - 1) * 200);
            var y = Math.round(50 - (maxSc ? s / maxSc : 0) * 40);
            return '<circle cx="' + x + '" cy="' + y + '" r="3.5" fill="var(--primary)" stroke="var(--surface)" stroke-width="1.5"/>';
          }).join("") +
        '</svg>'
      : '';
    apprHtml = sparkHtml +
      '<div style="display:flex;gap:6px;overflow-x:auto">' +
      appraisals.map(function(a) {
        var rCol = RCOLOR[a.overall_rating] || "var(--text3)";
        var lbl = (a.cycle_label || "").substring(0, 12);
        return '<div style="flex:1;min-width:56px;text-align:center;padding:6px 4px;border:1px solid var(--border);border-radius:var(--r-sm)">' +
          '<div style="font-size:var(--fs-base);font-weight:700;color:var(--text)">' + (a.score ? a.score.toFixed(1) : "—") + '</div>' +
          '<div style="font-size:var(--fs-xs);font-weight:600;color:' + rCol + ';margin:2px 0;line-height:1.2">' + (a.overall_rating || a.review_status || "—") + '</div>' +
          '<div style="font-size:var(--fs-xs);color:var(--text3)">' + lbl + '</div>' +
        '</div>';
      }).join("") +
      '</div>';
  }

  // Pending leave approvals
  var pending = d.pending_leaves || [];
  var pendHtml = pending.length
    ? '<div class="sc-card sc-full" style="margin-bottom:16px">' +
        '<div class="sc-card-hdr"><i class=ic-zap></i> Pending Requests (' + pending.length + ')</div>' +
        '<div class="sc-card-body">' +
        pending.map(function(l) {
          var days = parseFloat(l.total_leave_days || 0);
          return '<div class="appr-card" id="sc-appr-' + l.name + '" style="margin-bottom:8px">' +
            '<div class="appr-info"><div><div class="appr-name">' + esc(l.leave_type) + '</div>' +
            '<div class="appr-detail">' + fmtDate(l.from_date) + ' – ' + fmtDate(l.to_date) + ' · ' + days + ' day' + (days !== 1 ? 's' : '') + (l.description ? '<br>' + esc(l.description) : '') + '</div></div></div>' +
            '<div class="appr-actions"><button class="btn btn-green btn-sm" onclick="scActionLeave(\'' + l.name + '\',\'approve\')">&#10003; Approve</button>' +
            '<button class="btn btn-danger btn-sm" onclick="scActionLeave(\'' + l.name + '\',\'reject\')">&#10007; Reject</button></div>' +
          '</div>';
        }).join("") +
        '</div></div>'
    : '';

  // Assemble body
  document.getElementById("sc-body").innerHTML =
    statsHtml +
    pendHtml +
    '<div class="sc-grid">' +
      '<div class="sc-card">' +
        '<div class="sc-card-hdr">Attendance — Last 6 Months</div>' +
        '<div class="sc-card-body">' + barsHtml + '</div>' +
      '</div>' +
      '<div class="sc-card">' +
        '<div class="sc-card-hdr">Goals Progress</div>' +
        '<div class="sc-card-body" style="max-height:220px;overflow-y:auto">' + goalsHtml + '</div>' +
      '</div>' +
      '<div class="sc-card">' +
        '<div class="sc-card-hdr">Leave Balances — This Year</div>' +
        '<div class="sc-card-body">' + leaveHtml + '</div>' +
      '</div>' +
      '<div class="sc-card">' +
        '<div class="sc-card-hdr">Appraisal History</div>' +
        '<div class="sc-card-body">' + apprHtml + '</div>' +
      '</div>' +
    '</div>';
}

window.scActionLeave = function(leaveName, action) {
  /* `leave_id` is the server's parameter name. `leave_name` was dropped on the
     wire and the call raised TypeError - see test_browser_call_args_045.py. */
  api("action_leave", {leave_id: leaveName, action: action}, function() {
    var card = document.getElementById("sc-appr-" + leaveName);
    if (card) card.innerHTML = '<div style="padding:10px;color:var(--text3);font-size:var(--fs-base)">' + (action === "approve" ? "<i class=ic-check></i> Approved" : "<i class=ic-x></i> Rejected") + '</div>';
    toast(action === "approve" ? "Leave approved" : "Leave rejected", action === "approve" ? "ok" : "");
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast(e.message || "Action failed", "err"); });
};

/* ── Team comparison charts ──────────────────────── */
function loadTeamComparison(team) {
  api("get_team_scorecard", {}, function(d) {
    renderTeamComparison(d.members || [], team || []);
  }, function() {
    var tcCont = document.getElementById("tc-card-container");
    if (tcCont) tcCont.innerHTML = "";
  });
}

function renderTeamComparison(members, teamBase) {
  var tcCont = document.getElementById("tc-card-container");
  if (!tcCont) return;
  if (!members.length) { tcCont.innerHTML = ""; return; }

  // Determine TEAM_COLORS index by matching name order from teamBase
  var colorMap = {};
  (teamBase || []).forEach(function(m, i) {
    colorMap[m.name] = TEAM_COLORS[i % TEAM_COLORS.length];
  });

  var maxPresent = Math.max.apply(null, members.map(function(m) { return m.present + m.absent + m.on_leave + m.wfh; }).concat([1]));
  var maxGoal    = Math.max.apply(null, members.map(function(m) { return m.goals_avg; }).concat([1]));
  var maxScore   = Math.max.apply(null, members.map(function(m) { return m.appraisal_score; }).concat([5]));

  function tcRow(m, barHtml, val) {
    var col = colorMap[m.name] || "var(--primary)";
    return '<div class="tc-row">' +
      '<div class="tc-name" onclick="openEmpScorecard(\'' + m.name + '\',\'' + col + '\')" title="' + m.employee_name + '">' + (m.employee_name.split(" ")[0]) + '</div>' +
      '<div class="tc-bars">' + barHtml + '</div>' +
      '<div class="tc-val">' + val + '</div>' +
    '</div>';
  }

  // Attendance section
  var attRows = members.map(function(m) {
    var total = m.present + m.absent + m.on_leave + m.wfh;
    var pW = maxPresent ? Math.round(m.present  / maxPresent * 100) : 0;
    var aW = maxPresent ? Math.round(m.absent   / maxPresent * 100) : 0;
    var lW = maxPresent ? Math.round(m.on_leave / maxPresent * 100) : 0;
    var bars =
      (pW ? '<div class="tc-bar" style="width:' + pW + '%;background:var(--green,var(--green))"></div>' : '') +
      (aW ? '<div class="tc-bar" style="width:' + aW + '%;background:var(--red,var(--red))"></div>' : '') +
      (lW ? '<div class="tc-bar" style="width:' + lW + '%;background:var(--amber,var(--amber))"></div>' : '');
    return tcRow(m, bars, m.present + "d");
  }).join("");

  // Goals section
  var goalRows = members.filter(function(m) { return m.goals_total > 0; }).map(function(m) {
    var col = colorMap[m.name] || "var(--primary)";
    var pW = maxGoal ? Math.round(m.goals_avg / maxGoal * 100) : 0;
    return tcRow(m, '<div class="tc-bar" style="width:' + pW + '%;background:' + col + '"></div>', m.goals_avg + "%");
  }).join("");

  // Appraisal section
  var apprRows = members.filter(function(m) { return m.appraisal_score > 0; }).map(function(m) {
    var col = colorMap[m.name] || "var(--primary)";
    var pW = maxScore ? Math.round(m.appraisal_score / maxScore * 100) : 0;
    return tcRow(m, '<div class="tc-bar" style="width:' + pW + '%;background:' + col + '"></div>', m.appraisal_score.toFixed(1));
  }).join("");

  var legend = '<div style="display:flex;gap:14px;font-size:var(--fs-xs);color:var(--text3);margin-bottom:12px;flex-wrap:wrap">' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--green,var(--green));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>Present</span>' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--red,var(--red));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>Absent</span>' +
    '<span><i style="display:inline-block;width:8px;height:8px;background:var(--amber,var(--amber));border-radius:var(--r-sm);margin-right:3px;vertical-align:middle"></i>On Leave</span>' +
  '</div>';

  tcCont.innerHTML = '<div class="tc-card">' +
    '<div class="tc-card-hdr">Team Comparison — This Month</div>' +
    '<div class="tc-card-body">' +
      '<div class="tc-section">' +
        '<div class="tc-sec-title">Attendance</div>' + legend + attRows +
      '</div>' +
      (goalRows ? '<div class="tc-section"><div class="tc-sec-title">Goal Progress (Avg)</div>' + goalRows + '</div>' : '') +
      (apprRows ? '<div class="tc-section"><div class="tc-sec-title">Latest Appraisal Score</div>' + apprRows + '</div>' : '') +
    '</div>' +
  '</div>';
}

function renderEmpDrawer(d, color) {
  const emp = d.employee;
  document.getElementById("ed-av").textContent        = initials(emp.employee_name);
  document.getElementById("ed-av").style.background   = color || "var(--primary)";
  document.getElementById("ed-name").textContent      = emp.employee_name;
  document.getElementById("ed-role").textContent      = [emp.designation, emp.department].filter(Boolean).join(" • ");

  const att     = d.month_att_summary || {};
  const present = (att["Present"] || 0) + Math.round((att["Half Day"] || 0) * 0.5);
  const absent  = att["Absent"] || 0;
  const onLeave = att["On Leave"] || 0;
  const wfh     = att["Work From Home"] || 0;

  // Today's status row
  const todayA   = d.today_attendance;
  const todayStatus = todayA ? todayA.status : (d.checked_in ? "Present" : "Not checked in");
  const statusCss = {Present:"badge-green","Half Day":"badge-amber",Absent:"badge-red","On Leave":"badge-amber","Work From Home":"badge-blue","Not checked in":"badge-gray"};
  const inTime  = todayA && todayA.in_time  ? "In: "  + new Date(todayA.in_time ).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}) : "";
  const outTime = todayA && todayA.out_time ? "  Out: " + new Date(todayA.out_time).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}) : "";
  const hours   = todayA && todayA.working_hours ? " (" + parseFloat(todayA.working_hours).toFixed(1) + "h)" : "";

  // Leave balances
  const balHtml = !(d.leave_balances || []).length
    ? '<div class="empty-state"><div class="empty-state-text">No leave allocations found.</div></div>'
    : d.leave_balances.map(function(b) {
        const bal = Math.max(0, parseFloat(b.balance) || 0);
        const alloc = parseFloat(b.allocated) || 0;
        const pct = alloc ? Math.round(bal / alloc * 100) : 0;
        return '<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px"><span style="font-size:var(--fs-base);color:var(--text)">' + esc(b.leave_type) + '</span><span style="font-size:var(--fs-base);font-weight:600;color:var(--primary)">' + bal + '<span style="color:var(--text3);font-weight:400;font-size:var(--fs-xs)"> / ' + alloc + '</span></span></div><div style="height:5px;border-radius:var(--r-full);background:var(--border)"><div style="height:100%;border-radius:var(--r-full);background:var(--primary);width:' + pct + '%"></div></div></div>';
      }).join("");

  // Pending approvals (with inline approve/reject)
  const pendHtml = !(d.pending_leaves || []).length
    ? '<div class="empty-state"><div class="empty-state-text">No pending requests.</div></div>'
    : d.pending_leaves.map(function(l) {
        const days = parseFloat(l.total_leave_days || 0);
        return '<div class="appr-card" id="ed-appr-' + l.name + '"><div class="appr-info"><div><div class="appr-name">' + esc(l.leave_type) + '</div><div class="appr-detail">' + fmtDate(l.from_date) + ' – ' + fmtDate(l.to_date) + ' · <strong>' + days + ' day' + (days !== 1 ? 's' : '') + '</strong>' + (l.description ? '<br>' + esc(l.description) : '') + '</div></div></div>' + (l.can_action ? '<div class="appr-actions"><button class="btn btn-green btn-sm" onclick="edActionLeave(\'' + l.name + '\',\'approve\')"><i class=ic-check></i> Approve</button><button class="btn btn-danger btn-sm" onclick="edActionLeave(\'' + l.name + '\',\'reject\')"><i class=ic-x></i> Reject</button></div>' : '<div class="appr-actions"><span style="font-size:var(--fs-xs);color:var(--text3)">Awaiting approver</span></div>') + '</div>';
      }).join("");

  // Recent leave history
  const histCss = {Approved:"badge-green",Rejected:"badge-red",Open:"badge-amber",Cancelled:"badge-gray"};
  const histHtml = !(d.recent_leaves || []).length
    ? '<div class="empty-state"><div class="empty-state-text">No leave history.</div></div>'
    : d.recent_leaves.map(function(l) {
        return '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">' + esc(l.leave_type) + ' &nbsp;·&nbsp; ' + l.total_leave_days + 'd</div><div class="holiday-days">' + fmtDate(l.from_date) + (l.to_date !== l.from_date ? ' – ' + fmtDate(l.to_date) : '') + '</div></div><span class="badge ' + (histCss[l.status]||"badge-gray") + '">' + esc(l.status) + '</span></div>';
      }).join("");

  // Contact info
  const contactHtml = [
    emp.cell_number     ? '<div class="holiday-item"><div class="holiday-name"><i class=ic-phone></i>&nbsp; ' + esc(emp.cell_number) + '</div></div>' : '',
    emp.company_email   ? '<div class="holiday-item"><div class="holiday-name"><i class=ic-mail></i>&nbsp; ' + esc(emp.company_email) + '</div></div>' : '',
    (!emp.company_email && emp.personal_email) ? '<div class="holiday-item"><div class="holiday-name"><i class=ic-mail></i>&nbsp; ' + esc(emp.personal_email) + '</div></div>' : '',
    emp.date_of_joining ? '<div class="holiday-item"><div class="holiday-name"><i class=ic-calendar></i>&nbsp; Joined ' + fmtDate(emp.date_of_joining) + '</div></div>' : '',
    emp.branch          ? '<div class="holiday-item"><div class="holiday-name"><i class=ic-building></i>&nbsp; ' + esc(emp.branch) + '</div></div>' : '',
  ].filter(Boolean).join("") || '<div class="empty-state"><div class="empty-state-text">No contact info.</div></div>';

  document.getElementById("ed-body").innerHTML =
    // Month stats
    '<div class="ed-stat-row">' +
      '<div class="ed-stat"><div class="ed-stat-val">' + present + '</div><div class="ed-stat-lbl">Present</div></div>' +
      '<div class="ed-stat"><div class="ed-stat-val">' + absent  + '</div><div class="ed-stat-lbl">Absent</div></div>' +
      '<div class="ed-stat"><div class="ed-stat-val">' + onLeave + '</div><div class="ed-stat-lbl">On Leave</div></div>' +
      '<div class="ed-stat"><div class="ed-stat-val">' + wfh     + '</div><div class="ed-stat-lbl">WFH</div></div>' +
    '</div>' +
    // Today
    '<div class="ed-section"><div class="ed-section-title">Today</div>' +
      '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">Attendance</div>' +
      (inTime ? '<div class="holiday-days">' + inTime + outTime + hours + '</div>' : '') +
      '</div><span class="badge ' + (statusCss[todayStatus]||"badge-gray") + '">' + todayStatus + '</span></div>' +
    '</div>' +
    // Leave balances
    '<div class="ed-section"><div class="ed-section-title">Leave Balances (This Year)</div>' + balHtml + '</div>' +
    // Pending
    '<div class="ed-section"><div class="ed-section-title">Pending Approvals</div>' + pendHtml + '</div>' +
    // History
    '<div class="ed-section"><div class="ed-section-title">Leave History</div>' + histHtml + '</div>' +
    // Contact
    '<div class="ed-section"><div class="ed-section-title">Contact & Info</div>' + contactHtml + '</div>';
}

function edActionLeave(leaveId, action) {
  const card = document.getElementById("ed-appr-" + leaveId);
  if (card) { card.style.opacity = ".5"; card.style.pointerEvents = "none"; }
  api("action_leave", {leave_id: leaveId, action: action}, function() {
    toast(action === "approve" ? "Leave approved" : "Leave rejected", action === "approve" ? "ok" : "");
    if (card) {
      card.querySelector(".appr-actions").innerHTML =
        '<span class="badge ' + (action === "approve" ? "badge-green" : "badge-red") + '">' +
        (action === "approve" ? "Approved" : "Rejected") + '</span>';
      card.style.opacity = "1";
      card.style.pointerEvents = "";
    }
    // Also refresh the team panel's pending count if it's visible
    const pc = document.getElementById("t-pending-count");
    if (pc) { const v = parseInt(pc.textContent)||0; pc.textContent = Math.max(0,v-1); }
    const badge = document.getElementById("sb-team-badge");
    if (badge) {
      const n = Math.max(0, (parseInt(badge.textContent)||0) - 1);
      badge.textContent = n; badge.style.display = n ? "flex" : "none";
    }
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
    if (card) { card.style.opacity = "1"; card.style.pointerEvents = ""; }
    toast((e.message || "Failed to " + action + " leave"), "err");
  });
}

/* ── Team panel ──────────────────────────────────── */
const TEAM_COLORS = ["var(--primary)","var(--primary)","var(--green)","var(--amber)","var(--red)","var(--green)","var(--amber)","var(--primary)"];

function loadTeamPanel() {
  loadTeamLateList();
  api("get_manager_dashboard", {}, function(d) {
    if (d.no_employee) {
      document.getElementById("team-grid").innerHTML = '<div class="empty-state"><div class="empty-state-text">No employee record found.</div></div>';
      return;
    }
    renderTeamData(d);
  }, function(e) { ["on-leave-body", "team-pending-list", "team-progress-approvals", "team-month-tbody"].forEach(function (id) { var el = document.getElementById(id); if (el) el.innerHTML = ""; }); failBox("team-grid", e, loadTeamPanel); });
  gpFetch("alvoraa_portal.hr_api.get_pending_approvals", {}).then(function(r) {
    renderProgressApprovals(r || {});
  }).catch(function() {
    pfSetHtml("team-progress-approvals", "<div class=\"empty-state\"><div class=\"empty-state-text\">Could not load progress approvals.</div></div>");
  });
}

function renderTeamData(d) {
  const team      = d.team       || [];
  const todayAtt  = d.today_att  || {};
  const onLeave   = d.on_leave_today || [];
  const pending   = d.pending_approvals || [];
  const monthLeav = d.month_leaves || [];

  // Stats
  document.getElementById("t-size").textContent         = team.length;
  document.getElementById("t-present").textContent      = Object.values(todayAtt).filter(s => s === "Present" || s === "Half Day").length;
  document.getElementById("t-on-leave").textContent     = onLeave.length;
  document.getElementById("t-pending-count").textContent = pending.length;
  // AC-72. For an HR caller this list is their HR scope, not their direct
  // reports, and it is capped. Say which, and say plainly when there are more
  // than the screen is showing - a count that does not match the list beside it
  // is worse than no count at all.
  const total  = (typeof d.team_total === "number") ? d.team_total : team.length;
  const capped = !!d.team_capped;
  const noun   = d.is_hr_scope ? "person" : "direct report";
  const plural = d.is_hr_scope ? "people" : "direct reports";
  document.getElementById("team-sub").textContent = capped
    ? "Showing the first " + team.length + " of " + total + " " + plural
    : total + " " + (total === 1 ? noun : plural);

  // Update sidebar pending badge
  const badge = document.getElementById("sb-team-badge");
  if (badge) { if (pending.length) { badge.textContent = pending.length; badge.style.display = "flex"; } else badge.style.display = "none"; }

  // Team attendance grid
  const statusCss = { Present:"badge-green", "Half Day":"badge-amber", Absent:"badge-red", "On Leave":"badge-amber", "Work From Home":"badge-blue" };
  document.getElementById("team-grid").innerHTML = !team.length
    ? '<div class="empty-state"><div class="empty-state-text">No direct reports.</div></div>'
    : team.map(function(m, i) {
        const status = todayAtt[m.name] || "—";
        const cls    = statusCss[status] || "badge-gray";
        const color  = TEAM_COLORS[i % TEAM_COLORS.length];
        return '<div class="team-card" onclick="openEmpScorecard(\'' + m.name + '\',\'' + color + '\')"><div class="team-avatar" style="background:' + color + '">' + initials(m.employee_name) + '</div><div class="team-card-name" title="' + esc(m.employee_name) + '">' + esc(m.employee_name) + '</div><div class="team-card-role" title="' + esc(m.designation||"") + '">' + esc(m.designation||"—") + '</div><div class="team-card-status"><span class="badge ' + cls + '">' + status + '</span></div></div>';
      }).join("");

  // On leave today
  document.getElementById("on-leave-body").innerHTML = !onLeave.length
    ? '<div class="empty-state"><div class="empty-state-text">No one is on leave today.</div></div>'
    : onLeave.map(function(l) {
        return '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">' + esc(l.employee_name) + '</div><div class="holiday-days">' + esc(l.leave_type||"Leave") + '</div></div></div>';
      }).join("");

  // Pending leave approvals
  document.getElementById("team-pending-list").innerHTML = !pending.length
    ? '<div class="empty-state"><div class="empty-state-text">No pending leave approvals.</div></div>'
    : pending.map(function(a) {
        const days = parseFloat(a.total_leave_days||0);
        return '<div class="appr-card" id="appr-' + a.name + '"><div class="appr-info"><div class="appr-avatar">' + initials(a.employee_name) + '</div><div><div class="appr-name">' + esc(a.employee_name) + '</div><div class="appr-detail">' + esc(a.leave_type||"Leave") + (a.half_day ? esc(drT(" (half day)")) : '') + ' &nbsp;·&nbsp; ' + fmtDate(a.from_date) + ' – ' + fmtDate(a.to_date) + ' &nbsp;·&nbsp; <strong>' + days + ' day' + (days !== 1 ? 's' : '') + '</strong>' + (a.description ? '<br>' + esc(a.description) : '') + lpApprLines(a) + '</div></div></div><div class="appr-actions"><button class="btn btn-green btn-sm" onclick="actionLeave(\'' + a.name + '\',\'approve\')"><i class=ic-check></i> Approve</button><button class="btn btn-danger btn-sm" onclick="actionLeave(\'' + a.name + '\',\'reject\')"><i class=ic-x></i> Reject</button></div></div>';
      }).join("");

  // Month team leaves table
  document.getElementById("team-month-tbody").innerHTML = !monthLeav.length
    ? '<tr><td colspan="4" style="text-align:center;color:var(--text3);padding:20px">No approved team leaves this month.</td></tr>'
    : monthLeav.map(function(l) {
        /* Slice 063 (S3): no leave type here; a half day reads 0.5. */
        return '<tr><td>' + esc(l.employee_name) + '</td><td class="num">' + fmtDate(l.from_date) + '</td><td class="num">' + fmtDate(l.to_date) + '</td><td class="num">' + parseFloat(l.total_leave_days || 0) + '</td></tr>';
      }).join("");

  // Team comparison charts
  var tcCont = document.getElementById("tc-card-container");
  if (!tcCont) {
    var tvAtt = document.getElementById("tv-attendance-panel");
    tcCont = document.createElement("div");
    tcCont.id = "tc-card-container";
    tvAtt.appendChild(tcCont);
  }
  tcCont.innerHTML = '<div class="tc-card"><div class="tc-card-hdr">Team Comparison — This Month</div><div class="tc-card-body" style="color:var(--text3);font-size:var(--fs-base);padding:20px;text-align:center">Loading…</div></div>';
  loadTeamComparison(team);
}

function renderProgressApprovals(r) {
  var goals = r.goals || [];
  var kpis  = r.kpis  || [];
  var rows  = [];
  goals.forEach(function(g) {
    var ev = g.evidence || {};
    rows.push(
      '<div class="appr-card" id="pa-goal-' + gpEsc(ev.row) + '">' +
        '<div class="appr-info"><div class="appr-avatar">' + initials(g.employee_name) + '</div>' +
        '<div><div class="appr-name">' + gpEsc(g.employee_name) + '</div>' +
        '<div class="appr-detail">Goal: <strong>' + gpEsc(g.goal_name) + '</strong>' +
        (ev.value ? ' &nbsp;·&nbsp; Value: ' + Number(ev.value).toLocaleString("en-IN", {maximumFractionDigits: 2}) + (g.unit ? ' ' + gpEsc(g.unit) : '') : '') +
        (ev.extracted_date ? ' &nbsp;·&nbsp; ' + fmtDate(ev.extracted_date) : '') +
        '</div></div></div>' +
        '<div class="appr-actions">' +
          '<button class="btn btn-green btn-sm" onclick="actionProgressApproval(\'goal\',\'' + gpEsc(g.name) + '\',\'' + gpEsc(ev.row) + '\',\'approve\',this)"><i class=ic-check></i> Approve</button>' +
          '<button class="btn btn-danger btn-sm" onclick="actionProgressApproval(\'goal\',\'' + gpEsc(g.name) + '\',\'' + gpEsc(ev.row) + '\',\'reject\',this)"><i class=ic-x></i> Reject</button>' +
        '</div>' +
      '</div>'
    );
  });
  kpis.forEach(function(k) {
    var log = k.log || {};
    rows.push(
      '<div class="appr-card">' +
        '<div class="appr-info"><div class="appr-avatar">' + initials(k.employee_name) + '</div>' +
        '<div><div class="appr-name">' + gpEsc(k.employee_name) + '</div>' +
        '<div class="appr-detail">KPI: <strong>' + gpEsc(k.kpi_name) + '</strong>' +
        (log.value != null ? ' &nbsp;·&nbsp; Value: ' + Number(log.value).toLocaleString("en-IN", {maximumFractionDigits: 2}) + (k.unit ? ' ' + k.unit : '') : '') +
        (log.log_date ? ' &nbsp;·&nbsp; ' + fmtDate(log.log_date) : '') +
        (log.note ? '<br><span style="color:var(--text3)">' + gpEsc(log.note) + '</span>' : '') +
        '</div></div></div>' +
        '<div class="appr-actions">' +
          '<button class="btn btn-green btn-sm" onclick="actionProgressApproval(\'kpi\',\'' + gpEsc(k.name) + '\',' + log.idx + ',\'approve\',this)"><i class=ic-check></i> Approve</button>' +
          '<button class="btn btn-danger btn-sm" onclick="actionProgressApproval(\'kpi\',\'' + gpEsc(k.name) + '\',' + log.idx + ',\'reject\',this)"><i class=ic-x></i> Reject</button>' +
        '</div>' +
      '</div>'
    );
  });
  pfSetHtml("team-progress-approvals",
    rows.length
      ? rows.join("")
      : '<div class="empty-state"><div class="empty-state-text">No pending progress approvals.</div></div>'
  );
}

function actionProgressApproval(type, docName, idx, action, btn) {
  if (btn) { btn.disabled = true; }
  var apiName = "alvoraa_portal.hr_api." + (type === "goal"
    ? (action === "approve" ? "approve_goal_evidence" : "reject_goal_evidence")
    : (action === "approve" ? "approve_kpi_progress" : "reject_kpi_progress"));
  var params = type === "goal"
    ? {goal_name: docName, evidence_row: idx}
    : {kpi_name: docName, log_idx: idx};
  gpFetch(apiName, params).then(function() {
    toast(action === "approve" ? "Approved" : "Rejected", action === "approve" ? "ok" : "");
    gpFetch("alvoraa_portal.hr_api.get_pending_approvals", {}).then(function(r) { renderProgressApprovals(r || {}); });
  }).catch(function(e) {
    if (btn) { btn.disabled = false; }
    toast(e.message || "Action failed", "err");
  });
}

function actionLeave(leaveId, action) {
  const card = document.getElementById("appr-" + leaveId);
  if (card) { card.style.opacity = ".5"; card.style.pointerEvents = "none"; }
  api("action_leave", {leave_id: leaveId, action: action}, function(r) {
    toast(action === "approve" ? "Leave approved" : "Leave rejected", action === "approve" ? "ok" : "");
    if (card) {
      card.classList.add(action === "approve" ? "approved" : "rejected");
      card.querySelector(".appr-actions").innerHTML = '<span class="badge ' + (action === "approve" ? "badge-green" : "badge-red") + '">' + (action === "approve" ? "Approved" : "Rejected") + '</span>';
      /* Slice 063 (R-58, R-59): who has been told, from what really happened. */
      if (r && r.first) {
        var det = card.querySelector(".appr-detail");
        if (det) det.insertAdjacentHTML("beforeend", '<div class="lp-told" role="status">' + gpEsc(lpDecisionWords(r)) + "</div>");
      }
      card.style.opacity = "1"; card.style.pointerEvents = "";
    }
    // Refresh pending count chip
    const pendingEl = document.getElementById("t-pending-count");
    if (pendingEl) {
      const cur = parseInt(pendingEl.textContent)||0;
      pendingEl.textContent = Math.max(cur - 1, 0);
    }
    const badge = document.getElementById("sb-team-badge");
    if (badge) {
      const cur = parseInt(badge.textContent)||0;
      const next = Math.max(cur - 1, 0);
      badge.textContent = next;
      if (!next) badge.style.display = "none";
    }
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
    if (card) { card.style.opacity = "1"; card.style.pointerEvents = ""; }
    toast((e.message || "Failed to " + action + " leave"), "err");
  });
}

/* ── Analytics panel ─────────────────────────────── */
function loadAnalyticsPanel() {
  api("get_hr_analytics", {}, function(d) {
    renderAnalyticsData(d);
  }, function() { toast("Failed to load HR analytics", "err"); });
}

function renderAnalyticsData(d) {
  // Slice 012: the "not linked" message, "data up to", doubtful days and the
  // review line. Not linked means no figures at all, so nothing below is drawn.
  drAnalyticsNotes(d);
  if (d.not_linked) return;
  const h   = d.headcount      || {};
  const kpi = d.kpis            || {};
  const oh  = d.org_health      || {};
  const depts = d.dept_distribution  || [];
  const gender = d.gender_distribution || [];
  const desigs = d.desig_distribution  || [];
  const confs  = d.confirmations_due   || [];
  const recent = d.recent_employees    || [];

  // KPIs
  document.getElementById("kpi-active").textContent       = h.active        || 0;
  document.getElementById("kpi-joiners").textContent      = h.new_joiners   || 0;
  // No data is "—", never 0% (slice 012).
  document.getElementById("kpi-att-rate").textContent     = kpi.attendance_rate == null ? "—" : kpi.attendance_rate + "%";
  document.getElementById("kpi-pend-leaves").textContent  = kpi.pending_approvals || 0;
  document.getElementById("kpi-confirmations").textContent = oh.confirmations_due || 0;
  document.getElementById("kpi-leave-util").textContent   = kpi.leave_utilization == null ? "—" : kpi.leave_utilization + "%";

  // Org health
  document.getElementById("oh-present").textContent = oh.present_this_month || 0;
  document.getElementById("oh-absent").textContent  = oh.absent_this_month  || 0;
  document.getElementById("oh-pending").textContent = oh.pending_approvals  || 0;
  document.getElementById("oh-conf").textContent    = oh.confirmations_due  || 0;

  // Department bar chart
  const maxDept = Math.max.apply(null, depts.map(function(r){ return r.count; })) || 1;
  document.getElementById("dept-chart").innerHTML = !depts.length
    ? '<div class="empty-state"><div class="empty-state-text">No data</div></div>'
    : depts.slice(0,8).map(function(r, i) {
        const pct = Math.round(r.count / maxDept * 100);
        return '<div class="bar-row"><div class="bar-label" title="' + esc(r.department) + '">' + esc(r.department) + '</div><div class="bar-track"><div class="bar-fill" style="width:' + pct + '%;background:' + TEAM_COLORS[i % TEAM_COLORS.length] + '">' + (pct > 15 ? r.count : "") + '</div></div><div class="bar-count">' + r.count + '</div></div>';
      }).join("");

  // Designation bar chart
  const maxDesig = Math.max.apply(null, desigs.map(function(r){ return r.count; })) || 1;
  document.getElementById("desig-chart").innerHTML = !desigs.length
    ? '<div class="empty-state"><div class="empty-state-text">No data</div></div>'
    : desigs.slice(0,8).map(function(r, i) {
        const pct = Math.round(r.count / maxDesig * 100);
        return '<div class="bar-row"><div class="bar-label" title="' + esc(r.designation) + '">' + esc(r.designation) + '</div><div class="bar-track"><div class="bar-fill" style="width:' + pct + '%;background:' + TEAM_COLORS[(i+3) % TEAM_COLORS.length] + '">' + (pct > 15 ? r.count : "") + '</div></div><div class="bar-count">' + r.count + '</div></div>';
      }).join("");

  // Gender chart
  const totalGender = gender.reduce(function(s, g){ return s + g.count; }, 0) || 1;
  const genderColors = { "Male":"var(--primary)", "Female":"var(--red)", "Not Specified":"var(--border2)" };
  document.getElementById("gender-chart").innerHTML = gender.map(function(g) {
    const pct = Math.round(g.count / totalGender * 100);
    const col = genderColors[g.gender] || "var(--primary)";
    return '<div class="gender-row"><div class="gender-label">' + esc(g.gender||"Other") + '</div><div class="gender-track"><div class="gender-fill" style="width:' + pct + '%;background:' + col + '"></div></div><div class="gender-pct">' + pct + '%</div></div>';
  }).join("");

  // Confirmations due
  document.getElementById("confirmations-list").innerHTML = !confs.length
    ? '<div class="empty-state"><div class="empty-state-text">No confirmations due this month.</div></div>'
    : confs.map(function(c) {
        return '<div class="conf-item"><div class="conf-date-pill">' + fmtDate(c.scheduled_confirmation_date) + '</div><div><div class="conf-name">' + esc(c.employee_name) + '</div><div class="conf-meta">' + esc(c.designation||"") + (c.department ? " · " + esc(c.department) : "") + '</div></div></div>';
      }).join("");

  // Recent joiners table
  document.getElementById("recent-emp-tbody").innerHTML = !recent.length
    ? '<tr><td colspan="4" style="text-align:center;color:var(--text3);padding:20px">No recent employees found.</td></tr>'
    : recent.map(function(e) {
        return '<tr><td>' + esc(e.employee_name) + '</td><td>' + esc(e.designation||"—") + '</td><td>' + esc(e.department||"—") + '</td><td class="num">' + fmtDate(e.date_of_joining) + '</td></tr>';
      }).join("");
}

/* ── Data to review (slice 012) ──────────────────────
   Its own block and name prefix (dr). The server decides everything shown here -
   scope, which records exist, what may be confirmed, every figure. The page only
   draws it; a hidden button is not a permission. */
var DR = { cards: [], pending: null, returnFocus: null };

// Translation when Frappe's __ is on the page; the plain English otherwise.
// {0}, {1}... are filled here so no sentence is built from pieces.
function drT(text, args) {
  var out = (typeof window.__ === "function") ? window.__(text) : text;
  (args || []).forEach(function (a, i) { out = out.split("{" + i + "}").join(a); });
  return out;
}

function drDay(iso) {
  return new Date(iso + "T00:00:00").toLocaleDateString(undefined, { day: "numeric", month: "short" });
}

function drDates(list) {
  var days = (list || []).map(drDay);
  try { return new Intl.ListFormat(undefined, { type: "conjunction" }).format(days); }
  catch (e) { return days.join(", "); }
}

function drWhen(stamp) {
  if (!stamp) return "";
  var dt = new Date(String(stamp).slice(0, 19).replace(" ", "T"));
  return dt.toLocaleDateString(undefined, { day: "numeric", month: "short" }) + ", " +
    dt.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit", hour12: false });
}

function drSetBadge(n) {
  var b = document.getElementById("sb-dr-badge");
  if (!b) return;
  b.textContent = n || 0;
  b.style.display = n ? "" : "none";
}

function drNotLinkedHtml() {
  return '<div class="dr-note neutral" role="status"><p><b>' +
    esc(drT("Your account is not linked to a company, so there are no figures to show.")) + '</b></p><p>' +
    esc(drT("Ask your System Manager to give you permission for your company, or to link your employee record to your login.")) +
    '</p></div>';
}

/* The lines at the top of HR Analytics. */
function drAnalyticsNotes(d) {
  var box = document.getElementById("ana-dr-notes");
  var panel = document.getElementById("panel-analytics");
  if (!box || !panel) return;
  panel.querySelectorAll(":scope > .kpi-grid, :scope > .g2, :scope > .card").forEach(function (el) {
    el.style.display = d.not_linked ? "none" : "";
  });
  if (d.not_linked) { box.innerHTML = drNotLinkedHtml(); return; }

  var html = "";
  if (d.data_up_to) {
    html += '<p class="dr-upto">' + esc(drT("Data up to {0}", [fmtDate(d.data_up_to)])) + '</p>';
  }
  var review = d.review || {};
  var dates = review.doubtful_dates || [];
  if (dates.length) {
    html += '<div class="dr-note" role="status"><p><b>' + esc(drT("Some attendance days look wrong")) + '</b></p><p>' +
      esc(drT("On {0} almost everyone is marked absent. This is usually missing check-in data, not real absence. These days are left out of the attendance figures below until HR fixes or confirms them.", [drDates(dates)])) +
      '</p></div>';
  }
  var n = review.open_count || 0;
  if (n) {
    html += '<div class="dr-note neutral"><p><b>' +
      esc(n === 1 ? drT("1 figure needs review.") : drT("{0} figures need review.", [n])) + '</b> ' +
      esc(drT("Leaders see 'Needs review' until they are fixed.")) + '</p>' +
      '<p><button type="button" class="dr-link" onclick="switchPanel(\'data-review\')">' +
      esc(drT("Open Data to review")) + '</button></p></div>';
  }
  drSetBadge(n);
  box.innerHTML = html;
}

function drLoad() {
  var body = document.getElementById("dr-body");
  body.setAttribute("aria-busy", "true");
  return window.gpFetch("alvoraa_portal.data_review.data_review_items", {}).then(function (d) {
    drRender(d);
  }).catch(function (e) {
    body.innerHTML = '<div class="dr-note" role="alert"><p><b>' + esc(drT("Data to review did not load.")) +
      '</b></p><p>' + esc((e && e.message) || drT("Check your connection and try again.")) + '</p>' +
      '<p><button type="button" class="dr-link" onclick="drLoad()">' + esc(drT("Try again")) + '</button></p></div>';
  }).then(function () {
    body.setAttribute("aria-busy", "false");
  });
}

function drDeskUrl(route, filters) {
  var q = Object.keys(filters).map(function (k) {
    var v = filters[k];
    return encodeURIComponent(k) + "=" + encodeURIComponent(typeof v === "string" ? v : JSON.stringify(v));
  }).join("&");
  return "/app/" + route + (q ? "?" + q : "");
}

function drCard(c, i, manyCompanies) {
  var title, chip, lines = [], leaders, acts = [], meta;
  var company = manyCompanies ? '<p class="dr-meta">' + esc(drT("Company: {0}", [c.company])) + '</p>' : "";
  if (c.kind === "doubtful") {
    var n = c.dates.length;
    title = n === 1 ? drT("1 attendance day looks wrong") : drT("{0} attendance days look wrong", [n]);
    chip = '<span class="dr-chip warn">' + esc(drT("Doubtful days")) + '</span>';
    var pct = c.absent_pct ? (c.absent_pct[0] === c.absent_pct[1] ? c.absent_pct[0] + "%" : c.absent_pct[0] + "–" + c.absent_pct[1] + "%") : "";
    lines.push(drT("On {0}, {1} of the people expected at work at {2} are marked absent, and no more than {3}% checked in. This usually means the check-in device did not send its data.",
      [drDates(c.dates), pct, (c.branches || []).join(", "), c.checked_in_pct || 0]));
    lines.push(drT("These days are left out of attendance, late arrivals and short days, for HR and for leaders."));
    leaders = n === 1 ? drT("an amber warning, \"1 doubtful day left out\", and attendance without that day.")
                      : drT("an amber warning, \"{0} doubtful days left out\", and attendance without those days.", [n]);
    acts.push('<a class="btn btn-primary" target="_blank" rel="noopener" href="' + esc(drDeskUrl("attendance", {
      company: c.company, alvoraa_branch: ["in", c.branches || []],
      attendance_date: ["between", [c.dates[0], c.dates[n - 1]]] })) + '">' + esc(drT("Open attendance for these days")) + '</a>');
    if (c.can_confirm) acts.push('<button type="button" class="btn btn-outline" onclick="drAsk(' + i + ', this)">' + esc(drT("The absence was real")) + '</button>');
    meta = drT("Found {0} · Checked again every morning", [drWhen(c.found_on)]);
  } else if (c.kind === "leave") {
    title = drT("Leave used");
    chip = '<span class="dr-chip review">' + esc(drT("Needs review")) + '</span>';
    lines.push(drT("Only {0} leave requests have been entered this leave year, for {1} people with {2} days of leave between them.",
      [c.requests, c.people, Number(c.days_allocated || 0).toLocaleString()]));
    lines.push(drT("Leave is probably being recorded somewhere else, so \"leave used 0%\" would mislead."));
    leaders = drT("\"Needs review\" for leave used, on leave today and requests waiting.");
    acts.push('<a class="btn btn-primary" target="_blank" rel="noopener" href="' + esc(drDeskUrl("leave-application", { company: c.company })) + '">' + esc(drT("Open leave requests")) + '</a>');
    if (c.can_confirm) acts.push('<button type="button" class="btn btn-outline" onclick="drAsk(' + i + ', this)">' + esc(drT("The figure is right, show it")) + '</button>');
    meta = drT("Found {0} · Checked again every morning", [drWhen(c.found_on)]);
  } else {
    title = drT("Leavers and attrition");
    chip = '<span class="dr-chip review">' + esc(drT("Needs review")) + '</span>';
    leaders = drT("\"Needs review\" for leavers and attrition.");
    if (c.rule === "D18-1") {
      lines.push(c.branch
        ? drT("{0} people at {1} are marked as left but have no leaving date. Without a date, nobody can tell whether they left in the last 12 months.", [c.people, c.branch])
        : drT("{0} people with no branch are marked as left but have no leaving date. Without a date, nobody can tell whether they left in the last 12 months.", [c.people]));
      var f = { company: c.company, status: "Left", relieving_date: ["is", "not set"] };
      if (c.branch) f.branch = c.branch;
      acts.push('<a class="btn btn-primary" target="_blank" rel="noopener" href="' + esc(drDeskUrl("employee", f)) + '">' + esc(drT("Open these {0} people", [c.people])) + '</a>');
      meta = drT("Found {0} · Clears by itself once every leaver has a leaving date", [drWhen(c.found_on)]);
    } else {
      lines.push(drT("Nobody in {0} has a leaving date in the last 12 months. If people did leave, their records are missing a leaving date.", [c.company]));
      acts.push('<a class="btn btn-primary" target="_blank" rel="noopener" href="' + esc(drDeskUrl("employee", { company: c.company, status: "Left" })) + '">' + esc(drT("Open employees who left")) + '</a>');
      if (c.can_confirm) acts.push('<button type="button" class="btn btn-outline" onclick="drAsk(' + i + ', this)">' + esc(drT("The figure is right, show it")) + '</button>');
      meta = drT("Found {0} · Checked again every morning", [drWhen(c.found_on)]);
    }
  }
  return '<section class="card dr-card" aria-labelledby="dr-card-' + i + '"><div class="card-header">' +
    '<h2 class="card-title" id="dr-card-' + i + '">' + esc(title) + '</h2>' + chip + '</div><div class="card-body">' +
    company + lines.map(function (l) { return '<p>' + esc(l) + '</p>'; }).join("") +
    '<p class="dr-leaders"><b>' + esc(drT("Leaders see:")) + '</b> ' + esc(leaders) + '</p>' +
    '<div class="dr-actions">' + acts.join("") + '</div>' +
    '<p class="dr-meta">' + esc(meta) + '</p></div></section>';
}

function drRender(d) {
  var body = document.getElementById("dr-body");
  if (d.not_linked) { body.innerHTML = drNotLinkedHtml(); drSetBadge(0); return; }
  DR.cards = d.cards || [];
  drSetBadge(d.open_count || 0);

  var html = '<p class="dr-intro">' + esc(drT("These figures show 'Needs review' to company and branch heads until you fix the data or confirm it is right. Leaders see the label and a short reason, not these details.")) + '</p>';
  if (d.stale) {
    html += '<div class="dr-note" role="status"><p>' + esc(d.last_checked
      ? drT("Checks have not run since {0}", [drWhen(d.last_checked)])
      : drT("Checks have not run yet. They run every morning.")) + '</p></div>';
  } else if (d.last_checked) {
    html += '<p class="dr-upto" style="margin-top:0">' + esc(drT("Last checked {0}", [drWhen(d.last_checked)])) + '</p>';
  }
  if (!DR.cards.length) {
    html += '<div class="card"><div class="empty-state"><div class="empty-state-text">' +
      esc(drT("Nothing to review. The data behind every figure in your scope looks complete. It is checked again every morning.")) +
      '</div></div></div>';
  } else {
    var companies = {};
    DR.cards.forEach(function (c) { companies[c.company] = 1; });
    var many = Object.keys(companies).length > 1;
    html += DR.cards.map(function (c, i) { return drCard(c, i, many); }).join("");
  }
  html += '<p class="dr-foot">' + esc(drT("Every 'the figure is right' confirmation is kept with who made it and when.")) + '</p>';
  body.innerHTML = html;
}

/* Confirm dialogs: an alert dialog, focus on the safe choice, Escape keeps things as they are. */
function drAsk(i, trigger) {
  var c = DR.cards[i];
  if (!c) return;
  var title, text, keep, go, action;
  if (c.kind === "doubtful") {
    action = "absence_real";
    title = drT("Count these days as real absence?");
    text = (c.figure_with != null && drMovesFigure(c))
      ? drT("Count {0} as real absence? Attendance for this month will drop to about {1}%. This is recorded with your name.", [drDates(c.dates), c.figure_with])
      : drT("Count {0} as real absence? They will be counted in attendance again. This is recorded with your name.", [drDates(c.dates)]);
    keep = drT("Keep them left out"); go = drT("Count them");
  } else if (c.kind === "leave") {
    action = "figure_right";
    title = drT("Show leave used to leaders?");
    text = drT("Leaders will see leave used as {0}%. Only do this if leave really is recorded in Alvora. This is recorded with your name.", [c.used_pct == null ? 0 : c.used_pct]);
    keep = drT("Keep 'Needs review'"); go = drT("Show it");
  } else {
    action = "figure_right";
    title = drT("Show leavers to leaders?");
    text = drT("Leaders will see no leavers in the last 12 months for {0}. Only do this if nobody really left. This is recorded with your name.", [c.company]);
    keep = drT("Keep 'Needs review'"); go = drT("Show it");
  }
  DR.pending = { items: c.items, action: action };
  DR.returnFocus = trigger || null;
  document.getElementById("dr-confirm-title").textContent = title;
  document.getElementById("dr-confirm-text").textContent = text;
  document.getElementById("dr-confirm-keep").textContent = keep;
  document.getElementById("dr-confirm-go").textContent = go;
  document.getElementById("dr-confirm-go").disabled = false;
  document.getElementById("dr-confirm").classList.add("open");
  document.getElementById("dr-confirm-keep").focus();
}

// The "drop to about" figure is for this month; a doubtful day in an earlier month does not move it.
function drMovesFigure(c) {
  return c.figure_without != null && c.figure_with !== c.figure_without;
}

function drCloseConfirm() {
  DR.pending = null;
  document.getElementById("dr-confirm").classList.remove("open");
  if (DR.returnFocus && document.body.contains(DR.returnFocus)) DR.returnFocus.focus();
}

function drConfirmGo() {
  var p = DR.pending;
  if (!p) return;
  var go = document.getElementById("dr-confirm-go");
  go.disabled = true;           // a second tap sends nothing
  window.gpFetch("alvoraa_portal.data_review.data_review_confirm", { items: p.items, action: p.action }).then(function () {
    DR.returnFocus = null;
    drCloseConfirm();
    toast(drT("Recorded with your name. Leaders see the figure the next time they open their overview."));
    drLoad();
    loadedPanels.delete("analytics");   // HR Analytics picks up the change next time it opens
  }).catch(function (e) {
    go.disabled = false;
    toast((e && e.message) || drT("Could not record this. Try again."), "err");
  });
}

document.addEventListener("keydown", function (e) {
  var dlg = document.getElementById("dr-confirm");
  if (!dlg || !dlg.classList.contains("open")) return;
  if (e.key === "Escape") { e.preventDefault(); drCloseConfirm(); return; }
  if (e.key === "Tab") {        // keep focus inside the two choices
    var keep = document.getElementById("dr-confirm-keep"), go = document.getElementById("dr-confirm-go");
    var last = go.disabled ? keep : go;
    if (e.shiftKey && document.activeElement === keep) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); keep.focus(); }
  }
});

/* ── Home goals (compact) ────────────────────────── */
let _teamGoalData = null;

function loadHomeGoals() {
  if (_goalData) { renderHomeGoals(_goalData); return; }
  api("get_goals_portal_data", {}, function(data) {
    _goalData = data;
    renderHomeGoals(data);
  }, function() {
    const s = document.getElementById("home-goals-section");
    if (s) s.style.display = "none";
  });
}

function renderHomeGoals(data) {
  const section = document.getElementById("home-goals-section");
  if (!section) return;
  if (!data.available || data.no_employee) { section.style.display = "none"; return; }
  const goals = (data.goals || []).filter(function(g){ return g.status !== "Cancelled"; });
  section.style.display = "block";
  if (!goals.length) {
    document.getElementById("home-goals-list").innerHTML =
      '<div style="color:var(--text3);font-size:var(--fs-base);padding:14px 0">No active goals set for this period. Goals appear here once submitted by your manager.</div>';
    return;
  }
  const shown = goals.slice(0, 3);   /* slice 076: three on Home; "Full Portal" has the rest */
  document.getElementById("home-goals-list").innerHTML = shown.map(function(g) {
    const pct = Math.min(100, Math.round(parseFloat(g.progress_pct || 0)));
    const actFmt = parseFloat(g.actual_progress||0).toLocaleString("en-IN",{maximumFractionDigits:1});
    const tgtFmt = parseFloat(g.target_value||0).toLocaleString("en-IN",{maximumFractionDigits:1});
    return '<div class="hg-card ' + _trajClass(g.trajectory) + '" onclick="openGoalDrawer(\'' + g.name + '\')">' +
      '<div class="hg-traj"><span class="traj-badge ' + _trajBadge(g.trajectory) + '" style="font-size:var(--fs-xs);padding:2px 8px">' +
      '<span style="width:5px;height:5px;border-radius:50%;background:currentColor;display:inline-block;flex-shrink:0"></span> ' + esc(g.trajectory||"Not Started") + '</span>' +
      (g.docstatus===0 ? '<span class="badge badge-amber" style="font-size:var(--fs-xs);margin-left:4px;padding:1px 5px">Draft</span>' : '') + '</div>' +
      '<div class="hg-main"><div class="hg-name">' + esc(g.goal_name) + '</div>' +
      '<div class="hg-bar"><div class="hg-fill" style="width:' + pct + '%;background:' + _trajColor(g.trajectory) + '"></div></div>' +
      '<div class="hg-sub">' + actFmt + ' / ' + tgtFmt + (g.unit ? ' ' + esc(g.unit) : '') + '</div></div>' +
      '<div class="hg-right"><div class="hg-pct">' + pct + '%</div><div class="hg-arrow">›</div></div>' +
      '</div>';
  }).join("");
}

function loadTeamGoals() {
  api("get_team_goals", {}, function(data) {
    _teamGoalData = data;
    renderTeamGoals(data);
  }, function() {
    const s = document.getElementById("home-team-goals-section");
    if (s) s.style.display = "none";
  });
}

function renderTeamGoals(data) {
  const section = document.getElementById("home-team-goals-section");
  if (!section) return;
  if (!data.available) { section.style.display = "none"; return; }
  const byEmp = data.by_employee || {};
  section.style.display = "block";
  if (!Object.keys(byEmp).length) {
    document.getElementById("home-team-goals-list").innerHTML =
      '<div style="color:var(--text3);font-size:var(--fs-base);padding:14px 0">No submitted goals for your team yet.</div>';
    return;
  }
  let html = "";
  /* Three people, one goal each, on Home; the rest are on the Team page (slice 076, so the grid stays balanced). */
  const empIds = Object.keys(byEmp), HOME_TEAM_MAX = 3;
  empIds.slice(0, HOME_TEAM_MAX).forEach(function(empId) {
    const ed   = byEmp[empId];
    const rec  = ed.employee || {};
    html += '<div class="hg-member">' + esc(rec.employee_name||empId) + (rec.designation ? ' · ' + esc(rec.designation) : '') + '</div>';
    ed.goals.slice(0, 1).forEach(function(g) {
      const pct = Math.min(100, Math.round(parseFloat(g.progress_pct || 0)));
      html += '<div class="hg-card ' + _trajClass(g.trajectory) + '" onclick="openTeamGoalDrawer(\'' + g.name + '\')">' +
        '<div class="hg-traj"><span class="traj-badge ' + _trajBadge(g.trajectory) + '" style="font-size:var(--fs-xs);padding:2px 8px">' +
        '<span style="width:5px;height:5px;border-radius:50%;background:currentColor;display:inline-block;flex-shrink:0"></span> ' + esc(g.trajectory||"Not Started") + '</span></div>' +
        '<div class="hg-main"><div class="hg-name">' + esc(g.goal_name) + '</div>' +
        '<div class="hg-bar"><div class="hg-fill" style="width:' + pct + '%;background:' + _trajColor(g.trajectory) + '"></div></div></div>' +
        '<div class="hg-right"><div class="hg-pct">' + pct + '%</div><div class="hg-arrow">›</div></div>' +
        '</div>';
    });
  });
  if (empIds.length > HOME_TEAM_MAX) {
    html += '<button type="button" class="hm-tbtn" data-hm="team-all">' + esc(drT("View all {0}", [empIds.length])) + '</button>';
  }
  document.getElementById("home-team-goals-list").innerHTML = html;
}

function openTeamGoalDrawer(goalId) {
  document.getElementById("goal-drawer-overlay").classList.add("open");
  document.getElementById("goal-drawer").classList.add("open");
  document.body.style.overflow = "hidden";
  document.getElementById("gd-head").innerHTML =
    '<div style="flex:1"><div style="color:var(--surface);font-size:var(--fs-md);font-weight:600">Loading goal...</div></div>' +
    '<button class="emp-drawer-close" onclick="closeGoalDrawer()"><i class=ic-x></i></button>';
  document.getElementById("gd-body").innerHTML =
    '<div style="padding:40px;text-align:center;color:var(--text3)">Loading...</div>';
  api("get_goal_detail", {goal_id: goalId}, function(d) {
    renderGoalDrawer(d.goal, d.cascade || {}, d.is_owner, d.can_edit);
  }, function(e) {
    document.getElementById("gd-body").innerHTML =
      '<div class="callout callout-warn">' + esc((e && e.message) || "Failed to load goal details.") + '</div>';
  });
}

/* ── Goals & Performance ─────────────────────────── */
let _goalData = null;

function _trajClass(t) {
  if (t === "On Track")  return "on-track";
  if (t === "At Risk")   return "at-risk";
  if (t === "Off Track") return "off-track";
  if (t === "Completed") return "completed";
  return "not-started";
}
function _trajBadge(t) {
  if (t === "On Track")  return "traj-on-track";
  if (t === "At Risk")   return "traj-at-risk";
  if (t === "Off Track") return "traj-off-track";
  if (t === "Completed") return "traj-completed";
  return "traj-not-started";
}
function _trajColor(t) {
  if (t === "On Track" || t === "Completed") return "var(--green)";
  if (t === "At Risk")   return "var(--amber)";
  if (t === "Off Track") return "var(--red)";
  return "var(--text3)";
}

function loadGoalsPanel() {
  window._gpBoot();
}


function openGoalDrawer(goalId) {
  if (!_goalData) return;
  const goal = (_goalData.goals || []).find(function(g){ return g.name === goalId; });
  if (!goal) return;
  const cascMap = {};
  (_goalData.cascades || []).forEach(function(c){ cascMap[c.name] = c; });
  const casc = cascMap[goal.goal_cascade] || {};

  document.getElementById("goal-drawer-overlay").classList.add("open");
  document.getElementById("goal-drawer").classList.add("open");
  document.body.style.overflow = "hidden";
  renderGoalDrawer(goal, casc);
}

function closeGoalDrawer() {
  document.getElementById("goal-drawer-overlay").classList.remove("open");
  document.getElementById("goal-drawer").classList.remove("open");
  document.body.style.overflow = "";
}

// Only our own private file links are drawn. Anything else - an outside
// address, a javascript: link - draws no link at all (slice 010, SEC-11).
function _safeFileUrl(u) {
  u = String(u === null || u === undefined ? "" : u);
  return u.indexOf("/private/files/") === 0 ? esc(u) : "";
}

function renderGoalDrawer(g, casc, isOwner, canEdit) {
  if (isOwner === undefined) isOwner = true;
  if (canEdit === undefined) canEdit = true;
  const pct    = Math.min(100, Math.round(parseFloat(g.progress_pct || 0)));
  const tLabel = g.trajectory || "Not Started";
  const tColor = _trajColor(g.trajectory);
  const actFmt = parseFloat(g.actual_progress || 0).toLocaleString("en-IN", {maximumFractionDigits:1});
  const tgtFmt = parseFloat(g.target_value    || 0).toLocaleString("en-IN", {maximumFractionDigits:1});

  // Header
  document.getElementById("gd-head").innerHTML =
    '<div style="flex:1;min-width:0">' +
    '<div style="font-size:var(--fs-lg);font-weight:700;color:var(--surface);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(g.goal_name) + '</div>' +
    '<div style="margin-top:6px"><span class="traj-badge ' + _trajBadge(g.trajectory) + '">' +
    '<span style="width:6px;height:6px;border-radius:50%;background:currentColor;display:inline-block;flex-shrink:0"></span> ' + esc(tLabel) + '</span>' +
    (g.employee_name ? '<span style="font-size:var(--fs-xs);color:rgba(255,255,255,.5);margin-left:10px">' + esc(g.employee_name) + '</span>' : '') +
    /* An open review holds this objective (slice 010 group D, R5). */
    (window.riReviewBadge ? window.riReviewBadge(g.review_badge) : '') +
    '</div></div>' +
    '<button class="emp-drawer-close" onclick="closeGoalDrawer()"><i class=ic-x></i></button>';

  // Evidence list
  const gid = g.name;
  const evidence = g.evidence || [];
  const evHtml = evidence.length
    ? evidence.map(function(ev) {
        const vs    = ev.validation_status || "Pending";
        const parts = [esc(ev.evidence_type)];
        if (ev.extracted_date)   parts.push(fmtDate(ev.extracted_date));
        if (ev.extracted_amount) parts.push(parseFloat(ev.extracted_amount).toLocaleString("en-IN", {maximumFractionDigits: 2}));
        const safeFile = _safeFileUrl(ev.evidence_file);
        var isImg = safeFile && /\.(jpe?g|png|gif|webp|bmp|svg)$/i.test(safeFile);
        const fileHtml = safeFile
          ? (isImg
              ? '<div style="margin-top:6px"><a href="' + safeFile + '" target="_blank" rel="noopener"><img src="' + safeFile + '" alt="evidence" style="max-width:100%;max-height:120px;border-radius:var(--r-sm);border:1px solid var(--border);object-fit:cover;cursor:zoom-in"></a></div>'
              : '<div style="margin-top:4px"><a href="' + safeFile + '" target="_blank" rel="noopener" style="font-size:var(--fs-xs);color:var(--primary);display:flex;align-items:center;gap:4px"><svg width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>View attached file</a></div>')
          : '';
        const notesHtml = ev.validation_notes
          ? '<div style="font-size:var(--fs-xs);color:var(--text3);margin-top:2px;font-style:italic">' + esc(ev.validation_notes) + '</div>' : '';
        const rawNote = ev.raw_extracted_data
          ? '<div style="font-size:var(--fs-xs);color:var(--text2);margin-top:2px">' + esc(ev.raw_extracted_data) + '</div>' : '';
        return '<div class="ev-item">' +
          '<span class="ev-dot ' + esc(vs) + '"></span>' +
          '<div class="ev-body"><div class="ev-type">' + esc(ev.evidence_type || "Evidence") + '</div>' +
          '<div class="ev-meta">' + parts.join(" · ") + '</div>' + rawNote + fileHtml + notesHtml + '</div>' +
          '<span class="badge ' + (vs==="Approved"?"badge-green":vs==="Rejected"?"badge-red":"badge-amber") + '">' + esc(vs) + '</span>' +
          '</div>';
      }).join("")
    : '<div style="padding:14px 0;color:var(--text3);font-size:var(--fs-base)">No evidence submitted yet.</div>';

  // Submit evidence form (own goals only, when Active)
  const canSubmit = isOwner && g.status === "Active";
  const submitHtml = canSubmit
    ? '<div style="margin-top:14px">' +
      '<button class="btn btn-outline btn-sm" id="ev-toggle-' + gid + '" onclick="toggleGoalEvidenceForm(\'' + gid + '\')">+ Submit Evidence</button>' +
      '<div id="ev-form-' + gid + '" style="display:none;margin-top:14px;background:var(--surface2);border:1px solid var(--border);border-radius:var(--r-sm);padding:16px">' +
      '<div class="form-row"><div class="form-group"><label class="form-label">Value / Progress' + (g.unit ? ' (' + esc(g.unit) + ')' : '') + '</label><input class="form-control" type="number" id="ev-amount-' + gid + '" placeholder="e.g. 75" min="0" step="any"></div>' +
      '<div class="form-group"><label class="form-label">Date *</label><input class="form-control" type="date" id="ev-date-' + gid + '"></div></div>' +
      '<div class="form-group"><label class="form-label">Note / Description</label><input class="form-control" type="text" id="ev-note-' + gid + '" placeholder="Optional details"></div>' +
      '<div class="form-group"><label class="form-label">Attach Image or File</label>' +
      '<label style="display:flex;align-items:center;gap:10px;cursor:pointer;border:1.5px dashed var(--border);border-radius:var(--r-sm);padding:10px 14px;background:var(--surface);transition:border-color .2s" id="ev-file-lbl-' + gid + '" onclick="document.getElementById(\'ev-file-' + gid + '\').click()">' +
      '<svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>' +
      '<span id="ev-file-name-' + gid + '" style="font-size:var(--fs-sm);color:var(--text3)">Click to upload (image, PDF…)</span>' +
      '</label>' +
      '<input type="file" id="ev-file-' + gid + '" accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx" style="display:none" onchange="evFileChanged(\'' + gid + '\')">' +
      '</div>' +
      '<div class="form-actions" style="border-top:none;margin-top:0;padding-top:0">' +
      '<button class="btn btn-primary btn-sm" id="ev-submit-' + gid + '" onclick="submitGoalEvidence(\'' + gid + '\')">Submit</button>' +
      '<button class="btn btn-sm" onclick="toggleGoalEvidenceForm(\'' + gid + '\')" style="color:var(--text3)">Cancel</button>' +
      '</div></div></div>'
    : '';

  // Status update section (canEdit)
  const statusHtml = (canEdit && g.status !== "Cancelled")
    ? '<div class="ed-section">' +
      '<div class="ed-section-title">Update Status</div>' +
      '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">' +
      '<select class="form-control" id="gd-status-' + gid + '" style="max-width:160px">' +
      '<option value="Active"' + (g.status==="Active"?" selected":"") + '>Active</option>' +
      '<option value="Completed"' + (g.status==="Completed"?" selected":"") + '>Completed</option>' +
      '<option value="Cancelled"' + (g.status==="Cancelled"?" selected":"") + '>Cancelled</option>' +
      '</select>' +
      '<button class="btn btn-primary btn-sm" onclick="updateGoalStatus(\'' + gid + '\')">Update</button>' +
      '</div></div>'
    : '';

  document.getElementById("gd-body").innerHTML =
    // Progress
    '<div class="gd-progress-section">' +
    '<div class="gd-pct">' + pct + '<span style="font-size:var(--fs-xl);font-weight:400">%</span></div>' +
    '<div class="gd-pct-lbl">Progress towards target</div>' +
    '<div class="gd-prog-bar"><div class="gd-prog-fill" style="width:' + pct + '%;background:' + tColor + '"></div></div>' +
    '<div class="gd-actual">' + actFmt + ' / ' + tgtFmt + (g.unit ? ' ' + esc(g.unit) : '') + '</div>' +
    '</div>' +
    // Goal info
    '<div class="ed-section">' +
    '<div class="ed-section-title">Goal Details</div>' +
    '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">Period</div><div class="holiday-days">' + fmtDate(g.start_date) + ' → ' + fmtDate(g.end_date) + '</div></div></div>' +
    '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">Cascade</div><div class="holiday-days">' + esc(casc.cascade_name || '—') + '</div></div></div>' +
    '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">Target</div></div><div class="holiday-days num">' + tgtFmt + (g.unit ? ' ' + esc(g.unit) : '') + '</div></div>' +
    '<div class="holiday-item"><div style="flex:1"><div class="holiday-name">Status</div></div>' +
    '<span id="gd-status-badge-' + gid + '" class="badge ' + (g.status==="Active"?"badge-green":g.status==="Completed"?"badge-blue":"badge-gray") + '">' + (g.status||"—") + '</span></div>' +
    '</div>' +
    // Status update
    statusHtml +
    // Evidence
    '<div class="ed-section">' +
    '<div class="ed-section-title">Evidence (' + evidence.length + ')</div>' +
    evHtml + submitHtml +
    '</div>' +
    // Progress Updates
    '<div class="ed-section">' +
    '<div class="ed-section-title" style="display:flex;align-items:center;justify-content:space-between">Progress Updates' +
    (canSubmit ? '<button class="btn btn-outline btn-sm" onclick="gpOpenGoalLogModal(\'' + gid + '\')">+ Log Update</button>' : '') +
    '</div>' +
    '<div id="gd-upd-history-' + gid + '" class="upd-timeline"><div style="color:var(--text3);font-size:var(--fs-sm)">Loading…</div></div>' +
    '</div>' +
    // Comments
    '<div class="ed-section">' +
    '<div class="ed-section-title">Comments</div>' +
    '<div id="gd-comments-' + gid + '"><div style="color:var(--text3);font-size:var(--fs-sm);padding:8px 0">Loading comments...</div></div>' +
    '<div class="comment-input-row">' +
    '<input class="form-control" type="text" id="gd-comment-input-' + gid + '" placeholder="Add a comment..." onkeydown="if(event.key===\'Enter\')addGoalComment(\'' + gid + '\')">' +
    '<button class="btn btn-primary btn-sm" onclick="addGoalComment(\'' + gid + '\')">Post</button>' +
    '</div></div>';

  // Load comments and update history async
  loadGoalComments(gid);
  loadGoalUpdateHistory(gid);
}

function loadGoalComments(goalId) {
  api("get_goal_comments", {goal_id: goalId}, function(data) {
    const el = document.getElementById("gd-comments-" + goalId);
    if (!el) return;
    const comments = data.comments || [];
    if (!comments.length) {
      el.innerHTML = '<div style="color:var(--text3);font-size:var(--fs-sm);padding:8px 0">No comments yet.</div>';
      return;
    }
    el.innerHTML = comments.map(function(c) {
      const d = new Date(c.creation);
      const when = d.toLocaleDateString("en-IN", {day:"2-digit",month:"short"}) + " " +
                   d.toLocaleTimeString("en-IN", {hour:"2-digit",minute:"2-digit"});
      return '<div class="comment-item">' +
        '<div class="comment-av">' + initials(c.commenter_name) + '</div>' +
        '<div class="comment-body">' +
        '<div class="comment-meta"><strong>' + esc(c.commenter_name||c.owner) + '</strong> · ' + when + '</div>' +
        '<div class="comment-text">' + esc(c.content||"") + '</div>' +
        '</div></div>';
    }).join("");
  }, function() {
    const el = document.getElementById("gd-comments-" + goalId);
    if (el) el.innerHTML = '<div style="color:var(--text3);font-size:var(--fs-sm)">Failed to load comments.</div>';
  });
}

function addGoalComment(goalId) {
  const inp = document.getElementById("gd-comment-input-" + goalId);
  if (!inp || !inp.value.trim()) { toast("Enter a comment", "err"); return; }
  const content = inp.value.trim();
  inp.disabled = true;
  api("add_goal_comment", {goal_id: goalId, content: content}, function(c) {
    inp.value = "";
    inp.disabled = false;
    loadGoalComments(goalId);
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
    inp.disabled = false;
    toast((e && e.message) || "Failed to post comment", "err");
  });
}

function loadGoalUpdateHistory(goalId, focusRow) {
  window.gpFetch("alvoraa_portal.goals_api.get_goal_update_log", {goal_id: goalId}).then(function(rows) {
    var el = document.getElementById("gd-upd-history-" + goalId);
    if (!el) return;
    if (window.renderUpdateTimeline) window.renderUpdateTimeline(rows, "gd-upd-history-" + goalId, "Individual Goal", goalId);
    if (focusRow) {
      var r = document.getElementById("upd-row-" + focusRow);
      if (r) r.scrollIntoView({behavior:"smooth", block:"center"});
    }
  }).catch(function() {
    var el = document.getElementById("gd-upd-history-" + goalId);
    if (el) el.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">Could not load history.</div>";
  });
}

/* Goal log modal — mirrors the KPI log modal but targets Goals API */
var _gdLogGoalId = null;
var _gdLogModalEl = null;

window.gpOpenGoalLogModal = function(goalId) {
  _gdLogGoalId = goalId;
  if (!_gdLogModalEl) {
    _gdLogModalEl = document.createElement("div");
    _gdLogModalEl.className = "gp-backdrop";
    _gdLogModalEl.id = "gp-goal-log-modal";
    _gdLogModalEl.innerHTML =
      '<div class="gp-modal">' +
        '<div class="gp-modal-hdr">' +
          '<div class="gp-modal-title">Log Goal Update</div>' +
          '<button class="gp-modal-close" onclick="gpCloseGoalLogModal()">&times;</button>' +
        '</div>' +
        '<div class="gp-modal-body">' +
          '<div class="gp-error" id="gp-goal-log-error"></div>' +
          '<div class="gp-field">' +
            '<div class="gp-label">New Progress Value *</div>' +
            '<input class="gp-input" id="gp-goal-log-value" type="number" step="any" placeholder="e.g. 75">' +
          '</div>' +
          '<div class="gp-field">' +
            '<div class="gp-label">Comment <span style="font-weight:400;color:var(--text3)">(required)</span></div>' +
            '<input class="gp-input" id="gp-goal-log-note" placeholder="What changed since the last update?">' +
          '</div>' +
          '<div class="gp-field">' +
            '<div class="gp-label">Evidence <span style="font-weight:400;color:var(--text3)">(optional)</span></div>' +
            '<label class="ev-upload-zone" onclick="document.getElementById(\'gp-goal-log-file\').click()">' +
              '<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>' +
              '<span id="gp-goal-log-file-name" style="font-size:var(--fs-sm);color:var(--text3)">Click to attach image or document…</span>' +
            '</label>' +
            '<input type="file" id="gp-goal-log-file" accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx" style="display:none" onchange="document.getElementById(\'gp-goal-log-file-name\').textContent=this.files[0]?this.files[0].name:\'Click to attach image or document…\'">' +
          '</div>' +
        '</div>' +
        '<div class="gp-modal-footer">' +
          '<button class="btn btn-outline" onclick="gpCloseGoalLogModal()">Cancel</button>' +
          '<button class="btn btn-primary" id="gp-goal-log-submit-btn" onclick="gpSubmitGoalLog()">Save Update</button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(_gdLogModalEl);
  }
  document.getElementById("gp-goal-log-error").textContent = "";
  document.getElementById("gp-goal-log-value").value = "";
  document.getElementById("gp-goal-log-note").value = "";
  document.getElementById("gp-goal-log-file").value = "";
  document.getElementById("gp-goal-log-file-name").textContent = "Click to attach image or document…";
  _gdLogModalEl.style.display = "flex";
};

window.gpCloseGoalLogModal = function() { if (_gdLogModalEl) _gdLogModalEl.style.display = "none"; };

window.gpSubmitGoalLog = async function() {
  var value = document.getElementById("gp-goal-log-value").value;
  if (!value) { document.getElementById("gp-goal-log-error").textContent = "Enter a value."; return; }
  var btn = document.getElementById("gp-goal-log-submit-btn");
  btn.disabled = true; btn.textContent = "Saving…";
  try {
    var evidenceUrl = null;
    var fi = document.getElementById("gp-goal-log-file");
    if (fi.files.length > 0) {
      var fd = new FormData(); fd.append("file", fi.files[0]); fd.append("is_private", "1");
      var up = await fetch("/api/method/upload_file", {method:"POST", body:fd,
        headers:{"X-Frappe-CSRF-Token": frappe && frappe.csrf_token ? frappe.csrf_token : ""}});
      var ud = await up.json();
      if (ud && ud.message && ud.message.file_url) evidenceUrl = ud.message.file_url;
      else { document.getElementById("gp-goal-log-error").textContent = "File upload failed."; btn.disabled=false; btn.textContent="Save Update"; return; }
    }
    await window.gpFetch("alvoraa_portal.goals_api.submit_goal_update", {goal_id: _gdLogGoalId, new_value: value,
      note: document.getElementById("gp-goal-log-note").value, evidence_url: evidenceUrl});
    gpCloseGoalLogModal();
    loadGoalUpdateHistory(_gdLogGoalId);
  } catch(e) {
    document.getElementById("gp-goal-log-error").textContent = e.message || "Error saving update.";
  } finally { btn.disabled = false; btn.textContent = "Save Update"; }
};

/* Navigate to a goal's drawer and focus a specific update row (for manager notification clicks) */
window.gpOpenGoalDetail = function(goalId, focusRow) {
  openTeamGoalDrawer(goalId);
  if (focusRow) {
    var poll = setInterval(function() {
      var el = document.getElementById("upd-row-" + focusRow);
      if (el) { clearInterval(poll); el.scrollIntoView({behavior:"smooth", block:"center"}); }
    }, 300);
    setTimeout(function() { clearInterval(poll); }, 5000);
  }
};

function updateGoalStatus(goalId) {
  const sel = document.getElementById("gd-status-" + goalId);
  if (!sel) return;
  const newStatus = sel.value;
  api("update_goal_status", {goal_id: goalId, new_status: newStatus}, function() {
    toast("Status updated to " + newStatus, "ok");
    // Update badge in drawer
    const badge = document.getElementById("gd-status-badge-" + goalId);
    if (badge) {
      badge.textContent = newStatus;
      badge.className = "badge " + (newStatus==="Active"?"badge-green":newStatus==="Completed"?"badge-blue":"badge-gray");
    }
    // Refresh goal data so home page / goals panel stay current
    _goalData = null;
    _teamGoalData = null;
    loadedPanels.delete("goals");
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
    toast((e && e.message) || "Failed to update status", "err");
  });
}

function toggleGoalEvidenceForm(gid) {
  const form = document.getElementById("ev-form-" + gid);
  const btn  = document.getElementById("ev-toggle-" + gid);
  if (!form) return;
  const hidden = form.style.display === "none";
  form.style.display = hidden ? "block" : "none";
  if (btn) btn.textContent = hidden ? "<i class=ic-x></i> Cancel" : "+ Submit Evidence";
}

function evFileChanged(gid) {
  var fileEl = document.getElementById("ev-file-" + gid);
  var nameEl = document.getElementById("ev-file-name-" + gid);
  var lblEl  = document.getElementById("ev-file-lbl-" + gid);
  if (!fileEl || !fileEl.files || !fileEl.files.length) return;
  var name = fileEl.files[0].name;
  if (nameEl) nameEl.textContent = name;
  if (lblEl)  lblEl.style.borderColor = "var(--primary)";
}

function submitGoalEvidence(gid) {
  var amount  = (document.getElementById("ev-amount-" + gid) || {}).value || "";
  var date    = (document.getElementById("ev-date-"   + gid) || {}).value || "";
  var note    = (document.getElementById("ev-note-"   + gid) || {}).value || "";
  var fileEl  = document.getElementById("ev-file-" + gid);
  var hasFile = fileEl && fileEl.files && fileEl.files.length > 0;

  if (!date) { toast("Please select a date", "err"); return; }
  if (!amount && !hasFile && !note) {
    toast("Enter a value, note, or attach a file", "err"); return;
  }

  var btn = document.getElementById("ev-submit-" + gid);
  if (btn) { btn.disabled = true; btn.textContent = "Submitting…"; }

  function doSubmit(fileUrl) {
    api("submit_goal_evidence_portal", {
      goal_id:            gid,
      evidence_type:      "Manual Entry",
      value:              amount  || null,
      extracted_date:     date,
      evidence_file:      fileUrl || null,
      raw_extracted_data: note    || null,
    }, function() {
      toast("Evidence sent to your manager for approval", "ok");
      closeGoalDrawer();
      _goalData = null;
      gpResetContext();   // not `_gpCtx = null` - that assigns a different scope
      loadedPanels.delete("goals");
      loadHomeGoals();
      loadGoalsPanel();
    }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
      toast((e && e.message) || "Failed to submit evidence", "err");
      if (btn) { btn.disabled = false; btn.textContent = "Submit"; }
    });
  }

  if (hasFile) {
    if (btn) btn.textContent = "Uploading file...";
    var fd = new FormData();
    fd.append("file", fileEl.files[0]);
    fd.append("is_private", "1");
    var _ctrl = new AbortController();
    var _timer = setTimeout(function() { _ctrl.abort(); }, 30000);
    fetch("/api/method/upload_file", {
      method: "POST",
      headers: {"X-Frappe-CSRF-Token": frappe.csrf_token || ""},
      body: fd,
      signal: _ctrl.signal,
    })
    .then(function(r) { clearTimeout(_timer); return r.json(); })
    .then(function(resp) {
      var url = resp.message && resp.message.file_url;
      if (!url) { toast("File upload failed", "err"); if (btn) { btn.disabled = false; btn.textContent = "Submit"; } return; }
      doSubmit(url);
    })
    .catch(function(e) {
      clearTimeout(_timer);
      var msg = (e && e.name === "AbortError") ? "Upload timed out — try a smaller file" : "File upload failed";
      toast(msg, "err");
      if (btn) { btn.disabled = false; btn.textContent = "Submit"; }
    });
  } else {
    doSubmit(null);
  }
}

/* ── Drawer Goals (manager view) ────────────────── */
function renderDrawerGoals(goals, empId) {
  const el = document.getElementById("ed-body");
  if (!el) return;
  const sec = document.createElement("div");
  sec.className = "ed-section";
  sec.id = "ed-goals-" + empId;
  if (!goals || !goals.length) {
    sec.innerHTML = '<div class="ed-section-title">Goals</div>' +
      '<div style="color:var(--text3);font-size:var(--fs-sm);padding:8px 0">No active goals assigned.</div>';
  } else {
    let html = '<div class="ed-section-title">Goals (' + goals.length + ')</div>';
    goals.forEach(function(g) {
      const pct = Math.min(100, Math.round(parseFloat(g.progress_pct || 0)));
      const isDraft = g.docstatus === 0;
      html += '<div class="hg-card ' + _trajClass(g.trajectory) + '" onclick="openTeamGoalDrawer(\'' + g.name + '\')" style="margin-bottom:8px">' +
        '<div style="flex:1;min-width:0">' +
        '<div style="font-size:var(--fs-sm);font-weight:600;color:var(--text);margin-bottom:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(g.goal_name) +
        (isDraft ? ' <span class="badge badge-amber" style="font-size:var(--fs-xs)">Draft</span>' : '') + '</div>' +
        '<div style="background:var(--surface2);border-radius:var(--r-full);height:5px;overflow:hidden">' +
        '<div style="height:100%;border-radius:var(--r-full);width:' + pct + '%;background:' + _trajColor(g.trajectory) + '"></div></div>' +
        '<div style="font-size:var(--fs-xs);color:var(--text3);margin-top:3px">' + pct + '% · ' + (g.trajectory || "Not Started") + '</div>' +
        '</div><div style="font-size:var(--fs-md);color:var(--text3);margin-left:8px">›</div></div>';
    });
    sec.innerHTML = html;
  }
  el.appendChild(sec);
}

/* ── Manager Notes ──────────────────────────────── */
let _teamMemberMap = {};   // empId → empName, populated from portal context

function switchTeamTab(tab) {
  /* Two tabs again. "Attendance Review" was the third until 17 Oct 2026,
     when the team's day-by-day list moved to the Attendance page's own
     picker - the same job, reached through one door instead of two. */
  var tabs = ["attendance", "notes"];
  tabs.forEach(function (t) {
    var panel = document.getElementById("tv-" + t + "-panel");
    if (panel) panel.style.display = tab === t ? "" : "none";
    var btn = document.getElementById("tvtab-" + t);
    if (btn) btn.classList.toggle("active", tab === t);
  });
  if (tab === "notes") {
    populateTeamNoteEmpFilter();
    tnFillEmployeeSelect();
    tnHideAdd();
    loadTeamNotes();
  }
}

/* ── Slice 066: the grooming red ─────────────────────────────────────────
   A manager marks a direct report on the day; HR marks or removes any open
   day; the person sees who, why and what it costs, and can ask HR to look.

   THE SERVER DECIDES EVERY BUTTON. `can_mark`, `can_undo`, `can_remove`,
   `can_ask`, `can_keep` and the refusal sentence all come from
   `alvoraa_portal.grooming`, worked out with the same `may_mark` the record
   itself enforces - so a button here can never be one the server refuses.
   Nothing in this block works out a rule, and a manager is never sent a
   rupee figure. Words follow prototype v2 (approved 24 Oct 2026). */
var GM = "alvoraa_portal.grooming.";
var GM_REMOVE = ["Marked by mistake", "Marked on the wrong person",
                 "The employee showed it was wrong"];
var gmState = {today: null, flash: {}, sheet: null, last: null, dayFlash: {},
               reviewFlash: null};

/* AC-34: a grooming bell links to /hrms-employee?grooming=YYYY-MM-DD (and
   &who=EMPLOYEE for HR). The page opens that Attendance month at that day.
   The server's month() still decides whose month may be opened. */
window.addEventListener("load", function () {
  var day = /[?&]grooming=(\d{4}-\d{2}-\d{2})/.exec(location.search);
  if (!day || typeof switchPanel !== "function") return;
  var who = /[?&]who=([A-Za-z0-9._-]+)/.exec(location.search);
  acState.team = false;
  acState.employee = who ? who[1] : null;
  acState.year = parseInt(day[1].slice(0, 4), 10);
  acState.month = parseInt(day[1].slice(5, 7), 10);
  acState.open = day[1];
  switchPanel("att-record");
});

/* The bell's grooming notices (slices 066, 076): the bell and the Notices card
   on Home read one function, notices.notices_feed. See the Home block. */

/* No answer: gpFetch's lost calls carry `kind` (slice 070) - offline, network
   or timeout. Anything else ("refused", "server") is the office answering, in
   a sentence worth showing as it is. */
function gmIsNet(e) { return !e || e.kind === "offline" || e.kind === "network" || e.kind === "timeout"; }

function gmName(first) { return gpEsc(first || ""); }

/* ── the Today card on Whole team ───────────────────────────────────── */

window.gmToday = async function () {
  var el = document.getElementById("gm-today");
  if (!el) return;
  el.innerHTML = gmCard(null, '<div class="gm-skel"></div><div class="gm-skel"></div>'
    + '<div class="gm-skel"></div><p class="gm-muted" role="status">Loading today’s people…</p>');
  try {
    gmState.today = await gpFetch(GM + "today", {});
  } catch (e) {
    /* No answer: say so, with Try again - never a card that just vanishes. */
    if (gmIsNet(e)) failBox(el, e, gmToday, function (d) { gmState.today = d; gmPaintToday(); });
    else el.innerHTML = "";
    return;
  }
  gmPaintToday();
};

function gmCard(day, inner) {
  return '<section class="gm-card" aria-labelledby="gm-today-h"><div class="gm-card-h">'
    + '<h2 class="gm-card-t" id="gm-today-h">Today' + (day ? " · " + gpEsc(day) : "")
    + ' · Grooming red</h2><span class="gm-card-s">Your direct reports who have clocked in</span></div>'
    + '<div class="gm-card-b"><p class="gm-help">Off unless you mark it. Mark someone only if they '
    + "are not groomed well today. They are told at once, with your name and the reason.</p>"
    + inner + "</div></section>";
}

function gmPaintToday() {
  var el = document.getElementById("gm-today");
  var d = gmState.today;
  if (!el) return;
  if (!d || !d.show) { el.innerHTML = ""; return; }
  var inner = "";
  if (!d.rows.length) {
    inner += '<p class="gm-help">None of your people have clocked in yet today. They appear '
      + "here after their first punch.</p>";
  } else {
    inner += d.rows.map(gmRow).join("");
    if (d.not_in && d.not_in.length) {
      var more = d.not_in.length - 1;
      inner += '<p class="gm-muted">' + gpEsc(d.not_in[0])
        + (more > 0 ? " and " + more + " other" + (more > 1 ? "s" : "") : "")
        + " have not clocked in today, so they cannot be marked yet.</p>";
    }
  }
  inner += '<div class="gm-count">You have marked ' + d.count + " grooming red"
    + (d.count === 1 ? "" : "s") + " this month.</div>";
  el.innerHTML = gmCard(d.day, inner);
}

function gmRow(r, i) {
  var h = '<div class="gm-row" id="gm-row-' + i + '"><div class="gm-who"><div class="gm-nm">'
    + gpEsc(r.employee_name) + '</div><div class="gm-sub">'
    + (r.designation ? gpEsc(r.designation) + " · " : "") + "Clocked in " + gpEsc(r.in_at)
    + (r.half_day ? " · Half-day leave this afternoon" : "") + "</div></div>";
  var first = gmName(r.first);
  var m = r.mark;
  if (m) {
    var line;
    if (m.mine && m.locked) {
      line = "Marked by you yesterday at " + gpEsc(m.at) + ". The undo closed at midnight. "
        + "To remove it now, ask HR.";
    } else if (m.mine) {
      line = "Marked by you at " + gpEsc(m.at) + ". " + (m.has_login
        ? first + " has been told."
        : first + " has no login and will not get a notice. You confirmed you told them in person today.")
        + " You can undo this until midnight.";
    } else {
      line = "Marked by " + gpEsc(m.by) + (m.marked_as === "HR" ? " (HR)" : "") + " at "
        + gpEsc(m.at) + ". Only HR can remove it.";
    }
    h += '<div><span class="ac-tag warn gm-tag">Grooming red</span> ' + gpEsc(m.reason) + "</div>";
    if (m.mine && !m.locked) {
      h += '<button class="btn btn-outline gm-btn" onclick="gmUndo(' + i + ')" aria-label="Undo the grooming red for '
        + gpEsc(r.employee_name) + '">Undo</button>';
    }
    h += '<div class="gm-msg ' + (m.has_login === false && m.mine ? "warn" : "ok") + '">' + line + "</div>";
    return h + "</div>";
  }
  if (r.can_mark) {
    h += '<button class="btn btn-outline gm-btn" onclick="gmOpenToday(' + i + ')" aria-label="Mark a grooming red for '
      + gpEsc(r.employee_name) + '">Grooming red</button>';
    if (gmState.flash[r.employee]) h += '<div class="gm-msg">' + gpEsc(gmState.flash[r.employee]) + "</div>";
    return h + "</div>";
  }
  /* Contract staff read as a quiet line; every other refusal is a message. */
  if (r.why_code === "R4") return h + '<div class="gm-sub gm-full">' + gpEsc(r.why_not) + "</div></div>";
  /* v3 Z11: the limit row stays neutral - nothing is wrong with the person's day. */
  h += '<div class="gm-msg">' + gpEsc(r.why_not || "") + "</div>";
  /* At the limit: "Raise it with HR" (brief, Decisions (3)). It asks HR for a
     conversation and never adds a mark or a fine. */
  if (r.raise && r.raise.can) {
    h += '<button class="btn btn-outline gm-btn" onclick="gmOpenRaise(' + i + ')" aria-label="'
      + gpEsc(GM_WORDS.raiseSpoken(r.employee_name)) + '">' + gpEsc(GM_WORDS.raiseBtn) + "</button>";
  } else if (r.raise && r.raise.raised_on) {
    /* v3 Z8: the stop alone above, then when it was raised and what happens
       next; Z9: this line takes the focus after a raise. */
    h += '<div class="gm-msg" id="gm-raised-' + gpEsc(r.employee) + '" role="status" tabindex="-1">'
      + gpEsc(GM_WORDS.raisedOn(r.raise.raised_on, r.first, r.has_login, r.raise.reviewed_on)) + "</div>";
  }
  return h + "</div>";
}

window.gmOpenRaise = function (i) {
  var r = gmState.today.rows[i];
  gmOpen({kind: "raise", employee: r.employee, name: r.employee_name, first: r.first,
          login: r.has_login, from: "today"});
};

window.gmOpenToday = function (i) {
  var r = gmState.today.rows[i];
  gmOpen({kind: "mark", employee: r.employee, name: r.employee_name, first: r.first,
          tick: r.needs_told_tick, hr: false, day: "today", from: "today"});
};

window.gmUndo = async function (i) {
  var r = gmState.today.rows[i];
  try {
    await gpFetch(GM + "undo", {name: r.mark.name});
    gmState.flash[r.employee] = "Grooming red removed. " + r.first
      + (r.mark.has_login ? " has been told." : " has no login, so tell them it was removed.");
    await gmToday();
    var b = document.querySelector("#gm-row-" + i + " button");
    if (b) b.focus();
  } catch (e) {
    if (gmIsNet(e)) { alert("Could not undo the grooming red. Nothing changed. Check your connection and try again."); return; }
    /* Past midnight the server says no: the undo window has closed. */
    r.mark.locked = true;
    gmPaintToday();
  }
};

/* ── the month: tag, tile, box and the review line ─────────────────── */

function gmData() { return (acState.data || {}).grooming || null; }

function gmTag(x) {
  var g = gmData();
  return (g && g.days[x.date] && g.days[x.date].mark)
    ? '<span class="ac-tag warn gm-tag">Grooming red</span>' : "";
}

function gmTile() {
  var g = gmData();
  if (!g || !g.tile) return "";
  var t = g.tile;
  return '<div class="ac-tile warn gm-tile"><div class="n">' + t.n + ' <small>· '
    + gpEsc(t.amount) + (t.capped ? ", the legal limit" : "") + '</small></div><div class="l">'
    + "Grooming red · off " + gpEsc(t.month) + " pay</div></div>";
}

function gmRateWords(g) {
  return g.grade ? " (the " + gpEsc(g.grade) + " rate)" : "";
}

function gmBox(x) {
  var g = gmData();
  if (!g) return "";
  var day = g.days[x.date] || {};
  var m = day.mark;
  var first = gmName(g.first);
  var flash = gmState.dayFlash[x.date]
    ? '<p role="status">' + gpEsc(gmState.dayFlash[x.date]) + "</p>" : "";
  var h = '<div class="gm-box' + (m ? " on" : "") + '"><h3>Grooming red</h3>' + flash;

  if (!m) {
    if (g.viewer === "hr") {
      if (day.can_mark) {
        if (!g.has_manager) h += "<p>" + first + " has no reporting manager in Alvora, so only HR can mark "
          + first + "’s days.</p>";
        h += "<p>No grooming red on this day.</p>";
        return h + '<div class="gm-acts"><button class="btn btn-outline gm-btn" onclick="gmOpenDay(&quot;'
          + x.date + '&quot;)" aria-label="Mark a grooming red for ' + gpEsc(g.name) + '">Mark grooming red</button></div></div>';
      }
      if (!day.why_not) return flash ? h + "</div>" : "";
      if (day.why_code === "R7" || day.why_code === "R12" || day.why_code === "R10")
        h += "<p>No grooming red on this day.</p>";
      return h + "<p>" + gpEsc(day.why_not) + "</p></div>";
    }
    if (day.removed || flash) return h + "<p>No grooming red on this day.</p></div>";
    return "";
  }

  h += '<p><span class="ac-tag warn gm-tag">Grooming red</span> ' + gpEsc(m.reason) + ".</p>";
  if (g.viewer === "self") {
    h += "<p>Marked by " + gpEsc(m.by) + (m.marked_as === "HR" ? " (HR)" : ", your manager,")
      + " on " + gpEsc(m.on) + " at " + gpEsc(m.at) + ".</p>";
    if (g.tile && g.tile.capped) {
      h += "<p>A grooming red costs " + gpEsc(g.rate_words) + " a day" + gmRateWords(g) + ". You have "
        + g.tile.n + " this month, which would be " + gpEsc(g.tile.would_be) + ". The law limits fines "
        + "to 3% of your wages, so <b>" + gpEsc(g.tile.amount) + "</b> comes off your "
        + gpEsc(g.tile.month) + " pay.</p>";
    } else {
      h += "<p>This takes <b>" + gpEsc(g.rate_words) + "</b> off your " + gpEsc((g.tile || {}).month || "")
        + " pay" + gmRateWords(g) + ".</p>";
    }
    if (m.kept_by) h += "<p>HR (" + gpEsc(m.kept_by) + ") checked this on " + gpEsc(m.kept_on) + " and kept it.</p>";
    else if (m.asked_on) h += '<p role="status">You asked HR to look at this on ' + gpEsc(m.asked_on)
      + ". HR will decide, and you will be told on the bell.</p>";
    if (m.can_ask) h += '<div class="gm-acts"><button class="btn btn-outline gm-btn" onclick="gmOpenAsk(&quot;'
      + x.date + '&quot;)">Ask HR to look at this</button></div>';
    return h + "</div>";
  }
  if (g.viewer === "hr") {
    h += "<p>Marked by " + (m.by_me ? "you" : gpEsc(m.by)) + " (" + (m.marked_as === "HR" ? "HR" : "manager")
      + ") on " + gpEsc(m.on) + " at " + gpEsc(m.at) + ".</p>";
    if (m.asked_on && !m.kept_by) h += '<p class="gm-msg warn">' + first + " asked HR to look at this on "
      + gpEsc(m.asked_on) + ".</p>";
    if (m.kept_by) h += "<p>" + (m.kept_by_me ? "You" : gpEsc(m.kept_by)) + " checked it on " + gpEsc(m.kept_on)
      + " and kept it. " + first + " has been told.</p>";
    var acts = "";
    if (m.can_remove) acts += '<button class="btn btn-outline gm-btn" onclick="gmOpenRemove(&quot;' + x.date
      + '&quot;)">Remove this mark</button>';
    if (m.can_keep) acts += '<button class="btn btn-outline gm-btn" onclick="gmOpenKeep(&quot;' + x.date
      + '&quot;)">Keep it and tell ' + first + "</button>";
    if (!m.can_remove && g.closed_month) h += "<p>" + first + "’s pay slip for " + gpEsc(g.closed_month)
      + " is submitted, so grooming reds for " + gpEsc(g.closed_month) + " are closed. They cannot be added or removed now.</p>";
    return h + (acts ? '<div class="gm-acts">' + acts + "</div>" : "") + "</div>";
  }
  /* A manager, or somebody who marked: their own marks, and today's. Never money. */
  if (m.by_me) {
    h += "<p>Marked by you on " + gpEsc(m.on) + " at " + gpEsc(m.at) + ". " + (g.has_login
      ? first + " has been told."
      : first + " has no login and will not get a notice. You confirmed you told them in person.")
      + (m.can_undo ? " You can undo this until midnight." : "") + "</p>";
    if (m.can_undo) h += '<div class="gm-acts"><button class="btn btn-outline gm-btn" onclick="gmUndoDay(&quot;'
      + x.date + '&quot;)">Undo</button></div>';
  } else {
    h += "<p>Marked by " + gpEsc(m.by) + (m.marked_as === "HR" ? " (HR)" : "") + " at " + gpEsc(m.at)
      + ". Only HR can remove it.</p>";
  }
  return h + "</div>";
}

/* The review line, at the top of the month (US-14, US-15). */
function gmReview() {
  var g = gmData();
  if (!g || !g.review || !g.review.length) return "";
  var first = gmName(g.first);
  return g.review.map(function (r, i) {
    var h = '<section class="gm-flag" aria-labelledby="gm-rv-' + i + '">';
    if (gmState.reviewFlash && !r.carried) h += '<p role="status"><b>' + gpEsc(gmState.reviewFlash) + "</b></p>";
    var month = gpEsc(r.month);
    if (r.state === "pending") {
      h += '<h2 id="gm-rv-' + i + '">Grooming review pending' + (r.carried ? " (" + month + ")" : "") + "</h2>";
      if (r.why === "raised") {
        if (g.viewer === "self") {
          h += "<p>" + gpEsc(GM_WORDS.employeeLine(r.raise_by)) + "</p>";
        } else if (g.viewer === "hr") {
          h += "<p>" + gpEsc(GM_WORDS.hrLine(r.raise_by, r.raise_on, r.raise_reason))
            + "</p><p>Talk to " + first + " about dress, agree an action, then record it here.</p>"
            + '<div class="gm-acts"><button class="btn btn-primary gm-btn" onclick="gmOpenReview(' + i
            + ')" aria-label="Record the grooming review for ' + gpEsc(g.name) + '">Record the review</button></div>';
        } else {
          h += "<p>" + gpEsc(GM_WORDS.managerLine(r.raise_by_me ? "You" : r.raise_by, r.raise_on, g.first)) + "</p>";
        }
        return h + "</section>";
      }
      if (g.viewer === "self") {
        h += (r.why === "max"
          ? "<p>You have " + r.live + " grooming reds in " + month + ", the most allowed in a month, so HR will talk to you about it.</p>"
          : "<p>You have " + r.live + " grooming red" + (r.live === 1 ? "" : "s") + " in " + month + " ("
            + gpEsc(r.amount) + "). One more would pass the legal limit of " + gpEsc(r.limit)
            + " (3% of your wages), so no more can be marked this month. HR will talk to you about it.</p>")
          + "<p>The review does not change your fines.</p>";
      } else if (g.viewer === "hr") {
        h += "<p>Raised on " + gpEsc(r.raised_on) + ": " + first + (r.why === "max"
          ? " reached 3 grooming reds in " + month + ", the most allowed in a month."
          : " reached the legal limit for grooming reds in " + month + " (" + r.live + " mark"
            + (r.live === 1 ? "" : "s") + "; limit " + gpEsc(r.limit) + " = 3% of Basic " + gpEsc(r.base) + ").")
          + "</p><p>Talk to " + first + " about dress, agree an action, then record it here.</p>"
          + '<div class="gm-acts"><button class="btn btn-primary gm-btn" onclick="gmOpenReview(' + i
          + ')" aria-label="Record the grooming review for ' + gpEsc(g.name) + '">Record the review</button></div>';
      } else {
        h += "<p>" + first + (r.why === "max"
          ? " has had " + r.live + " grooming reds in " + month + ", the most allowed"
          : " has reached the most grooming reds the law allows in " + month)
          + ", so HR will talk to " + first + " about it. You do not need to do anything.</p>";
      }
      return h + "</section>";
    }
    if (g.viewer === "manager" && r.note) {
      /* Prototype v2: the direct manager reads HR's note; the person does not. */
      return h + '<h2 id="gm-rv-' + i + '">Grooming review recorded</h2><p>Recorded by ' + gpEsc(r.by)
        + " (HR) on " + gpEsc(r.on) + ".</p><blockquote>" + gpEsc(r.note) + "</blockquote>"
        + '<p class="gm-muted">Only HR and you, as ' + first + "’s manager, can read this. " + first
        + " sees only “Action agreed on " + gpEsc(r.on) + "”.</p></section>";
    }
    if (g.viewer !== "hr") {
      return h + '<h2 id="gm-rv-' + i + '">Grooming review</h2><p>Action agreed on ' + gpEsc(r.on) + ".</p></section>";
    }
    h += '<h2 id="gm-rv-' + i + '">Grooming review recorded</h2><p>'
      + (r.by_me ? "Recorded by you" : "Recorded by " + gpEsc(r.by) + " (HR)") + " on " + gpEsc(r.on) + ".</p>"
      + "<blockquote>" + gpEsc(r.note || "") + "</blockquote>"
      + "<p>" + gpEsc(r.after_raise ? GM_WORDS.noMoreReviews(g.first, r.month)
                                    : GM_WORDS.managerMayRaise(g.first, r.month)) + "</p>"
      + '<p class="gm-muted">This note cannot be changed or deleted. Only HR and ' + first
      + "’s manager can read it. " + first + " sees only “Action agreed on " + gpEsc(r.on) + "”.</p>";
    return h + "</section>";
  }).join("");
}

window.gmOpenDay = function (date) {
  var g = gmData();
  gmOpen({kind: "mark", employee: acState.data.employee, name: g.name, first: g.first,
          tick: (g.days[date] || {}).needs_told_tick, hr: true, date: date,
          day: "on " + gmDayWords(date), from: "month"});
};
window.gmOpenRemove = function (date) {
  var g = gmData();
  gmOpen({kind: "remove", mark: g.days[date].mark.name, first: g.first, login: g.has_login,
          date: date, from: "month"});
};
window.gmOpenKeep = function (date) {
  var g = gmData();
  gmOpen({kind: "keep", mark: g.days[date].mark.name, first: g.first, date: date,
          rate: g.rate_words, month: (g.tile || {}).month || g.month_name, from: "month"});
};
window.gmOpenAsk = function (date) {
  gmOpen({kind: "ask", mark: gmData().days[date].mark.name, date: date, from: "month"});
};
window.gmOpenReview = function (i) {
  var g = gmData(), r = g.review[i];
  gmOpen({kind: "review", employee: acState.data.employee, name: g.name, first: g.first,
          month: r.month_start, from: "month"});
};

window.gmUndoDay = async function (date) {
  var g = gmData();
  try {
    await gpFetch(GM + "undo", {name: g.days[date].mark.name});
    gmState.dayFlash[date] = "Grooming red removed. " + g.first
      + (g.has_login ? " has been told." : " has no login, so tell them it was removed.");
  } catch (e) {
    alert(gmIsNet(e) ? "Could not undo the grooming red. Nothing changed. Check your connection and try again."
                     : (e.message || "Could not undo the grooming red."));
  }
  await gmReloadMonth();
};

/* "Wed 21 Oct", from the day's own date - never the browser's time zone. */
function gmDayWords(iso) {
  var p = String(iso).split("-");
  var d = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2]));
  var days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  var mons = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return days[d.getUTCDay()] + " " + (+p[2]) + " " + mons[+p[1] - 1];
}

async function gmReloadMonth() {
  try {
    acState.data = await acApi("month", {year: acState.year, month: acState.month,
                                         employee: acState.employee});
  } catch (e) { /* the page keeps what it had; the next load corrects it */ }
  acPaint();
  /* Said once, where the action was taken; the next repaint is quiet. */
  gmState.dayFlash = {};
  gmState.reviewFlash = null;
}

/* ── the sheets: bottom sheet on a phone, dialog on a desk ───────────── */

function gmTodayIso() {
  var d = new Date();
  return d.getFullYear() + "-" + ("0" + (d.getMonth() + 1)).slice(-2) + "-" + ("0" + d.getDate()).slice(-2);
}

function gmOpen(sheet) {
  gmState.flash = {};
  gmState.last = document.activeElement;
  gmState.sheet = sheet;
  gmPaintSheet(false);
}

window.gmClose = function () {
  gmState.sheet = null;
  var host = document.getElementById("gm-sheet-host");
  if (host) host.innerHTML = "";
  if (gmState.last && document.body.contains(gmState.last)) gmState.last.focus();
};

function gmPaintSheet(keepFocus) {
  var s = gmState.sheet;
  var host = document.getElementById("gm-sheet-host");
  if (!host) {
    host = document.createElement("div");
    host.id = "gm-sheet-host";
    document.body.appendChild(host);
  }
  if (!s) { host.innerHTML = ""; return; }
  var first = gmName(s.first);
  /* The portal's own dialog shell (.gp-backdrop.open + .gp-modal), as the
     leave sheet builds it; .gm-* only adds the phone bottom sheet. */
  var h = '<div class="gp-backdrop open gm-bd" onclick="if(event.target===this)gmClose()"><div class="gp-modal gm-sheet" role="dialog"'
    + ' aria-modal="true" aria-labelledby="gm-sh-t" onkeydown="if(event.key===&quot;Escape&quot;)gmClose()">';
  var go, no = "Cancel";
  if (s.kind === "mark") {
    h += '<h2 id="gm-sh-t" tabindex="-1">Grooming red for ' + gpEsc(s.name) + " " + gpEsc(s.day) + "?</h2>"
      + '<p class="gm-help" id="gm-sh-help">' + gpEsc(GM_WORDS.sheetHelp) + "</p>"
      + '<div role="radiogroup" aria-labelledby="gm-sh-t" aria-describedby="gm-sh-help">'
      + (gmState.today && gmState.today.reasons || GM_REASONS).map(function (r) {
          var on = s.chosen === r;
          return '<label class="gm-opt' + (on ? " sel" : "") + '"><input type="radio" name="gm-r" value="'
            + gpEsc(r) + '"' + (on ? " checked" : "") + ' onchange="gmPick(this.value)"> ' + gpEsc(r) + "</label>";
        }).join("") + "</div>";
    if (s.chosen === "Other") {
      h += '<label class="gm-fld" for="gm-other">' + gpEsc(GM_WORDS.otherLabel) + "</label>"
        + '<p class="gm-help" id="gm-other-help">' + gpEsc(GM_WORDS.otherHint) + "</p>"
        + '<input type="text" id="gm-other" class="gm-other" maxlength="' + GM_WORDS.otherMax + '" autocomplete="off"'
        + ' aria-describedby="gm-other-help gm-other-count" value="' + gpEsc(s.other || "") + '"'
        + ' oninput="gmOther(this.value)">'
        + '<p class="gm-counter" id="gm-other-count">' + gpEsc(GM_WORDS.otherCount((s.other || "").length)) + "</p>";
    }
    if (s.tick) {
      h += '<div class="gm-info">' + first + (s.hr
          ? " has no login and will not get a notice from the app. Tell " + first + " in person, with the reason, before you mark it."
          : " has no login and will not get a notice from the app. Tell them today, and tell them they can speak to HR.")
        + "</div>"
        + '<label class="gm-opt' + (s.told ? " sel" : "") + '"><input type="checkbox"' + (s.told ? " checked" : "")
        + ' onchange="gmTold(this.checked)"> I have told ' + first + (s.hr ? " in person" : " in person today") + "</label>";
    } else {
      h += '<div class="gm-info">' + (s.chosen === "Other"
          ? gpEsc(GM_WORDS.otherInfo(s.first, s.hr))
          : first + " will be told now, with your name and this reason."
            + (s.hr ? " You are marking as HR." : " You can undo this until midnight.")) + "</div>";
    }
    go = "Mark grooming red";
  } else if (s.kind === "remove") {
    h += '<h2 id="gm-sh-t" tabindex="-1">Remove this grooming red?</h2><p class="gm-help" id="gm-sh-help">'
      + 'Why are you removing it?</p><div role="radiogroup" aria-labelledby="gm-sh-help">'
      + GM_REMOVE.map(function (r) {
          var on = s.chosen === r;
          return '<label class="gm-opt' + (on ? " sel" : "") + '"><input type="radio" name="gm-w" value="'
            + gpEsc(r) + '"' + (on ? " checked" : "") + ' onchange="gmPick(this.value)"> ' + gpEsc(r) + "</label>";
        }).join("") + '</div><div class="gm-info">' + first
      + (s.login ? " will be told it was removed, by you, and why." : " has no login, so tell them it was removed, by you, and why.")
      + " The person who marked it will see it is gone. A record of the mark and of its removal is kept.</div>";
    go = "Remove it";
    no = "Keep the mark";
  } else if (s.kind === "raise") {
    h += '<h2 id="gm-sh-t" tabindex="-1">' + gpEsc(GM_WORDS.raiseTitle(s.name)) + "</h2>"
      + '<p class="gm-help" id="gm-sh-help">' + gpEsc(GM_WORDS.raiseHelp) + "</p>"
      + '<div role="radiogroup" aria-labelledby="gm-sh-t" aria-describedby="gm-sh-help">'
      + ((gmState.today && gmState.today.raise_reasons) || GM_REASONS.slice(0, 4)).map(function (r) {
          var on = s.chosen === r;
          return '<label class="gm-opt' + (on ? " sel" : "") + '"><input type="radio" name="gm-x" value="'
            + gpEsc(r) + '"' + (on ? " checked" : "") + ' onchange="gmPick(this.value)"> ' + gpEsc(r) + "</label>";
        }).join("") + "</div>"
      + '<div class="gm-info">' + gpEsc(GM_WORDS.raiseInfo(s.first, s.login !== false)) + "</div>";
    go = GM_WORDS.raiseBtn;
  } else if (s.kind === "keep") {
    h += '<h2 id="gm-sh-t" tabindex="-1">Keep the grooming red?</h2><div class="gm-info">' + first
      + " will be told that HR has checked it and the mark stays. " + gpEsc(s.rate || "") + " still comes off "
      + first + "’s " + gpEsc(s.month || "") + " pay.</div>";
    go = "Keep it and tell " + (s.first || "");
  } else if (s.kind === "ask") {
    h += '<h2 id="gm-sh-t" tabindex="-1">Ask HR to look at this grooming red?</h2><div class="gm-info">'
      + "HR will see your request and decide. You will be told on the bell. Until then the mark stays.</div>";
    go = "Send to HR";
  } else if (s.kind === "review") {
    h += '<h2 id="gm-sh-t" tabindex="-1">Record the grooming review for ' + gpEsc(s.name) + "</h2>"
      + '<label class="gm-fld" for="gm-rv-text">What you talked about and the action plan</label>'
      + '<p class="gm-help" id="gm-rv-help">Keep it to dress and the action you agreed. Do not write about '
      + "health, family, religion or anything else personal.</p>"
      + '<textarea id="gm-rv-text" aria-describedby="gm-rv-help gm-rv-info" oninput="gmText(this.value)">'
      + gpEsc(s.text || "") + "</textarea>"
      + '<div class="gm-info" id="gm-rv-info">Only HR and ' + first + "’s manager can read this. " + first
      + " sees only “Action agreed on " + gpEsc(gmDayWords(gmTodayIso())) + "”. You cannot change or delete it after "
      + "saving. It clears the review. It does not remove any grooming red or change any fine.</div>";
    go = "Save and clear";
  }
  if (s.error) h += '<p class="gm-err" role="alert">' + gpEsc(s.error) + "</p>";
  if (s.failed) go = "Try again";
  h += '<div class="gm-acts"><button class="btn btn-primary gm-btn" onclick="gmConfirm()"' + (s.busy ? " disabled" : "")
    + ">" + (s.busy ? "Saving…" : gpEsc(go)) + '</button><button class="btn btn-outline gm-btn" onclick="gmClose()">'
    + gpEsc(no) + "</button></div></div></div>";
  host.innerHTML = h;
  if (!keepFocus) { var t = document.getElementById("gm-sh-t"); if (t) t.focus(); }
}

var GM_REASONS = ["Not in uniform", "Uniform incomplete", "No name badge", "Wrong footwear", "Other"];

/* "Raise it with HR": every word in one place, so prototype v3 changes one
   table. The brief gave the warning, the employee's line, HR's line and
   "Raised with HR on..."; the sheet's heading, help and info are the
   engineer's until v3 is drawn. (The server's own copies - the warning and
   the bells - are in grooming.py.) */
var GM_WORDS = {
  // "Other" (D-6; v3 Z1-Z4)
  sheetHelp: "Choose the one reason that fits. Choose Other only if none fits.",
  otherLabel: "What was wrong",
  otherHint: "Clothing or grooming only. Nothing about health or family.",
  otherMax: 100,
  otherCount: function (n) { return n + " of 100 characters"; },
  otherBlank: "Write what was wrong first.",
  otherInfo: function (n, hr) {
    return n + " will be told now, with your name. Your words stay on the day, not in the notice."
      + (hr ? " You are marking as HR." : " You can undo this until midnight.");
  },
  // "Raise it with HR" (D-7; v3 Z7-Z12)
  raiseBtn: "Raise it with HR",
  raiseSpoken: function (name) { return "Raise " + name + "\’s grooming with HR"; },
  raiseTitle: function (name) { return "Raise " + name + "\’s grooming with HR?"; },
  raiseHelp: "Choose the one reason that fits. You cannot add your own words.",
  raiseInfo: function (first, login) {
    return "HR will be told and will talk to " + first + ". "
      + (login ? first + " will be told you raised it." : first + " has no login, so HR will tell " + first + ".")
      + " This adds no fine and no grooming red.";
  },
  raisedOn: function (on, first, login, reviewed) {
    return "Raised with HR on " + on + ". " + (reviewed ? "HR recorded a review on " + reviewed + "."
      : login ? "HR will talk to " + first + "." : first + " has no login, so HR will tell " + first + ".");
  },
  raiseFailed: "Could not raise it. Nothing was sent. Check your connection and try again.",
  employeeLine: function (by) { return by + ", your manager, has asked HR to talk to you about grooming. This adds no fine."; },
  managerLine: function (who, on, first) {
    return who + " raised it with HR on " + on + ". HR will talk to " + first + ". You do not need to do anything.";
  },
  hrLine: function (by, on, reason) { return by + " raised it with HR on " + on + ": " + (reason || "") + "."; },
  // After a review (v3 Z16: true under the raise rule)
  noMoreReviews: function (first, month) {
    return "The grooming reds this month still stand. The review will not be raised again for " + first + " in " + month + ".";
  },
  managerMayRaise: function (first, month) {
    return "The grooming reds this month still stand. More grooming reds in " + month + " will not raise it again. "
      + first + "\’s manager can still raise it with HR once this month.";
  }
};

window.gmPick = function (v) { gmState.sheet.chosen = v; gmState.sheet.error = null; gmPaintSheet(true); };
window.gmTold = function (v) { gmState.sheet.told = v; gmState.sheet.error = null; gmPaintSheet(true); };
window.gmText = function (v) { gmState.sheet.text = v; };
window.gmOther = function (v) {
  gmState.sheet.other = v;
  var c = document.getElementById("gm-other-count");
  if (c) c.textContent = GM_WORDS.otherCount(String(v || "").length);
};

window.gmConfirm = async function () {
  var s = gmState.sheet;
  if (!s || s.busy) return;
  if ((s.kind === "mark" || s.kind === "remove" || s.kind === "raise") && !s.chosen) {
    /* Only the remove sheet asks "why"; the mark and raise sheets ask for a reason. */
    s.error = s.kind === "remove" ? "Choose why you are removing it." : "Choose a reason first.";
    gmPaintSheet(true);
    var r = document.querySelector('.gm-sheet input[type="radio"]');
    if (r) r.focus();
    return;
  }
  if (s.kind === "mark" && s.chosen === "Other" && !(s.other || "").trim()) {
    s.error = GM_WORDS.otherBlank;
    gmPaintSheet(true);
    var o = document.getElementById("gm-other");
    if (o) o.focus();
    return;
  }
  if (s.kind === "review" && !(s.text || "").trim()) {
    s.error = "Write what you talked about and the action plan first.";
    gmPaintSheet(true);
    var ta = document.getElementById("gm-rv-text");
    if (ta) ta.focus();
    return;
  }
  if (s.kind === "mark" && s.tick && !s.told) {
    s.error = "Tick the box to confirm you told " + s.first + " in person.";
    gmPaintSheet(true);
    var c = document.querySelector('.gm-sheet input[type="checkbox"]');
    if (c) c.focus();
    return;
  }
  s.busy = true; s.error = null;
  gmPaintSheet(true);
  var call, args;
  if (s.kind === "mark") {
    call = "mark";
    args = {employee: s.employee, reason: s.chosen, told_in_person: s.told ? 1 : 0, date: s.date || null,
            other_reason: s.chosen === "Other" ? (s.other || "") : null};
  } else if (s.kind === "remove") { call = "remove"; args = {name: s.mark, reason: s.chosen}; }
  else if (s.kind === "keep") { call = "keep"; args = {name: s.mark}; }
  else if (s.kind === "raise") { call = "raise_with_hr"; args = {employee: s.employee, reason: s.chosen}; }
  else if (s.kind === "ask") { call = "ask"; args = {name: s.mark}; }
  else { call = "record_review"; args = {employee: s.employee, month: s.month, note: s.text}; }
  try {
    await gpFetch(GM + call, args);
  } catch (e) {
    s.busy = false;
    if (gmIsNet(e)) {
      s.failed = true;
      s.error = s.kind === "mark"
        ? "Could not save the grooming red. Nothing was saved. Check your connection and try again."
        : s.kind === "remove"
          ? "Could not remove the mark. Nothing changed. Check your connection and try again."
          : s.kind === "raise" ? GM_WORDS.raiseFailed
            : "Could not save that. Nothing changed. Check your connection and try again.";
    } else {
      s.error = e.message;
    }
    gmPaintSheet(true);
    return;
  }
  gmState.sheet = null;
  gmPaintSheet(true);
  if (s.from === "today") {
    await gmToday();
    if (s.kind === "raise") {
      var line = document.getElementById("gm-raised-" + s.employee);
      if (line) { line.focus(); return; }
    }
  } else {
    if (s.kind === "mark") {
      gmState.dayFlash[s.date] = s.tick
        ? "Saved. " + s.first + " has no login and will not get a notice. You confirmed you told them in person."
        : s.chosen === "Other" ? "Saved. " + s.first + " has been told, with your name."
          : "Saved. " + s.first + " has been told, with your name and the reason.";
    } else if (s.kind === "remove") {
      gmState.dayFlash[s.date] = s.login
        ? "Removed. " + s.first + " has been told it was removed, by you: " + s.chosen + "."
        : "Removed. " + s.first + " has no login, so tell them it was removed, by you: " + s.chosen + ".";
    } else if (s.kind === "review") {
      gmState.reviewFlash = "Review recorded. The grooming reds this month still stand.";
    }
    await gmReloadMonth();
  }
  if (gmState.last && document.body.contains(gmState.last)) gmState.last.focus();
};

/* ── The team's days, worst first ────────────────────────────────────────
   Surbhi, 17 Oct 2026: "we would need one page with filter for all the
   reporting persons first", and "only attendance facts" - not pay
   consequences. So nothing here shows money, and a test asserts it stays
   that way.

   REACHED FROM THE ATTENDANCE PAGE'S OWN PICKER, as "Whole team". It was a
   third tab on Team View for one day. Checking one person's month and
   checking the team's are the same job, and they were behind two different
   doors - which is the duplication the 17 Oct consolidation removed.

   THE SERVER DECIDES WHO MAY BE SEEN AND ACTED ON. `can_raise` comes back
   per row, because acting stops at the direct reports while the whole line
   may be viewed - so the button is simply absent where it would refuse.
   This screen never works the reporting line out for itself. */
var trState = {
  from: null, to: null, employee: "", only: "", depth: "direct",
  department: "", branch: "", group: "person", start: 0, size: 50,
  data: null, open: null
};

/* The server's flags, in words, with how loudly to say them. Worst first,
   the same order the server sorts by. */
var TR_FLAGS = [
  ["no_clock_out", "No clock-out", "bad"],
  ["absent_not_counted", "Absent: check-out not counted", "bad"],
  ["absent_short", "Absent: too few hours", "bad"],
  ["absent", "Absent", "warn"],
  ["short", "Short hours", "warn"],
  ["ok", "Fine", "ok"]
];

/* The server refuses in words worth showing - "nobody reports to you", a
   period longer than three months, "does not report directly to you". Note
   `gpErr` is private to a closure further down this file, so it cannot be
   used here: calling it would throw a ReferenceError at the exact moment
   something had already gone wrong. */
function trErr(e) {
  return (e && e.message) ? e.message : "Could not load that.";
}

function trFlag(key) {
  for (var i = 0; i < TR_FLAGS.length; i++) {
    if (TR_FLAGS[i][0] === key) return TR_FLAGS[i];
  }
  return [key, key, "warn"];
}

function trDaysAgo(n) {
  var d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().slice(0, 10);
}

window.trOpen = async function () {
  if (!trState.from) {
    /* A fortnight. Long enough to catch last week's missing clock-out,
       short enough that the first screen is not a wall. */
    trState.to = trDaysAgo(0);
    trState.from = trDaysAgo(13);
  }
  if (!acState.reasons) {
    try { acState.reasons = await acApi("reasons"); } catch (e) { acState.reasons = []; }
  }
  gmToday();
  trLoad();
};

window.trLoad = async function () {
  var body = document.getElementById("tr-body");
  if (body) body.innerHTML = '<p class="ac-empty">Loading&hellip;</p>';
  try {
    trState.data = await acApi("team_days", {
      from_date: trState.from,
      to_date: trState.to,
      employee: trState.employee || null,
      only: trState.only || null,
      depth: trState.depth,
      department: trState.department || null,
      branch: trState.branch || null,
      start: trState.start,
      page_length: trState.size
    });
  } catch (e) {
    /* The server refuses in words - "nobody reports to you", a period too
       long - so show what it said rather than a generic failure. */
    if (body) body.innerHTML = '<p class="ac-empty">' + gpEsc(trErr(e)) + "</p>";
    trBar();
    return;
  }
  trBar();
  trChips();
  trRows();
  trPager();
};

/* ── the filters ──────────────────────────────────────────────────────── */

function trPicks(values, chosen, blank) {
  return '<option value="">' + gpEsc(blank) + "</option>"
    + values.filter(Boolean).map(function (v) {
        return '<option value="' + gpEsc(v) + '"'
          + (String(v) === String(chosen) ? " selected" : "") + ">"
          + gpEsc(v) + "</option>";
      }).join("");
}

function trBar() {
  var bar = document.getElementById("tr-bar");
  if (!bar) return;
  var d = trState.data || {};
  var people = d.people || [];
  var depts = [], branches = [];
  people.forEach(function (p) {
    if (p.department && depts.indexOf(p.department) < 0) depts.push(p.department);
    if (p.branch && branches.indexOf(p.branch) < 0) branches.push(p.branch);
  });
  depts.sort();
  branches.sort();

  var html = '<label class="tr-f"><span>From</span>'
    + '<input type="date" class="form-control" value="' + gpEsc(trState.from || "")
    + '" onchange="trSet(&quot;from&quot;,this.value)"></label>'
    + '<label class="tr-f"><span>To</span>'
    + '<input type="date" class="form-control" value="' + gpEsc(trState.to || "")
    + '" onchange="trSet(&quot;to&quot;,this.value)"></label>'
    + '<label class="tr-f"><span>Person</span>'
    + '<select class="form-control" onchange="trSet(&quot;employee&quot;,this.value)">'
    + '<option value="">Everyone</option>'
    + people.map(function (p) {
        return '<option value="' + gpEsc(p.name) + '"'
          + (p.name === trState.employee ? " selected" : "") + ">"
          + gpEsc(p.employee_name || p.name) + "</option>";
      }).join("")
    + "</select></label>";

  /* Offered only where there is a choice to make. One department is not a
     filter, it is a control that does nothing. */
  if (depts.length > 1) {
    html += '<label class="tr-f"><span>Department</span>'
      + '<select class="form-control" onchange="trSet(&quot;department&quot;,this.value)">'
      + trPicks(depts, trState.department, "All") + "</select></label>";
  }
  if (branches.length > 1) {
    html += '<label class="tr-f"><span>Branch</span>'
      + '<select class="form-control" onchange="trSet(&quot;branch&quot;,this.value)">'
      + trPicks(branches, trState.branch, "All") + "</select></label>";
  }

  html += '<label class="tr-f"><span>Group by</span>'
    + '<select class="form-control" onchange="trSet(&quot;group&quot;,this.value)">'
    + '<option value="person"' + (trState.group === "person" ? " selected" : "")
    + ">Person</option>"
    + '<option value="date"' + (trState.group === "date" ? " selected" : "")
    + ">Date</option></select></label>";

  /* HR already sees everybody, so depth changes nothing for them. */
  if (!d.everybody) {
    html += '<label class="tr-f"><span>Show</span>'
      + '<select class="form-control" onchange="trSet(&quot;depth&quot;,this.value)">'
      + '<option value="direct"' + (trState.depth === "direct" ? " selected" : "")
      + ">My direct reports</option>"
      + '<option value="all"' + (trState.depth === "all" ? " selected" : "")
      + ">Everyone below me</option></select></label>";
  }

  bar.innerHTML = html;
}

window.trSet = function (key, value) {
  trState[key] = value;
  trState.open = null;
  /* Grouping only rearranges what is already here, so it needs no round
     trip. Everything else changes what is being asked for and starts again
     at the first page - keeping the offset would land somebody on an empty
     page three. */
  if (key === "group") { trRows(); return; }
  trState.start = 0;
  trLoad();
};

/* ── the chips ────────────────────────────────────────────────────────── */

function trChips() {
  var el = document.getElementById("tr-chips");
  if (!el) return;
  var counts = (trState.data || {}).counts || {};
  var html = '<span class="tr-chip' + (trState.only ? "" : " on")
    + '" onclick="trSet(&quot;only&quot;,&quot;&quot;)">Everything</span>';
  TR_FLAGS.forEach(function (f) {
    var n = counts[f[0]] || 0;
    if (!n) return;
    html += '<span class="tr-chip ' + f[2] + (trState.only === f[0] ? " on" : "")
      + '" onclick="trSet(&quot;only&quot;,&quot;' + f[0] + '&quot;)">'
      + gpEsc(f[1]) + " <b>" + n + "</b></span>";
  });
  el.innerHTML = html;
}

/* ── the days ─────────────────────────────────────────────────────────── */

function trRows() {
  var body = document.getElementById("tr-body");
  if (!body) return;
  var d = trState.data || {};
  if (d.nobody) {
    body.innerHTML = '<p class="ac-empty">Nobody reports to you, so there is '
      + "nothing to review here.</p>";
    return;
  }
  var rows = d.rows || [];
  if (!rows.length) {
    body.innerHTML = '<p class="ac-empty">'
      + (trState.only
          ? "Nothing in this period needs that."
          : "No attendance recorded for this period.")
      + "</p>";
    return;
  }

  var byPerson = trState.group === "person";
  var groups = [], index = {};
  rows.forEach(function (r) {
    var key = byPerson ? r.employee : r.date;
    if (!(key in index)) {
      index[key] = groups.length;
      groups.push({
        label: byPerson ? (r.employee_name || r.employee) : fmtDate(r.date),
        sub: byPerson
          ? [r.designation, r.department, r.branch].filter(Boolean).join(" · ")
          : "",
        items: []
      });
    }
    groups[index[key]].items.push(r);
  });

  body.innerHTML = groups.map(function (g) {
    return '<div class="tr-group"><div class="tr-group-hdr">'
      + '<span class="tr-group-name">' + gpEsc(g.label) + "</span>"
      + (g.sub ? '<span class="tr-group-sub">' + gpEsc(g.sub) + "</span>" : "")
      /* Grouped by person these are days; grouped by date they are people.
         Saying "1 day" under a date heading reads as nonsense. */
      + '<span class="tr-group-n">' + g.items.length + " "
      + (byPerson ? (g.items.length === 1 ? "day" : "days")
                  : (g.items.length === 1 ? "person" : "people")) + "</span></div>"
      + g.items.map(function (r) { return trDay(r, byPerson); }).join("")
      + "</div>";
  }).join("");
}

function trDay(r, byPerson) {
  var f = trFlag(r.flag);
  /* ALV-211: the shift's own absent threshold, when it sets one. */
  if (r.flag === "absent_short" && r.absent_under) {
    f = [f[0], "Absent: under " + r.absent_under + " hours worked", f[2]];
  }
  var key = r.employee + "|" + r.date;
  var who = byPerson ? fmtDate(r.date) : (r.employee_name || r.employee);
  var bits = [];
  if (r.shift) bits.push(r.shift);
  bits.push(r.hours ? r.hours + "h" : "no hours");
  bits.push(r.punches + (r.punches === 1 ? " punch" : " punches"));
  if (r.late) bits.push("late in");
  if (r.early) bits.push("left early");
  var times = (r.in_time || "--:--") + " – " + (r.out_time || "--:--");

  /* The name is a button, not a bolded label, because clicking it opens that
     person's month at that day - so it has to be reachable by keyboard and
     show its focus. */
  return '<div class="tr-day"><span class="tr-dot ' + f[2] + '"></span>'
    + '<div class="tr-day-main"><div class="tr-day-top">'
    + '<button class="tr-open" onclick="acFromTeam(&quot;' + gpEsc(r.employee)
    + '&quot;,&quot;' + r.date + '&quot;)">' + gpEsc(who) + "</button>"
    + '<span class="tr-status">' + gpEsc(r.status || "") + "</span>"
    + '<span class="tr-need ' + f[2] + '">' + gpEsc(f[1]) + "</span></div>"
    + '<div class="tr-day-sub">' + gpEsc(times) + " · "
    + gpEsc(bits.join(" · ")) + "</div>"
    + (trState.open === key ? trAskForm(r) : "")
    + "</div>"
    /* No button where the server says this is not ours to raise. Acting
       stops at the direct reports, and a button that refuses when pressed
       is worse than no button. */
    + (r.can_raise
        ? '<button class="btn btn-outline btn-sm tr-ask" onclick="trAsk(&quot;'
          + gpEsc(key) + '&quot;)">'
          + (trState.open === key ? "Cancel" : "Ask HR to fix") + "</button>"
        : "")
    + "</div>";
}

window.trAsk = function (key) {
  trState.open = trState.open === key ? null : key;
  trRows();
};

function trAskForm(r) {
  var opts = (acState.reasons || []).map(function (o) {
    return '<option value="' + gpEsc(o.value) + '">' + gpEsc(o.value) + "</option>";
  }).join("");
  return '<div class="ac-form tr-form">'
    + '<label class="form-label">What happened on this day?</label>'
    + '<select id="tr-reason"><option value="">Choose a reason&hellip;</option>'
    + opts + "</select>"
    + '<label class="form-label">Anything HR should know</label>'
    + '<textarea id="tr-explain" placeholder="Say briefly what happened."></textarea>'
    + '<p class="ac-help">HR decides this. Your name goes on the request, so '
    + "they know you are standing behind it.</p>"
    + '<div class="ac-acts"><button class="btn btn-primary" onclick="trSubmit(&quot;'
    + gpEsc(r.employee) + '&quot;,&quot;' + r.date + '&quot;)">Send to HR</button>'
    + "</div></div>";
}

window.trSubmit = async function (employee, date) {
  var reason = (document.getElementById("tr-reason") || {}).value;
  var explain = (document.getElementById("tr-explain") || {}).value;
  if (!reason) { toast("Please choose a reason.", "err"); return; }
  /* One request per press, and nothing incomplete - the same two rules as
     `acSubmit`, for the same reason. */
  if (acSending) return;
  if (!employee || !date) {
    toast("This row has lost track of whose day this is. Reload the page and try again.", "err");
    return;
  }
  acSending = true;
  showLoad();
  try {
    await acApi("raise_for_report", {
      employee: employee, from_date: date, reason: reason, explanation: explain
    });
    toast("Sent to HR. They will confirm or reject it.", "ok");
    trState.open = null;
    await trLoad();
  } catch (e) {
    toast(trErr(e), "err");
  } finally {
    acSending = false;
    hideLoad();
  }
};

/* ── the pager ────────────────────────────────────────────────────────── */

function trPager() {
  var el = document.getElementById("tr-pager");
  if (!el) return;
  var d = trState.data || {};
  var total = d.total || 0;
  var start = d.start || 0;
  if (!total) { el.innerHTML = ""; return; }
  var last = Math.min(start + (d.rows || []).length, total);
  /* The total counts the whole period, not this page, so somebody can tell
     whether they have finished. */
  el.innerHTML = '<span class="tr-count">Showing ' + (start + 1) + "–" + last
    + " of " + total + "</span>"
    + '<button class="btn btn-outline btn-sm" ' + (start <= 0 ? "disabled" : "")
    + ' onclick="trPage(-1)">Previous</button>'
    + '<button class="btn btn-outline btn-sm" ' + (last >= total ? "disabled" : "")
    + ' onclick="trPage(1)">Next</button>';
}

window.trPage = function (direction) {
  var d = trState.data || {};
  var size = d.page_length || trState.size;
  trState.start = Math.max(0, (d.start || 0) + direction * size);
  trState.open = null;
  trLoad();
};

function populateTeamNoteEmpFilter() {
  const sel = document.getElementById("tn-emp");
  if (!sel || sel.options.length > 1) return;
  Object.keys(_teamMemberMap).forEach(function(id) {
    const o = document.createElement("option");
    o.value = id;
    o.textContent = _teamMemberMap[id];
    sel.appendChild(o);
  });
}

function loadTeamNotes() {
  const from = document.getElementById("tn-from").value || "";
  const to   = document.getElementById("tn-to").value   || "";
  const emp  = document.getElementById("tn-emp").value  || "";
  const args = {};
  if (from) args.from_date = from;
  if (to)   args.to_date   = to;
  if (emp)  args.employee_id = emp;
  document.getElementById("tn-list").innerHTML = '<div class="notes-empty">Loading...</div>';
  api("get_manager_notes", args, function(data) {
    if (emp && !args.from_date && !args.to_date) {
      Object.assign(_teamMemberMap, data.employees || {});
    } else {
      Object.assign(_teamMemberMap, data.employees || {});
    }
    populateTeamNoteEmpFilter();
    renderTeamNotesList(data.notes || [], data.employees || {});
  }, function() {
    document.getElementById("tn-list").innerHTML = '<div class="notes-empty">Failed to load notes.</div>';
  });
}

/* ── Adding a note from the Manager Notes tab ──────
   The backend has supported create/update/delete all along; this tab simply
   never offered a way in, so notes could only be written from an individual
   employee's drawer. */

function tnShowAdd() {
  const form = document.getElementById("tn-add-form");
  if (!form) return;
  tnFillEmployeeSelect();
  const d = document.getElementById("tn-new-date");
  if (d && !d.value) d.value = new Date().toISOString().slice(0, 10);
  const err = document.getElementById("tn-new-err");
  if (err) err.classList.remove("show");
  form.style.display = "block";
  // Pre-select whoever the list is already filtered to, so the common case of
  // "reading X's notes, want to add one about X" needs no extra choice.
  const filtered = (document.getElementById("tn-emp") || {}).value || "";
  const sel = document.getElementById("tn-new-emp");
  if (sel && filtered) sel.value = filtered;
  const ta = document.getElementById("tn-new-text");
  if (ta) ta.focus();
}

function tnHideAdd() {
  const form = document.getElementById("tn-add-form");
  if (form) form.style.display = "none";
  const ta = document.getElementById("tn-new-text");
  if (ta) ta.value = "";
}

function tnFillEmployeeSelect() {
  const sel = document.getElementById("tn-new-emp");
  if (!sel) return;
  const ids = Object.keys(_teamMemberMap || {});
  if (!ids.length) {
    sel.innerHTML = '<option value="">No team members found</option>';
    return;
  }
  const keep = sel.value;
  sel.innerHTML = ids
    .sort(function(a, b) { return (_teamMemberMap[a] || "").localeCompare(_teamMemberMap[b] || ""); })
    .map(function(id) {
      return '<option value="' + escHtml(id) + '">' + escHtml(_teamMemberMap[id] || id) + '</option>';
    }).join("");
  if (keep) sel.value = keep;
}

function tnSaveNote() {
  const emp  = (document.getElementById("tn-new-emp")  || {}).value || "";
  const date = (document.getElementById("tn-new-date") || {}).value || "";
  const text = (document.getElementById("tn-new-text") || {}).value || "";
  const err  = document.getElementById("tn-new-err");
  const btn  = document.getElementById("tn-save-btn");

  function fail(msg) {
    if (err) { err.textContent = msg; err.classList.add("show"); }
  }
  if (err) err.classList.remove("show");
  if (!emp)          return fail("Pick which employee this note is about.");
  if (!date)         return fail("A date is required.");
  if (!text.trim())  return fail("The note is empty.");

  if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }
  api("save_manager_note", {employee_id: emp, note_text: text, note_date: date}, function() {
    if (btn) { btn.disabled = false; btn.textContent = "Save Note"; }
    toast("Note saved", "ok");
    tnHideAdd();
    loadTeamNotes();
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
    if (btn) { btn.disabled = false; btn.textContent = "Save Note"; }
    fail((e && e.message) || "Could not save the note.");
  });
}

function renderTeamNotesList(notes, empMap) {
  const el = document.getElementById("tn-list");
  if (!notes.length) {
    el.innerHTML = '<div class="notes-empty">No notes found for the selected criteria.' +
      '<div style="margin-top:10px"><button class="btn btn-primary btn-sm" onclick="tnShowAdd()">+ Add Note</button></div></div>';
    return;
  }
  el.innerHTML = notes.map(function(n) {
    const empName = empMap[n.employee_id] || n.employee_name || n.employee_id;
    return '<div class="note-card" id="tnc-' + n.id + '">' +
      '<div class="note-card-header">' +
      '<span class="note-date">' + n.date + '</span>' +
      '<span class="note-emp">· ' + empName + '</span>' +
      '<div class="note-actions">' +
      '<button class="note-action-btn" onclick="editTeamNote(\'' + n.id + '\',\'' + n.employee_id + '\')">Edit</button>' +
      '<button class="note-action-btn" onclick="printNote(\'' + n.id + '\',\'' + empName + '\',\'' + n.date + '\')">Print</button>' +
      '<button class="note-action-btn del" onclick="deleteNote(\'' + n.id + '\',\'tnc-\')">Delete</button>' +
      '</div></div>' +
      '<div class="note-text" id="ntxt-' + n.id + '">' + escHtml(n.text) + '</div>' +
      '<div class="note-meta">Added ' + n.created + (n.modified !== n.created ? ' · Edited ' + n.modified : '') + '</div>' +
      '</div>';
  }).join("");
}

function editTeamNote(noteId, empId) {
  const txtEl = document.getElementById("ntxt-" + noteId);
  if (!txtEl) return;
  const currentText = txtEl.textContent;
  const card = document.getElementById("tnc-" + noteId);
  const origContent = card.innerHTML;
  card.innerHTML =
    '<div class="note-add-form">' +
    '<textarea class="form-control" id="nedit-' + noteId + '" rows="4" style="margin-bottom:8px">' + escHtml(currentText) + '</textarea>' +
    '<div style="display:flex;gap:8px">' +
    '<button class="btn btn-primary btn-sm" onclick="saveNoteEdit(\'' + noteId + '\',\'' + empId + '\')">Save</button>' +
    '<button class="btn btn-sm" onclick="loadTeamNotes()">Cancel</button>' +
    '</div></div>';
}

function saveNoteEdit(noteId, empId) {
  const ta = document.getElementById("nedit-" + noteId);
  if (!ta || !ta.value.trim()) { toast("Note cannot be empty", "err"); return; }
  // Get the current date from the existing note
  api("get_manager_notes", {employee_id: empId}, function(data) {
    const note = (data.notes || []).find(function(n) { return n.id === noteId; });
    const nd = note ? note.date : new Date().toISOString().slice(0, 10);
    api("save_manager_note", {employee_id: empId, note_text: ta.value, note_date: nd, note_id: noteId}, function() {
      toast("Note updated", "ok");
      loadTeamNotes();
    }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast((e && e.message) || "Failed to save", "err"); });
  });
}

function deleteNote(noteId, prefix) {
  if (!confirm("Delete this note?")) return;
  api("delete_manager_note", {note_id: noteId}, function() {
    const el = document.getElementById((prefix || "") + noteId);
    if (el) el.remove();
    toast("Note deleted", "ok");
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast((e && e.message) || "Failed to delete", "err"); });
}

function printNote(noteId, empName, noteDate) {
  const txtEl = document.getElementById("ntxt-" + noteId);
  const text  = txtEl ? txtEl.textContent : "";
  const w = window.open("", "_blank", "width=700,height=600");
  w.document.write('<html><head><title>Manager Note</title><style>body{font-family:Arial,sans-serif;padding:40px;max-width:600px;margin:auto}h2{font-size:var(--fs-md);margin-bottom:4px}p.meta{font-size:var(--fs-sm);color:var(--text2);margin-bottom:20px}pre{white-space:pre-wrap;font-family:inherit;font-size:var(--fs-base);line-height:1.6;border-top:1px solid var(--surface2);padding-top:16px}</style></head><body>' +
    '<h2>Manager Note — ' + escHtml(empName) + '</h2>' +
    '<p class="meta">Date: ' + noteDate + '</p>' +
    '<pre>' + escHtml(text) + '</pre>' +
    '<script>window.onload=function(){window.print()}<\/script>' +
    '</body></html>');
  w.document.close();
}

function printTeamNotes() {
  const items = document.querySelectorAll("#tn-list .note-card");
  if (!items.length) { toast("No notes to print", "err"); return; }
  let rows = "";
  items.forEach(function(card) {
    const dateEl = card.querySelector(".note-date");
    const empEl  = card.querySelector(".note-emp");
    const txtEl  = card.querySelector(".note-text");
    rows += '<div style="border-bottom:1px solid var(--surface2);padding:14px 0">' +
      '<div style="font-weight:bold;font-size:var(--fs-sm)">' + (dateEl ? dateEl.textContent : "") + " " + (empEl ? empEl.textContent : "") + '</div>' +
      '<pre style="white-space:pre-wrap;font-family:inherit;font-size:var(--fs-base);margin:8px 0 0">' + (txtEl ? escHtml(txtEl.textContent) : "") + '</pre>' +
      '</div>';
  });
  const w = window.open("", "_blank", "width=800,height=700");
  w.document.write('<html><head><title>Manager Notes</title><style>body{font-family:Arial,sans-serif;padding:40px;max-width:720px;margin:auto}h2{font-size:var(--fs-lg);margin-bottom:20px}</style></head><body>' +
    '<h2>Manager Notes</h2>' + rows +
    '<script>window.onload=function(){window.print()}<\/script></body></html>');
  w.document.close();
}

function escHtml(str) {
  return String(str || "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
}

/* Notes in employee drawer */
function renderDrawerNotes(empId, empName) {
  const body = document.getElementById("ed-body");
  if (!body) return;
  const sec = document.createElement("div");
  sec.className = "ed-section";
  sec.id = "ed-notes-sec-" + empId;
  sec.innerHTML = '<div class="ed-section-title">Manager Notes <span style="float:right"><button class="note-action-btn" onclick="showAddNoteForm(\'' + empId + '\')">+ Add Note</button></span></div>' +
    '<div id="ed-add-note-' + empId + '" style="display:none" class="note-add-form">' +
    '<input type="date" class="form-control" id="ed-note-date-' + empId + '" style="margin-bottom:8px;max-width:160px" value="' + new Date().toISOString().slice(0,10) + '">' +
    '<textarea class="form-control" id="ed-note-text-' + empId + '" rows="3" placeholder="Add a private note about ' + escHtml(empName) + '..." style="margin-bottom:8px"></textarea>' +
    '<div style="display:flex;gap:8px">' +
    '<button class="btn btn-primary btn-sm" onclick="saveDrawerNote(\'' + empId + '\')">Save Note</button>' +
    '<button class="btn btn-sm" onclick="hideAddNoteForm(\'' + empId + '\')">Cancel</button>' +
    '</div></div>' +
    '<div id="ed-notes-list-' + empId + '"><div style="color:var(--text3);font-size:var(--fs-sm);padding:8px 0">Loading notes...</div></div>';
  body.appendChild(sec);
  loadDrawerNotes(empId);
}

function showAddNoteForm(empId) {
  const el = document.getElementById("ed-add-note-" + empId);
  if (el) el.style.display = "block";
}

function hideAddNoteForm(empId) {
  const el = document.getElementById("ed-add-note-" + empId);
  if (el) el.style.display = "none";
}

function saveDrawerNote(empId) {
  const text = (document.getElementById("ed-note-text-" + empId) || {}).value || "";
  const date = (document.getElementById("ed-note-date-" + empId) || {}).value || new Date().toISOString().slice(0,10);
  if (!text.trim()) { toast("Note text required", "err"); return; }
  api("save_manager_note", {employee_id: empId, note_text: text, note_date: date}, function() {
    toast("Note saved", "ok");
    const ta = document.getElementById("ed-note-text-" + empId);
    if (ta) ta.value = "";
    hideAddNoteForm(empId);
    loadDrawerNotes(empId);
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast((e && e.message) || "Failed to save", "err"); });
}

function loadDrawerNotes(empId) {
  const el = document.getElementById("ed-notes-list-" + empId);
  if (!el) return;
  api("get_manager_notes", {employee_id: empId}, function(data) {
    const notes = data.notes || [];
    const empName = (data.employees || {})[empId] || empId;
    if (!notes.length) {
      el.innerHTML = '<div style="color:var(--text3);font-size:var(--fs-sm);padding:8px 0">No notes yet.</div>';
      return;
    }
    el.innerHTML = notes.map(function(n) {
      return '<div class="note-card" id="dnc-' + n.id + '" style="margin-bottom:8px">' +
        '<div class="note-card-header">' +
        '<span class="note-date">' + n.date + '</span>' +
        '<div class="note-actions">' +
        '<button class="note-action-btn" onclick="editDrawerNote(\'' + n.id + '\',\'' + empId + '\')">Edit</button>' +
        '<button class="note-action-btn" onclick="printNote(\'' + n.id + '\',\'' + escHtml(empName) + '\',\'' + n.date + '\')">Print</button>' +
        '<button class="note-action-btn del" onclick="deleteDrawerNote(\'' + n.id + '\',\'' + empId + '\')">Delete</button>' +
        '</div></div>' +
        '<div class="note-text" id="dntxt-' + n.id + '">' + escHtml(n.text) + '</div>' +
        '<div class="note-meta">' + n.created + '</div>' +
        '</div>';
    }).join("");
  }, function() {
    if (el) el.innerHTML = '<div style="color:var(--text3);font-size:var(--fs-sm)">Failed to load notes.</div>';
  });
}

function editDrawerNote(noteId, empId) {
  const txtEl = document.getElementById("dntxt-" + noteId);
  const card  = document.getElementById("dnc-" + noteId);
  if (!txtEl || !card) return;
  const currentText = txtEl.textContent;
  const dateEl = card.querySelector(".note-date");
  const currentDate = dateEl ? dateEl.textContent : new Date().toISOString().slice(0,10);
  card.innerHTML =
    '<div class="note-add-form">' +
    '<input type="date" class="form-control" id="dedit-date-' + noteId + '" value="' + currentDate + '" style="margin-bottom:8px;max-width:160px">' +
    '<textarea class="form-control" id="dedit-' + noteId + '" rows="3" style="margin-bottom:8px">' + escHtml(currentText) + '</textarea>' +
    '<div style="display:flex;gap:8px">' +
    '<button class="btn btn-primary btn-sm" onclick="saveDrawerNoteEdit(\'' + noteId + '\',\'' + empId + '\')">Save</button>' +
    '<button class="btn btn-sm" onclick="loadDrawerNotes(\'' + empId + '\')">Cancel</button>' +
    '</div></div>';
}

function saveDrawerNoteEdit(noteId, empId) {
  const ta   = document.getElementById("dedit-" + noteId);
  const date = (document.getElementById("dedit-date-" + noteId) || {}).value || new Date().toISOString().slice(0,10);
  if (!ta || !ta.value.trim()) { toast("Note cannot be empty", "err"); return; }
  api("save_manager_note", {employee_id: empId, note_text: ta.value, note_date: date, note_id: noteId}, function() {
    toast("Note updated", "ok");
    loadDrawerNotes(empId);
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast((e && e.message) || "Failed to save", "err"); });
}

function deleteDrawerNote(noteId, empId) {
  if (!confirm("Delete this note?")) return;
  api("delete_manager_note", {note_id: noteId}, function() {
    loadDrawerNotes(empId);
    toast("Note deleted", "ok");
  }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; } toast((e && e.message) || "Failed to delete", "err"); });
}

/* ── Goals Portal (embedded IIFE) ───────────────── */
(function() {
  "use strict";

  var _gpCtx = null;

  // _gpCtx is private to this IIFE. Code outside it that wrote `_gpCtx = null`
  // was creating a DIFFERENT global, so this cache was never cleared and
  // gpLoadGoalsPanel() returned early on its `if (_gpCtx)` guard - the goals
  // panel kept showing stale progress after evidence was submitted.
  window.gpResetContext = function () { _gpCtx = null; };
  var _gpCascades = [];
  var _gpLoadedTabs = {};
  var _gpOnGoalCreated = null; // callback set when dialog opened from within a review

  window.gpEsc = function gpEsc(s) { return esc(s); };

  function gpFmtDate(d) {
    return d ? (fmtDate(d) || String(d)) : "—";
  }

  /* Pull a readable sentence out of whatever Frappe returned.

     Slice 070 (SEC-4): only the server's own message (`_server_messages`) is
     ever shown. `exc` is the traceback Frappe sends to system users - HR and
     managers included - and it can name tables, SQL and record IDs; the HTTP
     status text says nothing useful either. Anything without a message gets a
     fixed sentence. The error carries `kind` (see callKind) and `server`
     (true when the words are the server's own). */
  function gpErr(r, status) {
    var msg = "";
    try { msg = JSON.parse(JSON.parse(r._server_messages)[0]).message; } catch (e) {}
    var kind = callKind(r, status);
    if (kind !== "refused") msg = "";
    var e = new Error(msg || callWords(kind));
    e.kind = kind;
    e.server = !!msg;
    return e;
  }

  /* An error for a call that never got an answer (slice 070). */
  function gpCallErr(kind) {
    var e = new Error(callWords(kind));
    e.kind = kind;
    return e;
  }

  /* The token this page was rendered with, cleaned up.

     Frappe writes it into the HTML as `frappe.csrf_token = "<value>"`. When the
     session has no token yet, that value is Python's None printed as the string
     "None" - truthy in JavaScript, so it used to be sent as though it were real. */
  function gpCsrf() {
    var c = (window.frappe && window.frappe.csrf_token) || "";
    return (c === "None" || c === "null" || c === "undefined") ? "" : c;
  }

  /* Ask the server for the session's current token.

     Every rendered page carries it, so re-reading one is the way to find out
     what it is now. Needed because the value is fixed when the page is built:
     a tab left open from before the session gained a token will hold the old
     one for as long as it stays open, and nothing else would ever correct it. */
  function gpRefreshCsrf() {
    return fetch(window.location.pathname, {credentials: "same-origin"})
      .then(function(r) { return r.text(); })
      .then(function(html) {
        /* Only the <script> line Frappe injects. The looser pattern this
           replaced also matched the example in the comment above gpCsrf(),
           which comes first in the page, so every repair sent the literal
           text <value> as the token and broke all later requests until the
           page was reloaded by hand. */
        var m = html.match(/<script>frappe\.csrf_token\s*=\s*"([^"]*)"/);
        var tok = m ? m[1] : "";
        if (tok && tok !== "None") {
          if (!window.frappe) window.frappe = {};
          /* Set globally, so frappe.call() - which api() uses everywhere else
             on this page - is repaired by the same round trip. */
          window.frappe.csrf_token = tok;
          return tok;
        }
        return "";
      })
      .catch(function() { return ""; });
  }

  function gpSend(method, args) {
    var headers = {"Content-Type": "application/json"};
    var csrf = gpCsrf();
    /* Sent only when it is a real token. An absent header is fine for a session
       that has none, because Frappe skips the check in that case; a wrong one
       is refused either way. */
    if (csrf) headers["X-Frappe-CSRF-Token"] = csrf;
    var opts = {method: args !== undefined ? "POST" : "GET", headers: headers,
                credentials: "same-origin"};
    if (args) opts.body = JSON.stringify(args);
    return fetch("/api/method/" + method, opts).then(function(res) {
      /* An nginx 502/504 page is HTML, not JSON (slice 070). */
      return res.json().catch(function() { return {}; })
        .then(function(data) { return {res: res, data: data}; });
    });
  }

  /* Slice 070: no signal -> rejects at once, nothing sent. No answer in 15 s
     -> rejects with kind "timeout"; the request is not cancelled, and the
     error carries `late`, a promise of the answer still on its way, so a panel
     can replace its message with the data when it lands. A dropped connection
     or an unreadable answer (an nginx 502 page) -> "network". */
  /* Review M2 / OPS-S3: a write (named by its verb) never ends at 15 s - its
     caller would turn the button back on while the save may still be running,
     and a second tap would save twice. It waits for the real answer, as
     before 070. Only a caller that handles a lost answer itself (the leave,
     expense and advance forms) passes {lostAnswerHandled: true}. */
  var WRITE_CALL = new RegExp("^(save|create|update|delete|submit|approve|reject|set|assign|end|post|"
    + "propose|add|remove|archive|send|invite|log|relink|return|advance|answer|acknowledge|hr_create|"
    + "hr_generate|hr_set|hr_start|raise|withdraw|decide|undo|mark|keep|ask|record|apply|cancel|"
    + "action|attach|publish|sync|unarchive)(_|$)|^(data_review_confirm|my_notices_seen)$");
  function gpFetch(method, args, opts) {
    if (navigator.onLine === false) return Promise.reject(gpCallErr("offline"));
    var call = new Promise(function(resolve, reject) {
      function lost(err) {
        reject(err && err.kind ? err
               : gpCallErr(navigator.onLine === false ? "offline" : "network"));
      }
      gpSend(method, args).then(function(out) {
        var res = out.res, data = out.data;
        if (res.ok && !data.exc_type) { resolve(data.message); return; }

        var stale = data.exc_type === "CSRFTokenError"
          || (res.status === 400 && /invalid request/i.test(data.message || ""));
        if (!stale) { reject(gpErr(data, res.status)); return; }

        /* One retry, with a token read fresh from the server. If that fails
           too the answer is a real refusal, not a stale token. */
        gpRefreshCsrf().then(function(tok) {
          if (!tok) { reject(gpErr(data, res.status)); return; }
          gpSend(method, args).then(function(o2) {
            if (o2.res.ok && !o2.data.exc_type) { resolve(o2.data.message); }
            else { reject(gpErr(o2.data, o2.res.status)); }
          }).catch(lost);
        });
      }).catch(lost);
    });
    if (WRITE_CALL.test(String(method).split(".").pop()) && !(opts && opts.lostAnswerHandled)) return call;
    return new Promise(function(resolve, reject) {
      var timer = setTimeout(function() {
        var e = gpCallErr("timeout");
        e.late = call;
        call.catch(function() {});   /* a late failure is nobody's business */
        reject(e);
      }, CALL_LIMIT_MS);
      call.then(function(v) { clearTimeout(timer); resolve(v); },
                function(e) { clearTimeout(timer); reject(e); });
    });
  }
  window.gpFetch = gpFetch; // expose for cross-module use

  function gpProgressRing(pct, color, size) {
    size = size || 48;
    var r = (size / 2) - 5;
    var circ = 2 * Math.PI * r;
    var offset = circ * (1 - Math.min(pct, 100) / 100);
    return "<svg width=\"" + size + "\" height=\"" + size + "\" viewBox=\"0 0 " + size + " " + size + "\">" +
      "<circle cx=\"" + (size/2) + "\" cy=\"" + (size/2) + "\" r=\"" + r + "\" fill=\"none\" stroke=\"var(--border2)\" stroke-width=\"4\"/>" +
      "<circle cx=\"" + (size/2) + "\" cy=\"" + (size/2) + "\" r=\"" + r + "\" fill=\"none\" stroke=\"" + color + "\" stroke-width=\"4\"" +
        " stroke-dasharray=\"" + circ.toFixed(1) + "\"" +
        " stroke-dashoffset=\"" + offset.toFixed(1) + "\"" +
        " stroke-linecap=\"round\"" +
        " transform=\"rotate(-90 " + (size/2) + " " + (size/2) + ")\"/>" +
      "<text x=\"" + (size/2) + "\" y=\"" + ((size/2)+4) + "\" text-anchor=\"middle\" font-size=\"" + Math.round(size*0.21) + "\" font-weight=\"800\" fill=\"" + color + "\">" + pct + "</text>" +
      "</svg>";
  }

  /* ── Rich text <-> plain text ───────────────────────
     Appraisal.reflections is a Text Editor field, so anything written from the
     Frappe desk arrives as Quill HTML ("<div class=ql-editor...><p>..."). Put
     straight into a <textarea> that shows up as literal markup, which is what
     people were seeing. Convert on the way in, and emit simple HTML on the way
     out so the desk still renders it properly.

     Note this parses the stored value and reads textContent rather than
     injecting it, so markup saved by one person can never execute for another. */

  function gpHtmlToText(html) {
    var s = String(html || "");
    if (!s) return "";
    // No tags at all: already plain text, leave it untouched.
    if (!/<[a-z/!][^>]*>/i.test(s)) return s;
    s = s.replace(/<br\s*\/?>/gi, "\n")
         .replace(/<\/(p|div|li|h[1-6]|tr)>/gi, "\n")
         .replace(/<li[^>]*>/gi, "• ");
    var el = document.createElement("div");
    el.innerHTML = s;                      // parsed only, never inserted
    var text = el.textContent || "";
    return text.replace(/\n{3,}/g, "\n\n").replace(/[ \t]+\n/g, "\n").trim();
  }

  function gpTextToHtml(text) {
    var t = String(text || "").trim();
    if (!t) return "";
    return t.split(/\n{2,}/).map(function(para) {
      return "<p>" + gpEsc(para).replace(/\n/g, "<br>") + "</p>";
    }).join("");
  }


  function gpTrajColor(t) {
    if (t === "On Track" || t === "Completed") return "var(--green)";
    if (t === "At Risk")  return "var(--amber)";
    if (t === "Off Track") return "var(--red)";
    return "var(--text3)";
  }

  function gpTrajBadge(t) {
    var map = {"On Track":"b-on-track","At Risk":"b-at-risk","Off Track":"b-off-track","Not Started":"b-not-started","Completed":"b-completed"};
    return "<span class=\"badge " + (map[t] || "b-not-started") + "\">" + gpEsc(t || "Not Started") + "</span>";
  }

  function gpStatusBadge(s) {
    var map = {"Active":"b-active","Completed":"b-completed","Cancelled":"b-cancelled"};
    return "<span class=\"badge " + (map[s] || "") + "\">" + gpEsc(s || "—") + "</span>";
  }

  // ── Tab switching ──────────────────────────────────
  window.gpShowTab = function(tab) {
    // "perf" is deliberately absent: the appraisal moved out of this tab strip
    // into its own Appraisals item in the sidebar.
    // The tree's overlays live on <body>, so they must be dismissed explicitly
    // when the view behind them changes.
    if (window.tvClosePop) { tvClosePop(); tvCloseNew(); }
    // "perf" is deliberately absent: the appraisal lives in its own sidebar
    // panel. "goals" and "kpis" merged into the single "tree" tab.
    ["overview","tree","reviews","team","hr","calibration","distribution"].forEach(function(t) {
      var panel = document.getElementById("gp-tab-" + t);
      var btn   = document.getElementById("gtab-" + t);
      if (panel) panel.style.display = (t === tab) ? "" : "none";
      if (btn)   btn.classList.toggle("active", t === tab);
    });
    if (!_gpLoadedTabs[tab]) {
      _gpLoadedTabs[tab] = true;
      if (tab === "overview")   gpRenderOverview();
      if (tab === "tree")       tvLoad();
      if (tab === "reviews") {
        mrLoad(false);
        var teamSec = document.getElementById("rev-sec-team-reviews");
        if (teamSec && teamSec.style.display !== "none") pfLoadReviews();
      }
      if (tab === "team")       gpLoadTeam(false);
      if (tab === "hr")            pfLoadHr(false);
      if (tab === "calibration")   calInit();
      if (tab === "distribution")  pdInit();
    }
  };

  // Main boot called by loadGoalsPanel()
  window._gpBoot = function() {
    if (_gpCtx) { gpShowTab("overview"); return; }
    gpFetch("alvoraa_portal.goals_api.get_portal_context").then(function(ctx) {
      _gpCtx = ctx;
      var attn = ((_gpCtx.dashboard || {}).at_risk || 0);
      var gbadge = document.getElementById("sb-goals-badge");
      if (gbadge) { gbadge.textContent = attn; gbadge.style.display = attn ? "flex" : "none"; }
      if (_gpCtx.is_manager) {
        var tBtn = document.getElementById("gtab-team");
        if (tBtn) tBtn.style.display = "";
      }
      pfBoot();
      gpShowTab("overview");
    }).catch(function(e) {
      var kpis = document.getElementById("gp-kpis");
      if (kpis) kpis.innerHTML = "<div class=\"callout callout-warn\" style=\"grid-column:1/-1\">Failed to load Goals portal: " + gpEsc(e.message) + "</div>";
    });
  };

  // ── Overview Tab ───────────────────────────────────
  function gpRenderOverview() {
    if (!_gpCtx) return;
    var d = _gpCtx.dashboard || {};
    var c = _gpCtx.cycle;

    var bannerEl = document.getElementById("gp-cycle-banner");
    if (c && bannerEl) {
      bannerEl.innerHTML = "<div class=\"cycle-banner\" style=\"margin-bottom:20px\">" +
        "<div class=\"cycle-dot\"></div>" +
        "<div class=\"cycle-info\"><div class=\"cycle-name\">" + gpEsc(c.cycle_name) + "</div>" +
        "<div class=\"cycle-dates\">" + gpFmtDate(c.start_date) + " – " + gpFmtDate(c.end_date) + "</div></div>" +
        "<span class=\"cycle-status\">" + gpEsc(c.status) + "</span>" +
        "</div>";
    }

    var kpis = [
      {val: d.active || 0,               lbl: "Active Goals",    color: "var(--primary)"},
      {val: (d.avg_progress || 0) + "%", lbl: "Avg Progress",    color: "var(--green)"},
      {val: d.at_risk || 0,              lbl: "At Risk",         color: "var(--amber)"},
      {val: d.upcoming_deadlines || 0,   lbl: "Due in 30 Days",  color: "var(--red)"},
    ];
    var kpisEl = document.getElementById("gp-kpis");
    if (kpisEl) kpisEl.innerHTML = kpis.map(function(k) {
      return "<div class=\"stat-chip\" onclick=\"gpShowTab('tree')\" style=\"cursor:pointer\" title=\"View Objectives & KPIs\">" +
        "<div class=\"stat-chip-val num\" style=\"color:" + k.color + "\">" +
        gpEsc(String(k.val)) + "</div><div class=\"stat-chip-lbl\">" + k.lbl + "</div></div>";
    }).join("");

    var total = (d.total || 1);
    var traj = [
      {label: "On Track",  count: Math.max(0, (d.active||0) - (d.at_risk||0)), color: "var(--green)"},
      {label: "At Risk",   count: d.at_risk || 0,                               color: "var(--amber)"},
      {label: "Completed", count: d.completed || 0,                             color: "var(--sky)"},
    ].filter(function(t) { return t.count > 0; });

    var trajEl = document.getElementById("gp-traj");
    if (trajEl) trajEl.innerHTML = traj.length
      ? traj.map(function(t) {
          var pct = Math.round((t.count / total) * 100);
          return "<div class=\"gp-traj-row\">" +
            "<div class=\"gp-traj-dot\" style=\"background:" + t.color + "\"></div>" +
            "<div class=\"gp-traj-label\">" + t.label + "</div>" +
            "<div class=\"gp-traj-count\">" + t.count + "</div>" +
            "<div class=\"gp-traj-bar\"><div class=\"gp-traj-fill\" style=\"width:" + pct + "%;background:" + t.color + "\"></div></div>" +
            "</div>";
        }).join("")
      : "<div class=\"empty-state\"><div class=\"empty-state-text\">No goals yet — set your first goal.</div></div>";

    gpRenderDeadlines();
    if (typeof pfLoadMyReviewStatus === "function") pfLoadMyReviewStatus();
  }

  function gpRenderDeadlines() {
    var el = document.getElementById("gp-deadlines");
    gpFetch("alvoraa_portal.goals_api.get_my_goals").then(function(all) {
      var now = new Date();
      var d30 = new Date(); d30.setDate(d30.getDate() + 30);
      var upcoming = (all || []).filter(function(g) {
        if (g.status !== "Active" || !g.end_date) return false;
        var d = new Date(g.end_date);
        return d >= now && d <= d30;
      }).sort(function(a, b) { return a.end_date.localeCompare(b.end_date); });

      if (!upcoming.length) {
        el.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-text\">No goals due in the next 30 days.</div></div>";
        return;
      }
      el.innerHTML = "<div class=\"gp-deadline-list\">" +
        upcoming.map(function(g) {
          var pct = Math.round(g.progress_pct || 0);
          var tColor = gpTrajColor(g.trajectory);
          return "<div class=\"gp-deadline-row\" onclick=\"gpOpenDetail('" + gpEsc(g.name) + "')\">" +
            "<div class=\"gp-deadline-pct\" style=\"color:" + tColor + "\">" + pct + "%</div>" +
            "<div class=\"gp-deadline-info\"><div class=\"gp-deadline-name\">" + gpEsc(g.goal_name) + "</div>" +
            "<div class=\"gp-deadline-date\">Due " + gpFmtDate(g.end_date) + "</div></div>" +
            "</div>";
        }).join("") + "</div>";
    }).catch(function() {
      if (el) el.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-text\">Could not load deadlines.</div></div>";
    });
  }

  // The My Goals list and its filter row were folded into the combined
  // Objectives & KPIs tree (tvLoad/tvRender). gpOpenDetail below is still
  // used from there, and the create/edit modal is shared.

  // -- Key Result Areas ------------------------------
  //
  // KRAs belong to the ROLE, not the person: they come from the employee's
  // appraisal template. So "no KRAs" does not mean the employee did anything
  // wrong - it means HR has not assigned them a template yet, and the only
  // useful thing to do is say so and offer to tell HR.
  window._gpKraState = { mandatory: false, available: true };

  window.gpLoadKras = function() {
    var sel  = document.getElementById("gp-c-kra");
    var req  = document.getElementById("gp-kra-req");
    var hint = document.getElementById("gp-kra-hint");
    if (!sel) return;
    pf("kra_api.get_my_kras", {}).then(function(r) {
      window._gpKraState = { mandatory: !!r.mandatory, available: !!r.available };
      sel.innerHTML = '<option value="">- None -</option>';
      (r.kras || []).forEach(function(k) {
        var o = document.createElement("option");
        o.value = k.kra;
        o.textContent = k.title + (k.weightage ? "  (" + k.weightage + "%)" : "");
        sel.appendChild(o);
      });
      if (req) req.style.display = r.mandatory ? "inline" : "none";
      if (hint) {
        if (!r.available) {
          hint.textContent = "No Key Result Areas have been assigned to you yet.";
          hint.style.display = "block";
        } else if (r.total_weightage && r.total_weightage !== 100) {
          // Weightages are meant to sum to 100. Saying so is more useful than
          // silently accepting a template nobody has finished.
          hint.textContent = "Weightages total " + r.total_weightage + "%, not 100%. HR may still be setting these up.";
          hint.style.display = "block";
        } else { hint.style.display = "none"; }
      }
      // Only interrupt when it actually blocks them.
      if (r.mandatory && !r.available) gpShowNoKraDialog();
    }).catch(function() {
      // Never block goal creation because this lookup failed.
      if (req)  req.style.display  = "none";
      if (hint) hint.style.display = "none";
    });
  };

  window.gpShowNoKraDialog = function() {
    pfOpenModal("gp-nokra-modal");
  };
  window.gpCloseNoKraDialog = function() {
    pfCloseModal("gp-nokra-modal");
  };

  window.gpReportMissingKra = function() {
    var btn = document.getElementById("gp-nokra-report");
    var msg = (document.getElementById("gp-nokra-note") || {}).value || "";
    if (btn) { btn.disabled = true; btn.textContent = "Sending..."; }
    pf("kra_api.report_missing_kra", { message: msg }).then(function(r) {
      pfCloseModal("gp-nokra-modal");
      toast("HR has been notified (" + (r.notified || 0) + " recipient" + ((r.notified === 1) ? "" : "s") + ").", "ok");
    }).catch(function(e) {
      toast(e.message || "Could not notify HR.", "err");
    }).finally(function() {
      if (btn) { btn.disabled = false; btn.textContent = "Report to HR"; }
    });
  };

  // ── Create Goal Modal ──────────────────────────────
  window.gpOpenCreateGoal = function() {
    var sel = document.getElementById("gp-sel-cascade");
    if (sel) sel.value = "";
    ["gp-c-name","gp-c-target","gp-c-start","gp-c-end"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    var srch = document.getElementById("gp-align-search");
    if (srch) { srch.value = ""; srch._lastSelected = ""; }
    var cycleEl = document.getElementById("gp-c-cycle"); if (cycleEl) cycleEl.value = "";
    var gtSel = document.getElementById("gp-c-goal-type"); if (gtSel) gtSel.value = "Business";
    gpLoadKras();
    var cvSel = document.getElementById("gp-c-company-value"); if (cvSel) cvSel.value = "";
    var stretch = document.getElementById("gp-c-stretch"); if (stretch) stretch.checked = false;
    var hint = document.getElementById("gp-c-unit-hint"); if (hint) hint.textContent = "";
    var errEl = document.getElementById("gp-create-error"); if (errEl) errEl.style.display = "none";
    var lbl = document.getElementById("gp-create-label"); if (lbl) lbl.textContent = "Create Goal";
    var btn = document.getElementById("gp-create-btn"); if (btn) btn.disabled = false;

    document.getElementById("gp-create-modal").classList.add("open");
    document.getElementById("gp-edit-id").value = "";
    document.getElementById("gp-modal-title").textContent = "Create New Goal";
    var pSel = document.getElementById("gp-sel-parent"); if (pSel) pSel.value = "";
    gpLoadCompanyValues();
    gpFillGoalEmployees().then(function() { gpReloadAlignment(); });
  };

  function gpLoadCompanyValues() {
    var sel = document.getElementById("gp-c-company-value");
    if (!sel || sel.dataset.loaded) return;
    gpFetch("alvoraa_portal.performance_api.get_company_values").then(function(vals) {
      sel.innerHTML = "<option value=\"\">— None —</option>" +
        (vals || []).map(function(v) {
          return "<option value=\"" + gpEsc(v.name) + "\">" +
            (v.icon_emoji ? v.icon_emoji + " " : "") + gpEsc(v.value_name) + "</option>";
        }).join("");
      sel.dataset.loaded = "1";
    }).catch(function() {});
  }

  window.gpOpenEditGoal = function(json) {
    var g = typeof json === "string" ? JSON.parse(json) : json;
    var errEl = document.getElementById("gp-create-error"); if (errEl) errEl.style.display = "none";
    document.getElementById("gp-modal-title").textContent = "Edit Goal";
    document.getElementById("gp-edit-id").value = g.name;
    document.getElementById("gp-c-name").value = g.goal_name || "";
    document.getElementById("gp-c-target").value = g.target_value || "";
    document.getElementById("gp-c-start").value = g.start_date || "";
    document.getElementById("gp-c-end").value = g.end_date || "";
    var gtSel = document.getElementById("gp-c-goal-type");
    if (gtSel) gtSel.value = g.goal_type || "Business";
    var stretch = document.getElementById("gp-c-stretch");
    if (stretch) stretch.checked = !!g.is_extra_initiative;
    // Load company values, then set the saved selection reliably (no timeout race)
    (function setCompanyValue() {
      var sel = document.getElementById("gp-c-company-value");
      if (!sel) return;
      if (sel.dataset.loaded) { sel.value = g.company_value || ""; return; }
      gpFetch("alvoraa_portal.performance_api.get_company_values").then(function(vals) {
        sel.innerHTML = "<option value=\"\">— None —</option>" +
          (vals || []).map(function(v) {
            return "<option value=\"" + gpEsc(v.name) + "\">" +
              (v.icon_emoji ? v.icon_emoji + " " : "") + gpEsc(v.value_name) + "</option>";
          }).join("");
        sel.dataset.loaded = "1";
        sel.value = g.company_value || "";
      }).catch(function() {});
    })();
    var lbl = document.getElementById("gp-create-label"); if (lbl) lbl.textContent = "Save Goal";
    var btn = document.getElementById("gp-create-btn"); if (btn) btn.disabled = false;
    document.getElementById("gp-create-modal").classList.add("open");
    // The subject cannot change on an existing goal — moving it between people
    // would silently rewrite someone's targets.
    var wrap = document.getElementById("gp-employee-field");
    gpFillGoalEmployees(g.employee).then(function() {
      if (wrap) wrap.style.display = "none";
      gpReloadAlignment(g.parent_goal || g.goal_cascade || "");
    });
  };

  window.gpDeleteGoal = function(goalId, label) {
    if (!confirm("Delete goal \"" + label + "\"? This cannot be undone.")) return;
    gpFetch("alvoraa_portal.goals_api.delete_goal", {goal_id: goalId})
      .then(function() { tvLoad(); })
      .catch(function(e) { alert(e.message); });
  };

  // Employee picker for the goal modal — self plus subtree, HR gets everyone.
  function gpFillGoalEmployees(selected) {
    return gpFetch("alvoraa_portal.goals_api.get_manageable_employees").then(function(rows) {
      var sel = document.getElementById("gp-c-employee");
      var wrap = document.getElementById("gp-employee-field");
      if (!sel) return;
      sel.innerHTML = (rows || []).map(function(e) {
        return "<option value=\"" + gpEsc(e.name) + "\">" + gpEsc(e.employee_name) +
               (e.is_self ? " (me)" : "") + "</option>";
      }).join("");
      if (selected) sel.value = selected;
      else {
        var me = (rows || []).filter(function(e) { return e.is_self; })[0];
        if (me) sel.value = me.name;
      }
      // Show "Goal for" only when there's someone to choose; always show creator.
      if (wrap) wrap.style.display = (rows || []).length > 1 ? "" : "none";
      // Creator display — always the logged-in user (self)
      var selfEmp = (rows || []).filter(function(e) { return e.is_self; })[0];
      var creatorEl = document.getElementById("gp-creator-display");
      var creatorWrap = document.getElementById("gp-creator-field");
      if (creatorEl && selfEmp) {
        creatorEl.textContent = selfEmp.employee_name;
        if (creatorWrap) creatorWrap.style.display = "";
      }
    });
  }

  window.gpOpenCascadeDropdown = function() {
    var listEl = document.getElementById("gp-cascade-list");
    var inp = document.getElementById("gp-align-search");
    if (!listEl || !listEl.children.length) return;
    /* Clear value so user can type a fresh filter; restore on close if nothing chosen */
    if (inp) { inp._lastSelected = inp.value; inp.value = ""; }
    listEl.style.display = "";
    /* Show all items */
    Array.prototype.forEach.call(listEl.children, function(el) { el.style.display = ""; });
  };

  window.gpCloseCascadeDropdown = function() {
    var listEl = document.getElementById("gp-cascade-list");
    var inp = document.getElementById("gp-align-search");
    if (listEl) listEl.style.display = "none";
    /* If nothing newly selected, restore the previous label */
    if (inp && !inp.value && inp._lastSelected) inp.value = inp._lastSelected;
  };

  /* Close cascade dropdown when clicking anywhere outside the wrap */
  document.addEventListener("click", function(e) {
    var wrap = document.getElementById("gp-cascade-wrap");
    if (wrap && !wrap.contains(e.target)) gpCloseCascadeDropdown();
  });

  window.gpReloadAlignment = function(selectedValue) {
    var listEl = document.getElementById("gp-cascade-list");
    var chainEl = document.getElementById("gp-align-chain");
    if (chainEl) chainEl.textContent = "";
    listEl.style.display = "none";
    listEl.innerHTML = "";

    /* **This asked for one employee's chain and never got it.**
       `goals_api.get_alignment_options()` declares no parameters, so Frappe
       dropped `employee` on the wire and the server answered with the CALLER's
       reporting line. Raising a goal for somebody else therefore offered
       parents from the wrong chain, and `create_goal` then refused the save,
       because it checks the parent against the SUBJECT's chain. Sending a name
       the server does not declare is not a way to ask for anything, so the key
       is gone. Making the picker right needs `get_alignment_options(employee)`
       on the server, guarded by `_require_manages` - see the addendum to
       docs/slices/045-redesign-wave4/00-impact-analysis.md, D7. */
    gpFetch("alvoraa_portal.goals_api.get_alignment_options", {}).then(function(data) {
      _gpCascades = (data && data.options) || [];
      var chain = (data && data.chain) || [];
      if (chainEl) {
        chainEl.textContent = chain.length
          ? "Reporting line: " + chain.join(" → ")
          : "No manager on record for this employee, so only company objectives are offered.";
      }
      if (!_gpCascades.length) {
        listEl.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm);padding:8px\">Nothing to align to yet. Ask HR to publish a company objective.</div>";
        return;
      }
      // Options arrive ordered company-first, then down the reporting line, so
      // rendering in order reproduces the cascade top-down.
      var lastLevel = null;
      listEl.innerHTML = _gpCascades.map(function(o) {
        var header = "";
        if (o.level !== lastLevel) {
          lastLevel = o.level;
          header = "<div class=\"cascade-group\">" + gpEsc(o.level) + "</div>";
        }
        return header +
          "<div class=\"cascade-opt\" id=\"gp-co-" + gpEsc(o.value) + "\" onclick=\"gpSelectCascade('" + gpEsc(o.value) + "')\">" +
          "<div class=\"cascade-opt-name\">" + gpEsc(o.label) + "</div>" +
          "<div class=\"cascade-opt-sub\">" +
            (o.target ? "Target " + o.target + " " + gpEsc(o.unit || "") + " · " : "") +
            gpFmtDate(o.period_start) + " – " + gpFmtDate(o.period_end) +
          "</div></div>";
      }).join("");
      if (selectedValue) gpSelectCascade(selectedValue);
      gpFilterAlignList();
    }).catch(function(e) {
      listEl.innerHTML = "<div style=\"color:var(--red);font-size:var(--fs-sm)\">" + gpEsc(e.message) + "</div>";
    });
  };

  // Type-to-filter: opens the dropdown and hides non-matching rows.
  window.gpFilterAlignList = function() {
    var q = ((document.getElementById("gp-align-search") || {}).value || "").toLowerCase();
    var listEl = document.getElementById("gp-cascade-list");
    if (!listEl) return;
    listEl.style.display = ""; /* ensure open while typing */
    var shownUnder = 0, lastHeader = null, anyShown = false;
    Array.prototype.forEach.call(listEl.children, function(el) {
      if (el.id === "gp-align-empty") return;
      if (el.classList.contains("cascade-group")) {
        if (lastHeader) lastHeader.style.display = shownUnder ? "" : "none";
        lastHeader = el; shownUnder = 0;
        return;
      }
      var hit = !q || el.textContent.toLowerCase().indexOf(q) >= 0;
      el.style.display = hit ? "" : "none";
      if (hit) { shownUnder++; anyShown = true; }
    });
    if (lastHeader) lastHeader.style.display = shownUnder ? "" : "none";
    var empty = document.getElementById("gp-align-empty");
    if (!anyShown && q) {
      if (!empty) {
        empty = document.createElement("div");
        empty.id = "gp-align-empty";
        empty.style.cssText = "color:var(--text3);font-size:var(--fs-sm);padding:10px 14px";
        listEl.appendChild(empty);
      }
      empty.textContent = 'No matches for "' + q + '"';
      empty.style.display = "";
    } else if (empty) {
      empty.style.display = "none";
    }
  };

  function pfGoalEmployee() {
    var el = document.getElementById("gp-c-employee");
    return el ? el.value : "";
  }

  window.gpSelectCascade = function(id) {
    var o = _gpCascades.filter(function(x) { return x.value === id; })[0];
    // Company objectives set only the cascade; a manager's goal also sets the
    // parent, which is what makes the roll-up chain traceable. The "none"
    // option clears both, which is how an organisational goal is expressed.
    var selC = document.getElementById("gp-sel-cascade");
    var selP = document.getElementById("gp-sel-parent");
    if (selC) selC.value = o ? (o.cascade || "") : "";
    if (selP) selP.value = o ? (o.parent_goal || "") : "";
    var selN = document.getElementById("gp-sel-standalone");
    if (selN) selN.value = (o && o.type === "none") ? "1" : "";

    document.querySelectorAll(".cascade-opt").forEach(function(el) {
      el.classList.toggle("selected", el.id === "gp-co-" + id);
    });

    /* Update the search input to show the selected label and close the dropdown */
    var inp = document.getElementById("gp-align-search");
    if (inp) {
      var label = o ? (o.label || "") : "";
      inp.value = label;
      inp._lastSelected = label;
    }
    gpCloseCascadeDropdown();

    if (o) {
      var hint = document.getElementById("gp-c-unit-hint");
      if (hint) hint.textContent = o.unit ? "Unit: " + o.unit : "";
      var s = document.getElementById("gp-c-start"); if (s && !s.value) s.value = o.period_start || "";
      var en = document.getElementById("gp-c-end");  if (en && !en.value) en.value = o.period_end   || "";
    }
  };

  window.gpCloseCreateGoal = function() {
    document.getElementById("gp-create-modal").classList.remove("open");
  };

  window.gpSubmitCreateGoal = function() {
    var errEl = document.getElementById("gp-create-error");
    var btn   = document.getElementById("gp-create-btn");
    var lbl   = document.getElementById("gp-create-label");
    if (errEl) errEl.style.display = "none";

    var cascade    = (document.getElementById("gp-sel-cascade") || {}).value || "";
    var parent     = (document.getElementById("gp-sel-parent") || {}).value || "";
    var standalone = (document.getElementById("gp-sel-standalone") || {}).value || "";
    var name       = ((document.getElementById("gp-c-name") || {}).value || "").trim();
    var target  = (document.getElementById("gp-c-target") || {}).value || "";
    var start   = (document.getElementById("gp-c-start") || {}).value || "";
    var end     = (document.getElementById("gp-c-end") || {}).value || "";

    function showErr(msg) { if (errEl) { errEl.textContent = msg; errEl.style.display = "block"; } }
    // Either it aligns to something, or it is explicitly declared standalone.
    if (!cascade && !parent && !standalone) {
      return showErr("Pick what this goal aligns to, or mark it an organisational objective.");
    }
    if (!name)    return showErr("Goal name is required.");
    if (!target || parseFloat(target) <= 0) return showErr("Enter a valid target value.");
    if (!start || !end) return showErr("Start and end dates are required.");
    if (start > end)    return showErr("End date must be after start date.");

    var editing = (document.getElementById("gp-edit-id") || {}).value || "";
    if (btn) btn.disabled = true;
    if (lbl) lbl.textContent = editing ? "Saving…" : "Creating…";

    var goalType = (document.getElementById("gp-c-goal-type") || {}).value || "Business";
    var companyValue = (document.getElementById("gp-c-company-value") || {}).value || "";
    var isStretch = (document.getElementById("gp-c-stretch") || {}).checked ? 1 : 0;

    var call = editing
      ? gpFetch("alvoraa_portal.goals_api.update_goal", {
          goal_id: editing, goal_name: name, target_value: parseFloat(target),
          start_date: start, end_date: end, parent_goal: parent,
          goal_type: goalType, company_value: companyValue, is_extra_initiative: isStretch,
        })
      : gpFetch("alvoraa_portal.goals_api.create_goal", {
          goal_name: name, cascade_id: cascade, target_value: parseFloat(target),
          start_date: start, end_date: end, parent_goal: parent,
          employee: pfGoalEmployee(),
          goal_type: goalType, company_value: companyValue, is_extra_initiative: isStretch,
          kra: ((document.getElementById("gp-c-kra") || {}).value || "") || undefined,
          appraisal_cycle: ((document.getElementById("gp-c-cycle") || {}).value || "") || undefined,
        });

    call.then(function(result) {
      window.gpCloseCreateGoal();
      if (typeof _gpOnGoalCreated === "function") {
        var cb = _gpOnGoalCreated;
        _gpOnGoalCreated = null;
        cb(result);
      } else {
        _gpLoadedTabs["overview"] = false;
        tvLoad();
      }
    }).catch(function(e) {
      showErr(e.message);
      if (btn) btn.disabled = false;
      if (lbl) lbl.textContent = editing ? "Save Goal" : "Create Goal";
    });
  };

  // ── Goal Detail Side Panel ─────────────────────────
  window.gpOpenDetail = function(goalId) {
    document.getElementById("gp-detail-panel").classList.add("open");
    document.getElementById("gp-detail-overlay").style.display = "block";
    var nm = document.getElementById("gp-dp-name"); if (nm) nm.textContent = "Loading…";
    var cas = document.getElementById("gp-dp-cascade"); if (cas) cas.textContent = "";
    var ring = document.getElementById("gp-dp-ring"); if (ring) ring.innerHTML = gpProgressRing(0, "var(--border2)", 56);
    var ev = document.getElementById("gp-dp-evidence"); if (ev) ev.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">Loading…</div>";

    gpFetch("alvoraa_portal.goals_api.get_goal_detail", {goal_id: goalId}).then(function(g) {
      var pct = Math.round(g.progress_pct || 0);
      var tColor = gpTrajColor(g.trajectory);

      var el;
      el = document.getElementById("gp-dp-name");         if (el) el.textContent = g.goal_name;
      el = document.getElementById("gp-dp-description");
      if (el) { if (g.description) { el.textContent = g.description; el.style.display = ""; } else { el.style.display = "none"; } }
      el = document.getElementById("gp-dp-cascade");
      if (el) el.textContent = g.is_organisational
        ? "Organisational objective — not derived from anything above"
        : (g.cascade_name || g.goal_cascade || "");
      el = document.getElementById("gp-dp-ring");         if (el) el.innerHTML = gpProgressRing(pct, tColor, 60);
      el = document.getElementById("gp-dp-progress-line");if (el) el.textContent = (g.actual_progress || 0) + " / " + g.target_value + " " + (g.unit || "");
      /* R5: the owner and the line see that a review holds this objective. */
      el = document.getElementById("gp-dp-trajectory");   if (el) el.innerHTML = gpTrajBadge(g.trajectory) + " " + riReviewBadge(g.review_badge);
      el = document.getElementById("gp-dp-status");       if (el) el.innerHTML = gpStatusBadge(g.status);
      el = document.getElementById("gp-dp-start");        if (el) el.textContent = gpFmtDate(g.start_date);
      el = document.getElementById("gp-dp-end");          if (el) el.textContent = gpFmtDate(g.end_date);
      el = document.getElementById("gp-dp-target");       if (el) el.textContent = g.target_value + " " + (g.unit || "");
      el = document.getElementById("gp-dp-actual");       if (el) el.textContent = (g.actual_progress || 0) + " " + (g.unit || "");
      el = document.getElementById("gp-dp-assignee");     if (el) el.textContent = g.employee_name || g.employee || "—";
      el = document.getElementById("gp-dp-owner");        if (el) el.textContent = g.created_by_name || g.owner || "—";
      el = document.getElementById("gp-dp-cv-row");       if (el) el.style.display = g.company_value ? "" : "none";
      el = document.getElementById("gp-dp-cv");           if (el) el.textContent = g.company_value || "";
      el = document.getElementById("gp-dp-gt-row");       if (el) el.style.display = g.goal_type ? "" : "none";
      el = document.getElementById("gp-dp-gt");           if (el) el.textContent = g.goal_type || "";

      // Editable progress — shown to HR/managers (can_edit) when not the direct employee
      var editSec = document.getElementById("gp-dp-edit-section");
      if (editSec) {
        if (g.can_edit && g.status === "Active") {
          editSec.style.display = "";
          var inp = document.getElementById("gp-dp-prog-inp");
          if (inp) inp.value = g.actual_progress || 0;
          var unit = document.getElementById("gp-dp-prog-unit");
          if (unit) unit.textContent = g.unit || "";
          editSec.dataset.goalId = g.name;
          editSec.dataset.unit = g.unit || "";
        } else { editSec.style.display = "none"; }
      }

      // Evidence submit form — shown to goal owner when Active
      var evSec = document.getElementById("gp-dp-ev-section");
      if (evSec) {
        if (g.is_mine && g.status === "Active") {
          evSec.style.display = "";
          var evForm = document.getElementById("gp-dp-ev-form");
          if (evForm) evForm.innerHTML =
            '<div class="form-row"><div class="form-group"><label class="form-label">Value / Progress' + (g.unit ? ' (' + esc(g.unit) + ')' : '') + '</label><input class="form-control" type="number" id="dp-ev-amount" placeholder="e.g. 75" min="0" step="any"></div>' +
            '<div class="form-group"><label class="form-label">Date *</label><input class="form-control" type="date" id="dp-ev-date"></div></div>' +
            '<div class="form-group"><label class="form-label">Note</label><input class="form-control" type="text" id="dp-ev-note" placeholder="Optional"></div>' +
            '<div class="form-group"><label class="form-label">Attach Image or File</label>' +
            '<label style="display:flex;align-items:center;gap:10px;cursor:pointer;border:1.5px dashed var(--border);border-radius:var(--r-sm);padding:9px 12px;background:var(--surface);transition:border-color .2s" onclick="document.getElementById(\'dp-ev-file\').click()">' +
            '<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>' +
            '<span id="dp-ev-file-name" style="font-size:var(--fs-sm);color:var(--text3)">Click to upload (image, PDF...)</span></label>' +
            '<input type="file" id="dp-ev-file" accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx" style="display:none" onchange="dpEvFileChanged()"></div>' +
            '<div class="form-actions" style="border-top:none;padding-top:0;margin-top:8px">' +
            '<button class="btn btn-primary btn-sm" id="dp-ev-btn" onclick="gpSubmitPanelEvidence(\'' + g.name + '\')">Submit</button></div>';
        } else { evSec.style.display = "none"; }
      }

      // Everything feeding this objective. One objective deliberately collects
      // KPIs from several people down the owner's branch, so group by person.
      var contribEl = document.getElementById("gp-dp-contributors");
      if (contribEl) {
        if (!g.contributors || !g.contributors.length) {
          contribEl.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">" +
            "No KPIs are linked to this objective yet.</div>";
        } else {
          contribEl.innerHTML = g.contributors.map(function(c) {
            return "<div class=\"gp-contrib\">" +
              "<div class=\"gp-contrib-hdr\">" +
                "<span class=\"gp-contrib-name\">" + gpEsc(c.employee_name) + "</span>" +
                "<span class=\"gp-contrib-avg\">" + pfNum(c.avg_attainment) + "% avg</span>" +
              "</div>" +
              c.kpis.map(function(k) {
                var colour = pfAttColor(k.attainment_pct || 0);
                return "<div class=\"gp-contrib-kpi\">" +
                  "<span>" + gpEsc(k.kpi_name) + "</span>" +
                  "<span style=\"color:" + colour + ";font-weight:700\">" +
                    pfNum(k.actual_value, 2) + " / " + pfNum(k.target_value, 2) +
                    " · " + pfNum(k.attainment_pct) + "%</span>" +
                "</div>";
              }).join("") +
            "</div>";
          }).join("");
        }
      }

      var evEl = document.getElementById("gp-dp-evidence");
      if (evEl) {
        if (!g.evidence || !g.evidence.length) {
          evEl.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">No evidence submitted yet.</div>";
        } else {
          evEl.innerHTML = "<div class=\"gp-evidence-list\">" + g.evidence.map(function(e) {
            var vs = e.validation_status || "Pending";
            var vBadge = "<span class=\"badge b-" + vs.toLowerCase().replace(" ","-") + "\">" + gpEsc(vs) + "</span>";
            var val = e.extracted_amount
              ? Number(e.extracted_amount).toLocaleString("en-IN", {maximumFractionDigits: 2})
              : "—";
            return "<div class=\"gp-evidence-row\">" +
              "<div class=\"gp-ev-type\">" + gpEsc(e.evidence_type || "Evidence") + "</div>" +
              "<div class=\"gp-ev-date\">" + gpFmtDate(e.extracted_date || e.upload_date) + "</div>" +
              "<div class=\"gp-ev-val\">" + val + "</div>" +
              vBadge + "</div>";
          }).join("") + "</div>";
        }
      }
    }).catch(function(e) {
      var nm2 = document.getElementById("gp-dp-name"); if (nm2) nm2.textContent = "Error loading goal";
      var ev2 = document.getElementById("gp-dp-evidence"); if (ev2) ev2.innerHTML = "<div style=\"color:var(--red);font-size:var(--fs-sm)\">" + gpEsc(e.message) + "</div>";
    });
  };

  window.gpCloseDetail = function() {
    document.getElementById("gp-detail-panel").classList.remove("open");
    document.getElementById("gp-detail-overlay").style.display = "none";
  };

  window.gpSaveProgress = function() {
    var sec = document.getElementById("gp-dp-edit-section");
    if (!sec) return;
    var gid = sec.dataset.goalId;
    var inp = document.getElementById("gp-dp-prog-inp");
    var val = parseFloat((inp && inp.value) || 0);
    if (isNaN(val)) { toast("Enter a valid number", "err"); return; }
    var btn = sec.querySelector("button");
    if (btn) { btn.disabled = true; btn.textContent = "Saving..."; }
    gpFetch("alvoraa_portal.goals_api.set_goal_progress", {goal_id: gid, actual_progress: val})
      .then(function() {
        toast("Progress updated", "ok");
        window.gpOpenDetail(gid);
        _gpCtx = null;
      })
      .catch(function(e) {
        toast((e && e.message) || "Failed to save progress", "err");
        if (btn) { btn.disabled = false; btn.textContent = "Save"; }
      });
  };

  window.dpEvFileChanged = function() {
    var f = document.getElementById("dp-ev-file");
    var lbl = document.getElementById("dp-ev-file-name");
    if (lbl) lbl.textContent = (f && f.files && f.files.length) ? f.files[0].name : "Click to upload (image, PDF...)";
  };

  window.gpSubmitPanelEvidence = function(gid) {
    var amount  = (document.getElementById("dp-ev-amount") || {}).value || "";
    var date    = (document.getElementById("dp-ev-date")   || {}).value || "";
    var note    = (document.getElementById("dp-ev-note")   || {}).value || "";
    var fileEl  = document.getElementById("dp-ev-file");
    var hasFile = fileEl && fileEl.files && fileEl.files.length > 0;
    if (!date) { toast("Please select a date", "err"); return; }
    if (!amount && !note && !hasFile) { toast("Enter a value, note, or attach a file", "err"); return; }
    var btn = document.getElementById("dp-ev-btn");
    if (btn) { btn.disabled = true; btn.textContent = "Submitting..."; }

    function doSubmit(fileUrl) {
      api("submit_goal_evidence_portal", {
        goal_id: gid, evidence_type: "Manual Entry",
        value: amount || null,
        extracted_date: date,
        raw_extracted_data: note || null, evidence_file: fileUrl || null,
      }, function() {
        toast("Evidence sent to your manager for approval", "ok");
        window.gpOpenDetail(gid);
        _goalData = null; _gpCtx = null;
      }, function(e) { if (mayHaveGone(e)) { sayMayHaveGone(e); return; }
        toast((e && e.message) || "Failed to submit evidence", "err");
        if (btn) { btn.disabled = false; btn.textContent = "Submit"; }
      });
    }

    if (hasFile) {
      if (btn) btn.textContent = "Uploading file...";
      var fd = new FormData();
      fd.append("file", fileEl.files[0]);
      fd.append("is_private", "1");
      var ctrl = new AbortController();
      var timer = setTimeout(function() { ctrl.abort(); }, 30000);
      fetch("/api/method/upload_file", {
        method: "POST",
        headers: {"X-Frappe-CSRF-Token": frappe.csrf_token || ""},
        body: fd, signal: ctrl.signal,
      })
      .then(function(r) { clearTimeout(timer); return r.json(); })
      .then(function(resp) {
        var url = resp.message && resp.message.file_url;
        if (!url) { toast("File upload failed", "err"); if (btn) { btn.disabled = false; btn.textContent = "Submit"; } return; }
        doSubmit(url);
      })
      .catch(function(e) {
        clearTimeout(timer);
        toast((e && e.name === "AbortError") ? "Upload timed out" : "File upload failed", "err");
        if (btn) { btn.disabled = false; btn.textContent = "Submit"; }
      });
    } else {
      doSubmit(null);
    }
  };

  /* ── Appraisals panel (sidebar) ─────────────────────
     A list of every appraisal the caller may see, opening into the detail
     screen. HR additionally gets "New Appraisal Process", which creates the
     cycle and generates its appraisals in one step. */

  var _apLoaded = false;
  var _apCurrent = null;

  window._gpLoadAppraisal = function(force) {
    if (_apLoaded && !force) return;
    _apLoaded = true;
    apLoadList();
  };

  window.apBack = function() {
    document.getElementById("ap-detail-view").style.display = "none";
    document.getElementById("ap-list-view").style.display = "";
    _apCurrent = null;
    apLoadList();
  };

  window.apLoadList = function() {
    document.getElementById("ap-detail-view").style.display = "none";
    document.getElementById("ap-list-view").style.display = "";
    pfSetHtml("ap-list-body", pfEmpty("Loading appraisals…"));

    // The cycle picker is filled from the shared performance context.
    pfFillCycleSelect("ap-cycle", pfVal("ap-cycle"));
    var cySel = document.getElementById("ap-cycle");
    if (cySel && cySel.options.length && cySel.options[0].value !== "") {
      cySel.insertAdjacentHTML("afterbegin", "<option value=\"\">All cycles</option>");
      if (!pfVal("ap-cycle")) cySel.value = "";
    }

    pf("list_appraisals", {cycle: pfVal("ap-cycle"), status: pfVal("ap-status")})
      .then(function(d) {
        var btn = document.getElementById("ap-new-btn");
        if (btn) btn.style.display = d.is_hr ? "" : "none";
        var sub = document.getElementById("ap-sub");
        if (sub) sub.textContent = d.is_hr
          ? "Every appraisal in the organisation"
          : "Your appraisal, and your team's";
        pfSetHtml("ap-list-body", apListHtml(d));
      })
      .catch(function(e) {
        pfSetHtml("ap-list-body",
          "<div class=\"callout callout-warn\">Failed to load appraisals: " + gpEsc(e.message) + "</div>");
      });
  };

  function apListHtml(d) {
    var rows = d.appraisals || [];
    if (!rows.length) {
      return pfEmpty(d.is_hr
        ? 'No appraisals yet. Use "New Appraisal Process" to start one.'
        : "No appraisals for you or your team yet.");
    }
    var c = d.counts || {};
    var head = "<div class=\"tv-meta\" style=\"margin-bottom:10px\">" +
      c.total + " appraisal" + (c.total === 1 ? "" : "s") + " · " +
      c.submitted + " submitted · " + c.draft + " open</div>";

    return head + "<div class=\"pf-card\"><div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
      "<th>Employee</th><th>Cycle</th><th>Period</th>" +
      "<th class=\"pf-num\">Goal</th><th class=\"pf-num\">Self</th>" +
      "<th class=\"pf-num\">Final</th><th>Status</th><th></th>" +
      "</tr></thead><tbody>" +
      rows.map(function(r) {
        return "<tr>" +
          "<td style=\"font-weight:600\">" + gpEsc(r.employee_name) +
            (r.is_own ? " <span class=\"tv-badge tv-badge-obj\">You</span>" : "") +
            "<div class=\"pf-card-meta\">" + gpEsc(r.designation || "—") + "</div></td>" +
          "<td>" + gpEsc(r.appraisal_cycle) +
            "<div class=\"pf-card-meta\">" + gpEsc(r.cycle_status || "") + "</div></td>" +
          "<td>" + gpFmtDate(r.start_date) + " – " + gpFmtDate(r.end_date) + "</td>" +
          "<td class=\"pf-num\">" + pfNum(r.total_score, 2) + "</td>" +
          "<td class=\"pf-num\">" + pfNum(r.self_score, 2) + "</td>" +
          "<td class=\"pf-num\" style=\"font-weight:700\">" + pfNum(r.final_score, 2) + "</td>" +
          "<td>" + (r.status === "Submitted"
            ? "<span class=\"badge b-completed\">Submitted</span>"
            : "<span class=\"badge b-draft\">Draft</span>") + "</td>" +
          "<td><button class=\"btn btn-outline btn-sm\" onclick=\"apOpen('" + gpEsc(r.name) + "')\">Open</button></td>" +
        "</tr>";
      }).join("") + "</tbody></table></div></div>";
  }

  window.apOpen = function(name) {
    _apCurrent = name;
    document.getElementById("ap-list-view").style.display = "none";
    document.getElementById("ap-detail-view").style.display = "";
    pfSetHtml("ap-d-msg", "");
    pfSetHtml("ap-d-items", "");
    var refresh = document.getElementById("ap-d-refresh");
    if (refresh) refresh.onclick = function() { apOpen(name); };
    gpLoadPerformance(name);
  };

  /* Everything attached to the cycle — scored or not — with passed deadlines
     called out. This is the "what is being considered" view, separate from the
     scored table below it. */
  window.apLoadCycleItems = function(cycle, employee) {
    if (!cycle) return;
    pf("get_cycle_items", {cycle: cycle, employee: employee || ""}).then(function(d) {
      var items = (d.goals || []).concat(d.kpis || []);
      if (!items.length) { pfSetHtml("ap-d-items", ""); return; }

      var rows = items.map(function(i) {
        var end = i.end_date || i.period_end || "";
        var pct = i.kind === "goal" ? i.progress_pct : i.attainment_pct;
        return "<tr class=\"" + (i.is_overdue ? "ap-overdue" : "") + "\">" +
          "<td><span class=\"tv-badge " + (i.kind === "goal" ? "tv-badge-obj" : "tv-badge-kpi") + "\">" +
            (i.kind === "goal" ? "Objective" : "KPI") + "</span></td>" +
          "<td style=\"font-weight:600\">" + gpEsc(i.label) +
            (i.is_overdue ? " <span class=\"ap-overdue-tag\">deadline passed</span>" : "") + "</td>" +
          "<td class=\"pf-num\">" + pfNum(i.target_value, 2) + " " + gpEsc(i.unit || "") + "</td>" +
          "<td class=\"pf-num\">" + pfNum(pct) + "%</td>" +
          "<td class=\"pf-num\">" + (flt0(i.weightage) ? pfNum(i.weightage) + "%" :
            "<span style=\"color:var(--text3)\">context only</span>") + "</td>" +
          "<td>" + gpFmtDate(end) + "</td>" +
        "</tr>";
      }).join("");

      var warn = d.overdue_count
        ? pfAlert("warn", d.overdue_count + " item" + (d.overdue_count === 1 ? "" : "s") +
                  " passed their deadline. They stay in the review — that is what there is to discuss.")
        : "";
      var wt = d.weightage_complete
        ? pfAlert("ok", "Weightage allocated: " + pfNum(d.total_weightage) + "% — complete.")
        : pfAlert("warn", "Weightage allocated: " + pfNum(d.total_weightage) +
                  "% of 100%. Items at 0% ride along for context but are not scored.");

      pfSetHtml("ap-d-items",
        "<div class=\"card\" style=\"margin-bottom:16px\">" +
        "<div class=\"card-header\"><span class=\"card-title\">Considered in This Cycle</span>" +
          "<span style=\"font-size:var(--fs-xs);color:var(--text3);margin-left:auto\">" +
          items.length + " item" + (items.length === 1 ? "" : "s") + "</span></div>" +
        "<div class=\"card-body\">" + warn + wt +
        "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
          "<th>Type</th><th>Name</th><th class=\"pf-num\">Target</th>" +
          "<th class=\"pf-num\">Progress</th><th class=\"pf-num\">Weight</th><th>Ends</th>" +
        "</tr></thead><tbody>" + rows + "</tbody></table></div></div></div>");
    }).catch(function() { pfSetHtml("ap-d-items", ""); });
  };

  function flt0(v) { return parseFloat(v || 0); }

  // flt() is a Frappe global on DESK pages. This is a website page, where it is not
  // guaranteed, and the distribution code below calls it ~10 times - an undefined flt
  // makes those handlers throw ReferenceError and silently do nothing. Prefer Frappe's
  // when present, otherwise fall back. Every call site here passes a single argument.
  var flt = window.flt || function (v) { return parseFloat(v || 0); };

  window.apSync = function(name) {
    pfSetHtml("ap-d-msg", pfAlert("warn", "Pulling ratings…"));
    pf("sync_appraisal_from_kpis", {appraisal: name}).then(function(r) {
      pfSetHtml("ap-d-msg", pfAlert("ok", r.message +
        " Goal score " + pfNum(r.total_score, 2) + " / 5."));
      gpLoadPerformance(name);
    }).catch(function(e) { pfSetHtml("ap-d-msg", pfAlert("err", e.message)); });
  };

  window.apSubmit = function(name) {
    if (!confirm("Submit this appraisal? It cannot be edited afterwards.")) return;
    pfSetHtml("ap-d-msg", pfAlert("warn", "Submitting…"));
    pf("submit_appraisal", {appraisal: name}).then(function(r) {
      pfSetHtml("ap-d-msg", pfAlert("ok", "Submitted. Final score " +
        pfNum(r.final_score, 2) + " / 5."));
      gpLoadPerformance(name);
    }).catch(function(e) { pfSetHtml("ap-d-msg", pfAlert("err", e.message)); });
  };

  window.apOpenProcessModal = function() {
    pfClearErr("ap-process-error");
    ["ap-p-name", "ap-p-start", "ap-p-end", "ap-p-desc"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    var gen = document.getElementById("ap-p-generate"); if (gen) gen.checked = true;
    pfOpenModal("ap-process-modal");
  };

  window.apSubmitProcess = function() {
    var name = pfVal("ap-p-name"), s = pfVal("ap-p-start"), e = pfVal("ap-p-end");
    if (!name || !s || !e) {
      pfShowErr("ap-process-error", "Name, start date and end date are required.");
      return;
    }
    var gen = document.getElementById("ap-p-generate");
    pf("hr_start_appraisal_process", {
      cycle_name: name, start_date: s, end_date: e, description: pfVal("ap-p-desc"),
      generate: gen && gen.checked ? 1 : 0
    }).then(function(r) {
      pfCloseModal("ap-process-modal");
      var msg = r.message;
      var kind = "ok";
      if (r.skipped && r.skipped.length) {
        kind = "warn";
        msg += " Skipped: " + r.skipped.map(function(x) { return x.employee; }).join(", ") +
               " — check their KPI weightages total 100%.";
      }
      pfSetHtml("ap-msg", pfAlert(kind, msg));
      // The new cycle has to appear in every cycle picker, not just this one.
      return pf("get_performance_context").then(function(ctx) {
        _pfCtx = ctx; pfFillCycleSelects(); apLoadList();
      });
    }).catch(function(err) {
      pfShowErr("ap-process-error", err.message);
    });
  };

  /* "Score breakdown": the three weighted parts and the attendance figures
     behind the final score, when the cycle includes attendance. */
  function gpScoreBreakdown(ap, c) {
    var sc = (c && c.scoring) || {};
    if (!sc.include_attendance) return "";
    function bar(lbl, weight, val) {
      var v = parseFloat(val || 0);
      var pct = Math.max(0, Math.min(100, Math.round(v / 5 * 100)));
      return "<div style=\"display:grid;grid-template-columns:150px 1fr 60px;gap:10px;align-items:center;margin:6px 0\">" +
        "<div style=\"font-size:var(--fs-base)\">" + lbl + " <span style=\"color:var(--text3)\">" + weight + "%</span></div>" +
        "<div class=\"gp-score-meter\"><div class=\"gp-score-fill\" style=\"width:" + pct + "%\"></div></div>" +
        "<div style=\"text-align:right;font-weight:700\">" + v.toFixed(2) + "</div></div>";
    }
    var att = [];
    if (ap.attendance_reliability_pct != null) att.push("Reliability " + parseFloat(ap.attendance_reliability_pct).toFixed(1) + "%");
    if (ap.attendance_punctuality_pct != null) att.push("Punctuality " + parseFloat(ap.attendance_punctuality_pct).toFixed(1) + "%");
    if (parseFloat(ap.attendance_deduction_days || 0) > 0) att.push(parseFloat(ap.attendance_deduction_days) + " day(s) deducted by the late-coming rule");
    return "<div class=\"card\" style=\"margin-bottom:16px\"><div class=\"card-body\">" +
      "<div style=\"font-weight:700;margin-bottom:6px\">Score breakdown</div>" +
      bar("Targets", sc.goal_weight, ap.total_score) +
      bar("Manager feedback", sc.feedback_weight, ap.avg_feedback_score) +
      bar("Attendance", sc.attendance_weight, ap.attendance_score) +
      (att.length ? "<div style=\"font-size:var(--fs-sm);color:var(--text2);margin-top:8px\">" + gpEsc(att.join(" · ")) + "</div>" : "") +
      (ap.attendance_summary ? "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-top:4px\">" + gpEsc(ap.attendance_summary) + "</div>"
                             : "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-top:4px\">The attendance score is worked out when the appraisal is saved.</div>") +
      "</div></div>";
  }

  function gpLoadPerformance(appraisalName) {
    var body   = document.getElementById("gp-perf-body");
    var banner = document.getElementById("gp-perf-cycle-banner");
    body.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-text\">Loading appraisal…</div></div>";

    // A named appraisal comes from the list; without one, fall back to the
    // caller's own for the current cycle.
    var call = appraisalName
      ? pf("get_appraisal", {appraisal: appraisalName})
      : gpFetch("alvoraa_portal.goals_api.get_appraisal_data");

    call.then(function(d) {
      var c = d.cycle, ap = d.appraisal;
      if (ap) {
        var t = document.getElementById("ap-d-title");
        var s = document.getElementById("ap-d-sub");
        if (t) t.textContent = (ap.employee_name || "Appraisal") +
                               (ap.is_own ? " (you)" : "");
        if (s) s.textContent = [ap.designation, ap.department, c && c.cycle_name]
                                 .filter(Boolean).join(" · ");
        if (c) apLoadCycleItems(c.name, ap.employee);
      }

      if (c && banner) {
        banner.innerHTML = "<div class=\"cycle-banner\" style=\"margin-bottom:20px\">" +
          "<div class=\"cycle-dot\"></div>" +
          "<div class=\"cycle-info\"><div class=\"cycle-name\">" + gpEsc(c.cycle_name) + "</div>" +
          "<div class=\"cycle-dates\">" + gpFmtDate(c.start_date) + " – " + gpFmtDate(c.end_date) + "</div></div>" +
          "<span class=\"cycle-status\">" + gpEsc(c.status) + "</span></div>";
      } else if (banner) { banner.innerHTML = ""; }

      if (!c) {
        body.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-icon\"><i class=ic-clipboard></i></div>" +
          "<div class=\"empty-state-text\">No active appraisal cycle. Your HR team hasn't started a performance review yet.</div></div>";
        return;
      }
      if (!ap) {
        body.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-icon\"><i class=ic-clipboard></i></div>" +
          "<div class=\"empty-state-text\">Your appraisal hasn't been set up yet. Contact your HR Manager.</div></div>";
        return;
      }

      var scores = [
        {val: ap.total_score, lbl: "Goal Score"},
        {val: ap.self_score,  lbl: "Self Rating"},
        {val: ap.final_score, lbl: "Final Score"},
      ];
      /* A score of null means the review has not released it yet (decision 3).
         That is different from a score of nothing, so it is said in words. */
      var scoreHtml = "<div class=\"gp-score-grid\">" + scores.map(function(s) {
        var pending = (s.val === null || s.val === undefined);
        var pct = (!pending && s.val) ? Math.round((parseFloat(s.val) / 5) * 100) : 0;
        return "<div class=\"gp-score-card\">" +
          "<div class=\"gp-score-val\"" + (pending ? " style=\"font-size:var(--fs-sm);color:var(--text3)\"" : "") + ">" +
            (pending ? "Not shared yet" : (s.val ? parseFloat(s.val).toFixed(1) : "—")) + "</div>" +
          "<div class=\"gp-score-lbl\">" + s.lbl + "</div>" +
          "<div class=\"gp-score-meter\"><div class=\"gp-score-fill\" style=\"width:" + pct + "%\"></div></div></div>";
      }).join("") + "</div>" +
      (scores.some(function(s) { return s.val === null || s.val === undefined; })
        ? "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin:-8px 0 16px\">" +
            "Your scores appear here once your manager sends the review to you.</div>"
        : "");

      var kraHtml;
      if (ap.goals && ap.goals.length) {
        // KPI-scored appraisal: HRMS fills the manual `goals` table, each row
        // a KPI rated out of 5 by the line manager.
        /* Item ratings are given inside the review and shown there, never on a
           screen outside it (slice 010 group D, R14). This table keeps the list
           of items and their weights, which is what the screen is for. */
        kraHtml = "<div class=\"card\" style=\"margin-bottom:16px\">" +
          "<div class=\"card-header\"><span class=\"card-title\">KPI Performance</span>" +
          "<span style=\"font-size:var(--fs-xs);color:var(--text3);margin-left:auto\">Rated inside the review</span></div>" +
          "<div class=\"tbl-wrap\"><table class=\"kra-table\"><thead><tr>" +
          "<th>KPI</th><th>Weight</th>" +
          "</tr></thead><tbody>" +
          ap.goals.map(function(g) {
            return "<tr><td style=\"font-weight:600\">" + gpEsc(g.kra) + "</td>" +
              "<td>" + parseFloat(g.per_weightage || 0).toFixed(0) + "%</td></tr>";
          }).join("") + "</tbody></table></div>" +
          "<div style=\"padding:0 16px 14px;font-size:var(--fs-sm);color:var(--text3)\">" +
            "Each item's rating lives in the review itself. Open your review to see it.</div></div>";
      } else if (ap.kras && ap.kras.length) {
        kraHtml = "<div class=\"card\" style=\"margin-bottom:16px\">" +
          "<div class=\"card-header\"><span class=\"card-title\">KRA Performance</span></div>" +
          "<div class=\"tbl-wrap\"><table class=\"kra-table\"><thead><tr>" +
          "<th>Key Result Area</th><th>Weight</th><th>Goal Completion</th><th>Score</th>" +
          "</tr></thead><tbody>" +
          ap.kras.map(function(k) {
            var cpct = Math.round(k.goal_completion || 0);
            return "<tr><td style=\"font-weight:600\">" + gpEsc(k.kra) + "</td>" +
              "<td>" + (k.per_weightage || 0) + "%</td>" +
              "<td>" + cpct + "%<div class=\"kra-mini-bar\"><div class=\"kra-mini-fill\" style=\"width:" + cpct + "%\"></div></div></td>" +
              "<td style=\"font-weight:700;color:var(--primary)\">" + parseFloat(k.goal_score || 0).toFixed(2) + "</td></tr>";
          }).join("") + "</tbody></table></div></div>";
      } else {
        kraHtml = "<div class=\"card\" style=\"margin-bottom:16px\"><div class=\"card-body\"><div class=\"kra-empty\">" +
          "No KPIs or KRAs are attached to this appraisal yet. Your HR team assigns these when the cycle is set up." +
          "</div></div></div>";
      }

      // Writing reflections belongs to the person being appraised; submitting
      // belongs to their manager (or HR). A manager viewing a report's
      // appraisal therefore sees the text read-only, plus a Submit action.
      var mine = ap.can_self_assess === undefined
        ? ap.docstatus === 0                 // own-appraisal fallback path
        : !!ap.can_self_assess;
      var statusBadge = ap.docstatus === 1
        ? "<span class=\"badge b-completed\" style=\"margin-left:auto\">Submitted</span>"
        : "<span class=\"badge b-draft\" style=\"margin-left:auto\">Draft</span>";
      var selfHtml = "<div class=\"card\">" +
        "<div class=\"card-header\"><span class=\"card-title\">Self Assessment</span>" + statusBadge + "</div>" +
        "<div class=\"card-body\">" +
        "<div class=\"gp-error\" id=\"gp-perf-error\"></div>" +
        "<div class=\"gp-success\" id=\"gp-perf-success\"></div>" +
        "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-bottom:8px\">" +
          (mine ? "Reflect on your performance, key achievements, and areas for improvement this cycle."
                : "Written by " + gpEsc(ap.employee_name || "the employee") + ".") + "</div>" +
        "<textarea class=\"gp-textarea\" id=\"gp-self-reflections\" placeholder=\"" +
          (mine ? "Share your reflections…" : "Nothing written yet.") + "\"" +
          (mine ? "" : " disabled") + ">" + gpEsc(gpHtmlToText(ap.reflections)) + "</textarea>" +
        (mine
          ? "<div style=\"margin-top:12px;display:flex;justify-content:flex-end\">" +
            "<button class=\"btn btn-primary btn-sm\" id=\"gp-save-ref-btn\" onclick=\"gpSaveReflections('" + gpEsc(ap.name) + "')\">Save Self-Assessment</button></div>"
          : (ap.docstatus === 1
             ? "<div style=\"margin-top:8px;font-size:var(--fs-xs);color:var(--text3)\">Appraisal submitted — contact HR Manager for changes.</div>"
             : "")) +
        "</div></div>";

      var reviewHtml = "";
      if (ap.can_review) {
        reviewHtml = "<div class=\"card\" style=\"margin-top:16px\">" +
          "<div class=\"card-header\"><span class=\"card-title\">Manager Actions</span></div>" +
          "<div class=\"card-body\">" +
          "<div style=\"font-size:var(--fs-sm);color:var(--text2);margin-bottom:10px\">" +
            "Ratings live on the KPIs — set them in Reviews, then pull them through and submit." +
          "</div>" +
          "<div style=\"display:flex;gap:8px;flex-wrap:wrap\">" +
            "<button class=\"btn btn-outline btn-sm\" onclick=\"apSync('" + gpEsc(ap.name) + "')\">Pull latest KPI ratings</button>" +
            "<button class=\"btn btn-primary btn-sm\" onclick=\"apSubmit('" + gpEsc(ap.name) + "')\">Submit Appraisal</button>" +
          "</div></div></div>";
      }

      body.innerHTML = scoreHtml + gpScoreBreakdown(ap, c) + kraHtml + selfHtml + reviewHtml;
    }).catch(function(e) {
      if (body) body.innerHTML = "<div class=\"callout callout-warn\">Failed to load appraisal: " + gpEsc(e.message) + "</div>";
    });
  }

  window.gpSaveReflections = function(appraisalId) {
    var btn   = document.getElementById("gp-save-ref-btn");
    var errEl = document.getElementById("gp-perf-error");
    var okEl  = document.getElementById("gp-perf-success");
    if (errEl) errEl.style.display = "none";
    if (okEl)  okEl.style.display  = "none";

    var text = ((document.getElementById("gp-self-reflections") || {}).value || "").trim();
    if (!text) {
      if (errEl) { errEl.textContent = "Please write your reflections before saving."; errEl.style.display = "block"; }
      return;
    }
    if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }

    // Store as simple HTML: the field is a Text Editor, so plain text with
    // newlines would collapse into one run wherever it is rendered.
    gpFetch("alvoraa_portal.goals_api.save_self_assessment",
            {appraisal_id: appraisalId, reflections: gpTextToHtml(text)}).then(function() {
      if (okEl) { okEl.textContent = "Self-assessment saved successfully."; okEl.style.display = "block"; }
      if (btn)  { btn.innerHTML = "Saved <i class=ic-check></i>"; }
      setTimeout(function() {
        if (btn) { btn.disabled = false; btn.textContent = "Save Self-Assessment"; }
        if (okEl) okEl.style.display = "none";
      }, 3000);
    }).catch(function(e) {
      if (errEl) { errEl.textContent = e.message; errEl.style.display = "block"; }
      if (btn)   { btn.disabled = false; btn.textContent = "Save Self-Assessment"; }
    });
  };

  // ── Team Tab ───────────────────────────────────────
  window.gpLoadTeam = function(force) {
    var el = document.getElementById("gp-team-body");
    if (!force && el && el.innerHTML && el.innerHTML.indexOf("Loading") < 0) return;
    if (el) el.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-text\">Loading team goals…</div></div>";

    gpFetch("alvoraa_portal.goals_api.get_team_goals").then(function(team) {
      if (!Array.isArray(team) || !team.length) {
        if (el) el.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-icon\"><i class=ic-users></i></div><div class=\"empty-state-text\">No direct reports found.</div></div>";
        return;
      }
      if (el) el.innerHTML = "<div class=\"gp-team-grid\">" + team.map(function(m) {
        var initials = ((m.employee_name || "?") + "?").slice(0, 2).toUpperCase();
        var pct = m.avg_progress || 0;
        var pfill = pct > 70 ? "var(--green)" : pct > 40 ? "var(--amber)" : "var(--red)";
        var alert = m.at_risk > 0
          ? "<span class=\"badge b-at-risk\">" + m.at_risk + " at risk</span>"
          : "<span class=\"badge b-on-track\">" + (m.on_track||0) + " on track</span>";
        return "<div class=\"gp-team-card\">" +
          "<div class=\"gp-team-top\">" +
            (m.avatar
              ? "<div class=\"gp-team-av\"><img src=\"" + gpEsc(m.avatar) + "\" alt=\"\"></div>"
              : "<div class=\"gp-team-av\">" + initials + "</div>") +
            "<div><div class=\"gp-team-name\">" + gpEsc(m.employee_name) + "</div>" +
            "<div class=\"gp-team-role\">" + gpEsc(m.designation || "—") + "</div></div>" +
          "</div>" +
          "<div class=\"gp-team-stats\">" +
            "<div><span>" + (m.total_goals||0) + "</span> goals</div>" +
            "<div><span>" + (m.on_track||0) + "</span> on track</div>" +
            (m.at_risk > 0 ? "<div style=\"color:var(--amber)\"><span>" + m.at_risk + "</span> at risk</div>" : "") +
          "</div>" +
          "<div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:6px\">" +
            "<div style=\"font-size:var(--fs-xs);color:var(--text3)\">Avg progress</div>" +
            "<div style=\"font-size:var(--fs-sm);font-weight:700\">" + pct + "%</div>" +
          "</div>" +
          "<div class=\"gp-team-pbar\"><div class=\"gp-team-pfill\" style=\"width:" + pct + "%;background:" + pfill + "\"></div></div>" +
          "<div style=\"margin-top:10px\">" + alert + "</div></div>";
      }).join("") + "</div>";
    }).catch(function(e) {
      if (el) el.innerHTML = "<div class=\"callout callout-warn\">Failed to load team goals: " + gpEsc(e.message) + "</div>";
    });
  };

  /* ══════════════════════════════════════════════════════════════════
     Performance: KPIs, manager reviews, HR administration.
     All reads and writes go through alvoraa_portal.performance_api,
     which enforces role and reporting-line scoping server-side — nothing
     here is trusted to keep a user inside their own data.
     ══════════════════════════════════════════════════════════════════ */

  var PF = "alvoraa_portal.performance_api.";
  var _pfCtx = null;
  var _pfSetup = null;

  function pf(method, args) { return gpFetch(PF + method, args || {}); }

  function pfNum(v, dp) { return parseFloat(v || 0).toFixed(dp === undefined ? 1 : dp); }

  function pfAttColor(pct) {
    if (pct >= 100) return "var(--green)";
    if (pct >= 70)  return "var(--primary)";
    if (pct >= 40)  return "var(--amber)";
    return "var(--red)";
  }

  function pfAlert(kind, msg) {
    return "<div class=\"pf-alert pf-alert-" + kind + "\">" + gpEsc(msg) + "</div>";
  }

  function pfEmpty(msg) {
    return "<div class=\"empty-state\"><div class=\"empty-state-text\">" + gpEsc(msg) + "</div></div>";
  }

  window.pfSetHtml = function pfSetHtml(id, html) {
    var el = document.getElementById(id);
    if (el) el.innerHTML = html;
  };

  // These modals reuse the .gp-backdrop shell, which is revealed by `.open`
  // (`.gp-backdrop.open{display:flex}`) — not `.show`.
  window.pfCloseModal = function(id) {
    var el = document.getElementById(id);
    if (el) el.classList.remove("open");
  };

  /* ── Toast notifications ── */
  (function() {
    var wrap;
    function getWrap() {
      if (!wrap || !wrap.parentNode) {
        wrap = document.createElement("div");
        wrap.className = "gp-toast-wrap";
        document.body.appendChild(wrap);
      }
      return wrap;
    }
    window.gpShowToast = function(msg, type) {
      var t = document.createElement("div");
      t.className = "gp-toast " + (type || "success");
      t.textContent = msg;
      getWrap().appendChild(t);
      setTimeout(function() {
        t.classList.add("gp-toast-out");
        setTimeout(function() { t.remove(); }, 280);
      }, 3500);
    };
  }());

  window.toggleRevSec = function(key) {
    var body = document.getElementById("rev-body-" + key);
    var chev = document.getElementById("rev-chev-" + key);
    if (!body) return;
    var open = body.style.display !== "none";
    body.style.display = open ? "none" : "";
    if (chev) chev.style.transform = open ? "rotate(-90deg)" : "";
  };

  window.pfOpenModal = function pfOpenModal(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add("open");
  };

  // .gp-error is display:none with no .show rule — the rest of this page
  // reveals it by setting display inline, so do the same.
  window.pfShowErr = function pfShowErr(id, msg) {
    var el = document.getElementById(id);
    if (!el) return;
    el.textContent = msg;
    el.style.display = "block";
  };

  window.pfClearErr = function pfClearErr(id) {
    var el = document.getElementById(id);
    if (el) el.style.display = "none";
  };

  function pfVal(id) {
    var el = document.getElementById(id);
    return el ? el.value.trim() : "";
  }

  function pfFillCycleSelect(id, selected) {
    var sel = document.getElementById(id);
    if (!sel) return;
    var cycles = (_pfCtx && _pfCtx.cycles) || [];
    if (!cycles.length) { sel.innerHTML = "<option value=\"\">No cycles yet</option>"; return; }
    sel.innerHTML = cycles.map(function(c) {
      return "<option value=\"" + gpEsc(c.name) + "\">" +
             gpEsc(c.cycle_name || c.name) + " · " + gpEsc(c.status) + "</option>";
    }).join("");
    if (selected) sel.value = selected;
  }

  // Populate the three cycle pickers from one context fetch.
  function pfFillCycleSelects() {
    var cycles = (_pfCtx && _pfCtx.cycles) || [];
    var activeName = (_pfCtx && _pfCtx.active_cycle) ? _pfCtx.active_cycle.name : "";
    // tv-cycle is a *filter*, so it needs a way back to "no cycle filter".
    // The others pick a cycle to act on, where blank would be meaningless.
    [["tv-cycle", true], ["pf-review-cycle", false], ["pf-hr-cycle", false]].forEach(function(pair) {
      var id = pair[0], allowAll = pair[1];
      var sel = document.getElementById(id);
      if (!sel) return;
      // An empty value means "All cycles" once the select exists, but on the
      // very first fill it just means "not populated yet" — so only then do we
      // fall back to the active cycle.
      var firstFill = sel.options.length === 0;
      var keep = sel.value;
      if (!cycles.length) {
        sel.innerHTML = "<option value=\"\">No cycles yet</option>";
        return;
      }
      var opts = cycles.map(function(c) {
        return "<option value=\"" + gpEsc(c.name) + "\">" +
               gpEsc(c.cycle_name || c.name) + " · " + gpEsc(c.status) + "</option>";
      }).join("");
      sel.innerHTML = (allowAll ? "<option value=\"\">All cycles</option>" : "") + opts;
      sel.value = firstFill ? activeName : keep;
      if (!sel.value && !allowAll) sel.value = activeName;
    });
  }

  window.pfBoot = function() {
    pf("get_performance_context").then(function(ctx) {
      _pfCtx = ctx;
      pfFillCycleSelects();
      // Reveal role-gated tabs. The server enforces these too; hiding them is
      // only so people are not offered actions they cannot complete.
      /* My team's reviews is the manager's list only; HR's list is in HR Setup
         (decision 37). */
      if (ctx.has_team_reviews) {
        var teamSec = document.getElementById("rev-sec-team-reviews");
        if (teamSec) teamSec.style.display = "";
        if (_gpLoadedTabs && _gpLoadedTabs["reviews"]) pfLoadReviews();
      }
      if (ctx.is_hr) {
        var h = document.getElementById("gtab-hr");
        if (h) h.style.display = "";
        var calBtn = document.getElementById("gtab-calibration");
        if (calBtn) calBtn.style.display = "";
        var distBtn = document.getElementById("gtab-distribution");
        if (distBtn) distBtn.style.display = "";
      }
      // For someone with no reports "Me & my team" is identical to "Just me",
      // and the organisation-wide view is supervisory and not theirs. The
      // server refuses it either way, so do not offer a dead end.
      var scopeSel = document.getElementById("tv-scope");
      if (scopeSel && !ctx.is_manager && !ctx.is_hr) {
        ["team", "organisation"].forEach(function(v) {
          var opt = scopeSel.querySelector('option[value="' + v + '"]');
          if (opt) opt.remove();
        });
        if (["", "team", "organisation"].indexOf(scopeSel.value) >= 0) scopeSel.value = "mine";
      }
    }).catch(function(e) {
      pfSetHtml("tv-body", "<div class=\"callout callout-warn\">Could not load performance context: " + gpEsc(e.message) + "</div>");
    });
  };

/* ── Rating bands: one rule for every screen that places a rating ─────────
   A review's overall rating is the average of its items, so for about half
   the company it is a half-point - 4.5, 3.5 - that is not on the rating
   scale at all. Until 2026-09-19 every screen here matched a rating against
   the scale by exact value and dropped anything unmatched into the lowest
   band. That put 204 of 403 people in the wrong box of the calibration
   grid, in the worst direction, and left the middle column empty.

   Nothing below matches by exact value again. There are two rules, and they
   are deliberately different:

     pfRatingBand        - where a rating sits on the scale, as a third.
                           The 9-box grid places by this. Nothing is rounded.
     pfRatingToBandValue - which bar a rating is drawn on in a distribution
                           chart, where the bars are the named bands.

   Every statistic is worked out from the raw ratings by pfRatingStats,
   never from the rounded chart values. */

/* The scale's values as plain numbers, ascending. */
window.pfScaleValues = function(scale) {
  if (!scale || !scale.items || !scale.items.length) return [];
  return scale.items
    .map(function(it) { return parseFloat(it.value); })
    .filter(function(v) { return !isNaN(v); })
    .sort(function(a, b) { return a - b; });
};

/* Where a rating sits on the scale: 0 low, 1 moderate, 2 high. By its
   position along the scale, not its position in a list, so on a 1-5 scale
   a 4.5 is high and a 3.5 is moderate. Returns null when there is no
   rating to place - an unrated person is never placed anywhere. */
window.pfRatingBand = function(value, values) {
  if (value === null || value === undefined || value === "") return null;
  var v = parseFloat(value);
  if (isNaN(v) || !values || !values.length) return null;
  var lo = values[0], hi = values[values.length - 1];
  if (hi <= lo) return 1;
  var norm = (v - lo) / (hi - lo);
  if (norm < 0) norm = 0;
  if (norm > 1) norm = 1;
  return norm < 1 / 3 ? 0 : (norm < 2 / 3 ? 1 : 2);
};

/* The band a rating is drawn on in a distribution chart, as that band's
   scale value.

   A rating that sits exactly between two bands - a 4.5 between 4 and 5 -
   ROUNDS UP. Where a rating is genuinely ambiguous the benefit goes to the
   employee rather than against them. This moves a lot of people, so it is
   said here in those words for whoever asks later.

   This is for placing a mark on a chart. It is never used for an average. */
window.pfRatingToBandValue = function(value, values) {
  if (value === null || value === undefined || value === "") return null;
  var v = parseFloat(value);
  if (isNaN(v) || !values || !values.length) return null;
  var best = values[0], bestDist = Math.abs(v - values[0]);
  for (var i = 1; i < values.length; i++) {
    var dist = Math.abs(v - values[i]);
    /* "<=" with an ascending list is what makes a tie round up. */
    if (dist <= bestDist + 1e-9) { best = values[i]; bestDist = dist; }
  }
  return best;
};

/* Is there a rating here at all? A rating scale starts at 1, and the field
   holding it is a number that defaults to 0, so a stored 0 means "nobody
   rated this" - unless the scale itself has a 0, in which case 0 is a real
   answer and is kept. */
window.pfHasRating = function(value, values) {
  if (value === null || value === undefined || value === "") return false;
  var v = parseFloat(value);
  if (isNaN(v)) return false;
  if (v !== 0) return true;
  return !!(values && values.indexOf(0) >= 0);
};

/* Average, median and the share in the top two bands - all from the RAW
   ratings. An average of rounded numbers would be a second distortion of
   the same kind as the bug this replaced, so the rounded values never come
   near this function. */
window.pfRatingStats = function(rawValues, scaleValues) {
  var nums = (rawValues || [])
    .map(function(v) { return parseFloat(v); })
    .filter(function(n) { return !isNaN(n); })
    .sort(function(a, b) { return a - b; });
  var n = nums.length;
  if (!n) return {total: 0, avg: null, median: null, pctHigh: 0};
  var sum = nums.reduce(function(s, v) { return s + v; }, 0);
  var mid = Math.floor(n / 2);
  var median = (n % 2) ? nums[mid] : (nums[mid - 1] + nums[mid]) / 2;
  /* "Above expectations" is the top two bands of the scale. */
  var pctHigh = 0;
  if (scaleValues && scaleValues.length > 1) {
    var cut = scaleValues[scaleValues.length - 2];
    var above = nums.filter(function(v) { return v >= cut; }).length;
    pctHigh = Math.round(above / n * 100);
  }
  return {total: n, avg: sum / n, median: median, pctHigh: pctHigh};
};

/* A rating as a person reads it: the band's name when it is exactly that
   band, otherwise the number itself. Never a blank. */
window.pfRatingLabel = function(value, scale) {
  if (value === null || value === undefined || value === "") return "";
  var v = parseFloat(value);
  if (isNaN(v)) return String(value);
  var items = (scale && scale.items) || [];
  for (var i = 0; i < items.length; i++) {
    if (Math.abs(parseFloat(items[i].value) - v) < 1e-9) return items[i].label;
  }
  return String(v);
};

/* ── Performance Distribution (Bell Curve) ──────────────────────── */
(function() {
  var _pdData         = null;
  var _pdCycle        = "";
  var _pdFilteredRows = [];
  var _pdClickedOverall   = null;
  var _pdClickedPotential = null;
  var _pdSortCol = "overall_rating";
  var _pdSortDir = -1;

  var _pdPalette = ["var(--primary)","var(--green)","var(--primary)","var(--amber)","var(--green)","var(--primary)","var(--red)","var(--green)"];
  function _pdColor(name) {
    var h = 0;
    for (var i = 0; i < (name || "").length; i++) h += name.charCodeAt(i);
    return _pdPalette[h % _pdPalette.length];
  }
  function _pdInitials(name) {
    var w = (name || "?").trim().split(/\s+/);
    return (w[0][0] + (w.length > 1 ? w[w.length - 1][0] : "")).toUpperCase();
  }

  /* ── Cycle selector init ──────────────────────────────────── */
  window.pdInit = function() {
    var sel = document.getElementById("pd-cycle-sel");
    if (!sel) return;
    function _populate(cycles) {
      if (!cycles || !cycles.length) {
        sel.innerHTML = "<option value=''>No appraisal cycles found</option>";
        return;
      }
      var sorted = cycles.slice().sort(function(a, b) {
        return (b.start_date || "") > (a.start_date || "") ? 1 : -1;
      });
      sel.innerHTML = sorted.map(function(c) {
        return "<option value='" + gpEsc(c.name) + "'>" + gpEsc(c.cycle_name || c.name) + "</option>";
      }).join("");
      pdLoad();
    }
    if (window._pfCtx && _pfCtx.cycles && _pfCtx.cycles.length) {
      _populate(_pfCtx.cycles);
    } else {
      pf("get_performance_context").then(function(ctx) {
        if (ctx) window._pfCtx = ctx;
        _populate((ctx || {}).cycles || []);
      });
    }
  };

  window.pdLoad = function() {
    var sel = document.getElementById("pd-cycle-sel");
    var cycle = sel ? sel.value : "";
    if (!cycle) return;
    _pdCycle = cycle;
    _pdClickedOverall = null;
    _pdClickedPotential = null;
    pfSetHtml("pd-body", "<div class='empty-state'><div class='empty-state-text'>Loading distribution data…</div></div>");
    pf("get_calibration_matrix", {cycle: cycle}).then(function(d) {
      _pdData = d;
      _pdPopulateFilters(d.filter_options);
      _pdFilteredRows = d.rows || [];
      _pdRefresh();
    }).catch(function(e) {
      pfSetHtml("pd-body", "<div class='callout callout-warn'>Failed to load: " + gpEsc((e || {}).message || String(e)) + "</div>");
    });
  };

  /* ── Filter panel ─────────────────────────────────────────── */
  function _pdPopulateFilters(opts) {
    if (!opts) return;
    function _fillSel(id, items) {
      var el = document.getElementById(id);
      if (!el) return;
      el.innerHTML = items.map(function(it) {
        var val = typeof it === "object" ? it.id : it;
        var lbl = typeof it === "object" ? it.name : it;
        return "<option value='" + gpEsc(String(val)) + "'>" + gpEsc(lbl) + "</option>";
      }).join("");
    }
    _fillSel("pd-f-dept",    opts.departments    || []);
    _fillSel("pd-f-desig",   opts.designations   || []);
    _fillSel("pd-f-emptype", opts.employment_types || []);
    _fillSel("pd-f-mgr",     opts.managers       || []);
    var hasOpts = (opts.departments && opts.departments.length) || (opts.managers && opts.managers.length);
    var fBtn = document.getElementById("pd-filter-btn");
    if (fBtn) fBtn.style.display = hasOpts ? "" : "none";
    var pdExpBtn = document.getElementById("pd-export-btn");
    if (pdExpBtn) pdExpBtn.style.display = "";
    var fPanel = document.getElementById("pd-filters");
    if (fPanel) fPanel.style.display = "none";
  }

  function _pdGetSelected(id) {
    var el = document.getElementById(id);
    if (!el) return [];
    return Array.from(el.selectedOptions).map(function(o) { return o.value; });
  }

  window.pdToggleFilters = function() {
    var el = document.getElementById("pd-filters");
    if (el) el.style.display = el.style.display === "none" ? "" : "none";
  };

  window.pdApplyFilters = function() {
    if (!_pdData) return;
    var fD = _pdGetSelected("pd-f-dept"),   fDes = _pdGetSelected("pd-f-desig");
    var fE = _pdGetSelected("pd-f-emptype");
    var fM = _pdGetSelected("pd-f-mgr");
    _pdFilteredRows = (_pdData.rows || []).filter(function(r) {
      if (fD.length   && !fD.includes(r.department))       return false;
      if (fDes.length && !fDes.includes(r.designation))    return false;
      if (fE.length   && !fE.includes(r.employment_type))  return false;
      if (fM.length   && !fM.includes(r.reports_to))       return false;
      return true;
    });
    var activeCount = fD.length + fDes.length + fE.length + fM.length;
    var badge = document.getElementById("pd-filter-badge");
    if (badge) { badge.hidden = !activeCount; badge.textContent = activeCount; }
    _pdClickedOverall = null;
    _pdClickedPotential = null;
    _pdRefresh();
  };

  window.pdClearFilters = function() {
    ["pd-f-dept","pd-f-desig","pd-f-emptype","pd-f-mgr"].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) Array.from(el.options).forEach(function(o) { o.selected = false; });
    });
    var badge = document.getElementById("pd-filter-badge");
    if (badge) { badge.hidden = true; badge.textContent = ""; }
    _pdClickedOverall = null;
    _pdClickedPotential = null;
    _pdFilteredRows = (_pdData && _pdData.rows) ? _pdData.rows.slice() : [];
    _pdRefresh();
  };

  /* ── Distribution computation ─────────────────────────────── */
  /* The ratings actually given for one field, raw and unrounded. An
     unrated person contributes nothing rather than a zero. */
  function _pdRawValues(rows, scale, field) {
    var vals = pfScaleValues(scale);
    return rows
      .filter(function(r) { return pfHasRating(r[field], vals); })
      .map(function(r) { return parseFloat(r[field]); });
  }

  /* Counts per bar. Every rating is drawn on its nearest band, with a
     half-point rounding up (see pfRatingToBandValue) - so nobody is left
     off the chart, which is what used to happen to 204 of 403 people. */
  function _pdBuildDist(rows, scale, field, clickedVal) {
    if (!scale || !scale.items) return [];
    var vals = pfScaleValues(scale);
    var countMap = {}, total = 0;
    rows.forEach(function(r) {
      if (!pfHasRating(r[field], vals)) return;
      var band = pfRatingToBandValue(r[field], vals);
      if (band === null) return;
      countMap[String(band)] = (countMap[String(band)] || 0) + 1;
      total += 1;
    });
    return scale.items.map(function(item) {
      var cnt = countMap[String(flt(item.value))] || 0;
      return {
        value:    item.value,
        label:    item.label,
        color:    item.color || "var(--primary)",
        count:    cnt,
        pct:      total ? Math.round(cnt / total * 100) : 0,
        selected: clickedVal !== null && String(flt(clickedVal)) === String(flt(item.value)),
      };
    });
  }

  /* The figures above the charts. They come from the raw ratings, never
     from the rounded bars - rounding is for drawing, not for arithmetic. */
  function _pdStats(rows, scale, field) {
    var vals = pfScaleValues(scale);
    var s = pfRatingStats(_pdRawValues(rows, scale, field), vals);
    if (!s.total) return {total: 0, avg: "—", median: "—", pctHigh: 0};
    return {
      total:   s.total,
      avg:     pfNum(s.avg, 2),
      median:  pfRatingLabel(s.median, scale),
      pctHigh: s.pctHigh,
    };
  }

  function _pdShape(dist) {
    var counts = dist.map(function(d) { return d.count; });
    var total  = counts.reduce(function(a, b) { return a + b; }, 0);
    var n = counts.length;
    if (!total || n < 3) return {label: "", cls: ""};
    var mean = total / n;
    var maxC = Math.max.apply(null, counts);
    var peaks = [];
    for (var i = 1; i < n - 1; i++) {
      if (counts[i] > counts[i-1] && counts[i] > counts[i+1] && counts[i] > mean) peaks.push(i);
    }
    if (peaks.length >= 2) return {label: "<i class=ic-alert></i> Bimodal — review manager consistency", cls: "pd-health-warn"};
    if (maxC / mean < 1.4) return {label: "<i class=ic-alert></i> Flat — insufficient differentiation", cls: "pd-health-warn"};
    var wIdx   = counts.reduce(function(s, c, i) { return s + c * i; }, 0) / total;
    var center = (n - 1) / 2;
    var skew   = center > 0 ? (wIdx - center) / center : 0;
    if (skew > 0.3)  return {label: "<i class=ic-alert></i> Skewed high — calibration recommended", cls: "pd-health-skewed"};
    if (skew < -0.3) return {label: "<i class=ic-alert></i> Skewed low", cls: "pd-health-warn"};
    return {label: "<i class=ic-check></i> Normally distributed", cls: "pd-health-normal"};
  }

  /* ── Smooth Catmull-Rom → cubic bezier ────────────────────── */
  function _pdSmoothPath(pts, baseY) {
    if (pts.length < 2) return {line: "", fill: ""};
    var d = "M " + pts[0].x + " " + pts[0].y;
    for (var i = 0; i < pts.length - 1; i++) {
      var p0 = pts[Math.max(0, i - 1)], p1 = pts[i];
      var p2 = pts[i + 1],              p3 = pts[Math.min(pts.length - 1, i + 2)];
      var c1x = p1.x + (p2.x - p0.x) / 6, c1y = p1.y + (p2.y - p0.y) / 6;
      var c2x = p2.x - (p3.x - p1.x) / 6, c2y = p2.y - (p3.y - p1.y) / 6;
      d += " C " + c1x + "," + c1y + " " + c2x + "," + c2y + " " + p2.x + "," + p2.y;
    }
    var last = pts[pts.length - 1], first = pts[0];
    return {line: d, fill: d + " L " + last.x + "," + baseY + " L " + first.x + "," + baseY + " Z"};
  }

  /* ── SVG chart renderer ───────────────────────────────────── */
  function _pdRenderChart(containerId, dist, clickFn) {
    var el = document.getElementById(containerId);
    if (!el) return;
    var n = dist.length;
    if (!n) { el.innerHTML = "<div class='empty-state'><div class='empty-state-text'>No data for this cycle.</div></div>"; return; }

    var W = 380, H = 195, pL = 34, pR = 14, pT = 24, pB = 54;
    var cW = W - pL - pR, cH = H - pT - pB;
    var maxCnt = Math.max.apply(null, dist.map(function(d) { return d.count; })) || 1;
    var gap    = Math.min(10, Math.floor(cW / n * 0.22));
    var barW   = Math.max(8, Math.floor((cW - gap * (n - 1)) / n));
    var selActive = dist.some(function(d) { return d.selected; });

    var bars = dist.map(function(d, i) {
      var bH = d.count > 0 ? Math.max(4, Math.round(d.count / maxCnt * cH)) : 0;
      var x  = pL + i * (barW + gap);
      return {x: x, y: pT + cH - bH, w: barW, h: bH, cx: x + barW / 2, d: d};
    });

    var curvePts = bars.filter(function(b) { return b.d.count > 0; })
                       .map(function(b) { return {x: b.cx, y: b.y}; });
    if (curvePts.length >= 2) {
      var dx0 = curvePts.length > 1 ? curvePts[1].x - curvePts[0].x : 20;
      var dxN = curvePts.length > 1 ? curvePts[curvePts.length-1].x - curvePts[curvePts.length-2].x : 20;
      curvePts.unshift({x: curvePts[0].x - dx0, y: pT + cH});
      curvePts.push({x: curvePts[curvePts.length-1].x + dxN, y: pT + cH});
    }
    var paths = _pdSmoothPath(curvePts, pT + cH);
    var uid   = containerId.replace(/[^a-z0-9]/gi, "");

    var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" class="pd-chart-svg" preserveAspectRatio="xMidYMid meet">';
    svg += '<defs><linearGradient id="pdg' + uid + '" x1="0" y1="0" x2="0" y2="1">' +
           '<stop offset="0%" stop-color="var(--primary)" stop-opacity="0.16"/>' +
           '<stop offset="100%" stop-color="var(--primary)" stop-opacity="0.01"/></linearGradient></defs>';

    /* grid */
    [0.25, 0.5, 0.75, 1].forEach(function(f) {
      var gy = pT + cH - Math.round(f * cH);
      svg += '<line x1="' + pL + '" y1="' + gy + '" x2="' + (W-pR) + '" y2="' + gy +
             '" stroke="var(--border)" stroke-width="0.5" opacity="0.7"/>';
      svg += '<text x="' + (pL-3) + '" y="' + (gy+3) + '" text-anchor="end" font-size="8.5" fill="var(--text3)">' +
             Math.round(f * maxCnt) + '</text>';
    });
    svg += '<line x1="' + pL + '" y1="' + pT + '" x2="' + pL + '" y2="' + (pT+cH) + '" stroke="var(--border)" stroke-width="1"/>';
    svg += '<line x1="' + pL + '" y1="' + (pT+cH) + '" x2="' + (W-pR) + '" y2="' + (pT+cH) + '" stroke="var(--border)" stroke-width="1"/>';

    /* curve */
    if (paths.fill) svg += '<path d="' + paths.fill + '" fill="url(#pdg' + uid + ')"/>';
    if (paths.line) svg += '<path d="' + paths.line + '" fill="none" stroke="var(--primary)" stroke-width="1.8" opacity="0.45" stroke-linecap="round" stroke-linejoin="round"/>';

    /* bars */
    bars.forEach(function(b) {
      var dimmed = selActive && !b.d.selected;
      var barOp  = dimmed ? "0.25" : "1";
      var txtOp  = dimmed ? "0.3" : "1";
      var vStr   = typeof b.d.value === "string"
                    ? '"' + String(b.d.value).replace(/"/g, '\\"') + '"'
                    : String(b.d.value);
      svg += '<g onclick="' + clickFn + '(' + vStr + ')" style="cursor:pointer">';
      if (b.h > 0) {
        svg += '<rect x="' + b.x + '" y="' + b.y + '" width="' + b.w + '" height="' + b.h +
               '" fill="' + b.d.color + '" opacity="' + barOp + '" rx="3" ry="3"/>';
        if (b.d.selected) {
          svg += '<rect x="' + (b.x-2) + '" y="' + (b.y-2) + '" width="' + (b.w+4) + '" height="' + (b.h+2) +
                 '" fill="none" stroke="' + b.d.color + '" stroke-width="2" rx="4" opacity="0.9"/>';
        }
        svg += '<text x="' + b.cx + '" y="' + (b.y-5) +
               '" text-anchor="middle" font-size="11" font-weight="700" fill="var(--text)" opacity="' + txtOp + '">' +
               b.d.count + '</text>';
      }
      var shortLbl = (b.d.label || "").split(" ")[0];
      svg += '<text x="' + b.cx + '" y="' + (pT+cH+13) + '" text-anchor="middle" font-size="9.5" fill="var(--text3)">' +
             gpEsc(shortLbl) + '</text>';
      svg += '<text x="' + b.cx + '" y="' + (pT+cH+25) + '" text-anchor="middle" font-size="8.5" fill="var(--text3)" opacity="0.7">' +
             (b.d.count > 0 ? b.d.pct + "%" : "") + '</text>';
      svg += '</g>';
    });
    svg += '</svg>';
    el.innerHTML = svg;
  }

  /* ── Bar click handlers ───────────────────────────────────── */
  window.pdClickOverall = function(value) {
    var s = String(flt(value));
    _pdClickedOverall = (_pdClickedOverall !== null && String(flt(_pdClickedOverall)) === s) ? null : value;
    _pdRefresh();
  };
  window.pdClickPotential = function(value) {
    var s = String(flt(value));
    _pdClickedPotential = (_pdClickedPotential !== null && String(flt(_pdClickedPotential)) === s) ? null : value;
    _pdRefresh();
  };

  /* ── Label lookup ─────────────────────────────────────────── */
  function _pdLabel(scale, value) {
    if (!scale) return String(value);
    return pfRatingLabel(value, scale);
  }

  /* Clicking a bar selects everyone drawn on that bar, which is everyone
     whose rating rounds to it - not only an exact match. */
  function _pdOnBand(row, field, scale, bandVal) {
    var vals = pfScaleValues(scale);
    if (!pfHasRating(row[field], vals)) return false;
    return String(pfRatingToBandValue(row[field], vals)) === String(flt(bandVal));
  }

  /* ── Core refresh ─────────────────────────────────────────── */
  function _pdRefresh() {
    if (!_pdData) return;
    var base = _pdFilteredRows;

    /* distribution for overall: if potential is clicked, narrow base */
    var oScale = _pdData.overall_scale;
    var pScale = _pdData.potential_scale;

    var oBase = (_pdClickedPotential !== null)
      ? base.filter(function(r) { return _pdOnBand(r, "potential_rating", pScale, _pdClickedPotential); })
      : base;
    var oDist  = _pdBuildDist(oBase, oScale, "overall_rating", _pdClickedOverall);

    /* distribution for potential: if overall is clicked, narrow base */
    var pBase  = (_pdClickedOverall !== null)
      ? base.filter(function(r) { return _pdOnBand(r, "overall_rating", oScale, _pdClickedOverall); })
      : base;
    var pDist  = pScale ? _pdBuildDist(pBase, pScale, "potential_rating", _pdClickedPotential) : null;

    /* rows shown in table: apply both click filters */
    var dispRows = base.filter(function(r) {
      if (_pdClickedOverall !== null && !_pdOnBand(r, "overall_rating", oScale, _pdClickedOverall)) return false;
      if (_pdClickedPotential !== null && !_pdOnBand(r, "potential_rating", pScale, _pdClickedPotential)) return false;
      return true;
    });

    var oStats = _pdStats(oBase, oScale, "overall_rating");
    var pStats = pDist ? _pdStats(pBase, pScale, "potential_rating") : null;
    var oShape = _pdShape(oDist);
    var pShape = pDist ? _pdShape(pDist) : null;

    /* ── Stats strip ───────────────────── */
    var html = '<div class="pd-stats-strip">';
    html += _pdStat(String(_pdData.all_participants || 0), "Total Participants");
    html += _pdStat(String(dispRows.length), "In Selection");
    html += _pdStat(String(oStats.avg), "Avg Overall");
    html += _pdStat(oStats.median || "—", "Median Overall");
    html += _pdStat(oStats.pctHigh + "%", "Above Expectations");
    if (pStats) html += _pdStat(String(pStats.avg), "Avg Potential");
    html += '</div>';

    /* An overall rating is an average of the items in the review, so it is
       often a half-point that no bar is drawn at. Say which figures are
       exact and which are rounded, rather than let the two disagree in
       silence. */
    html += '<div class="pd-figures-note" style="font-size:var(--fs-xs);color:var(--text3);margin:-4px 0 12px">' +
            gpEsc("Averages and the median are worked out from the exact ratings, so they can fall between two bands. " +
                  "On the charts each rating is drawn on its nearest band, and a half-point is drawn on the higher one.") +
            '</div>';

    /* ── Charts row ────────────────────── */
    html += '<div class="pd-charts-row">';

    html += '<div class="pd-chart-card">';
    html += '<div class="pd-chart-title">Overall Performance</div>';
    /* Count the ratings the chart is actually drawn from, not the rows. */
    html += '<div class="pd-chart-sub">' + gpEsc((oScale || {}).scale_name || "Rating") + ' · ' + oStats.total + ' rated</div>';
    html += '<div id="pd-chart-overall"></div>';
    if (oShape.label) html += '<div class="pd-health-label ' + oShape.cls + '">' + oShape.label + '</div>';
    if (_pdClickedOverall !== null) {
      html += '<button class="pd-filter-chip" onclick="pdClickOverall(' + JSON.stringify(_pdClickedOverall) + ')">' +
              gpEsc(_pdLabel(oScale, _pdClickedOverall)) + ' <span style="opacity:.6"><i class=ic-x></i></span></button>';
    }
    html += '</div>';

    if (pScale) {
      html += '<div class="pd-chart-card">';
      html += '<div class="pd-chart-title">Potential for Next Role</div>';
      html += '<div class="pd-chart-sub">' + gpEsc(pScale.scale_name) + ' · ' + pStats.total + ' rated</div>';
      html += '<div id="pd-chart-potential"></div>';
      if (pShape && pShape.label) html += '<div class="pd-health-label ' + pShape.cls + '">' + pShape.label + '</div>';
      if (_pdClickedPotential !== null) {
        html += '<button class="pd-filter-chip" onclick="pdClickPotential(' + JSON.stringify(_pdClickedPotential) + ')">' +
                gpEsc(_pdLabel(pScale, _pdClickedPotential)) + ' <span style="opacity:.6"><i class=ic-x></i></span></button>';
      }
      html += '</div>';
    }
    html += '</div>'; /* end charts-row */

    /* ── Selection summary ─────────────── */
    if (_pdClickedOverall !== null || _pdClickedPotential !== null) {
      html += '<div style="margin-bottom:10px;font-size:var(--fs-sm);color:var(--text3)">Showing <strong>' +
              dispRows.length + '</strong> of ' + base.length + ' employees</div>';
    }

    /* ── Employee table ────────────────── */
    html += _pdTable(dispRows);

    pfSetHtml("pd-body", html);

    /* charts must be rendered after DOM is ready */
    _pdRenderChart("pd-chart-overall", oDist, "pdClickOverall");
    if (pScale) _pdRenderChart("pd-chart-potential", pDist, "pdClickPotential");
  }

  function _pdStat(val, lbl) {
    /* A figure and a rating name want different sizes, and only the value
       itself can say which this is. */
    var isWord = !/^[\d.,%\s—-]+$/.test(String(val));
    return '<div class="pd-stat"><div class="pd-stat-val' + (isWord ? " pd-stat-val-word" : "")
      + '">' + gpEsc(val) + '</div><div class="pd-stat-lbl">' + gpEsc(lbl) + '</div></div>';
  }

  /* ── Employee table ───────────────────────────────────────── */
  function _pdTable(rows) {
    var oScale = _pdData.overall_scale;
    var pScale = _pdData.potential_scale;

    /* A half-point rating keeps its own number and borrows the colour of
       the band it is drawn on, so it reads as a rating rather than as a
       blank or a guess. */
    function _badge(scale, value) {
      var vals = pfScaleValues(scale);
      if (!scale || !pfHasRating(value, vals)) return '<span style="color:var(--text3)">—</span>';
      var band = pfRatingToBandValue(value, vals);
      var item = (scale.items || []).find(function(it) { return String(flt(it.value)) === String(band); });
      var lbl  = pfRatingLabel(value, scale);
      var col  = item ? (item.color || "var(--text3)") : "var(--text3)";
      return '<span class="pd-rating-badge" style="background:' + col + '22;color:' + col + '">' + gpEsc(lbl) + '</span>';
    }

    var sorted = rows.slice().sort(function(a, b) {
      var av = a[_pdSortCol], bv = b[_pdSortCol];
      if (typeof av === "number") return _pdSortDir * (bv - av);
      return _pdSortDir * ((av || "").localeCompare(bv || ""));
    });

    function _sortIcon(col) {
      if (_pdSortCol !== col) return '<span class="pd-sort-ind">↕</span>';
      return '<span class="pd-sort-ind" style="opacity:1;color:var(--primary)">' + (_pdSortDir === -1 ? "↓" : "↑") + '</span>';
    }

    if (!sorted.length) {
      return '<div class="empty-state" style="margin-top:16px"><div class="empty-state-text">No employees match the current selection.</div></div>';
    }

    var h = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">';
    h += '<div style="font-size:var(--fs-base);font-weight:700;color:var(--text)">' + sorted.length + ' employees</div>';
    h += '<button class="btn btn-outline btn-sm" onclick="pdExportCSV()" style="font-size:var(--fs-sm)">Export CSV</button>';
    h += '</div>';
    h += '<div class="pd-table-wrap"><table class="pd-table"><thead><tr>';

    var cols = [
      {k:"employee_name",  l:"Employee"},
      {k:"department",     l:"Department"},
      {k:"designation",    l:"Designation"},
      {k:"overall_rating", l:"Overall Rating"},
    ];
    if (pScale) cols.push({k:"potential_rating", l:"Potential"});
    cols.push({k:"reports_to_name", l:"Manager"});

    cols.forEach(function(c) {
      h += '<th onclick="pdSortTable(\'' + c.k + '\')" title="Sort">' + gpEsc(c.l) + _sortIcon(c.k) + '</th>';
    });
    h += '</tr></thead><tbody>';

    sorted.forEach(function(r) {
      var initials    = _pdInitials(r.employee_name);
      var avatarColor = _pdColor(r.employee_name);
      h += '<tr>';
      h += '<td><div class="pd-emp-cell">' +
           '<div class="pd-avatar" style="background:' + avatarColor + '">' + gpEsc(initials) + '</div>' +
           '<div><div class="pd-emp-name">' + gpEsc(r.employee_name) + '</div>' +
           '<div class="pd-emp-sub">' + gpEsc(r.employee || "") + '</div></div>' +
           '</div></td>';
      h += '<td>' + gpEsc(r.department || "—") + '</td>';
      h += '<td>' + gpEsc(r.designation || "—") + '</td>';
      h += '<td>' + _badge(oScale, r.overall_rating) + '</td>';
      if (pScale) h += '<td>' + _badge(pScale, r.potential_rating) + '</td>';
      h += '<td>' + gpEsc(r.reports_to_name || "—") + '</td>';
      h += '</tr>';
    });

    h += '</tbody></table></div>';
    return h;
  }

  window.pdSortTable = function(col) {
    if (_pdSortCol === col) { _pdSortDir *= -1; } else { _pdSortCol = col; _pdSortDir = (col === "overall_rating" || col === "potential_rating") ? -1 : 1; }
    _pdRefresh();
  };

  window.pdExportCSV = function() {
    var rows = _pdFilteredRows;
    if (!rows || !rows.length) return;
    var oScale = (_pdData || {}).overall_scale;
    var pScale = (_pdData || {}).potential_scale;
    var cols   = ["employee_name","employee","department","designation","overall_rating","potential_rating","reports_to_name"];
    var hdrs   = ["Name","Employee ID","Department","Designation","Overall Rating","Overall Label","Potential Rating","Potential Label","Manager"];
    var lines  = [hdrs.join(",")];
    rows.forEach(function(r) {
      var vals = [
        r.employee_name, r.employee, r.department, r.designation,
        r.overall_rating, pfRatingLabel(r.overall_rating, oScale),
        r.potential_rating, pfRatingLabel(r.potential_rating, pScale),
        r.reports_to_name,
      ].map(function(v) {
        var s = String(v || "");
        return (s.includes(",") || s.includes('"')) ? '"' + s.replace(/"/g, '""') + '"' : s;
      });
      lines.push(vals.join(","));
    });
    var blob = new Blob([lines.join("\n")], {type: "text/csv"});
    var url  = URL.createObjectURL(blob);
    var a    = document.createElement("a");
    a.href = url; a.download = "distribution_" + (_pdCycle || "export") + ".csv";
    a.click(); URL.revokeObjectURL(url);
  };

})(); /* end Distribution module */

/* ── Calibration Matrix ─────────────────────────────── */
(function() {
  var _calData          = null;  /* raw API response */
  var _calCycle         = "";
  var _calFilteredRows  = null;  /* last rendered row set — used by CSV export */

  /* avatar colour palette */
  var _calPalette = ["var(--primary)","var(--green)","var(--primary)","var(--amber)","var(--green)","var(--primary)","var(--red)","var(--green)"];
  function _calColor(name) {
    var h = 0;
    for (var i = 0; i < (name || "").length; i++) h += name.charCodeAt(i);
    return _calPalette[h % _calPalette.length];
  }
  function _calInitials(name) {
    var w = (name || "?").trim().split(/\s+/);
    return (w[0][0] + (w.length > 1 ? w[w.length-1][0] : "")).toUpperCase();
  }

  /* populate cycle selector — always repopulate and auto-select latest */
  window.calInit = function() {
    var sel = document.getElementById("cal-cycle-sel");
    if (!sel) return;
    function _doPopulate(cycles) {
      if (!cycles || !cycles.length) {
        sel.innerHTML = "<option value=\"\">No appraisal cycles found</option>";
        pfSetHtml("cal-body", "<div class=\"empty-state\"><div class=\"empty-state-text\">No appraisal cycles are configured yet.</div></div>");
        return;
      }
      var sorted = cycles.slice().sort(function(a, b) {
        return (b.start_date || "") > (a.start_date || "") ? 1 : -1;
      });
      sel.innerHTML = sorted.map(function(c) {
        return "<option value=\"" + gpEsc(c.name) + "\">" + gpEsc(c.cycle_name || c.name) + "</option>";
      }).join("");
      calLoad();
    }
    if (window._pfCtx && _pfCtx.cycles && _pfCtx.cycles.length) {
      _doPopulate(_pfCtx.cycles);
    } else {
      pf("get_performance_context").then(function(ctx) {
        if (ctx) window._pfCtx = ctx;
        _doPopulate((ctx || {}).cycles || []);
      });
    }
  };

  window.calLoad = function() {
    var sel = document.getElementById("cal-cycle-sel");
    var cycle = sel ? sel.value : "";
    if (!cycle) return;
    _calCycle = cycle;
    pfSetHtml("cal-body", "<div class=\"empty-state\"><div class=\"empty-state-text\">Loading calibration data…</div></div>");
    var filtersEl = document.getElementById("cal-filters");
    if (filtersEl) filtersEl.style.display = "none";
    var infoEl = document.getElementById("cal-cycle-info");
    if (infoEl) infoEl.style.display = "none";
    pf("get_calibration_matrix", {cycle: cycle}).then(function(d) {
      _calData = d;
      _calShowCycleInfo(d);
      _calPopulateFilters(d.filter_options);
      calApplyFilters();
    }).catch(function(e) {
      pfSetHtml("cal-body", "<div class=\"callout callout-warn\">Failed to load calibration data: " + gpEsc((e || {}).message || e) + "</div>");
    });
  };

  /* duration strip + stage tiles shown after a cycle loads */
  function _calShowCycleInfo(d) {
    var infoEl = document.getElementById("cal-cycle-info");
    if (!infoEl) return;
    var ci = d.cycle_info || {};
    var durationHtml = "";
    if (ci.start_date || ci.end_date) {
      durationHtml = "<div class=\"cal-duration\">" +
        "<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">" +
          "<rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/>" +
          "<line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/>" +
        "</svg>" +
        "<span>" + gpEsc(ci.start_date) + " – " + gpEsc(ci.end_date) + "</span>" +
      "</div>";
    }
    var STAGES = [
      {key:"Not Started",           label:"Not Started",     color:"var(--text3)", bg:"var(--surface2)", border:"var(--border)"},
      {key:"Employee Review",       label:"Self-Review",     color:"var(--primary)",      bg:"var(--primary-lt)",         border:"var(--primary-lt)"},
      {key:"Manager Review",        label:"With Manager",    color:"var(--amber)",      bg:"var(--amber-lt)",         border:"var(--amber)"},
      // color was --green-lt, the SAME value as its own background, so the
      // count and the word "Feedback Shared" were painted in the background
      // colour and the tile looked blank.
      {key:"Employee Final Review", label:"Feedback Shared", color:"var(--green)",      bg:"var(--green-lt)",         border:"var(--green)"},
      {key:"HR Review",             label:"HR Review",       color:"var(--primary)",      bg:"var(--primary-lt)",         border:"var(--primary-lt)"},
      {key:"Completed",             label:"Completed",       color:"var(--green)",      bg:"var(--green-lt)",         border:"var(--green)"},
    ];
    var sc    = d.stage_counts || {};
    var total = d.all_participants || 0;
    var tilesHtml = "<div class=\"cal-stage-tiles\">" +
      "<div class=\"cal-stage-tile\">" +
        "<div class=\"cal-stage-tile-num\" style=\"color:var(--text)\">" + total + "</div>" +
        "<div class=\"cal-stage-tile-lbl\" style=\"color:var(--text3)\">Total</div>" +
      "</div>" +
      STAGES.map(function(s) {
        var cnt = sc[s.key] || 0;
        return "<div class=\"cal-stage-tile\" style=\"background:" + s.bg + ";border-color:" + s.border + "\">" +
          "<div class=\"cal-stage-tile-num\" style=\"color:" + s.color + "\">" + cnt + "</div>" +
          "<div class=\"cal-stage-tile-lbl\" style=\"color:" + s.color + "\">" + gpEsc(s.label) + "</div>" +
        "</div>";
      }).join("") +
    "</div>";
    infoEl.innerHTML = durationHtml + tilesHtml;
    infoEl.style.display = "";
  }

  function _calPopulateFilters(opts) {
    if (!opts) return;
    function _fillSel(id, items, labelKey) {
      var el = document.getElementById(id);
      if (!el) return;
      el.innerHTML = items.map(function(it) {
        var val = labelKey ? it[labelKey] : it;
        var lbl = labelKey === "id" ? (it.name || it.id) : it;
        if (labelKey && typeof it === "object") { val = it.id; lbl = it.name; }
        return "<option value=\"" + gpEsc(String(val)) + "\">" + gpEsc(lbl) + "</option>";
      }).join("");
    }
    _fillSel("cal-f-dept",    opts.departments   || []);
    _fillSel("cal-f-desig",   opts.designations  || []);
    _fillSel("cal-f-emptype", opts.employment_types || []);
    /* managers are objects {id, name} */
    var mgrEl = document.getElementById("cal-f-mgr");
    if (mgrEl) {
      mgrEl.innerHTML = (opts.managers || []).map(function(m) {
        return "<option value=\"" + gpEsc(m.id) + "\">" + gpEsc(m.name) + "</option>";
      }).join("");
    }
    var filtersEl = document.getElementById("cal-filters");
    if (filtersEl) filtersEl.style.display = "none"; /* collapsed by default; toggled by button */
    var hasOpts = (opts.departments && opts.departments.length) || (opts.managers && opts.managers.length);
    var fBtn = document.getElementById("cal-filter-btn");
    if (fBtn) { fBtn.style.display = hasOpts ? "" : "none"; fBtn.setAttribute("aria-expanded", "false"); }
    var expBtn = document.getElementById("cal-export-btn");
    if (expBtn) expBtn.style.display = "";
    var sofBtn = document.getElementById("cal-signoff-btn");
    if (sofBtn) sofBtn.style.display = "";
  }

  function _calGetSelectedValues(id) {
    var el = document.getElementById(id);
    if (!el) return [];
    return Array.from(el.selectedOptions).map(function(o) { return o.value; });
  }

  window.calApplyFilters = function() {
    if (!_calData) return;
    var fDept    = _calGetSelectedValues("cal-f-dept");
    var fDesig   = _calGetSelectedValues("cal-f-desig");
    var fEmptype = _calGetSelectedValues("cal-f-emptype");
    var fMgr     = _calGetSelectedValues("cal-f-mgr");

    var rows = (_calData.rows || []).filter(function(r) {
      if (fDept.length    && fDept.indexOf(r.department)     === -1) return false;
      if (fDesig.length   && fDesig.indexOf(r.designation)   === -1) return false;
      if (fEmptype.length && fEmptype.indexOf(r.employment_type) === -1) return false;
      if (fMgr.length     && fMgr.indexOf(r.reports_to)      === -1) return false;
      return true;
    });

    /* summary */
    var sumEl = document.getElementById("cal-filter-summary");
    var total  = (_calData.rows || []).length;
    var activeCount = fDept.length + fDesig.length + fEmptype.length + fMgr.length;
    if (sumEl) {
      sumEl.style.display = activeCount ? "" : "none";
      sumEl.textContent = "Showing " + rows.length + " of " + total + " employees";
    }
    var fBadge = document.getElementById("cal-filter-badge");
    if (fBadge) { fBadge.hidden = !activeCount; fBadge.textContent = activeCount; }

    _calFilteredRows = rows;
    _calRender(rows);
  };

  window.calToggleFilters = function() {
    var el = document.getElementById("cal-filters");
    if (!el) return;
    var open = el.style.display !== "none";
    el.style.display = open ? "none" : "";
    var btn = document.getElementById("cal-filter-btn");
    if (btn) btn.setAttribute("aria-expanded", String(!open));
  };

  window.calClearFilters = function() {
    ["cal-f-dept","cal-f-desig","cal-f-emptype","cal-f-mgr"].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) Array.from(el.options).forEach(function(o) { o.selected = false; });
    });
    calApplyFilters();
  };

  /* ── 9-box color scheme ──────────────────────────────────────────────
     Matches the Performance Value Matrix reference image exactly.
     perfZone: 0=low(left), 1=mid, 2=high(right)
     potZone:  0=low(bottom), 1=mid, 2=high(top)
     Color table [potZone][perfZone]                                    */
  /* The grid's own scale, not the page's semantic colours. Four bands that
     have to stay apart from each other: mapping them onto --red/--amber/--green
     collapsed both oranges into one and both greens into another, and a
     nine-box grid whose cells look alike tells you nothing. */
  /* Colour follows the MEANING of the square, not its position in the grid.
     The old mapping had Potential Gem in red and Inconsistent Player in green,
     which told the reader the opposite of the truth.

       green   somebody to keep - Solid Performer, High Performer,
               Potential Gem, High Potential
       blue    Core Player, the dependable middle
       yellow  Star, the one square that should catch the eye
       orange  needs a conversation - Average Performer, Inconsistent Player
       red     Risk

     Pastel on purpose. Nine saturated blocks make every square shout equally,
     and the point of this grid is that your eye lands on the few that matter. */
  var _CAL_COLORS = [
    /* pot LOW  */  ["var(--box-red)",   "var(--box-orange)", "var(--box-green)"],
    /* pot MID  */  ["var(--box-orange)","var(--box-blue)",   "var(--box-green)"],
    /* pot HIGH */  ["var(--box-green)", "var(--box-green)",  "var(--box-yellow)"],
  ];
  /* Every square now carries text from --box-fg, which flips with the theme -
     dark on the pastels, light on their deepened dark-mode counterparts. The
     flag stays true everywhere so the one text path is used for all nine. */
  var _CAL_DARK_TEXT = [[true,true,true],[true,true,true],[true,true,true]];

  function _calZone(normPerf, normPot) {
    /* normalize 0-1 → 0/1/2 zone bucket */
    var pf = normPerf < 0.34 ? 0 : (normPerf < 0.67 ? 1 : 2);
    var pt = normPot  < 0.34 ? 0 : (normPot  < 0.67 ? 1 : 2);
    return {bg: _CAL_COLORS[pt][pf], dark: _CAL_DARK_TEXT[pt][pf]};
  }

  function _calEmpRow(r, darkText) {
    var meta = [r.department, r.designation].filter(Boolean).join(" · ");
    var nameStyle = darkText ? "color:var(--box-fg)" : "color:var(--surface)";
    var metaStyle = darkText ? "color:var(--box-fg-dim)" : "color:rgba(255,255,255,.72)";
    var avBg      = _calColor(r.employee_name);
    return "<div class=\"cal-emp-row" + (darkText ? " cal-emp-row-dark" : "") + "\">" +
      "<div class=\"cal-emp-av\" style=\"background:" + avBg + "\">" + _calInitials(r.employee_name) + "</div>" +
      "<div class=\"cal-emp-info\">" +
        "<div class=\"cal-emp-name\" style=\"" + nameStyle + "\">" + gpEsc(r.employee_name) + "</div>" +
        (meta ? "<div class=\"cal-emp-meta\" style=\"" + metaStyle + "\">" + gpEsc(meta) + "</div>" : "") +
      "</div>" +
    "</div>";
  }

  function _calEmpCapped(bkt, dark, cellId, dimClr) {
    var CAP = 5;
    var visible = bkt.slice(0, CAP);
    var rest    = bkt.slice(CAP);
    var html    = visible.map(function(r) { return _calEmpRow(r, dark); }).join("");
    if (rest.length) {
      var mId  = "cal-more-lbl-" + cellId;
      var rId  = "cal-more-rest-" + cellId;
      var togFn = "var m=document.getElementById('" + mId + "'),r=document.getElementById('" + rId + "');" +
        "if(r){r.style.display='';m.style.display='none';}";
      var collFn = "var m=document.getElementById('" + mId + "'),r=document.getElementById('" + rId + "');" +
        "m.style.display='';r.style.display='none';";
      html += "<div id=\"" + mId + "\" class=\"cal-more-toggle\" style=\"color:" + dimClr + "\" onclick=\"" +
        togFn + "\">&hellip;&thinsp;" + rest.length + " more</div>" +
        "<div id=\"" + rId + "\" style=\"display:none\">" +
          rest.map(function(r) { return _calEmpRow(r, dark); }).join("") +
          "<div style=\"text-align:center;margin-top:4px\">" +
            "<span style=\"cursor:pointer;font-size:var(--fs-xs);color:" + dimClr + ";opacity:.7\" onclick=\"" + collFn + "\">↑ show less</span>" +
          "</div>" +
        "</div>";
    }
    return html;
  }

  function _calRender(rows) {
    var d = _calData;
    var overall   = d.overall_scale;
    var potential = d.show_potential ? d.potential_scale : null;

    if (!overall || !overall.items || !overall.items.length) {
      pfSetHtml("cal-body",
        "<div class=\"callout callout-info\">No rating scale is configured for this appraisal cycle. " +
        "Set up the Overall Rating scale in HR Setup → Appraisal Cycle → Manager Feedback page.</div>");
      return;
    }

    var oCols = overall.items.slice();   /* ascending */

    function _calSummary(plottedCount) {
      return "<div class=\"cal-summary\">" +
        "<span><strong>" + plottedCount + "</strong> employees plotted</span>" +
        (potential
          ? "<span>X: <strong>" + gpEsc(overall.scale_name) + "</strong></span>" +
            "<span>Y: <strong>" + gpEsc(potential.scale_name) + "</strong></span>"
          : "<span>Scale: <strong>" + gpEsc(overall.scale_name) + "</strong></span>") +
      "</div>";
    }
    var summaryHtml = _calSummary(rows.length);

    /* ── 1D fallback ──────────────────────────────────────────────────── */
    if (!potential) {
      var cols1d = "";
      /* Same rule as the charts: a rating is shown in the column of the band
         it is nearest, a half-point in the higher one. It used to need an
         exact match, so a 4.5 appeared in no column at all. */
      var oVals1d = pfScaleValues(overall);
      oCols.forEach(function(col, ci) {
        var bucket  = rows.filter(function(r) {
          if (!pfHasRating(r.overall_rating, oVals1d)) return false;
          return String(pfRatingToBandValue(r.overall_rating, oVals1d)) === String(parseFloat(col.value));
        });
        var normPf  = oCols.length > 1 ? ci / (oCols.length - 1) : 0.5;
        var zone    = _calZone(normPf, 0.5);
        var dim1d   = zone.dark ? "var(--box-fg-dim)" : "rgba(255,255,255,.72)";
        var empHtml = bucket.length
          ? _calEmpCapped(bucket, zone.dark, "1d-" + ci, dim1d)
          : "<div style=\"font-size:var(--fs-xs);padding:6px 2px;font-style:italic;color:" +
              (zone.dark ? "var(--box-fg-dim)" : "rgba(255,255,255,.45)") + "\">No employees</div>";
        var lblColor  = zone.dark ? "var(--box-fg)" : "var(--surface)";
        var filterBtn1d = "<span class=\"cal-cell-filter-btn\" style=\"color:" + lblColor + "\" title=\"Open filters\"" +
          " onclick=\"(function(){var f=document.getElementById('cal-filters');if(f&&f.style.display==='none'){calToggleFilters();}document.getElementById('cal-filter-btn').scrollIntoView({behavior:'smooth',block:'nearest'});})()\">" +
          "<svg width='11' height='11' viewBox='0 0 12 12' fill='currentColor'><path d='M1 2h10L7 7v3.5l-2-1V7z'/></svg>" +
          "</span>";
        cols1d += "<div class=\"cal-1d-col\" style=\"background:" + zone.bg + "\">" +
          "<div class=\"cal-1d-col-hdr\" style=\"color:" + lblColor + "\">" +
            "<span>" + gpEsc(col.label) + " Performance" +
            (bucket.length ? "<span class=\"cal-cell-count\">(" + bucket.length + ")</span>" : "") + "</span>" +
            filterBtn1d +
          "</div>" +
          "<div class=\"cal-1d-emps\">" + empHtml + "</div>" +
        "</div>";
      });
      /* Same rule as the grid: nobody disappears without being named. */
      var noRating = rows.filter(function(r) { return !pfHasRating(r.overall_rating, oVals1d); });
      var noRatingHtml = noRating.length
        ? "<div class=\"callout callout-warn\" style=\"margin-bottom:12px\"><strong>" + noRating.length + "</strong> " +
            (noRating.length === 1 ? "person is" : "people are") + " not shown - no overall rating: " +
            noRating.map(function(r) { return gpEsc(r.employee_name || r.employee); }).join(", ") + "</div>"
        : "";
      pfSetHtml("cal-body", _calSummary(rows.length - noRating.length) + noRatingHtml +
                "<div class=\"cal-1d-wrap\">" + cols1d + "</div>");
      return;
    }

    /* ── 2D matrix: 3×3 zone-based grid ────────────────────────── */
    var ZONE_NAMES = [
      /* pot LOW  */ ["Risk",                "Average Performer", "Solid Performer"],
      /* pot MID  */ ["Inconsistent Player", "Core Player",       "High Performer"],
      /* pot HIGH */ ["Potential Gem",       "High Potential",    "Star"],
    ];
    var PERF_HDR = ["Low", "Moderate", "High"];
    var POT_HDR  = ["Low", "Moderate", "High"];

    /* Sorted once per render, not once per person: this used to re-sort the
       scale for every cell lookup - 806 sorts for 403 people. */
    var oVals = pfScaleValues(overall);
    var pVals = pfScaleValues(potential);

    /* Bucket into 3x3. A person goes in a box only when both ratings exist:
       a 9-box cell is a claim about someone, and an unrated potential used
       to read as a rating of zero and put them in Risk. */
    var bkts = [[[], [], []], [[], [], []], [[], [], []]];
    var unplotted = [];
    rows.forEach(function(r) {
      var pz  = pfRatingBand(r.overall_rating,   oVals);
      var ptz = pfRatingBand(r.potential_rating, pVals);
      if (!pfHasRating(r.overall_rating, oVals) || pz === null) {
        unplotted.push({row: r, why: "no overall rating"});
        return;
      }
      if (!pfHasRating(r.potential_rating, pVals) || ptz === null) {
        unplotted.push({row: r, why: "no potential rating"});
        return;
      }
      bkts[ptz][pz].push(r);
    });

    /* header row of grid */
    var gridHtml =
      "<div class=\"cal-9box-corner\"></div>" +
      PERF_HDR.map(function(h) { return "<div class=\"cal-9box-col-hdr\">" + h + "</div>"; }).join("");

    /* 3 data rows, high potential first */
    for (var ptz = 2; ptz >= 0; ptz--) {
      gridHtml += "<div class=\"cal-9box-row-hdr\">" + POT_HDR[ptz].toUpperCase() + "</div>";
      for (var pz = 0; pz <= 2; pz++) {
        var bg     = _CAL_COLORS[ptz][pz];
        var dark   = _CAL_DARK_TEXT[ptz][pz];
        var lblClr = dark ? "var(--box-fg)" : "var(--surface)";
        var dimClr = dark ? "var(--box-fg-dim)" : "rgba(255,255,255,.72)";
        var bkt    = bkts[ptz][pz];
        var empsHtml = bkt.length
          ? _calEmpCapped(bkt, dark, ptz + "-" + pz, dimClr)
          : "<div style=\"font-size:var(--fs-xs);font-style:italic;color:" + dimClr + ";padding:4px 0\">No employees</div>";
        var filterBtn9 = "<span class=\"cal-cell-filter-btn\" style=\"color:" + lblClr + "\" title=\"Open filters\"" +
          " onclick=\"(function(){var f=document.getElementById('cal-filters');if(f&&f.style.display==='none'){calToggleFilters();}document.getElementById('cal-filter-btn').scrollIntoView({behavior:'smooth',block:'nearest'});})()\">" +
          "<svg width='11' height='11' viewBox='0 0 12 12' fill='currentColor'><path d='M1 2h10L7 7v3.5l-2-1V7z'/></svg>" +
          "</span>";
        gridHtml +=
          "<div class=\"cal-9box-cell\" style=\"background:" + bg + "\">" +
            "<div class=\"cal-9box-zone-lbl\" style=\"color:" + lblClr + "\">" +
              "<span>" + gpEsc(ZONE_NAMES[ptz][pz]) +
              (bkt.length ? " <span class=\"cal-cell-count\">(" + bkt.length + ")</span>" : "") + "</span>" +
              filterBtn9 +
            "</div>" +
            "<div class=\"cal-9box-zone-desc\" style=\"color:" + dimClr + "\">" +
              PERF_HDR[pz] + " performance &middot; " + POT_HDR[ptz] + " potential" +
            "</div>" +
            "<div class=\"cal-9box-emps\">" + empsHtml + "</div>" +
          "</div>";
      }
    }

    /* Somebody with a rating missing is named, not quietly dropped and not
       placed in a box the missing rating did not earn them. */
    var unplottedHtml = "";
    if (unplotted.length) {
      var byReason = {};
      unplotted.forEach(function(u) { (byReason[u.why] = byReason[u.why] || []).push(u.row); });
      unplottedHtml = "<div class=\"callout callout-warn\" style=\"margin-bottom:12px\">" +
        "<strong>" + unplotted.length + "</strong> " +
        (unplotted.length === 1 ? "person is" : "people are") + " not plotted." +
        Object.keys(byReason).map(function(why) {
          var names = byReason[why].map(function(r) { return gpEsc(r.employee_name || r.employee); });
          return "<div style=\"margin-top:6px\">" + gpEsc(why.charAt(0).toUpperCase() + why.slice(1)) +
                 ": " + names.join(", ") + "</div>";
        }).join("") +
        "<div style=\"margin-top:6px\">Add the missing rating on the review, then reload this tab.</div>" +
      "</div>";
    }

    pfSetHtml("cal-body", _calSummary(rows.length - unplotted.length) + unplottedHtml +
      "<div class=\"cal-9box-outer\">" +
        "<div class=\"cal-9box-yaxis\">Potential</div>" +
        "<div class=\"cal-9box-right\">" +
          "<div class=\"cal-9box-grid\">" + gridHtml + "</div>" +
          "<div class=\"cal-9box-xaxis\">← " + gpEsc(overall.scale_name) + " (Performance) →</div>" +
        "</div>" +
      "</div>");
  }

  /* ── Calibration CSV export ─────────────────────────────────────── */
  window.calExportCsv = function() {
    var rows = _calFilteredRows || (_calData && _calData.rows) || [];
    if (!rows.length) { frappe.msgprint("No data to export."); return; }
    var oScale = (_calData || {}).overall_scale;
    var pScale = (_calData || {}).potential_scale;
    var hdrs = ["Name", "Employee ID", "Department", "Designation", "Overall Rating", "Overall Label", "Potential Rating", "Potential Label", "Manager"];
    var lines = [hdrs.join(",")];
    rows.forEach(function(r) {
      var vals = [
        r.employee_name, r.employee, r.department, r.designation,
        r.overall_rating, pfRatingLabel(r.overall_rating, oScale),
        r.potential_rating || "", pfRatingLabel(r.potential_rating, pScale),
        r.reports_to_name || ""
      ].map(function(v) {
        var s = String(v == null ? "" : v);
        return (s.indexOf(",") !== -1 || s.indexOf('"') !== -1) ? '"' + s.replace(/"/g, '""') + '"' : s;
      });
      lines.push(vals.join(","));
    });
    var blob = new Blob([lines.join("\n")], { type: "text/csv" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url; a.download = "calibration_" + (_calCycle || "export") + ".csv";
    a.click(); URL.revokeObjectURL(url);
  };

  /* ── Sign-off modal ─────────────────────────────────────────────── */
  window.calOpenSignoff = function() {
    var modal = document.getElementById("cal-signoff-modal");
    var lbl   = document.getElementById("cal-signoff-cycle-lbl");
    var txt   = document.getElementById("cal-signoff-text");
    if (!modal) return;
    if (lbl && _calData && _calData.cycle_info) lbl.textContent = _calData.cycle_info.cycle_name || _calCycle;
    if (txt) txt.value = "";
    modal.style.display = "flex";
  };

  window.calCloseSignoff = function() {
    var modal = document.getElementById("cal-signoff-modal");
    if (modal) modal.style.display = "none";
  };

  window.calSubmitSignoff = function() {
    var txt = document.getElementById("cal-signoff-text");
    var summary = txt ? txt.value.trim() : "";
    if (!summary) { frappe.msgprint("Please add a summary before signing off."); return; }
    if (!_calCycle) { frappe.msgprint("No cycle selected."); return; }
    pf("save_calibration_signoff", { cycle: _calCycle, summary: summary }).then(function(d) {
      calCloseSignoff();
      _calShowSignoffBanner(d);
    }).catch(function(e) {
      frappe.msgprint("Failed to save sign-off: " + (e.message || e));
    });
  };

  function _calShowSignoffBanner(d) {
    if (!d) return;
    var banner  = document.getElementById("cal-signoff-banner");
    var meta    = document.getElementById("cal-signoff-meta");
    var summary = document.getElementById("cal-signoff-summary");
    if (!banner) return;
    /* The API calls this field signed_on. Reading d.signed_at gave undefined,
       so the line ended at "on " with no date. */
    var signedOn = d.signed_on || d.signed_at || "";
    if (meta) meta.textContent = "by " + (d.signed_by || "") + (signedOn ? " on " + String(signedOn).slice(0, 10) : "");
    if (summary) summary.textContent = d.summary || "";
    banner.style.display = "";
  }

  /* Load existing sign-off when a cycle is selected */
  var _calOrigLoad = window.calLoad;
  window.calLoad = function() {
    if (_calOrigLoad) _calOrigLoad();
    var cycle = (document.getElementById("cal-cycle-sel") || {}).value;
    if (!cycle) return;
    pf("get_calibration_signoff", { cycle: cycle }).then(function(d) {
      if (d && d.summary) {
        _calShowSignoffBanner(d);
      } else {
        var banner = document.getElementById("cal-signoff-banner");
        if (banner) banner.style.display = "none";
      }
    }).catch(function() {});
  };

})();

/* ── KPI helpers shared with the tree view ────────── */

  // Rendering moved into the combined Objectives & KPIs tree; what remains is
  // the lookup the Log Progress / Rate Myself modals need for context.
  var _pfMyKpis = [];
  var _pfMyEmployee = "";

  function pfFindMyKpi(id) {
    var found = _pfMyKpis.filter(function(k) { return k.name === id; });
    return found.length ? found[0] : null;
  }

  // Called by the tree after every load so modal context stays current.
  window.pfCacheKpis = function(kpis, employeeId) {
    _pfMyKpis = kpis || [];
    _pfMyEmployee = employeeId || "";
  };

  // Anything that used to refresh the KPI list now refreshes the tree.
  window.pfLoadMyKpis = function() { tvLoad(); };

  window.pfOpenLog = function(kpiId, focusRow) {
    var k = pfFindMyKpi(kpiId);
    pfClearErr("pf-log-error");
    document.getElementById("pf-log-kpi").value = kpiId;
    /* A cumulative KPI adds up its readings, so the box asks for the amount
       since the last update and starts empty. An absolute one is a reading of
       where things stand now, so it starts at the current number (decision 1). */
    var cumulative = !k || (k.progress_mode || "Cumulative") !== "Absolute";
    document.getElementById("pf-log-value").value = cumulative ? "" : (k.actual_value || "");
    /* The person's own day, not the UTC day: between midnight and 05:30 in
       India the UTC day is still yesterday (code review minor 4). */
    var now = new Date();
    var localDay = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" +
      String(now.getDate()).padStart(2, "0");
    document.getElementById("pf-log-date").value = localDay;
    document.getElementById("pf-log-date").max = localDay;
    document.getElementById("pf-log-note").value = "";
    document.getElementById("pf-log-file").value = "";
    document.getElementById("pf-log-file-name").textContent = "Click to attach image or document…";
    var label = document.getElementById("pf-log-value-label");
    if (label) label.textContent = cumulative
      ? "Amount since your last update *"
      : "The reading now *";
    pfSetHtml("pf-log-context", k
      ? "<strong>" + gpEsc(k.kpi_name) + "</strong><br>Target " + pfNum(k.target_value, 2) +
        " " + gpEsc(k.unit || "") + " · currently at " + pfNum(k.attainment_pct) + "%" +
        /* An open review holds this KPI (R5). */
        (k.review_badge ? "<br>" + riReviewBadge(k.review_badge) : "")
      : "");
    var hint = document.getElementById("pf-log-hint");
    if (hint) hint.textContent = k && k.direction === "Lower is Better"
      ? "Lower is better for this KPI — attainment rises as the value falls."
      : (cumulative
          ? "Not the running total: just what you added since you last logged progress."
          : "The value as it stands today, not the amount added.");
    pfSetHtml("pf-log-history", "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">Loading history…</div>");
    pfOpenModal("pf-log-modal");
    pfLoadKpiUpdateHistory(kpiId, focusRow);
  };

  window.pfLogFileChanged = function() {
    var f = document.getElementById("pf-log-file").files[0];
    document.getElementById("pf-log-file-name").textContent = f ? f.name : "Click to attach image or document…";
  };

  window.pfSubmitLog = async function() {
    var kpi = pfVal("pf-log-kpi"), value = pfVal("pf-log-value");
    if (value === "") { pfShowErr("pf-log-error", "Enter a value."); return; }
    var btn = document.getElementById("pf-log-submit-btn");
    btn.disabled = true; btn.textContent = "Saving…";
    try {
      var evidenceUrl = null;
      var fileInput = document.getElementById("pf-log-file");
      if (fileInput.files.length > 0) {
        var fd = new FormData();
        fd.append("file", fileInput.files[0]);
        fd.append("is_private", "1");
        var upResp = await fetch("/api/method/upload_file", {method: "POST", body: fd,
          headers: {"X-Frappe-CSRF-Token": frappe && frappe.csrf_token ? frappe.csrf_token : ""}});
        var upData = await upResp.json();
        if (upData && upData.message && upData.message.file_url) {
          evidenceUrl = upData.message.file_url;
        } else {
          pfShowErr("pf-log-error", "File upload failed — please try again.");
          btn.disabled = false; btn.textContent = "Save Progress"; return;
        }
      }
      await pf("log_kpi_progress", {kpi: kpi, value: value, note: pfVal("pf-log-note"),
                                    evidence_url: evidenceUrl, log_date: pfVal("pf-log-date")});
      pfCloseModal("pf-log-modal");
      fileInput.value = "";
      document.getElementById("pf-log-file-name").textContent = "Click to attach image or document…";
      pfLoadMyKpis();
    } catch(e) {
      pfShowErr("pf-log-error", e.message);
    } finally {
      btn.disabled = false; btn.textContent = "Save Progress";
    }
  };

  /* ── Update history & approval JS ──────────────────── */

  var _pfIsManager = false; // set when the notif panel opens, from get_pending_approvals

  function pfFmtDate(dt) {
    if (!dt) return "";
    return new Date(dt).toLocaleString(undefined, {day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"});
  }

  function renderUpdateTimeline(rows, containerId, doctype, docname) {
    var el = document.getElementById(containerId);
    if (!el) return;
    if (!rows || !rows.length) {
      el.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">No updates yet.</div>";
      return;
    }
    var html = "";
    rows.forEach(function(r) {
      var status = (r.approval_status || "Pending").toLowerCase();
      var evHtml = "";
      if (r.evidence_file) {
        evHtml = "<a class=\"upd-ev-link\" href=\"" + gpEsc(r.evidence_file) + "\" target=\"_blank\" rel=\"noopener\"><i class=ic-paperclip></i> View Evidence</a>";
      } else {
        evHtml = "<span class=\"upd-ev-missing\"><i class=ic-alert></i> No evidence attached</span>";
      }
      var approvalHtml = "";
      // r.can_action, not _pfIsManager: being A manager is not being THIS
      // person's manager. The server knows who the goal owner reports to; the
      // browser does not, and drawing the buttons for every manager offered an
      // action the backend then refused.
      if (status === "pending" && r.can_action) {
        approvalHtml = "<div class=\"upd-approve-row\">" +
          "<input class=\"upd-approve-comment\" placeholder=\"Comment (optional)\" id=\"apc-" + gpEsc(r.name) + "\">" +
          "<button class=\"upd-btn-approve\" onclick=\"approveUpdate('" + gpEsc(doctype) + "','" + gpEsc(docname) + "','" + gpEsc(r.name) + "','Approved')\">Approve</button>" +
          "<button class=\"upd-btn-reject\" onclick=\"approveUpdate('" + gpEsc(doctype) + "','" + gpEsc(docname) + "','" + gpEsc(r.name) + "','Rejected')\">Reject</button>" +
        "</div>";
      } else if (status !== "pending") {
        approvalHtml = "<div class=\"upd-approved-by\">" +
          (status === "approved" ? "<i class=ic-check></i> Approved" : "<i class=ic-x></i> Rejected") +
          (r.approved_by_name ? " by " + gpEsc(r.approved_by_name) : "") +
          (r.approved_on ? " · " + pfFmtDate(r.approved_on) : "") +
          (r.approval_comment ? " — " + gpEsc(r.approval_comment) : "") +
        "</div>";
      }
      html += "<div class=\"upd-entry " + gpEsc(status) + "\" id=\"upd-row-" + gpEsc(r.name) + "\">" +
        "<div class=\"upd-entry-hdr\">" +
          "<span class=\"upd-who\">" + gpEsc(r.logged_by_name || r.logged_by || "") + "</span>" +
          "<span class=\"upd-when\">" + pfFmtDate(r.log_date) + "</span>" +
          /* When it was typed, beside the day it is for, so a back-dated
             reading is plain to the approver (security review m2). */
          (r.logged_on && String(r.logged_on).slice(0, 10) !== String(r.log_date || "").slice(0, 10)
            ? "<span class=\"upd-when\">typed " + pfFmtDate(r.logged_on) + "</span>"
            : "") +
          "<span class=\"upd-val\">Value: <strong>" + pfNum(r.value, 2) + "</strong></span>" +
        "</div>" +
        (r.note ? "<div class=\"upd-note\">" + gpEsc(r.note) + "</div>" : "") +
        "<div class=\"upd-chips\">" +
          evHtml +
          "<span class=\"upd-chip " + gpEsc(status) + "\">" + gpEsc(r.approval_status || "Pending") + "</span>" +
        "</div>" +
        approvalHtml +
      "</div>";
    });
    el.innerHTML = html;
  }

  window.pfLoadKpiUpdateHistory = function(kpiId, focusRow) {
    pf("get_kpi_update_log", {kpi: kpiId}).then(function(rows) {
      renderUpdateTimeline(rows, "pf-log-history", "KPI", kpiId);
      if (focusRow) {
        var el = document.getElementById("upd-row-" + focusRow);
        if (el) { el.scrollIntoView({behavior:"smooth", block:"center"}); }
      }
    }).catch(function() {
      pfSetHtml("pf-log-history", "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">Could not load history.</div>");
    });
  };

  window.approveUpdate = function(doctype, docname, rowName, action) {
    var commentEl = document.getElementById("apc-" + rowName);
    var comment = commentEl ? commentEl.value : "";
    if (doctype === "KPI") {
      pf("approve_kpi_update", {kpi: docname, row_name: rowName, action: action, comment: comment}).then(function() {
        pfLoadKpiUpdateHistory(docname);
        hmPendingReload();
      }).catch(function(e) { alert("Error: " + e.message); });
    } else {
      gpFetch("alvoraa_portal.goals_api.approve_goal_update", {goal_id: docname, row_name: rowName, action: action, comment: comment}).then(function() {
        loadGoalUpdateHistory(docname);
        hmPendingReload();
      }).catch(function(e) { alert("Error: " + e.message); });
    }
  };

  // Expose for top-level goal drawer functions
  window.renderUpdateTimeline = renderUpdateTimeline;
  window.pfFmtDate = pfFmtDate;

  /* ── The bell ──────────────────────────────────────────────────────
     Slice 076: it opens the Notices sheet, the same one as "See all" on Home,
     and its number is the unread count the Notices card shows. */

  window.toggleNotifPanel = function(e) {
    if (e) e.stopPropagation();
    ntOpenAll();
  };

  /* ALV-213: the phone header's account menu (My Account, Log out). */
  function setAcctMenu(open) {
    var m = document.getElementById("mob-acct-menu"), b = document.getElementById("mob-avatar");
    if (!m || !b) return;
    m.classList.toggle("open", open);
    b.setAttribute("aria-expanded", String(open));
  }
  window.toggleAcctMenu = function(e) {
    if (e) e.stopPropagation();
    var m = document.getElementById("mob-acct-menu");
    setAcctMenu(!(m && m.classList.contains("open")));
  };
  document.addEventListener("click", function(e) {
    if (!e.target.closest("#mob-acct-menu")) setAcctMenu(false);
  });
  document.addEventListener("keydown", function(e) {
    var m = document.getElementById("mob-acct-menu");
    if (e.key === "Escape" && m && m.classList.contains("open")) {
      setAcctMenu(false);
      document.getElementById("mob-avatar").focus();
    }
  });

  /* Boot: the bell's number, from the same call the Notices card makes. */
  setTimeout(function() { ntBellBoot(); }, 1500);

  /* Rating a KPI outside the review is gone (slice 010 group D, R14). Ratings
     are given on the review's own copy, inside the review, so a rating can
     never reach a live record around the review's stage and stamp rules.
     pfOpenSelfRating, pfSubmitSelfRating, pfSaveRating and pfSuggest were the
     last callers of the retired endpoints and were removed with their dialog. */

  /* ══════════════════════════════════════════════════════════════════
     Objectives & KPIs — one view, hierarchy or flat list.
     Objectives nest by reporting line; each KPI sits under the objective
     it is linked to. Dragging a KPI onto an objective re-links it, and the
     server re-validates the move, so the drop is a request, not a decision.
     ══════════════════════════════════════════════════════════════════ */

  var _tvShow = "all";
  var _tvView = "tree";
  var _tvData = null;
  var _tvCollapsed = {};
  var _tvDrag = null;
  var _tvQuery = "";

  var TV_ICON = {
    edit: "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z\"/></svg>",
    del:  "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"3 6 5 6 21 6\"/><path d=\"M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6\"/><path d=\"M10 11v6M14 11v6\"/></svg>",
    log:  "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>",
    cycle: "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12a9 9 0 11-3-6.7L21 8\"/><path d=\"M21 3v5h-5\"/><circle cx=\"12\" cy=\"12\" r=\"2.5\"/></svg>",
    grip: "<svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><circle cx=\"9\" cy=\"6\" r=\"1.6\"/><circle cx=\"15\" cy=\"6\" r=\"1.6\"/><circle cx=\"9\" cy=\"12\" r=\"1.6\"/><circle cx=\"15\" cy=\"12\" r=\"1.6\"/><circle cx=\"9\" cy=\"18\" r=\"1.6\"/><circle cx=\"15\" cy=\"18\" r=\"1.6\"/></svg>",
    checkin: "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z\"/></svg>",
    upward: "<svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 19V5M5 12l7-7 7 7\"/></svg>"
  };

  /* ── Filter state ────────────────────────────────── */

  window.tvSetShow = function(mode) {
    _tvShow = mode;
    [["all","tvf-all"],["objectives","tvf-obj"],["kpis","tvf-kpi"]].forEach(function(p) {
      var b = document.getElementById(p[1]);
      if (b) { b.classList.toggle("active", p[0] === mode); b.setAttribute("aria-pressed", p[0] === mode); }
    });
    // A flat KPI set has no hierarchy to draw, so switch the view with it.
    if (mode === "kpis" && _tvView === "tree") tvSetView("list", true);
    else tvLoad();
  };

  window.tvSetView = function(view, skipLoad) {
    _tvView = view;
    [["tree","tvv-tree"],["list","tvv-list"]].forEach(function(p) {
      var b = document.getElementById(p[1]);
      if (b) { b.classList.toggle("active", p[0] === view); b.setAttribute("aria-pressed", p[0] === view); }
    });
    ["tv-dnd-hint"].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.style.display = view === "tree" ? "" : "none";
    });
    if (!skipLoad) tvRender();
    else tvLoad();
  };

  window.tvClearFilters = function() {
    ["tv-from","tv-to","tv-prog-min","tv-prog-max"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    var c = document.getElementById("tv-category"); if (c) c.value = "";
    var sc = document.getElementById("tv-scope"); if (sc) sc.value = "mine";
    document.querySelectorAll("input[name='tv-scope-radio']").forEach(function(r) { r.checked = (r.value === "mine"); });
    document.querySelectorAll(".tv-traj-cb").forEach(function(cb) { cb.checked = false; });
    tvClearSearch(true);
    tvSetShow("all");
  };

  /* ── Search: filters what is already loaded, so it is instant ──
     A match keeps its ancestors visible, otherwise a deep hit would appear
     detached from the hierarchy that gives it meaning. */

  window.tvSearch = function() {
    _tvQuery = (pfVal("tv-search") || "").toLowerCase().trim();
    var wrap = document.querySelector(".tv-search");
    if (wrap) wrap.classList.toggle("has-value", !!_tvQuery);
    tvRender();
  };

  window.tvClearSearch = function(skipRender) {
    var el = document.getElementById("tv-search");
    if (el) el.value = "";
    _tvQuery = "";
    var wrap = document.querySelector(".tv-search");
    if (wrap) wrap.classList.remove("has-value");
    if (!skipRender) tvRender();
  };

  window.tvSearchKey = function(ev) {
    if (ev.key === "Escape") { ev.preventDefault(); tvClearSearch(); ev.target.blur(); }
  };

  function tvHit(text) {
    return !!_tvQuery && String(text || "").toLowerCase().indexOf(_tvQuery) >= 0;
  }

  function tvHighlight(text) {
    var s = String(text || "");
    if (!_tvQuery) return gpEsc(s);
    var i = s.toLowerCase().indexOf(_tvQuery);
    if (i < 0) return gpEsc(s);
    return gpEsc(s.slice(0, i)) + "<mark>" + gpEsc(s.slice(i, i + _tvQuery.length)) +
           "</mark>" + gpEsc(s.slice(i + _tvQuery.length));
  }

  function tvGoalMatches(g) {
    return tvHit(g.goal_name) || tvHit(g.employee_name);
  }

  function tvKpiMatches(k) {
    return tvHit(k.kpi_name) || tvHit(k.employee_name) || tvHit(k.category);
  }

  // Keep a branch if it matches, or anything beneath it does.
  function tvBranchMatches(node) {
    if (!_tvQuery) return true;
    if (tvGoalMatches(node)) return true;
    if ((node.kpis || []).some(tvKpiMatches)) return true;
    return (node.children || []).some(tvBranchMatches);
  }

  /* ── Popovers ────────────────────────────────────── */

  /* Overlays are moved to <body> before they open. See the .tv-pop rule for
     why: the sticky control bar is a stacking context, so anything left inside
     it renders below the sidebar no matter what z-index it carries. */

  function tvPlace(el, btn) {
    if (!el || !btn) return;
    if (el.parentNode !== document.body) document.body.appendChild(el);
    var r = btn.getBoundingClientRect();
    var w = el.offsetWidth || parseFloat(window.getComputedStyle(el).width) || 300;
    // Right-align with the trigger, but never off either edge of the viewport.
    var left = Math.min(Math.max(12, r.right - w), Math.max(12, window.innerWidth - w - 12));
    el.style.top = (r.bottom + 6) + "px";
    el.style.left = left + "px";
  }

  function tvReposition() {
    var menu = document.getElementById("tv-new-menu");
    if (menu && menu.classList.contains("open")) tvPlace(menu, document.getElementById("tv-new-btn"));
    /* Slice 045: the filter popover is portaled too now, so it has to follow
       its trigger on resize and scroll like the New menu does - otherwise it
       sits where the button USED to be. */
    var pop = document.getElementById("tv-pop");
    if (pop && pop.classList.contains("open")) {
      tvPlace(pop, document.getElementById("tv-filter-btn"));
    }
  }
  window.addEventListener("resize", tvReposition);
  window.addEventListener("scroll", tvReposition, true);

  window.tvTogglePop = function(ev) {
    if (ev) ev.stopPropagation();
    tvCloseNew();
    var pop = document.getElementById("tv-pop");
    var bd  = document.getElementById("tv-pop-backdrop");
    var btn = document.getElementById("tv-filter-btn");
    if (!pop) return;
    var open = !pop.classList.contains("open");
    if (open) {
      /* **Slice 045: this line was missing, and the filter popover rendered
         under the sidebar.**

         The comment above this block says overlays are moved to <body> before
         they open, and the `.tv-pop` CSS rule says why: `.tv-controls` is
         `position: sticky` with a z-index, which forms a stacking context, so
         a descendant's z-index cannot lift it above the sidebar's 50 however
         large the number is. `tvToggleNew` below has always called `tvPlace`.
         This one never did, so the popover kept its 1180 and still painted
         underneath.

         Found by `portal_redesign_test.js`, which asserts exactly this and had
         **never run** - it was skipped for want of a fixture. A skipped test
         is not coverage; this is what was behind the skip. */
      tvPlace(pop, btn);
      if (bd && bd.parentNode !== document.body) { document.body.appendChild(bd); }
      pop.classList.add("open");
      if (bd) bd.classList.add("open");
    } else {
      pop.classList.remove("open");
      if (bd) bd.classList.remove("open");
    }
    if (btn) btn.setAttribute("aria-expanded", open);
  };
  window.tvClosePop = function() {
    var pop = document.getElementById("tv-pop");
    var bd  = document.getElementById("tv-pop-backdrop");
    var btn = document.getElementById("tv-filter-btn");
    if (pop) pop.classList.remove("open");
    if (bd)  bd.classList.remove("open");
    if (btn) btn.setAttribute("aria-expanded", "false");
  };
  window.tvToggleNew = function(ev) {
    if (ev) ev.stopPropagation();
    tvClosePop();
    var m = document.getElementById("tv-new-menu");
    var b = document.getElementById("tv-new-btn");
    if (!m) return;
    var open = !m.classList.contains("open");
    if (open) { tvPlace(m, b); m.classList.add("open"); tvPlace(m, b); }
    else m.classList.remove("open");
    if (b) b.setAttribute("aria-expanded", open);
  };
  window.tvCloseNew = function() {
    var m = document.getElementById("tv-new-menu");
    var b = document.getElementById("tv-new-btn");
    if (m) m.classList.remove("open");
    if (b) b.setAttribute("aria-expanded", "false");
  };

  // Once portaled, the overlay's parent is <body>, so "outside" has to be
  // measured against the overlay and its trigger rather than a wrapper.
  document.addEventListener("click", function(ev) {
    var pop = document.getElementById("tv-pop");
    var menu = document.getElementById("tv-new-menu");
    var popBtn = document.getElementById("tv-filter-btn");
    var newBtn = document.getElementById("tv-new-btn");
    if (pop && pop.classList.contains("open") &&
        !pop.contains(ev.target) && !(popBtn && popBtn.contains(ev.target))) tvClosePop();
    if (menu && menu.classList.contains("open") &&
        !menu.contains(ev.target) && !(newBtn && newBtn.contains(ev.target))) tvCloseNew();
  });

  document.addEventListener("keydown", function(ev) {
    if (ev.key === "Escape") { tvClosePop(); tvCloseNew(); }
  });

  // "/" jumps to search the way it does in most tools with a lot of rows.
  document.addEventListener("keydown", function(ev) {
    if (ev.key !== "/" || ev.metaKey || ev.ctrlKey || ev.altKey) return;
    var t = ev.target || {};
    if (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable) return;
    var panel = document.getElementById("gp-tab-tree");
    if (!panel || panel.style.display === "none") return;
    var box = document.getElementById("tv-search");
    if (box) { ev.preventDefault(); box.focus(); box.select(); }
  });

  window.tvExpandAll = function(expand) {
    if (!_tvData) return;
    (function walk(nodes) {
      (nodes || []).forEach(function(n) {
        _tvCollapsed[n.name] = !expand;
        walk(n.children);
      });
    })(_tvData.roots);
    tvRender();
  };

  /* ── Load & render ───────────────────────────────── */

  function tvSelectedTrajectories() {
    return Array.prototype.slice
      .call(document.querySelectorAll(".tv-traj-cb:checked"))
      .map(function(cb) { return cb.value; });
  }

  window.tvLoad = function() {
    pfSetHtml("tv-body", "<div class=\"tv-skeleton\" aria-busy=\"true\"><i></i><i></i><i></i></div>");
    pf("get_performance_tree", {
      show: _tvShow,
      scope: pfVal("tv-scope") || "team",
      cycle: pfVal("tv-cycle"),
      date_from: pfVal("tv-from"),
      date_to: pfVal("tv-to"),
      category: pfVal("tv-category"),
      trajectory: tvSelectedTrajectories().join(","),
      progress_min: pfVal("tv-prog-min"),
      progress_max: pfVal("tv-prog-max")
    }).then(function(d) {
      _tvData = d;
      tvFillCategories(d.categories || []);
      var flat = [];
      (function walk(nodes) {
        (nodes || []).forEach(function(n) {
          flat = flat.concat(n.kpis || []);
          walk(n.children);
        });
      })(d.roots);
      flat = flat.concat(d.unattached_kpis || []);
      pfCacheKpis(flat, d.employee_id);
      tvRenderChips();
      tvRender();
    }).catch(function(e) {
      pfSetHtml("tv-body", "<div class=\"callout callout-warn\">Failed to load: " + gpEsc(e.message) + "</div>");
    });
  };

  function tvFillCategories(cats) {
    var sel = document.getElementById("tv-category");
    if (!sel) return;
    var current = sel.value;
    sel.innerHTML = "<option value=\"\">All categories</option>" + cats.map(function(c) {
      return "<option value=\"" + gpEsc(c) + "\">" + gpEsc(c) + "</option>";
    }).join("");
    sel.value = current;
  }

  // Filters hidden in the popover still announce themselves, and each chip
  // removes exactly the one filter it names.
  function tvRenderChips() {
    var chips = [];
    var from = pfVal("tv-from"), to = pfVal("tv-to");
    if (from || to) {
      chips.push({label: "Period", value: (from ? gpFmtDate(from) : "any") + " – " + (to ? gpFmtDate(to) : "any"),
                  clear: "tvChipClear('dates')"});
    }
    var cat = pfVal("tv-category");
    if (cat) chips.push({label: "Category", value: cat, clear: "tvChipClear('category')"});
    var cySel = document.getElementById("tv-cycle");
    if (cySel && cySel.value) {
      var cyOpt = cySel.options[cySel.selectedIndex];
      if (cyOpt) chips.push({label: "Cycle", value: cyOpt.text.split(" · ")[0],
                  clear: "tvChipClear('cycle')"});
    }
    var scopeHid = document.getElementById("tv-scope");
    if (scopeHid && scopeHid.value && scopeHid.value !== "mine") {
      var _scopeLabels = {team: "Me & my team", department: "My department", organisation: "Whole organisation"};
      chips.push({label: "Scope", value: _scopeLabels[scopeHid.value] || scopeHid.value, clear: "tvChipClear('scope')"});
    }
    var traj = tvSelectedTrajectories();
    if (traj.length) {
      chips.push({label: "Status", value: traj.join(", "), clear: "tvChipClear('trajectory')"});
    }
    var lo = pfVal("tv-prog-min"), hi = pfVal("tv-prog-max");
    if (lo !== "" || hi !== "") {
      chips.push({label: "Progress",
                  value: (lo !== "" ? lo : "0") + "–" + (hi !== "" ? hi : "100") + "%",
                  clear: "tvChipClear('progress')"});
    }

    var el = document.getElementById("tv-chips");
    var count = document.getElementById("tv-filter-count");
    if (count) { count.hidden = !chips.length; count.textContent = chips.length; }
    if (!el) return;
    el.hidden = !chips.length;
    el.innerHTML = chips.map(function(c) {
      return "<span class=\"tv-chip\">" + gpEsc(c.label) + " <b>" + gpEsc(c.value) + "</b>" +
        "<button onclick=\"" + c.clear + "\" aria-label=\"Remove " + gpEsc(c.label) + " filter\">&times;</button></span>";
    }).join("") + (chips.length > 1
      ? "<button class=\"tv-ghost\" onclick=\"tvClearFilters()\">Clear all</button>" : "");
  }

  window.tvChipClear = function(which) {
    if (which === "dates") {
      ["tv-from","tv-to"].forEach(function(id) { var e = document.getElementById(id); if (e) e.value = ""; });
    } else if (which === "category") {
      var c = document.getElementById("tv-category"); if (c) c.value = "";
    } else if (which === "cycle") {
      var cy = document.getElementById("tv-cycle"); if (cy) cy.value = "";
    } else if (which === "scope") {
      var sc = document.getElementById("tv-scope"); if (sc) sc.value = "mine";
      document.querySelectorAll("input[name='tv-scope-radio']").forEach(function(r) { r.checked = (r.value === "mine"); });
    } else if (which === "trajectory") {
      document.querySelectorAll(".tv-traj-cb").forEach(function(cb) { cb.checked = false; });
    } else if (which === "progress") {
      ["tv-prog-min","tv-prog-max"].forEach(function(id) {
        var e = document.getElementById(id); if (e) e.value = "";
      });
    }
    tvLoad();
  };

  window.tvSetScope = function(v) {
    var sc = document.getElementById("tv-scope"); if (sc) sc.value = v;
    tvLoad();
  };

  function tvRender() {
    if (!_tvData) return;
    tvRenderChips();

    if (_tvView === "list" || _tvShow === "kpis") { tvRenderList(); return; }

    var roots = (_tvData.roots || []).filter(tvBranchMatches);
    var loose = (_tvData.unattached_kpis || []).filter(function(k) {
      return !_tvQuery || tvKpiMatches(k);
    });

    if (!roots.length && !loose.length) { tvEmpty(); return; }

    var html = roots.map(function(n) { return tvNode(n, 0); }).join("");
    if (_tvShow !== "objectives") {
      var zone = "<div class=\"tv-drop-zone\" data-drop=\"__none__\">" +
                 "Drop a KPI here to detach it from its objective</div>";
      html += (loose.length || !_tvQuery)
        ? "<div class=\"tv-group-title\">Not linked to an objective</div>" + zone +
          loose.map(function(k) { return tvKpiRow(k); }).join("")
        : "";
    }
    pfSetHtml("tv-body", html);
    tvSummary(roots, loose);
    tvBindDnd();
  }

  function tvRenderList() {
    var rows = [];
    if (_tvShow !== "kpis") {
      (_tvData.flat_goals || []).filter(function(g) { return !_tvQuery || tvGoalMatches(g); })
        .forEach(function(g) { rows.push(tvGoalRow(g, true)); });
    }
    var kpis = [];
    if (_tvShow !== "objectives") {
      (function walk(nodes) {
        (nodes || []).forEach(function(n) { kpis = kpis.concat(n.kpis || []); walk(n.children); });
      })(_tvData.roots);
      kpis = kpis.concat(_tvData.unattached_kpis || [])
              .filter(function(k) { return !_tvQuery || tvKpiMatches(k); });
      kpis.forEach(function(k) { rows.push(tvKpiRow(k, true)); });
    }
    if (!rows.length) { tvEmpty(); return; }
    pfSetHtml("tv-body", rows.join(""));
    tvSummaryFlat(rows.length);
    tvBindDnd();
  }

  function tvEmpty() {
    // Distinguish "you have nothing" from "nothing matches", because the
    // remedy is completely different.
    if (_tvQuery) {
      pfSetHtml("tv-body", "<div class=\"empty-state\"><div class=\"empty-state-icon\"><i class=ic-search></i></div>" +
        "<div class=\"empty-state-text\">Nothing matches \"" + gpEsc(_tvQuery) + "\".</div>" +
        "<div style=\"margin-top:10px\"><button class=\"btn btn-outline btn-sm\" onclick=\"tvClearSearch()\">Clear search</button></div></div>");
    } else {
      pfSetHtml("tv-body", "<div class=\"empty-state\"><div class=\"empty-state-icon\"><i class=ic-target></i></div>" +
        "<div class=\"empty-state-text\">Nothing here yet. Create an objective, then hang KPIs off it.</div>" +
        "<div style=\"margin-top:10px;display:flex;gap:8px;justify-content:center\">" +
        "<button class=\"btn btn-primary btn-sm\" onclick=\"gpOpenCreateGoal()\">+ Objective</button>" +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenKpiModal('tree')\">+ KPI</button></div></div>");
    }
    pfSetHtml("tv-summary", "");
  }

  function tvSummary(roots, loose) {
    var c = _tvData.counts || {};
    var shownObj = 0, shownKpi = loose.length, ctx = 0;
    (function walk(nodes) {
      (nodes || []).forEach(function(n) {
        shownObj++;
        if (n.context) ctx++;
        shownKpi += (n.kpis || []).length;
        walk(n.children);
      });
    })(roots);
    var matched = shownObj - ctx;
    var txt = matched + " objective" + (matched === 1 ? "" : "s") +
              " · " + shownKpi + " KPI" + (shownKpi === 1 ? "" : "s");
    if (ctx) txt += " · " + ctx + " parent" + (ctx === 1 ? "" : "s") + " shown for context";
    if (_tvQuery && (shownObj !== c.objectives || shownKpi !== c.kpis)) {
      txt += " matching \"" + _tvQuery + "\"";
    }
    var scopeHid2 = document.getElementById("tv-scope");
    if (scopeHid2 && _tvData.scope_size) {
      var _sl = {mine: "only mine", team: "me & my team", department: "my department", organisation: "whole organisation"};
      var scLbl = _sl[scopeHid2.value] || scopeHid2.value;
      if (scLbl) txt += " · " + scLbl + " (" + _tvData.scope_size + " employee" + (_tvData.scope_size === 1 ? "" : "s") + ")";
    }
    pfSetHtml("tv-summary", gpEsc(txt));
  }

  function tvSummaryFlat(n) {
    pfSetHtml("tv-summary", gpEsc(n + " row" + (n === 1 ? "" : "s") +
      (_tvQuery ? " matching \"" + _tvQuery + "\"" : "")));
  }

  function tvNode(node, depth) {
    // While searching, force branches open so hits are never hidden behind a
    // collapsed caret.
    var collapsed = _tvQuery ? false : _tvCollapsed[node.name];
    var kids = (node.children || []).filter(tvBranchMatches);
    var kpis = _tvShow === "objectives" ? []
             : (node.kpis || []).filter(function(k) { return !_tvQuery || tvKpiMatches(k); });
    var hasKids = kids.length || kpis.length;
    var inner = "";
    if (!collapsed && hasKids) {
      inner = "<div class=\"tv-children\" role=\"group\">" +
        kpis.map(function(k) { return tvKpiRow(k); }).join("") +
        kids.map(function(k) { return tvNode(k, depth + 1); }).join("") +
        "</div>";
    }
    return tvGoalRow(node, false, hasKids, collapsed) + inner;
  }

  function tvGoalRow(g, flat, hasKids, collapsed) {
    var pct = Math.round(g.progress_pct || 0);
    var colour = gpTrajColor(g.trajectory);
    var org = g.is_organisational;
    var hit = _tvQuery && tvGoalMatches(g);
    var mine = g.employee === (_tvData && _tvData.employee_id);
    var caret = (flat || !hasKids)
      ? "<span class=\"tv-caret tv-leaf\"></span>"
      : "<button class=\"tv-caret\" onclick=\"event.stopPropagation();tvToggle('" + gpEsc(g.name) + "')\"" +
        " aria-expanded=\"" + (!collapsed) + "\" aria-label=\"" + (collapsed ? "Expand" : "Collapse") + "\">" +
        (collapsed ? "&#9654;" : "&#9660;") + "</button>";

    // Rows pulled in only to keep the cascade whole are dimmed and labelled,
    // so a filtered view never looks like it returned unmatched results.
    var ctx = g.context
      ? "<span class=\"tv-ctx-tag\" title=\"Shown to keep the cascade intact\">context</span>" : "";

    return "<div class=\"tv-row " + (org ? "tv-goal-org" : "tv-goal") + (hit ? " tv-hit" : "") +
        (g.context ? " tv-context" : "") + (g.is_overdue ? " tv-overdue" : "") + "\"" +
        " role=\"treeitem\" data-drop=\"" + gpEsc(g.name) + "\" data-owner=\"" + gpEsc(g.employee) + "\">" +
      "<span class=\"tv-grip tv-grip-off\" aria-hidden=\"true\">" + TV_ICON.grip + "</span>" +
      caret +
      "<div class=\"tv-main\" onclick=\"gpOpenDetail('" + gpEsc(g.name) + "')\" title=\"Open objective\">" +
        "<div class=\"tv-name\">" + tvHighlight(g.goal_name) +
          "<span class=\"tv-badge " + (org ? "tv-badge-org" : "tv-badge-obj") + "\">" +
          (org ? "Organisational" : "Objective") + "</span>" + ctx +
          (g.goal_type === "Development" ? "<span class=\"tv-badge\" style=\"background:var(--sky);color:var(--surface)\">Dev</span>" : "") +
          (g.is_extra_initiative ? "<span class=\"tv-badge\" style=\"background:var(--amber);color:var(--surface)\">Stretch</span>" : "") +
          (g.company_value ? "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\" title=\"" + gpEsc(g.company_value) + "\">" + gpEsc(g.company_value) + "</span>" : "") +
          tvOverdueTag(g.is_overdue) + tvCycleTag(g.review_badge) + "</div>" +
        "<div class=\"tv-meta\">" + tvHighlight(g.employee_name || "") +
          " · target " + (g.target_value || 0) + " " + gpEsc(g.unit || "") +
          " · " + gpFmtDate(g.start_date) + " – " + gpFmtDate(g.end_date) + "</div>" +
      "</div>" +
      "<div class=\"tv-right\">" +
        "<div class=\"tv-bar\"><div class=\"tv-bar-fill\" style=\"width:" + pct + "%;background:" + colour + "\"></div></div>" +
        "<div class=\"tv-pct\">" + pct + "%</div>" +
        "<div class=\"tv-acts\">" +
        (mine ? "<button class=\"tv-icon\" title=\"Log a check-in\" aria-label=\"Log check-in\"" +
          " onclick=\"event.stopPropagation();gpOpenCheckin('" + gpEsc(g.name) + "','" + gpEsc(g.goal_name) + "')\">" + TV_ICON.checkin + "</button>" : "") +
        (g.can_edit
          ? "<button class=\"tv-icon\" title=\"Edit objective\" aria-label=\"Edit objective\"" +
              " onclick='event.stopPropagation();gpOpenEditGoal(" + JSON.stringify(JSON.stringify(g)) + ")'>" + TV_ICON.edit + "</button>" +
            "<button class=\"tv-icon tv-danger\" title=\"Delete objective\" aria-label=\"Delete objective\"" +
              " onclick=\"event.stopPropagation();gpDeleteGoal('" + gpEsc(g.name) + "','" + gpEsc(g.goal_name) + "')\">" + TV_ICON.del + "</button>"
          : "") + "</div>" +
      "</div></div>";
  }

  function tvKpiRow(k, flat) {
    var pct = Math.max(0, Math.min(100, k.attainment_pct || 0));
    var colour = pfAttColor(k.attainment_pct || 0);
    var mine = k.employee === (_tvData && _tvData.employee_id);
    var hit = _tvQuery && tvKpiMatches(k);
    // Only the author may re-link, so only they get a grip to drag by.
    var grip = k.can_edit
      ? "<span class=\"tv-grip\" title=\"Drag to re-link\" aria-hidden=\"true\">" + TV_ICON.grip + "</span>"
      : "<span class=\"tv-grip tv-grip-off\" aria-hidden=\"true\">" + TV_ICON.grip + "</span>";

    return "<div class=\"tv-row tv-kpi" + (hit ? " tv-hit" : "") +
        (k.is_overdue ? " tv-overdue" : "") + "\" role=\"treeitem\"" +
        " data-kpi=\"" + gpEsc(k.name) + "\" data-owner=\"" + gpEsc(k.employee) + "\"" +
        (k.can_edit ? " draggable=\"true\"" : "") + ">" +
      grip +
      "<span class=\"tv-caret tv-leaf\"></span>" +
      "<div class=\"tv-main\"" + (mine ? " onclick=\"pfOpenLog('" + gpEsc(k.name) + "')\" title=\"Log progress\"" : "") + ">" +
        "<div class=\"tv-name\">" + tvHighlight(k.kpi_name) +
          "<span class=\"tv-badge tv-badge-kpi\">KPI</span>" +
          (k.is_extra_initiative ? "<span class=\"tv-badge\" style=\"background:var(--amber);color:var(--surface)\">Stretch</span>" : "") +
          (k.company_value ? "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\" title=\"" + gpEsc(k.company_value) + "\">" + gpEsc(k.company_value) + "</span>" : "") +
          tvOverdueTag(k.is_overdue) + tvCycleTag(k.review_badge) + "</div>" +
        "<div class=\"tv-meta\">" + tvHighlight(k.employee_name || "") +
          " · " + tvHighlight(k.category || "") +
          " · target " + (k.target_value || 0) + " " + gpEsc(k.unit || "") +
          " · weight " + pfNum(k.weightage) + "%" +
          (flat && k.objective ? " · under \"" + gpEsc(k.objective) + "\"" : "") + "</div>" +
      "</div>" +
      "<div class=\"tv-right\">" +
        "<div class=\"tv-bar\"><div class=\"tv-bar-fill\" style=\"width:" + pct + "%;background:" + colour + "\"></div></div>" +
        "<div class=\"tv-pct\" style=\"color:" + colour + "\">" + pfNum(k.attainment_pct) + "%</div>" +
        "<div class=\"tv-acts\">" +
          (mine ? "<button class=\"tv-icon\" title=\"Log progress\" aria-label=\"Log progress\"" +
                  " onclick=\"event.stopPropagation();pfOpenLog('" + gpEsc(k.name) + "')\">" + TV_ICON.log + "</button>" : "") +
          (k.can_edit
            ? "<button class=\"tv-icon\" title=\"Edit KPI\" aria-label=\"Edit KPI\"" +
                " onclick='event.stopPropagation();pfEditKpi(" + JSON.stringify(JSON.stringify(Object.assign({}, k, {_returnTo: "tree"}))) + ")'>" + TV_ICON.edit + "</button>" +
              "<button class=\"tv-icon tv-danger\" title=\"Delete KPI\" aria-label=\"Delete KPI\"" +
                " onclick=\"event.stopPropagation();pfDeleteKpi('" + gpEsc(k.name) + "','" + gpEsc(k.kpi_name) + "')\">" + TV_ICON.del + "</button>"
            : "") +
        "</div>" +
      "</div></div>";
  }

  window.tvToggle = function(id) {
    _tvCollapsed[id] = !_tvCollapsed[id];
    tvRender();
  };

  function tvOverdueTag(flag) {
    return flag ? "<span class=\"tv-overdue-tag\" title=\"Deadline has passed\">overdue</span>" : "";
  }

  /* "In review" now means an open review holds this record, not that it is
     tagged to a cycle (slice 010 group D, R5). The wording says what it means
     for the owner: updates dated after that day do not change the review. It
     carries no review name, no rating and no link. */
  function tvCycleTag(badge) {
    return riReviewBadge(badge);
  }

  /* Nominating work for a cycle. Unlike editing, this is open to the item's
     owner and their managers — asking for something to be considered is not
     the same as rewriting it. */
  window.tvToggleCycle = function(kind, name, currentCycle) {
    var target = pfVal("tv-cycle") ||
                 ((_pfCtx && _pfCtx.active_cycle) ? _pfCtx.active_cycle.name : "");
    if (!target) {
      tvToast("err", "Pick a cycle in Filters first, or ask HR to open one.");
      return;
    }
    var include = currentCycle === target ? 0 : 1;
    pf("set_cycle_membership", {kind: kind, name: name, cycle: target, include: include})
      .then(function(r) { tvToast("ok", r.message); tvLoad(); })
      .catch(function(e) { tvToast("err", e.message); });
  };


  /* ── Drag and drop ─────────────────────────────────
     A KPI may only hang off an objective owned by its employee or someone
     above them. The client greys out obviously-invalid targets for feedback,
     but the server is what decides — the drop calls relink_kpi, which runs
     the same validation as any edit. */

  function tvBindDnd() {
    var body = document.getElementById("tv-body");
    if (!body) return;

    body.querySelectorAll(".tv-row.tv-kpi[draggable=true]").forEach(function(el) {
      el.addEventListener("dragstart", function(ev) {
        _tvDrag = {kpi: el.getAttribute("data-kpi"), owner: el.getAttribute("data-owner")};
        el.classList.add("tv-dragging");
        try { ev.dataTransfer.setData("text/plain", _tvDrag.kpi); } catch (e) {}
        ev.dataTransfer.effectAllowed = "move";
      });
      el.addEventListener("dragend", function() {
        el.classList.remove("tv-dragging");
        _tvDrag = null;
        body.querySelectorAll(".tv-drop-target,.tv-drop-reject").forEach(function(t) {
          t.classList.remove("tv-drop-target", "tv-drop-reject");
        });
      });
    });

    body.querySelectorAll("[data-drop]").forEach(function(zone) {
      zone.addEventListener("dragover", function(ev) {
        if (!_tvDrag) return;
        ev.preventDefault();
        ev.dataTransfer.dropEffect = "move";
        zone.classList.add("tv-drop-target");
      });
      zone.addEventListener("dragleave", function() {
        zone.classList.remove("tv-drop-target", "tv-drop-reject");
      });
      zone.addEventListener("drop", function(ev) {
        ev.preventDefault();
        zone.classList.remove("tv-drop-target", "tv-drop-reject");
        if (!_tvDrag) return;
        var target = zone.getAttribute("data-drop");
        tvRelink(_tvDrag.kpi, target === "__none__" ? "" : target);
      });
    });
  }

  // A floating toast, so confirming a move never reflows the tree under the
  // pointer mid-interaction.
  var _tvToastTimer = null;
  window.tvToast = function(kind, msg, sticky) {
    var el = document.getElementById("tv-msg");
    if (!el) return;
    el.className = "tv-toast tv-toast-" + kind;
    el.textContent = msg;
    el.hidden = false;
    el.setAttribute("role", kind === "err" ? "alert" : "status");
    clearTimeout(_tvToastTimer);
    if (!sticky) _tvToastTimer = setTimeout(function() { el.hidden = true; }, kind === "err" ? 7000 : 3500);
  };

  window.tvRelink = function(kpiId, goalId) {
    tvToast("warn", "Moving…", true);
    pf("relink_kpi", {kpi: kpiId, individual_goal: goalId}).then(function(r) {
      tvToast("ok", r.message);
      tvLoad();
    }).catch(function(e) {
      // The server refused — most often the objective is on a sibling branch.
      tvToast("err", e.message);
    });
  };

  /* ── Manager reviews ──────────────────────────────── */

  window.pfLoadReviews = function() {
    var cycle = pfVal("pf-review-cycle");
    pfSetHtml("pf-review-body", pfEmpty("Loading team…"));
    pf("get_team_reviews", {cycle: cycle}).then(function(d) {
      var team = d.team || [];
      if (!team.length) {
        pfSetHtml("pf-review-body", pfEmpty("You have no direct reports."));
        return;
      }
      pfSetHtml("pf-review-body",
        "<div class=\"tr-wrap\"><table class=\"tr-table\">" +
        "<thead><tr>" +
          "<th>Employee</th>" +
          "<th>Status</th>" +
          "<th>Progress</th>" +
          "<th>Period</th>" +
          "<th>Rating</th>" +
          "<th>Action</th>" +
        "</tr></thead>" +
        "<tbody>" +
        team.map(function(m) { return pfTeamReviewCard(m); }).join("") +
        "</tbody></table></div>"
      );
    }).catch(function(e) {
      pfSetHtml("pf-review-body", "<div class=\"callout callout-warn\">Failed to load team: " + gpEsc(e.message) + "</div>");
    });
  };

  function pfTeamReviewStatusBadge(status) {
    var cfg = {
      "Not Started":          {bg:"var(--surface2)",    color:"var(--text3)",    label:"Not Started"},
      "Employee Review":      {bg:"var(--primary-lt)",            color:"var(--primary)",         label:"Employee Review"},
      "Manager Review":       {bg:"var(--amber-lt)",            color:"var(--amber)",         label:"With You"},
      "Employee Final Review":{bg:"var(--green-lt)",            color:"var(--green)",         label:"Feedback Ready"},
      "HR Review":            {bg:"var(--primary-lt)",            color:"var(--primary)",         label:"HR Review"},
      "Completed":            {bg:"var(--kinexus-light,var(--green-lt))", color:"var(--kinexus,var(--green))", label:"Completed"},
    };
    var c = cfg[status] || {bg:"var(--surface2)", color:"var(--text3)", label: status || "Unknown"};
    return "<span style=\"display:inline-block;padding:2px 10px;border-radius:var(--r);font-size:var(--fs-xs);font-weight:700;background:" +
      c.bg + ";color:" + c.color + "\">" + gpEsc(c.label) + "</span>";
  }

  function pfTeamReviewCard(m) {
    var status = m.review_status || "Not Started";

    /* ── Avatar initials + deterministic color ── */
    var words = (m.employee_name || "?").trim().split(/\s+/);
    var initials = (words[0][0] + (words.length > 1 ? words[words.length - 1][0] : "")).toUpperCase();
    var palette = ["var(--primary)", "var(--green)", "var(--primary)", "var(--amber)", "var(--green)", "var(--primary)", "var(--red)", "var(--green)"];
    var h = 0;
    for (var ci = 0; ci < (m.employee_name || "").length; ci++) h += (m.employee_name || "").charCodeAt(ci);
    var avatarBg = palette[h % palette.length];

    /* ── Status chip ── */
    var chipCfg = {
      "Not Started":           {bg:"var(--surface2)",  color:"var(--text3)",   label:"Not Started"},
      "Employee Review":       {bg:"var(--primary-lt)",          color:"var(--primary)",        label:"Self-Review"},
      "Manager Review":        {bg:"var(--amber-lt)",          color:"var(--amber)",        label:"With You"},
      "Employee Final Review": {bg:"var(--green-lt)",          color:"var(--green-lt)",        label:"Feedback Ready"},
      "HR Review":             {bg:"var(--primary-lt)",          color:"var(--primary)",        label:"HR Review"},
      "Completed":             {bg:"var(--green-lt)",          color:"var(--green)",        label:"Completed"},
    };
    var chip = chipCfg[status] || {bg:"var(--surface2)", color:"var(--text3)", label: status};

    /* ── Pipeline progress dots ── */
    var stageOrder = ["Employee Review", "Manager Review", "Employee Final Review", "HR Review", "Completed"];
    var si = stageOrder.indexOf(status); /* -1 = Not Started */
    var isComplete = (status === "Completed");
    var pipe = "";
    for (var s = 0; s < stageOrder.length; s++) {
      var cls = (isComplete || s < si) ? "done" : (s === si ? "cur" : "");
      pipe += "<span class=\"tr-pd " + cls + "\"></span>";
    }

    /* ── Period ── */
    var period = (m.start_date && m.end_date)
      ? "<span style=\"font-size:var(--fs-sm);color:var(--text3);white-space:nowrap\">" + gpEsc(m.start_date) + " – " + gpEsc(m.end_date) + "</span>"
      : "<span style=\"color:var(--text3)\">—</span>";

    /* ── Rating ── */
    var ratingCell = (m.overall_rating != null && status !== "Not Started")
      ? "<span class=\"tr-rating\">" + pfNum(m.overall_rating, 1) + "<span class=\"tr-rating-denom\"> / 5</span></span>"
      : "<span style=\"color:var(--text3)\">—</span>";
    /* The numbers changed after this rating was given (R7, decision 12). */
    if (m.rating_needs_answer) {
      ratingCell += "<div style=\"font-size:var(--fs-xs);color:var(--amber);margin-top:2px\">" +
        "<i class=ic-alert></i> Rating needs your answer</div>";
    }

    /* ── Action ── */
    /* This list always opens a review as the manager (decision 37). HR's
       buttons, such as Finish Review, are on the HR review list only. */
    var action = "";
    if (!m.appraisal) {
      action = "<span class=\"tr-no-ap\">No appraisal</span>";
    } else if (status === "Manager Review") {
      action = "<button class=\"btn btn-primary btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"prOpenManagerReview('" +
        gpEsc(m.appraisal) + "','" + gpEsc(m.employee_name) + "','manager')\">Open Review</button>";
    } else if (status === "Employee Final Review" || status === "HR Review" || status === "Completed") {
      action = "<button class=\"btn " + (m.rating_needs_answer ? "btn-primary" : "btn-outline") +
        " btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"prOpenManagerReview('" +
        gpEsc(m.appraisal) + "','" + gpEsc(m.employee_name) + "','manager')\">" +
        (m.rating_needs_answer ? "Answer rating question" : "View Review") + "</button>";
    } else {
      action = "<span class=\"tr-await\">Awaiting employee</span>";
    }

    return "<tr>" +
      "<td><div class=\"tr-emp\">" +
        "<div class=\"tr-avatar\" style=\"background:" + avatarBg + "\">" + gpEsc(initials) + "</div>" +
        "<div class=\"tr-emp-name\">" + gpEsc(m.employee_name) + "</div>" +
      "</div></td>" +
      "<td><span class=\"tr-chip\" style=\"background:" + chip.bg + ";color:" + chip.color + "\">" +
        "<span class=\"tr-chip-dot\"></span>" + gpEsc(chip.label) +
      "</span></td>" +
      "<td><span class=\"tr-pipe\">" + pipe + "</span></td>" +
      "<td>" + period + "</td>" +
      "<td>" + ratingCell + "</td>" +
      "<td style=\"white-space:nowrap\">" + action + "</td>" +
    "</tr>";
  }

  /* pfSaveRating and pfSuggest are gone with the KPI rating row: a manager
     rates each item inside the review now (slice 010 group D, R14). The
     suggestion from measured attainment moved to riSuggestRatings, which reads
     the review's own copies. */

  window.pfSubmitReview = function(employee, cycle) {
    pfSetHtml("pf-rev-msg-" + employee, pfAlert("warn", "Submitting…"));
    pf("get_team_appraisal", {employee: employee, cycle: cycle}).then(function(d) {
      if (!d.appraisal) {
        pfSetHtml("pf-rev-msg-" + employee,
          pfAlert("err", "No appraisal exists for this employee yet — ask HR to generate appraisals for the cycle."));
        return;
      }
      return pf("submit_appraisal", {appraisal: d.appraisal.name}).then(function(res) {
        pfSetHtml("pf-rev-msg-" + employee,
          pfAlert("ok", "Submitted. Goal score " + pfNum(res.total_score, 2) +
                        " / 5, final score " + pfNum(res.final_score, 2) + " / 5."));
      });
    }).catch(function(e) {
      pfSetHtml("pf-rev-msg-" + employee, pfAlert("err", e.message));
    });
  };

  /* ── HR administration ────────────────────────────── */

  window.pfLoadHr = function(force) {
    if (_pfSetup && !force) { pfLoadHrCycle(); return; }
    pfSetHtml("pf-hr-body", pfEmpty("Loading setup…"));
    pf("hr_get_setup").then(function(s) {
      _pfSetup = s;
      pfFillHrSelects();
      pfLoadHrCycle();
    }).catch(function(e) {
      pfSetHtml("pf-hr-body", "<div class=\"callout callout-warn\">Failed to load HR setup: " + gpEsc(e.message) + "</div>");
    });
  };

  function pfFillHrSelects() {
    var s = _pfSetup || {};
    var empSel = document.getElementById("pf-k-employee");
    if (empSel) {
      empSel.innerHTML = (s.employees || []).map(function(e) {
        return "<option value=\"" + gpEsc(e.name) + "\">" + gpEsc(e.employee_name) +
               " · " + gpEsc(e.designation || "—") + "</option>";
      }).join("");
    }
    var cySel = document.getElementById("pf-k-cycle");
    if (cySel) {
      cySel.innerHTML = (s.cycles || []).map(function(c) {
        return "<option value=\"" + gpEsc(c.name) + "\">" + gpEsc(c.cycle_name || c.name) + "</option>";
      }).join("");
    }
  }

  /* ══════════════════════════════════════════════════════
     My Reviews Tab
  ══════════════════════════════════════════════════════ */

  var _mrLoaded = false;

  window.mrLoad = function(force) {
    if (_mrLoaded && !force) return;
    _mrLoaded = true;
    var body = document.getElementById("mr-body");
    if (body) body.innerHTML = "<div class=\"empty-state\"><div class=\"empty-state-text\">Loading your reviews…</div></div>";
    pf("get_my_appraisals", {}).then(function(data) {
      var own     = (data && data.own)     || (Array.isArray(data) ? data : []);
      var invited = (data && data.invited) || [];
      if (body) body.innerHTML = mrRenderList(own, invited);
    }).catch(function(e) {
      if (body) body.innerHTML = "<div class=\"callout callout-warn\">Failed to load reviews: " + gpEsc(e.message) + "</div>";
    });
  };

  function mrRenderList(rows, invitedRows) {
    var html = "";

    /* Own appraisals */
    if (!rows || !rows.length) {
      html += "<div class=\"pf-card\">" + pfEmpty("No performance reviews have been created for you yet.") + "</div>";
    } else {
      rows.forEach(function(r) {
        var statusMeta = _PF_REVIEW_STATUS_META[r.review_status] || {label: r.review_status || "Not Started", cls: "badge-gray"};
        var canOpen = r.review_status === "Not Started" || r.review_status === "Employee Review";
        var canViewFeedback = r.review_status === "Employee Final Review";
        var returnNote = r.return_reason
          ? "<div class=\"callout callout-warn\" style=\"margin:10px 0 0;font-size:var(--fs-sm)\"><strong>Returned:</strong> " + gpEsc(r.return_reason) + "</div>"
          : "";
        var ratingLine = (r.review_status === "Completed" && r.overall_rating != null)
          ? "<div style=\"font-size:var(--fs-sm);color:var(--text2);margin-top:6px\">Overall rating: <strong>" + pfNum(r.overall_rating, 1) + "</strong></div>"
          : "";
        var dateRange = (r.start_date || r.end_date)
          ? "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-top:2px\">" +
            (r.start_date ? gpFmtDate(r.start_date) : "?") + " – " + (r.end_date ? gpFmtDate(r.end_date) : "?") + "</div>"
          : "";
        var actionBtn;
        if (canOpen) {
          actionBtn = "<button class=\"btn btn-primary btn-sm\" onclick=\"prOpenReview('" + gpEsc(r.name) + "')\">Open Review</button>";
        } else if (canViewFeedback) {
          actionBtn = "<button class=\"btn btn-primary btn-sm\" onclick=\"prOpenReview('" + gpEsc(r.name) + "')\">View Feedback</button>";
        } else if (r.review_status === "Manager Review") {
          actionBtn = "<span style=\"font-size:var(--fs-sm);color:var(--text3)\">Awaiting manager review</span>";
        } else if (r.review_status === "HR Review") {
          actionBtn = "<span style=\"font-size:var(--fs-sm);color:var(--text3)\">Awaiting HR review</span>";
        } else if (r.review_status === "Completed") {
          actionBtn = "<span style=\"font-size:var(--fs-sm);color:var(--green)\">Review complete</span>";
        } else {
          actionBtn = "<span style=\"font-size:var(--fs-sm);color:var(--text3)\">Awaiting " + gpEsc(r.review_status) + "</span>";
        }
        html += "<div class=\"pf-card\" style=\"margin-bottom:14px;padding:18px 20px\">" +
          "<div style=\"display:flex;align-items:flex-start;gap:12px;flex-wrap:wrap\">" +
            "<div style=\"flex:1;min-width:180px\">" +
              "<div style=\"font-weight:700;font-size:var(--fs-md);color:var(--text)\">" + gpEsc(r.cycle_name) + "</div>" +
              dateRange + ratingLine + returnNote +
            "</div>" +
            "<div style=\"display:flex;flex-direction:column;align-items:flex-end;gap:10px;flex-shrink:0\">" +
              "<span class=\"badge " + statusMeta.cls + "\" style=\"font-size:var(--fs-sm);padding:4px 14px\">" + gpEsc(statusMeta.label) + "</span>" +
              actionBtn +
            "</div>" +
          "</div>" +
        "</div>";
      });
    }

    /* Invited reviewer section */
    if (invitedRows && invitedRows.length) {
      html += "<div style=\"font-size:var(--fs-base);font-weight:700;color:var(--text2);margin:24px 0 10px\">Feedback Requests</div>";
      invitedRows.forEach(function(r) {
        var alreadySubmitted = r.my_reviewer_status === "Submitted";
        var actionBtn = alreadySubmitted
          ? "<span style=\"font-size:var(--fs-sm);color:var(--green)\">Feedback submitted</span>"
          : "<button class=\"btn btn-primary btn-sm\" onclick=\"mrOpenFeedbackModal('" + gpEsc(r.appraisal) + "','" + gpEsc(r.employee_name) + "','goals','reviews')\">Submit Feedback</button>";
        var badge = alreadySubmitted
          ? "<span style=\"display:inline-block;padding:2px 10px;border-radius:var(--r);font-size:var(--fs-xs);font-weight:700;background:var(--green-lt);color:var(--green)\">Submitted</span>"
          : "<span style=\"display:inline-block;padding:2px 10px;border-radius:var(--r);font-size:var(--fs-xs);font-weight:700;background:var(--amber-lt);color:var(--amber)\">Pending</span>";
        html += "<div class=\"pf-card\" style=\"margin-bottom:14px;padding:18px 20px;border-left:3px solid var(--primary)\">" +
          "<div style=\"display:flex;align-items:flex-start;gap:12px;flex-wrap:wrap\">" +
            "<div style=\"flex:1;min-width:180px\">" +
              "<div style=\"font-size:var(--fs-xs);font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3);margin-bottom:4px\">Feedback Request</div>" +
              "<div style=\"font-weight:700;font-size:var(--fs-md)\">" + gpEsc(r.employee_name) + "</div>" +
              "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-top:2px\">" + gpEsc(r.cycle_name || r.appraisal_cycle) + "</div>" +
            "</div>" +
            "<div style=\"display:flex;flex-direction:column;align-items:flex-end;gap:10px;flex-shrink:0\">" +
              badge + actionBtn +
            "</div>" +
          "</div>" +
        "</div>";
      });
    }

    return html || "<div class=\"pf-card\">" + pfEmpty("No performance reviews yet.") + "</div>";
  }

  /* ── Reviewer feedback modal — tabbed per-page commenting ───────── */

  function mrBuildOverallPane(rv, readOnly) {
    var existing = rv.my_comments || "";
    return "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:12px\">Share your overall observations about this employee's performance.</div>" +
      (readOnly
        ? "<div style=\"background:var(--surface2);border-radius:var(--r-sm);padding:12px;font-size:var(--fs-base)\">" + gpEsc(existing || "(No overall comment provided)") + "</div>"
        : "<textarea id=\"mr-fb-text\" style=\"min-height:140px;width:100%;box-sizing:border-box\" placeholder=\"Share your overall observations and feedback…\">" + gpEsc(existing) + "</textarea>");
  }

  function mrRenderPageContent(pageKey, pageData, goals) {
    if (pageKey === "past-objectives" || pageKey === "future-objectives") {
      if (!goals.length) return "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">No objectives.</div>";
      return goals.map(function(g) {
        return "<div style=\"border-bottom:1px solid var(--border);padding:8px 0;font-size:var(--fs-base)\">" +
          "<div style=\"font-weight:600\">" + gpEsc(g.title || "(Untitled)") + "</div>" +
          (g.description ? "<div style=\"color:var(--text2);font-size:var(--fs-sm);margin-top:3px\">" + gpEsc(g.description) + "</div>" : "") +
        "</div>";
      }).join("");
    }
    var text = typeof pageData === "string" ? pageData : (pageData.text || pageData.content || pageData.value || "");
    if (!text) return "<div style=\"color:var(--text3);font-size:var(--fs-sm)\">No content provided by employee.</div>";
    return "<div style=\"font-size:var(--fs-base);white-space:pre-wrap;color:var(--text2)\">" + gpEsc(text) + "</div>";
  }

  function mrBuildPagePane(page, rv, readOnly) {
    var pageData = (rv.page_data || {})[page.key] || {};
    var existing = ((rv.my_page_comments || {})[page.key]) || "";
    var empContent = mrRenderPageContent(page.key, pageData, rv.goals || []);
    var commentArea = readOnly
      ? "<div style=\"background:var(--surface2);border-radius:var(--r-sm);padding:12px;font-size:var(--fs-base);margin-top:12px\">" +
          "<div style=\"font-size:var(--fs-xs);font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:6px\">Your comment</div>" +
          gpEsc(existing || "(No comment provided)") + "</div>"
      : "<div style=\"margin-top:16px\">" +
          "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:6px\">Your Comment</div>" +
          "<textarea class=\"mr-page-comment\" data-page=\"" + gpEsc(page.key) + "\" style=\"min-height:100px;width:100%;box-sizing:border-box\" placeholder=\"Write your comment on this section…\">" + gpEsc(existing) + "</textarea>" +
        "</div>";
    return "<div style=\"background:var(--surface2);border-radius:var(--r);padding:14px;margin-bottom:4px\">" +
      "<div style=\"font-size:var(--fs-xs);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Employee's Input</div>" +
      empContent +
    "</div>" + commentArea;
  }

  var _mrAppraisalId = "";
  var _mrBackPanel   = "goals";
  var _mrBackTab     = "reviews";

  window.mrCloseReview = function() {
    switchPanel(_mrBackPanel);
    if (window.gpShowTab && _mrBackTab) gpShowTab(_mrBackTab);
  };

  window.mrSwitchPane = function(idx) {
    document.querySelectorAll("#mr-rv-nav .pr-nav-item").forEach(function(el) {
      el.classList.toggle("active", parseInt(el.getAttribute("data-pane-idx"), 10) === idx);
    });
    document.querySelectorAll(".mr-rv-pane").forEach(function(p) { p.style.display = "none"; });
    var pane = document.getElementById("mr-rv-pane-" + idx);
    if (pane) pane.style.display = "block";
  };

  function mrBuildFeedbackView(rv) {
    var nav     = document.getElementById("mr-rv-nav");
    var content = document.getElementById("mr-rv-content");
    if (!nav || !content) return;
    var pages    = rv.allowed_pages || [];
    var readOnly = rv.my_status === "Submitted";
    var allPanes = pages.map(function(p) { return {key: p.key, label: p.label}; });
    allPanes.push({key: "__overall__", label: "Overall Comment"});
    // Pre-build all panes so switching preserves textarea values
    content.innerHTML = allPanes.map(function(t, i) {
      var pane = t.key === "__overall__" ? mrBuildOverallPane(rv, readOnly) : mrBuildPagePane(t, rv, readOnly);
      return "<div class=\"mr-rv-pane\" id=\"mr-rv-pane-" + i + "\" style=\"display:" + (i === 0 ? "block" : "none") + "\">" + pane + "</div>";
    }).join("");
    // Build left nav
    nav.innerHTML = "<div class=\"pr-nav-sec\">Review Sections</div>" +
      allPanes.map(function(t, i) {
        return "<div class=\"pr-nav-item" + (i === 0 ? " active" : "") + "\" data-pane-idx=\"" + i + "\" onclick=\"mrSwitchPane(" + i + ")\">" +
          "<span class=\"pr-navcheck\"></span>" + gpEsc(t.label) + "</div>";
      }).join("");
  }

  window.mrOpenFeedbackModal = function(appraisalId, employeeName, backPanel, backTab) {
    _mrAppraisalId = appraisalId;
    _mrBackPanel   = backPanel || "goals";
    _mrBackTab     = backTab   || "reviews";

    var title   = document.getElementById("mr-rv-title");
    var sub     = document.getElementById("mr-rv-sub");
    var status  = document.getElementById("mr-rv-status");
    var nav     = document.getElementById("mr-rv-nav");
    var content = document.getElementById("mr-rv-content");
    var msg     = document.getElementById("mr-rv-msg");
    var submit  = document.getElementById("mr-rv-submit");

    if (title)   title.textContent = "Submit Feedback — " + employeeName;
    if (sub)     sub.textContent   = "";
    if (status)  status.innerHTML  = "";
    if (nav)     nav.innerHTML     = "";
    if (msg)     msg.innerHTML     = "";
    if (submit)  { submit.disabled = false; submit.textContent = "Submit Feedback"; }
    if (content) content.innerHTML = "<div style=\"color:var(--text3);font-size:var(--fs-base);padding-top:40px;text-align:center\">Loading…</div>";

    switchPanel("mr-review");

    pf("get_reviewer_view", {appraisal: appraisalId}).then(function(rv) {
      window._mrReviewerView = rv;
      var submitBtn = document.getElementById("mr-rv-submit");
      if (rv.my_status === "Submitted" && submitBtn) {
        submitBtn.textContent = "Already Submitted";
        submitBtn.disabled = true;
        var st = document.getElementById("mr-rv-status");
        if (st) st.innerHTML = "<span style=\"display:inline-block;padding:2px 12px;border-radius:var(--r);font-size:var(--fs-xs);font-weight:700;background:var(--green-lt);color:var(--green)\">Submitted</span>";
      }
      var subEl = document.getElementById("mr-rv-sub");
      if (subEl) subEl.textContent = rv.cycle || "";
      mrBuildFeedbackView(rv);
    }).catch(function(e) {
      var c = document.getElementById("mr-rv-content");
      if (c) c.innerHTML = "<div style=\"color:var(--danger);padding:20px\">" + gpEsc(e.message || "Failed to load.") + "</div>";
    });
  };

  window.mrSubmitFeedback = function() {
    var text = (document.getElementById("mr-fb-text") || {}).value || "";
    var pageComments = {};
    document.querySelectorAll(".mr-page-comment").forEach(function(ta) {
      var pk = ta.getAttribute("data-page");
      if (pk && ta.value.trim()) pageComments[pk] = ta.value.trim();
    });
    if (!text.trim() && !Object.keys(pageComments).length) {
      gpShowToast("Please write at least one comment before submitting.", "error");
      return;
    }
    var submitBtn = document.getElementById("mr-rv-submit");
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Submitting..."; }
    pf("submit_reviewer_comments", {
      appraisal: _mrAppraisalId,
      comments: text,
      page_comments: JSON.stringify(pageComments)
    }).then(function() {
      mrCloseReview();
      gpShowToast("Feedback submitted successfully.");
      _mrLoaded = false;
      mrLoad(true);
    }).catch(function(e) {
      if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Submit Feedback"; }
      gpShowToast(e.message || "Submission failed.", "error");
    });
  };

  var _pfShowArchived = false;

  window.pfLoadHrCycle = function() {
    var cycle = pfVal("pf-hr-cycle");
    if (!cycle) {
      pfSetHtml("pf-hr-body", pfEmpty("No appraisal cycles yet. Create one to begin."));
      return;
    }
    pfSetHtml("pf-hr-body", pfEmpty("Loading cycle…"));
    pf("hr_list_appraisals", {cycle: cycle, show_archived: _pfShowArchived ? 1 : 0})
      .catch(function() { return []; })
      .then(function(appraisals) {
        pfSetHtml("pf-hr-body", pfHrAppraisalTable(appraisals, cycle));
      }).catch(function(e) {
        pfSetHtml("pf-hr-body", "<div class=\"callout callout-warn\">Failed to load cycle: " + gpEsc(e.message) + "</div>");
      });
  };

  window.pfToggleArchived = function() {
    _pfShowArchived = !_pfShowArchived;
    pfLoadHrCycle();
  };

  window.pfSendReminder = function(appraisalName, btn) {
    if (btn) { btn.disabled = true; btn.textContent = "Sending…"; }
    pf("send_review_reminder", {appraisal: appraisalName}).then(function(r) {
      if (btn) { btn.disabled = false; btn.textContent = "Remind"; }
      var msg = document.getElementById("pf-hr-msg");
      if (msg) { msg.innerHTML = "<div class=\"callout callout-ok\" style=\"margin-bottom:8px\">" + gpEsc(r.message || "Reminder sent.") + "</div>"; setTimeout(function() { if (msg) msg.innerHTML = ""; }, 4000); }
    }).catch(function(e) {
      if (btn) { btn.disabled = false; btn.textContent = "Remind"; }
      alert(e.message || "Failed to send reminder.");
    });
  };

  window.pfArchiveReview = function(appraisalName) {
    if (!confirm("Archive this completed review? It will be hidden from the default list.")) return;
    pf("archive_review", {appraisal: appraisalName}).then(function() {
      pfLoadHrCycle();
    }).catch(function(e) { alert(e.message || "Failed to archive."); });
  };

  window.pfUnarchiveReview = function(appraisalName) {
    pf("unarchive_review", {appraisal: appraisalName}).then(function() {
      pfLoadHrCycle();
    }).catch(function(e) { alert(e.message || "Failed to restore."); });
  };

  /* Someone in the subject's reporting line does not do the HR steps on their
     review, even with an HR role (decision 34). The server refuses; the page
     shows this instead of HR's buttons. Words, not colour alone. */
  window.pfHrStepsElsewhereNote = function() {
    return "<span class=\"hr-steps-elsewhere\" style=\"font-size:var(--fs-xs);color:var(--text3)\">" +
      "<i class=ic-info></i> Another HR person needs to do the HR steps for this review, because they report to you.</span>";
  };

  window.pfFinishHrReview = function(appraisalName, btn) {
    if (!confirm("Mark this review as completed? The employee will be notified.")) return;
    if (btn) { btn.disabled = true; btn.textContent = "Finishing…"; }
    pf("advance_review_status", {appraisal: appraisalName}).then(function() {
      gpShowToast("Review finalized — employee notified.");
      pfLoadHrCycle();
    }).catch(function(e) {
      if (btn) { btn.disabled = false; btn.textContent = "Finish Review"; }
      gpShowToast(e.message || "Failed to finalize review.", "error");
    });
  };

  /* ── Appraisal review-status table (HR view) ──────── */

  var _PF_REVIEW_STATUS_META = {
    "Not Started":          {label: "Not Started",          cls: "badge-gray"},
    "Employee Review":      {label: "Employee Review",       cls: "badge-blue"},
    "Manager Review":       {label: "With Manager",          cls: "badge-amber"},
    "Employee Final Review":{label: "Feedback Ready",        cls: "badge-green"},
    "HR Review":            {label: "With HR",               cls: "badge-purple"},
    "Completed":            {label: "Completed",             cls: "badge-green"},
  };

  function pfReviewStatusBadge(status) {
    var m = _PF_REVIEW_STATUS_META[status] || {label: status || "Not Started", cls: "badge-gray"};
    return '<span class="badge ' + m.cls + '">' + gpEsc(m.label) + '</span>';
  }

  /* Count how many appraisals are at each stage for the summary strip */
  function pfAppraisalStageBar(appraisals) {
    var counts = {"Not Started": 0, "Employee Review": 0, "Manager Review": 0, "Employee Final Review": 0, "HR Review": 0, "Completed": 0};
    var total = appraisals.length;
    appraisals.forEach(function(a) { if (counts[a.review_status] !== undefined) counts[a.review_status]++; else counts["Not Started"]++; });
    var pct = function(n) { return total ? Math.round(n / total * 100) : 0; };
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:16px">' +
      Object.keys(counts).map(function(k) {
        var m = _PF_REVIEW_STATUS_META[k] || {label: k, cls: "badge-gray"};
        return '<span class="badge ' + m.cls + '" style="font-size:var(--fs-sm);padding:4px 12px">' +
          gpEsc(m.label) + ' <strong>' + counts[k] + '</strong>' +
          (total ? ' <span style="opacity:.7">(' + pct(counts[k]) + '%)</span>' : '') + '</span>';
      }).join('') +
    '</div>';
  }

  window.pfHrAppraisalTable = function(appraisals, cycle) { return pfHrAppraisalTable(appraisals, cycle); };

  function pfHrAppraisalTable(appraisals, cycle) {
    var activeCount = (appraisals || []).filter(function(a) { return !a.archived; }).length;
    var archiveCount = (appraisals || []).filter(function(a) { return a.archived; }).length;
    var toggleLabel = _pfShowArchived
      ? "Hide Archived" + (archiveCount ? " (" + archiveCount + ")" : "")
      : "Show Archived" + (archiveCount ? " (" + archiveCount + ")" : "");

    var cardBody;
    if (!appraisals || !appraisals.length) {
      cardBody = pfEmpty(_pfShowArchived
        ? "No reviews in this cycle."
        : "No performance reviews generated yet. Launch a cycle to generate them.");
    } else {
      var rows = appraisals.map(function(a) {
        var ratingCell = (a.review_status === "Completed" && a.overall_rating != null)
          ? pfNum(a.overall_rating, 1) + " / 5"
          : "<span style=\"color:var(--text3)\">—</span>";
        var actionCell;
        if (a.archived) {
          actionCell = "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"pfUnarchiveReview('" + gpEsc(a.name) + "')\">Restore</button>";
        } else {
          var canRemind = a.review_status !== "Completed";
          var canArchive = a.review_status === "Completed";
          actionCell = "";
          /* This list always opens a review as HR (decision 37). HR opens a
             review once it reaches HR Review; before that it is with the
             employee and their manager. */
          var hrOpen = "prOpenManagerReview('" + gpEsc(a.name) + "','" + gpEsc(a.employee_name || a.employee) + "','hr')";
          if (a.review_status === "HR Review" && a.hr_steps_elsewhere) {
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"" + hrOpen + "\">View</button> ";
            actionCell += "<div>" + pfHrStepsElsewhereNote() + "</div>";
          } else if (a.review_status === "HR Review") {
            actionCell += "<button class=\"btn btn-primary btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"pfFinishHrReview('" + gpEsc(a.name) + "',this)\">Finish Review</button> ";
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"" + hrOpen + "\">View</button> ";
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"pfOpenCalibNoteModal('" + gpEsc(a.name) + "','" + gpEsc(a.employee_name || a.employee) + "')\">Calibration note</button> ";
          } else if (a.review_status === "Completed") {
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"" + hrOpen + "\">View</button> ";
          }
          if (canRemind) {
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" onclick=\"pfSendReminder('" + gpEsc(a.name) + "',this)\">Remind</button> ";
          }
          if (canArchive) {
            actionCell += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs);color:var(--text3)\" onclick=\"pfArchiveReview('" + gpEsc(a.name) + "')\">Archive</button>";
          }
        }
        return "<tr" + (a.archived ? " style=\"opacity:.55\"" : "") + ">" +
          "<td style=\"font-weight:600\">" + gpEsc(a.employee_name || a.employee) + "</td>" +
          "<td><span style=\"font-size:var(--fs-sm);color:var(--text3)\">" + gpEsc(a.department || "—") + "</span></td>" +
          "<td><span style=\"font-size:var(--fs-sm);color:var(--text3)\">" + gpEsc(a.designation || "—") + "</span></td>" +
          "<td>" + pfReviewStatusBadge(a.review_status) + (a.archived ? " <span style=\"font-size:var(--fs-xs);color:var(--text3);font-style:italic\">archived</span>" : "") + "</td>" +
          "<td class=\"pf-num\">" + ratingCell + "</td>" +
          "<td style=\"white-space:nowrap\">" + actionCell + "</td>" +
        "</tr>";
      }).join("");
      cardBody = pfAppraisalStageBar(appraisals.filter(function(a) { return !a.archived; })) +
        "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
          "<th>Employee</th><th>Department</th><th>Designation</th>" +
          "<th>Review Status</th><th class=\"pf-num\">Rating</th><th>Actions</th>" +
        "</tr></thead><tbody>" + rows + "</tbody></table></div>";
    }
    return "<div class=\"pf-card\" style=\"margin-bottom:20px\">" +
      "<div class=\"pf-card-hdr\">" +
        "<div><div class=\"pf-card-name\">HR review list</div>" +
        "<div class=\"pf-card-meta\">" + activeCount + " active review" + (activeCount === 1 ? "" : "s") + " in this cycle. " +
          "You open these as HR. Your own team's reviews are under Reviews, in My team's reviews.</div></div>" +
        "<div style=\"display:flex;gap:8px;align-items:center\">" +
          "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-sm)\" onclick=\"pfToggleArchived()\">" + gpEsc(toggleLabel) + "</button>" +
          "<button class=\"btn btn-outline btn-sm\" onclick=\"pfLoadHrCycle()\">&#8635; Refresh</button>" +
        "</div>" +
      "</div>" +
      cardBody +
    "</div>";
  }

  function pfHrSummary(s) {
    if (!s.rows.length) {
      return "<div class=\"pf-card\">" + pfEmpty('No KPIs assigned in this cycle yet. Use "Assign KPI" to start.') + "</div>";
    }
    var withAtt = !!(s.scoring && s.scoring.include_attendance);
    var rows = s.rows.map(function(r) {
      return "<tr>" +
        "<td style=\"font-weight:600\">" + gpEsc(r.employee_name) + "</td>" +
        "<td class=\"pf-num\">" + r.kpi_count + "</td>" +
        "<td class=\"pf-num\" style=\"color:" + (r.weightage_ok ? "var(--green)" : "var(--amber)") + ";font-weight:700\">" +
          pfNum(r.total_weightage) + "%</td>" +
        "<td class=\"pf-num\">" + r.rated + " / " + r.kpi_count + "</td>" +
        "<td class=\"pf-num\">" + pfNum(r.avg_attainment) + "%</td>" +
        "<td>" + (r.appraisal ? gpEsc(r.appraisal) : "<span style=\"color:var(--text3)\">not generated</span>") + "</td>" +
        (withAtt ? "<td class=\"pf-num\">" + (r.attendance_score != null ? pfNum(r.attendance_score, 2) : "—") + "</td>" : "") +
        "<td class=\"pf-num\">" + (r.submitted ? pfNum(r.final_score, 2) : "—") + "</td>" +
        "<td>" + (r.submitted
          ? "<span class=\"badge b-completed\">Submitted</span>"
          : "<span class=\"badge b-draft\">Open</span>") + "</td>" +
      "</tr>";
    }).join("");

    var byBranch = "";
    if (withAtt && s.attendance_by_branch && s.attendance_by_branch.length) {
      byBranch = "<div class=\"pf-card\" style=\"margin-bottom:20px\">" +
        "<div class=\"pf-card-hdr\"><div><div class=\"pf-card-name\">Attendance in the score, by branch</div>" +
        "<div class=\"pf-card-meta\">Weights: targets " + s.scoring.goal_weight + "% · manager feedback " + s.scoring.feedback_weight + "% · attendance " + s.scoring.attendance_weight + "%</div></div></div>" +
        "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr><th>Branch</th><th class=\"pf-num\">Appraisals</th>" +
        "<th class=\"pf-num\">Avg attendance score</th><th class=\"pf-num\">Avg final score</th></tr></thead><tbody>" +
        s.attendance_by_branch.map(function(b) {
          return "<tr><td>" + gpEsc(b.branch) + "</td><td class=\"pf-num\">" + b.count + "</td>" +
            "<td class=\"pf-num\">" + pfNum(b.avg_attendance, 2) + "</td><td class=\"pf-num\">" + pfNum(b.avg_final, 2) + "</td></tr>";
        }).join("") + "</tbody></table></div></div>";
    }

    return byBranch + "<div class=\"pf-card\">" +
      "<div class=\"pf-card-hdr\"><div><div class=\"pf-card-name\">Cycle Progress</div>" +
      "<div class=\"pf-card-meta\">" + s.assigned + " employees with KPIs · " +
        s.with_appraisal + " appraisals generated · " + s.submitted + " submitted</div></div></div>" +
      "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
        "<th>Employee</th><th class=\"pf-num\">KPIs</th><th class=\"pf-num\">Weightage</th>" +
        "<th class=\"pf-num\">Rated</th><th class=\"pf-num\">Avg attain</th>" +
        "<th>Appraisal</th>" + (withAtt ? "<th class=\"pf-num\">Attendance</th>" : "") + "<th class=\"pf-num\">Final</th><th>Status</th>" +
      "</tr></thead><tbody>" + rows + "</tbody></table></div></div>";
  }

  function pfHrKpiTable(kpis) {
    if (!kpis.length) return "";
    var rows = kpis.map(function(k) {
      return "<tr>" +
        "<td>" + gpEsc(k.employee_name) + "</td>" +
        "<td style=\"font-weight:600\">" + gpEsc(k.kpi_name) + "</td>" +
        "<td class=\"pf-num\">" + pfNum(k.target_value, 2) + "</td>" +
        "<td class=\"pf-num\">" + pfNum(k.actual_value, 2) + "</td>" +
        "<td class=\"pf-num\">" + pfNum(k.attainment_pct) + "%</td>" +
        "<td class=\"pf-num\">" + pfNum(k.weightage) + "%</td>" +
        "<td>" + gpEsc(k.objective || "—") + "</td>" +
        "<td>" + gpStatusBadge(k.status) + "</td>" +
        "<td style=\"white-space:nowrap\">" +
          "<button class=\"btn btn-outline btn-sm\" onclick='pfEditKpi(" +
            JSON.stringify(JSON.stringify(Object.assign({}, k, {_returnTo: "hr"}))) + ")'>Edit</button> " +
          "<button class=\"btn btn-outline btn-sm\" style=\"color:var(--red);border-color:var(--red)\"" +
            " onclick=\"pfDeleteKpi('" + gpEsc(k.name) + "','" + gpEsc(k.kpi_name) + "')\">Delete</button>" +
        "</td>" +
      "</tr>";
    }).join("");
    return "<div class=\"pf-card\">" +
      "<div class=\"pf-card-hdr\"><div class=\"pf-card-name\">Assigned KPIs</div></div>" +
      "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
        "<th>Employee</th><th>KPI</th><th class=\"pf-num\">Target</th><th class=\"pf-num\">Actual</th>" +
        "<th class=\"pf-num\">Attain</th><th class=\"pf-num\">Weight</th><th>Objective</th>" +
        "<th>Status</th><th></th>" +
      "</tr></thead><tbody>" + rows + "</tbody></table></div></div>";
  }

  function pfHrCalibration(r, cycle) {
    if (!r || !r.rows || !r.rows.length) {
      return "<div class=\"pf-card\" style=\"margin-top:16px\">" +
        "<div class=\"pf-card-hdr\"><div class=\"pf-card-name\">Calibration</div></div>" +
        pfEmpty("No employee data in this cycle yet.") + "</div>";
    }
    var rows = r.rows.map(function(row) {
      var statusBadge = {
        "Not Started": "<span class=\"badge b-draft\">Not Started</span>",
        "Employee Review": "<span class=\"badge b-draft\">Employee</span>",
        "Manager Review": "<span class=\"badge b-pending\">Manager</span>",
        "HR Review": "<span class=\"badge b-pending\">HR Review</span>",
        "Completed": "<span class=\"badge b-completed\">Completed</span>"
      }[row.review_status] || "<span class=\"badge b-draft\">" + gpEsc(row.review_status || "—") + "</span>";
      var potCat = row.potential_category
        ? "<span style=\"font-size:var(--fs-xs);color:var(--text3)\">" + gpEsc(row.potential_category) + "</span>"
        : "—";
      return "<tr>" +
        "<td style=\"font-weight:600\">" + gpEsc(row.employee_name) + "</td>" +
        "<td class=\"pf-num\">" + row.kpi_count + "</td>" +
        "<td class=\"pf-num\">" + pfNum(row.avg_attainment) + "%</td>" +
        "<td class=\"pf-num\">" + (row.overall_rating != null ? pfNum(row.overall_rating, 1) : "—") + "</td>" +
        "<td class=\"pf-num\">" + (row.avg_potential_rating != null ? pfNum(row.avg_potential_rating, 2) : "—") + "</td>" +
        "<td>" + potCat + "</td>" +
        "<td>" + statusBadge + "</td>" +
        "<td class=\"pf-num\">" + (row.action_items_count || 0) + "</td>" +
        "<td" + (row.hr_steps_elsewhere ? "" : " style=\"white-space:nowrap\"") + ">" +
          (row.appraisal && row.hr_steps_elsewhere
            ? pfHrStepsElsewhereNote()
            : row.appraisal
            ? "<button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenCalibNoteModal('" +
              gpEsc(row.appraisal) + "','" + gpEsc(row.employee_name) + "')\">Note</button>"
            : "—") +
        "</td>" +
      "</tr>";
    }).join("");
    return "<div class=\"pf-card\" style=\"margin-top:16px\">" +
      "<div class=\"pf-card-hdr\"><div><div class=\"pf-card-name\">Calibration</div>" +
      "<div class=\"pf-card-meta\">" + r.rows.length + " employees · cycle " + gpEsc(cycle) + "</div></div></div>" +
      "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
        "<th>Employee</th><th class=\"pf-num\">KPIs</th><th class=\"pf-num\">Avg Attain</th>" +
        "<th class=\"pf-num\">Overall</th><th class=\"pf-num\">Potential</th>" +
        "<th>Potential Cat</th><th>Status</th><th class=\"pf-num\">Actions</th><th></th>" +
      "</tr></thead><tbody>" + rows + "</tbody></table></div></div>";
  }

  function pfHrLeadershipPrinciples(principles) {
    var addBtn = "<button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenPrincipleModal(null)\" style=\"margin-left:auto\">+ Add Principle</button>";
    if (!principles || !principles.length) {
      return "<div class=\"pf-card\" style=\"margin-top:16px\">" +
        "<div class=\"pf-card-hdr\"><div class=\"pf-card-name\">Leadership Principles</div>" + addBtn + "</div>" +
        pfEmpty("No leadership principles defined. Add one to start using upward feedback.") + "</div>";
    }
    var rows = principles.map(function(p) {
      var behaviours = (p.expected_behaviours || "").split("\n").filter(Boolean);
      return "<tr>" +
        "<td style=\"font-weight:600\">" + gpEsc(p.principle_name) + "</td>" +
        "<td style=\"color:var(--text2)\">" + gpEsc(p.description || "—") + "</td>" +
        "<td><ul style=\"margin:0;padding-left:16px\">" +
          behaviours.map(function(b) { return "<li style=\"font-size:var(--fs-sm);color:var(--text2)\">" + gpEsc(b) + "</li>"; }).join("") +
        "</ul></td>" +
        "<td style=\"white-space:nowrap\">" +
          "<button class=\"btn btn-outline btn-sm\" onclick='pfOpenPrincipleModal(" +
            JSON.stringify(JSON.stringify(p)) + ")'>Edit</button>" +
        "</td>" +
      "</tr>";
    }).join("");
    return "<div class=\"pf-card\" style=\"margin-top:16px\">" +
      "<div class=\"pf-card-hdr\"><div class=\"pf-card-name\">Leadership Principles</div>" + addBtn + "</div>" +
      "<div class=\"pf-scroll\"><table class=\"pf-table\"><thead><tr>" +
        "<th>Principle</th><th>Description</th><th>Expected Behaviours</th><th></th>" +
      "</tr></thead><tbody>" + rows + "</tbody></table></div></div>";
  }

  /* ── Appraisal Setup Wizard ──────────────────────── */
  var _wizStep = 1;
  var _WIZ_TOTAL = 4;
  var _wizAllEmployees = [];   /* full list fetched from API */
  var _wizFilterOpts = null;   /* cached filter dropdowns data */

  function wizUpdateIndicator() {
    for (var i = 1; i <= _WIZ_TOTAL; i++) {
      var dot = document.getElementById("wiz-dot-" + i);
      if (!dot) continue;
      dot.className = "wiz-dot" + (i < _wizStep ? " done" : i === _wizStep ? " active" : "");
      var lbl = document.getElementById("wiz-lbl-" + i);
      if (lbl) lbl.style.color = i === _wizStep ? "var(--primary)" : "var(--text3)";
    }
    document.getElementById("wiz-back-btn").style.display = _wizStep > 1 ? "" : "none";
    document.getElementById("wiz-cancel-btn").style.display = _wizStep === 1 ? "" : "none";
    var nextBtn = document.getElementById("wiz-next-btn");
    nextBtn.textContent = _wizStep < _WIZ_TOTAL ? "Next →" : "Launch Cycle";
    for (var s = 1; s <= _WIZ_TOTAL; s++) {
      var el = document.getElementById("wiz-step-" + s);
      if (el) el.style.display = s === _wizStep ? "" : "none";
    }
  }

  window.wizStep = function(dir) {
    pfClearErr("pf-cycle-error");
    if (dir > 0 && _wizStep === 1) {
      var name = pfVal("pf-cy-name"), start = pfVal("pf-cy-start"), end = pfVal("pf-cy-end");
      if (!name) { pfShowErr("pf-cycle-error", "Cycle name is required."); return; }
      if (!start || !end) { pfShowErr("pf-cycle-error", "Start date and end date are required."); return; }
      if (start >= end) { pfShowErr("pf-cycle-error", "End date must be after start date."); return; }
    }
    if (dir > 0 && _wizStep === _WIZ_TOTAL) {
      wizFinish(); return;
    }
    _wizStep = Math.max(1, Math.min(_WIZ_TOTAL, _wizStep + dir));
    wizUpdateIndicator();
    if (_wizStep === 4) wizLoadFilterOptions();
  };

  function wizCollectEmployeeFields() {
    var fields = {};
    ["designation","department","branch","grade","joining_date","years_of_service","reports_to","employment_type"]
      .forEach(function(f) {
        var el = document.getElementById("wf-" + f);
        if (el) fields[f] = el.checked;
      });
    return fields;
  }

  function wizCollectPageConfig() {
    var pages = {};
    ["past-objectives","past-dev","future-objectives","future-dev","manager-feedback"]
      .forEach(function(p) {
        var el = document.getElementById("pg-" + p);
        if (el) pages[p] = el.checked;
      });
    return pages;
  }

  /* ── Wizard step 4 helpers ───────────────────────── */

  function wizLoadFilterOptions() {
    if (_wizFilterOpts) { wizPopulateFilterDropdowns(_wizFilterOpts); return; }
    var loadEl = document.getElementById("wiz-emp-loading");
    if (loadEl) loadEl.style.display = "";
    pf("get_wizard_filter_options").then(function(opts) {
      _wizFilterOpts = opts;
      if (loadEl) loadEl.style.display = "none";
      wizPopulateFilterDropdowns(opts);
      wizFetchEmployees();
    }).catch(function(e) {
      if (loadEl) loadEl.style.display = "none";
      pfShowErr("pf-cycle-error", "Could not load filter options: " + e.message);
    });
  }

  function wizPopulateFilterDropdowns(opts) {
    var deptSel = document.getElementById("wiz-f-dept");
    var mgrSel  = document.getElementById("wiz-f-mgr");
    var desigSel = document.getElementById("wiz-f-desig");
    if (deptSel && deptSel.options.length <= 1) {
      (opts.departments || []).forEach(function(d) {
        deptSel.add(new Option(d, d));
      });
    }
    if (mgrSel && mgrSel.options.length <= 1) {
      (opts.managers || []).forEach(function(m) {
        mgrSel.add(new Option(m.employee_name, m.name));
      });
    }
    if (desigSel && desigSel.options.length <= 1) {
      (opts.designations || []).forEach(function(d) {
        desigSel.add(new Option(d, d));
      });
    }
  }

  function wizFetchEmployees() {
    var loadEl = document.getElementById("wiz-emp-loading");
    if (loadEl) loadEl.style.display = "";
    var params = {
      department:   (document.getElementById("wiz-f-dept")  || {}).value  || "",
      manager:      (document.getElementById("wiz-f-mgr")   || {}).value  || "",
      designation:  (document.getElementById("wiz-f-desig") || {}).value  || "",
      joining_from: (document.getElementById("wiz-f-join-from") || {}).value || "",
      joining_to:   (document.getElementById("wiz-f-join-to")   || {}).value || "",
    };
    /* strip empty strings so backend filters cleanly */
    Object.keys(params).forEach(function(k) { if (!params[k]) delete params[k]; });
    pf("get_filterable_employees", params).then(function(emps) {
      if (loadEl) loadEl.style.display = "none";
      /* preserve existing selections */
      var prevSelected = {};
      _wizAllEmployees.forEach(function(e) { if (e._checked) prevSelected[e.name] = true; });
      _wizAllEmployees = emps.map(function(e) {
        e._checked = !!prevSelected[e.name];
        return e;
      });
      wizRenderEmpList();
    }).catch(function(e) {
      if (loadEl) loadEl.style.display = "none";
      pfShowErr("pf-cycle-error", "Could not load employees: " + e.message);
    });
  }

  window.wizApplyFilters = function() { wizFetchEmployees(); };

  window.wizRenderEmpList = function() {
    var q = ((document.getElementById("wiz-emp-search") || {}).value || "").toLowerCase();
    var list = document.getElementById("wiz-emp-list");
    if (!list) return;
    var visible = _wizAllEmployees.filter(function(e) {
      return !q || (e.employee_name || "").toLowerCase().indexOf(q) > -1
                || (e.designation || "").toLowerCase().indexOf(q) > -1;
    });
    if (!visible.length) {
      list.innerHTML = '<div class="empty-state" style="padding:24px"><div class="empty-state-text">No employees match the current filters</div></div>';
    } else {
      list.innerHTML = visible.map(function(e) {
        return '<label class="wiz-emp-row" onclick="wizToggleEmp(event,\'' + e.name + '\')">'
          + '<input type="checkbox"' + (e._checked ? ' checked' : '') + ' onclick="event.stopPropagation();wizToggleEmp(null,\'' + e.name + '\')" data-empid="' + e.name + '">'
          + '<div><div class="wiz-emp-name">' + (e.employee_name || e.name) + '</div>'
          + '<div class="wiz-emp-meta">' + [e.designation, e.department, e.reports_to_name ? ('Reports to: ' + e.reports_to_name) : ''].filter(Boolean).join(' · ') + '</div>'
          + '</div></label>';
      }).join('');
    }
    var total = _wizAllEmployees.length;
    var sel   = _wizAllEmployees.filter(function(e) { return e._checked; }).length;
    var cntEl = document.getElementById("wiz-sel-count");
    var totEl = document.getElementById("wiz-emp-count");
    if (cntEl) cntEl.textContent = sel;
    if (totEl) totEl.textContent = total;
  };

  window.wizToggleEmp = function(evt, empId) {
    if (evt) evt.preventDefault();
    var emp = _wizAllEmployees.find(function(e) { return e.name === empId; });
    if (emp) emp._checked = !emp._checked;
    wizRenderEmpList();
  };

  window.wizToggleAll = function(val) {
    _wizAllEmployees.forEach(function(e) { e._checked = val; });
    wizRenderEmpList();
  };

  function wizCollectSelectedEmployees() {
    return _wizAllEmployees.filter(function(e) { return e._checked; }).map(function(e) { return e.name; });
  }

  function wizFinish() {
    var nextBtn = document.getElementById("wiz-next-btn");
    var selected = wizCollectSelectedEmployees();
    if (selected.length === 0) {
      pfShowErr("pf-cycle-error", "Please select at least one employee to include in the cycle.");
      return;
    }
    nextBtn.disabled = true;
    nextBtn.textContent = "Creating…";
    pf("save_cycle_wizard", {
      cycle_name:          pfVal("pf-cy-name"),
      start_date:          pfVal("pf-cy-start"),
      end_date:            pfVal("pf-cy-end"),
      description:         pfVal("pf-cy-desc"),
      employee_fields:     JSON.stringify(wizCollectEmployeeFields()),
      page_config:         JSON.stringify(wizCollectPageConfig()),
      selected_employees:  JSON.stringify(selected),
    }).then(function(r) {
      pfCloseModal("pf-cycle-modal");
      var msg = r.message || ("Cycle created. " + (r.created || 0) + " appraisals generated.");
      frappe.show_alert({message: msg, indicator: "green"}, 6);
      return pf("get_performance_context").then(function(ctx) {
        _pfCtx = ctx; pfFillCycleSelects(); pfLoadHr(true);
      });
    }).catch(function(e) {
      pfShowErr("pf-cycle-error", e.message);
      nextBtn.disabled = false;
      nextBtn.textContent = "Launch Cycle";
    });
  }

  window.pfOpenCycleModal = function() {
    _wizStep = 1;
    _wizAllEmployees = [];
    pfClearErr("pf-cycle-error");
    /* reset step-4 filter dropdowns to default so they reload fresh */
    ["wiz-f-dept","wiz-f-mgr","wiz-f-desig","wiz-f-join-from","wiz-f-join-to","wiz-emp-search"].forEach(function(id) {
      var el = document.getElementById(id);
      if (el) el.value = "";
    });
    var empList = document.getElementById("wiz-emp-list");
    if (empList) empList.innerHTML = '<div class="empty-state" style="padding:24px"><div class="empty-state-text">Click a filter or type to load employees</div></div>';
    var cntEl = document.getElementById("wiz-sel-count"); if (cntEl) cntEl.textContent = "0";
    var totEl = document.getElementById("wiz-emp-count"); if (totEl) totEl.textContent = "0";
    ["pf-cy-name","pf-cy-start","pf-cy-end","pf-cy-desc"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    // Reset checkboxes to defaults
    var defaults = {designation:true, department:true, branch:false, grade:false,
                    joining_date:false, years_of_service:true, reports_to:true, employment_type:false};
    Object.keys(defaults).forEach(function(f) {
      var el = document.getElementById("wf-" + f); if (el) el.checked = defaults[f];
    });
    var pageDefaults = {"past-objectives":true,"past-dev":true,"future-objectives":false,
                        "future-dev":false,"manager-feedback":true};
    Object.keys(pageDefaults).forEach(function(p) {
      var el = document.getElementById("pg-" + p); if (el) el.checked = pageDefaults[p];
    });
    var nextBtn = document.getElementById("wiz-next-btn");
    if (nextBtn) { nextBtn.disabled = false; nextBtn.textContent = "Next →"; }
    wizUpdateIndicator();
    pfOpenModal("pf-cycle-modal");
  };

  /* alias kept so any legacy code calling pfSubmitCycle still works */
  window.pfSubmitCycle = wizFinish;

  window.pfOpenCascadeModal = function() {
    pfClearErr("pf-cascade-error");
    ["pf-ca-name","pf-ca-target","pf-ca-start","pf-ca-end"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    pfOpenModal("pf-cascade-modal");
  };

  window.pfSubmitCascade = function() {
    var name = pfVal("pf-ca-name"), target = pfVal("pf-ca-target");
    var start = pfVal("pf-ca-start"), end = pfVal("pf-ca-end");
    if (!name || !target || !start || !end) {
      pfShowErr("pf-cascade-error", "Name, target, and both dates are required."); return;
    }
    pf("hr_create_cascade", {
      cascade_name: name, company_target: target, unit: pfVal("pf-ca-unit"),
      period_start: start, period_end: end
    }).then(function() { pfCloseModal("pf-cascade-modal"); pfLoadHr(true); })
      .catch(function(e) { pfShowErr("pf-cascade-error", e.message); });
  };

  // Which tab opened the KPI modal, so saving refreshes the right view.
  var _pfKpiReturnTo = "kpis";

  // Employee list is server-filtered: HR gets everyone, a manager gets their
  // subtree, an individual contributor gets only themselves.
  function pfFillEmployeeSelect(selectId, selected) {
    return gpFetch("alvoraa_portal.goals_api.get_manageable_employees").then(function(rows) {
      var sel = document.getElementById(selectId);
      if (!sel) return rows;
      sel.innerHTML = (rows || []).map(function(e) {
        return "<option value=\"" + gpEsc(e.name) + "\">" +
               gpEsc(e.employee_name) + (e.is_self ? " (me)" : "") +
               (e.designation ? " · " + gpEsc(e.designation) : "") + "</option>";
      }).join("");
      if (selected) sel.value = selected;
      else {
        var me = (rows || []).filter(function(e) { return e.is_self; })[0];
        if (me) sel.value = me.name;
      }
      return rows;
    });
  }

  var _pfObjectives = [];

  /* ── Type-to-search combobox ───────────────────────
     A plain <select> is unusable once an org has more than a handful of
     objectives, so the linked-objective picker filters as you type. The hidden
     input holds the id; the visible one holds the label. */

  var _cbxIndex = {};   // id -> highlighted option index

  window.cbxFilter = function(base) {
    var q = (pfVal(base + "-search") || "").toLowerCase();
    var list = document.getElementById(base + "-list");
    if (!list) return;
    var matches = _pfObjectives.filter(function(o) {
      return !q || (o.goal_name || "").toLowerCase().indexOf(q) >= 0
                || (o.level || "").toLowerCase().indexOf(q) >= 0
                || (o.employee_name || "").toLowerCase().indexOf(q) >= 0;
    });
    _cbxIndex[base] = -1;
    var rows = "<div class=\"cbx-opt\" onmousedown=\"cbxPick('" + base + "','')\">" +
               "<div>— none —</div><div class=\"cbx-opt-sub\">Not linked to an objective</div></div>";
    rows += matches.length
      ? matches.map(function(o) {
          return "<div class=\"cbx-opt\" onmousedown=\"cbxPick('" + base + "','" + gpEsc(o.name) + "')\">" +
                 "<div>" + gpEsc(o.goal_name) + "</div>" +
                 "<div class=\"cbx-opt-sub\">" + gpEsc(o.level || "") + "</div></div>";
        }).join("")
      : "<div class=\"cbx-empty\">No objective matches \"" + gpEsc(q) + "\".</div>";
    list.innerHTML = rows;
    list.classList.add("open");
  };

  window.cbxPick = function(base, id) {
    var hidden = document.getElementById(base);
    var search = document.getElementById(base + "-search");
    var list   = document.getElementById(base + "-list");
    var o = _pfObjectives.filter(function(x) { return x.name === id; })[0];
    if (hidden) hidden.value = id || "";
    if (search) search.value = o ? o.goal_name : "";
    if (list) list.classList.remove("open");
    if (base === "pf-k-objective") pfShowCascadeNote();
  };

  window.cbxKey = function(ev, base) {
    var list = document.getElementById(base + "-list");
    if (!list) return;
    var opts = list.querySelectorAll(".cbx-opt");
    if (ev.key === "Escape") { list.classList.remove("open"); return; }
    if (!opts.length) return;
    if (ev.key === "ArrowDown" || ev.key === "ArrowUp") {
      ev.preventDefault();
      var i = (_cbxIndex[base] === undefined ? -1 : _cbxIndex[base]);
      i += (ev.key === "ArrowDown" ? 1 : -1);
      if (i < 0) i = opts.length - 1;
      if (i >= opts.length) i = 0;
      _cbxIndex[base] = i;
      opts.forEach(function(el, n) { el.classList.toggle("cbx-active", n === i); });
      opts[i].scrollIntoView({block: "nearest"});
    } else if (ev.key === "Enter") {
      ev.preventDefault();
      var sel = opts[_cbxIndex[base]];
      if (sel) sel.dispatchEvent(new window.MouseEvent("mousedown"));
    }
  };

  // Close any open combobox when focus moves elsewhere.
  document.addEventListener("click", function(ev) {
    document.querySelectorAll(".cbx-list.open").forEach(function(l) {
      if (!l.parentNode.contains(ev.target)) l.classList.remove("open");
    });
  });

  window.pfReloadObjectives = function(selected) {
    var emp = pfVal("pf-k-employee");
    return gpFetch("alvoraa_portal.goals_api.get_linkable_objectives", {employee: emp})
      .then(function(rows) {
        _pfObjectives = rows || [];
        cbxPick("pf-k-objective", selected || "");
      })
      .catch(function() {
        _pfObjectives = [];
        cbxPick("pf-k-objective", "");
      });
  };

  // The cascade is no longer an input; show what the chosen objective implies
  // so the derivation is visible rather than silent.
  window.pfShowCascadeNote = function() {
    var chosen = pfVal("pf-k-objective");
    var g = _pfObjectives.filter(function(o) { return o.name === chosen; })[0];
    if (!chosen) {
      pfSetHtml("pf-k-cascade-note",
        "Not linked to an objective — this KPI stands on its own.");
    } else if (g && g.goal_cascade) {
      pfSetHtml("pf-k-cascade-note",
        "Rolls up to cascade <strong>" + gpEsc(g.goal_cascade) + "</strong> via that objective.");
    } else {
      pfSetHtml("pf-k-cascade-note",
        "That objective is organisational, so this KPI rolls up to it directly.");
    }
  };

  window.pfOpenKpiModal = function(returnTo) {
    _pfKpiReturnTo = returnTo || "kpis";
    pfClearErr("pf-kpi-error");
    document.getElementById("pf-kpi-modal-title").textContent = "New KPI";
    document.getElementById("pf-k-id").value = "";
    ["pf-k-name","pf-k-target","pf-k-weightage"].forEach(function(id) {
      var el = document.getElementById(id); if (el) el.value = "";
    });
    var cycleSel = document.getElementById("pf-k-cycle");
    /* From inside a review nothing is chosen for the person: the cycle under
       review is not the next period's (decision 19, code review minor 1). */
    var current = _pfKpiReturnTo === "hr" ? pfVal("pf-hr-cycle")
      : (_pfKpiReturnTo === "review" ? "" : pfVal("tv-cycle"));
    pfFillCycleSelect("pf-k-cycle", current);
    pfFillEmployeeSelect("pf-k-employee").then(function() { pfReloadObjectives(); });
    pfOpenModal("pf-kpi-modal");
  };

  window.pfEditKpi = function(json) {
    var k = typeof json === "string" ? JSON.parse(json) : json;
    _pfKpiReturnTo = k._returnTo || "kpis";
    pfClearErr("pf-kpi-error");
    document.getElementById("pf-kpi-modal-title").textContent = "Edit KPI";
    document.getElementById("pf-k-id").value = k.name;
    document.getElementById("pf-k-name").value = k.kpi_name;
    document.getElementById("pf-k-target").value = k.target_value;
    document.getElementById("pf-k-weightage").value = k.weightage;
    document.getElementById("pf-k-unit").value = k.unit || "Number";
    document.getElementById("pf-k-direction").value = k.direction || "Higher is Better";
    document.getElementById("pf-k-category").value = k.category || "Financial";
    pfSetHtml("pf-k-cascade-note", k.goal_cascade
      ? "Rolls up to cascade <strong>" + gpEsc(k.goal_cascade) + "</strong>, inherited from the linked objective."
      : "");
    pfFillCycleSelect("pf-k-cycle", k.appraisal_cycle || "");
    pfFillEmployeeSelect("pf-k-employee", k.employee).then(function() {
      pfReloadObjectives(k.individual_goal || "");
    });
    pfOpenModal("pf-kpi-modal");
  };

  window.pfDeleteKpi = function(kpiId, label) {
    if (!confirm("Delete KPI \"" + label + "\"? This cannot be undone.")) return;
    pf("delete_kpi", {kpi: kpiId})
      .then(function() { pfAfterKpiSave(); })
      .catch(function(e) { alert(e.message); });
  };

  function pfAfterKpiSave() {
    if (window._pfKpiOnSaved) {
      var cb = window._pfKpiOnSaved;
      window._pfKpiOnSaved = null;
      cb();
      return;
    }
    if (_pfKpiReturnTo === "hr") pfLoadHrCycle();
    else if (_pfKpiReturnTo === "review") pfLoadReviews();
    else pfLoadMyKpis();
  }

  window.pfSubmitKpi = function() {
    var name = pfVal("pf-k-name"), target = pfVal("pf-k-target");
    if (!name || target === "") { pfShowErr("pf-kpi-error", "KPI name and target are required."); return; }
    if (!pfVal("pf-k-cycle")) { pfShowErr("pf-kpi-error", "Pick an appraisal cycle."); return; }
    var args = {
      employee: pfVal("pf-k-employee"),
      kpi_name: name,
      target_value: target,
      appraisal_cycle: pfVal("pf-k-cycle"),
      weightage: pfVal("pf-k-weightage") || 0,
      unit: pfVal("pf-k-unit"),
      direction: pfVal("pf-k-direction"),
      category: pfVal("pf-k-category"),
      // goal_cascade is not sent: it is derived from the linked objective.
      individual_goal: pfVal("pf-k-objective")
    };
    var existing = pfVal("pf-k-id");
    if (existing) args.kpi = existing;
    // save_kpi covers everyone: it lets HR through, a manager act for their
    // subtree, and an employee act for themselves.
    pf("save_kpi", args)
      .then(function() { pfCloseModal("pf-kpi-modal"); pfAfterKpiSave(); })
      .catch(function(e) { pfShowErr("pf-kpi-error", e.message); });
  };

  window.pfGenerateAppraisals = function() {
    var cycle = pfVal("pf-hr-cycle");
    if (!cycle) { pfSetHtml("pf-hr-msg", pfAlert("err", "Pick a cycle first.")); return; }
    pfSetHtml("pf-hr-msg", pfAlert("warn", "Generating appraisals…"));
    pf("hr_generate_appraisals", {cycle: cycle}).then(function(r) {
      var msg = r.message;
      if (r.skipped && r.skipped.length) {
        msg += " Skipped: " + r.skipped.map(function(s) { return s.employee; }).join(", ") +
               " — check their KPI weightages total 100%.";
        pfSetHtml("pf-hr-msg", pfAlert("warn", msg));
      } else {
        pfSetHtml("pf-hr-msg", pfAlert("ok", msg));
      }
      pfLoadHrCycle();
    }).catch(function(e) {
      pfSetHtml("pf-hr-msg", pfAlert("err", e.message));
    });
  };

  window.pfSetCycleStatus = function(status) {
    var cycle = pfVal("pf-hr-cycle");
    if (!cycle) { pfSetHtml("pf-hr-msg", pfAlert("err", "Pick a cycle first.")); return; }
    pf("hr_set_cycle_status", {cycle: cycle, status: status}).then(function(r) {
      pfSetHtml("pf-hr-msg", pfAlert("ok", r.message));
      return pf("get_performance_context").then(function(ctx) { _pfCtx = ctx; pfFillCycleSelects(); });
    }).catch(function(e) { pfSetHtml("pf-hr-msg", pfAlert("err", e.message)); });
  };

  /* ── Self-review narrative ────────────────────────── */

  var _pfNarrativeAppraisal = "";

  window.pfOpenNarrativeModal = function(appraisalId) {
    _pfNarrativeAppraisal = appraisalId;
    pfClearErr("pf-narrative-error");
    document.getElementById("pf-narrative-appraisal").value = appraisalId;
    var btn = document.getElementById("pf-narrative-btn");
    if (btn) { btn.disabled = true; btn.textContent = "Loading…"; }
    pf("get_appraisal_extension", {appraisal: appraisalId}).then(function(ext) {
      document.getElementById("pf-narrative-achievements").value = ext.achievements_text || "";
      document.getElementById("pf-narrative-challenges").value = ext.challenges_text || "";
      document.getElementById("pf-narrative-devneeds").value = ext.development_needs_text || "";
      document.getElementById("pf-narrative-support").value = ext.support_needed || "";
      document.getElementById("pf-narrative-forward").value = ext.next_period_goals_text || "";
      if (btn) { btn.disabled = false; btn.textContent = "Save Narrative"; }
      pfOpenModal("pf-narrative-modal");
    }).catch(function() {
      if (btn) { btn.disabled = false; btn.textContent = "Save Narrative"; }
      pfOpenModal("pf-narrative-modal");
    });
  };

  window.pfSubmitNarrative = function() {
    var ap = _pfNarrativeAppraisal;
    if (!ap) return;
    var btn = document.getElementById("pf-narrative-btn");
    if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }
    pf("save_self_review_narrative", {
      appraisal: ap,
      achievements_text: document.getElementById("pf-narrative-achievements").value,
      challenges_text: document.getElementById("pf-narrative-challenges").value,
      development_needs_text: document.getElementById("pf-narrative-devneeds").value,
    }).then(function() {
      return pf("save_support_needed", {
        appraisal: ap,
        support_needed: document.getElementById("pf-narrative-support").value,
      });
    }).then(function() {
      return pf("save_forward_planning", {
        appraisal: ap,
        next_period_goals_text: document.getElementById("pf-narrative-forward").value,
      });
    }).then(function() {
      pfCloseModal("pf-narrative-modal");
      pfLoadMyReviewStatus();
    }).catch(function(e) {
      pfShowErr("pf-narrative-error", e.message);
      if (btn) { btn.disabled = false; btn.textContent = "Save Narrative"; }
    });
  };

  /* ── Review status (overview tab) ────────────────── */

  window.pfLoadMyReviewStatus = function() {
    var card = document.getElementById("gp-review-status-card");
    if (!card) return;
    pf("get_appraisals", {}).then(function(data) {
      var own = (data.appraisals || []).filter(function(a) { return a.is_own && a.status !== "Submitted"; });
      if (!own.length) { card.style.display = "none"; return; }
      var ap = own[0];
      card.style.display = "";
      return pf("get_appraisal_extension", {appraisal: ap.name}).then(function(ext) {
        var status = ext.review_status || "Not Started";

        /* ── Stage bar ────────────────────────────────── */
        /* Stages in order: 0=Employee Review, 1=Manager Review, 2=HR Review, 3=Completed */
        var stageOrder = ["Employee Review", "Manager Review", "HR Review", "Completed"];
        /* Map API status → stage index that is CURRENTLY ACTIVE */
        var statusToActive = {
          "Not Started":     0,
          "Employee Review": 0,
          "Manager Review":  1,
          "HR Review":       2,
          "Completed":       3,
        };
        var activeIdx = statusToActive[status] !== undefined ? statusToActive[status] : 0;
        for (var si = 0; si < stageOrder.length; si++) {
          var dot  = document.getElementById("psb-dot-" + si);
          var step = document.getElementById("psb-step-" + si);
          var conn = document.getElementById("psb-conn-" + si);
          if (!dot || !step) continue;
          dot.className  = si < activeIdx ? "psb-dot done" : si === activeIdx ? "psb-dot active" : "psb-dot pending";
          /* clear the number on a done dot; .psb-dot.done::after draws the tick */
          dot.textContent = si < activeIdx ? "" : si + 1 + "";
          step.className = si < activeIdx ? "psb-step done" : si === activeIdx ? "psb-step active" : "psb-step";
          if (conn) conn.className = "psb-connector" + (si < activeIdx ? " done" : si === activeIdx ? " active" : "");
        }
        var body = document.getElementById("gp-review-status-body");
        if (body) {
          var returnNote = ext.return_reason
            ? "<div class=\"callout callout-warn\" style=\"margin-bottom:10px\"><strong>Returned for revision:</strong> " + gpEsc(ext.return_reason) + "</div>"
            : "";
          var hasNarr = ext.achievements_text || ext.challenges_text || ext.development_needs_text;
          var narrativeHint = hasNarr
            ? "<div style=\"font-size:var(--fs-base);color:var(--text2);margin-bottom:4px\">Self-review narrative written <i class=ic-check></i></div>"
            : "<div style=\"font-size:var(--fs-base);color:var(--text3);margin-bottom:4px\">No self-review narrative yet.</div>";
          var supportHint = ext.support_needed
            ? "<div style=\"font-size:var(--fs-sm);color:var(--text3)\">Support request noted.</div>"
            : "";
          var overallHint = (status === "Completed" && ext.overall_rating != null)
            ? "<div style=\"margin-top:8px;padding:8px 12px;background:var(--surface2);border-radius:var(--r-sm);font-size:var(--fs-base)\">" +
              "<strong>Overall Rating:</strong> " + pfNum(ext.overall_rating, 1) + " / 5" +
              (ext.potential_category ? " &nbsp;·&nbsp; Potential: " + gpEsc(ext.potential_category) : "") + "</div>"
            : "";
          var actionItemsHtml = "";
          if (ext.action_items && ext.action_items.length) {
            actionItemsHtml = "<div style=\"margin-top:8px\"><strong style=\"font-size:var(--fs-sm)\">Action Items:</strong>" +
              ext.action_items.map(function(a) {
                return "<div style=\"font-size:var(--fs-sm);color:var(--text2);padding:3px 0\">" +
                  gpEsc(a.description) + (a.due_date ? " · due " + gpEsc(a.due_date) : "") +
                  " <span style=\"color:" + (a.status === "Completed" ? "var(--green)" : "var(--amber)") + "\">[" + gpEsc(a.status) + "]</span></div>";
              }).join("") + "</div>";
          }
          body.innerHTML = returnNote + narrativeHint + supportHint + overallHint + actionItemsHtml;
        }
        var actions = document.getElementById("gp-review-actions");
        if (actions) {
          var btns = "";
          if (status !== "Completed") {
            btns += "<button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenNarrativeModal('" + gpEsc(ap.name) + "')\">Write Self-Review</button>";
          }
          if (status === "Not Started" || status === "Employee Review") {
            btns += " <button class=\"btn btn-primary btn-sm\" onclick=\"prOpenReview('" + gpEsc(ap.name) + "')\">Open My Review</button>";
          }
          // Upward feedback — shown to employees who have a manager, during Employee Review or once completed
          if (_gpCtx && _gpCtx.reports_to && (status === "Employee Review" || status === "Not Started" || status === "Completed")) {
            btns += " <button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenUpwardModal()\">Give Upward Feedback</button>";
          }
          actions.innerHTML = btns;
        }
      });
    }).catch(function() { if (card) card.style.display = "none"; });
  };

  window.pfAdvanceReview = function(appraisalId) {
    if (!confirm("Submit your self-review to your manager?")) return;
    pf("advance_review_status", {appraisal: appraisalId}).then(function() {
      pfLoadMyReviewStatus();
    }).catch(function(e) { alert(e.message); });
  };

  /* ══════════════════════════════════════════════════════
     Employee Review Wizard
  ══════════════════════════════════════════════════════ */

  var _pr = {
    appraisal: null,
    data: null,
    pages: [],       // [{key, label}] derived from page_config
    currentIdx: 0,
    saving: false,
  };

  /* Human-readable titles for built-in page keys — both dash and underscore variants */
  var _PR_PAGE_META = {
    "past-objectives":        {label: "Past Objectives & KPIs"},
    "past-dev":               {label: "Past Development"},
    "future-objectives":      {label: "Future Objectives & KPIs"},
    "future-dev":             {label: "Future Development Plan"},
    "manager-feedback":       {label: "Manager's Feedback"},
    "manager-feedback-form":  {label: "Manager Feedback"},
    "manager-submit":         {label: "Rate & Submit"},
    "employee-final-review":  {label: "Manager Feedback"},
    "employee-pre-review":    {label: "Feedback for Reporting Manager"},
    "summary":                {label: "Summary & Submit"},
    "past_objectives":        {label: "Past Objectives & KPIs"},
    "future_goals":           {label: "Future Objectives & KPIs"},
    "objectives-review":      {label: "Objectives Review"},
    "kpis-review":            {label: "KPIs & Metrics"},
    "strengths":              {label: "Key Achievements"},
    "challenges":             {label: "Challenges Faced"},
    "development":            {label: "Development Needs"},
    "support":                {label: "Support from Manager"},
  };

  /* How many objectives and KPIs this review is carrying. */
  function _prItemCount(d) {
    var n = ((d && d.goals) || []).length + ((d && d.standalone_kpis) || []).length;
    ((d && d.goals) || []).forEach(function(g) { n += (g.kpis || []).length; });
    return n;
  }

  /* A review whose cycle has no pages configured still renders: the wizard
     appends its own first and last steps, so it looks like a short but
     complete review. Everything the review actually holds is then invisible,
     with nothing on screen to say so - which is how a whole tenant went a
     quarter without anyone seeing an objective inside a review.

     A review that cannot show its items must say so. `configuredPages` is how
     many pages the cycle contributed, before the wizard's own steps. */
  window.prShowMissingPagesWarning = function(d, configuredPages) {
    var el = document.getElementById("pr-missing-pages");
    if (!el) return;
    var items = _prItemCount(d);
    if (!items || configuredPages > 0) {
      el.style.display = "none";
      el.innerHTML = "";
      return;
    }
    el.innerHTML = "<div class=\"callout callout-warn\">" +
      "<strong>" + gpEsc("This review cannot show its objectives and KPIs.") + "</strong> " +
      gpEsc("It holds " + items + (items === 1 ? " item" : " items") +
            ", but this appraisal cycle has no page set up to show them on. " +
            "Nothing has been lost. Ask HR to add the objectives page to the cycle, " +
            "then open this review again.") +
    "</div>";
    el.style.display = "";
  };

  window.prOpenReview = function(appraisalName) {
    _pr.appraisal = appraisalName;
    _pr.data = null;
    /* This is the person's own review. Clearing the role matters: without it a
       manager who opened someone else's review earlier in the same session
       would still be treated as a manager on their own screen. */
    _pr.viewerRole = null;
    _pr.pages = [];
    _pr.currentIdx = 0;
    _pr.viewMode = "hierarchical";  // "hierarchical" | "list"
    _pr.draftGoals = [];            // new goals added in future-objectives
    _pr.draftKpis  = [];            // new KPIs added in future-objectives
    switchPanel("pms-review");
    document.getElementById("pr-content").innerHTML =
      "<div style=\"color:var(--text3);font-size:var(--fs-base);padding-top:40px;text-align:center\">Loading your review...</div>";
    document.getElementById("pr-nav").innerHTML = "";
    /* The warning belongs to one review. Clear it before loading the next,
       so a review that fails to load cannot show the last one's banner. */
    var _mp = document.getElementById("pr-missing-pages");
    if (_mp) { _mp.innerHTML = ""; _mp.style.display = "none"; }
    pf("get_my_review", {appraisal: appraisalName}).then(function(d) {
      _pr.data = d;
      /* Normalize page_config — stored as {key:true} object or [{key,label}] array */
      var rawCfg = d.page_config || {};
      var cfgArr;
      if (Array.isArray(rawCfg)) {
        cfgArr = rawCfg;
      } else if (typeof rawCfg === "object") {
        cfgArr = Object.keys(rawCfg)
          .filter(function(k) { return rawCfg[k]; })
          .map(function(k) { return {key: k}; });
      } else { cfgArr = []; }
      var _EMP_SKIP = {
        "manager-feedback": true, "manager-feedback-form": true,
        "manager-submit": true, "employee-pre-review": true, "pages": true
      };
      var pages = [];
      cfgArr.forEach(function(p) {
        if (p.enabled === false) return;
        var key = p.key || p;
        if (_EMP_SKIP[key]) return;
        var meta = _PR_PAGE_META[key] || {};
        var customLabel = d.page_settings && d.page_settings[key] && d.page_settings[key].page_label;
        pages.push({key: key, label: customLabel || p.label || meta.label || key});
      });
      prShowMissingPagesWarning(d, pages.length);
      if (!pages.some(function(p) { return p.key === "employee-pre-review"; }))
        pages.push({key: "employee-pre-review", label: "Feedback for Reporting Manager"});
      if (!pages.some(function(p) { return p.key === "summary"; }))
        pages.push({key: "summary", label: "Summary & Submit"});
      /* If employee is viewing their final review, replace summary with acknowledge page */
      if (d.review_status === "Employee Final Review") {
        pages = pages.filter(function(p) { return p.key !== "summary"; });
        pages.push({key: "employee-final-review", label: "Manager Feedback"});
      }
      _pr.pages = pages;
      /* Restore draft goals/kpis from saved page_data */
      var futureSaved = (d.page_data && (d.page_data["future-objectives"] || d.page_data["future_goals"])) || {};
      _pr.draftGoals = futureSaved.new_goals || [];
      _pr.draftKpis  = futureSaved.new_kpis  || [];

      document.getElementById("pr-title").textContent = "My Performance Review";
      document.getElementById("pr-sub").textContent =
        (d.cycle && d.cycle.cycle_name ? d.cycle.cycle_name : "") +
        (d.employee_name ? " · " + d.employee_name : "");

      prUpdateStageBar(d.review_status);
      prBuildNav();
      prShowPage(0);
    }).catch(function(e) {
      document.getElementById("pr-content").innerHTML =
        "<div style=\"color:var(--danger,var(--red));padding:20px\">" + gpEsc(e.message || "Failed to load review.") + "</div>";
    });
  };

  window.prSetView = function(mode) {
    _pr.viewMode = mode;
    var key = _pr.pages[_pr.currentIdx] && _pr.pages[_pr.currentIdx].key;
    var editable = _pr.data &&
      (_pr.data.review_status === "Not Started" || _pr.data.review_status === "Employee Review") &&
      !_pr.viewerRole;
    if (key) prRenderPage(key, editable);
  };

  function prUpdateStageBar(status) {
    var stages = ["Employee Review", "Manager Review", "Final Review", "HR Review", "Completed"];
    var statusToActive = {
      "Not Started": 0, "Employee Review": 0,
      "Manager Review": 1,
      "Employee Final Review": 2,
      "HR Review": 3,
      "Completed": 4,
    };
    var activeIdx = statusToActive[status] !== undefined ? statusToActive[status] : 0;
    for (var i = 0; i < stages.length; i++) {
      var dot = document.getElementById("pr-sd-" + i);
      var step = document.getElementById("pr-ss-" + i);
      var conn = document.getElementById("pr-sc-" + i);
      if (!dot || !step) continue;
      if (i < activeIdx) {
        dot.className = "pr-sd done"; dot.innerHTML = "<i class=ic-check></i>";
        step.className = "pr-sst done";
      } else if (i === activeIdx) {
        dot.className = "pr-sd active"; dot.textContent = i + 1 + "";
        step.className = "pr-sst active";
      } else {
        dot.className = "pr-sd"; dot.textContent = i + 1 + "";
        step.className = "pr-sst";
      }
      if (conn) conn.className = "pr-sconn" + (i < activeIdx ? " done" : "");
    }
  }

  function prBuildNav() {
    var nav = document.getElementById("pr-nav");
    if (!nav) return;
    var done = (_pr.data && _pr.data.pages_completed) || [];
    var html = "";
    _pr.pages.forEach(function(p, i) {
      var isDone = done.indexOf(p.key) >= 0;
      var cls = "pr-nav-item" + (i === _pr.currentIdx ? " active" : "") + (isDone ? " done" : "");
      html += "<div class=\"" + cls + "\" id=\"pr-ni-" + i + "\" onclick=\"prShowPage(" + i + ")\">" +
        "<div class=\"pr-navcheck\">" + (isDone ? "<i class=ic-check></i>" : "") + "</div>" +
        "<span>" + gpEsc(p.label) + "</span></div>";
    });
    nav.innerHTML = html;
  }

  window.prShowPage = function(idx) {
    if (idx < 0 || idx >= _pr.pages.length) return;
    /* Auto-save current before switching (unless we're already on this page) */
    if (_pr.currentIdx !== idx && _pr.data) {
      prAutoSave(_pr.pages[_pr.currentIdx].key, null);
    }
    _pr.currentIdx = idx;
    prBuildNav();

    var prevBtn = document.getElementById("pr-prev-btn");
    var nextBtn = document.getElementById("pr-next-btn");
    if (prevBtn) prevBtn.style.display = idx > 0 ? "" : "none";
    if (nextBtn) {
      var isSummary = _pr.pages[idx].key === "summary";
      nextBtn.style.display = isSummary ? "none" : "";
      nextBtn.textContent = idx < _pr.pages.length - 2 ? "Save & Continue" : "Save & Finish";
    }

    var isManagerPage = (_pr.pages[idx].key === "manager-feedback-form" || _pr.pages[idx].key === "manager-submit");
    var editable = isManagerPage
      ? (_pr.data && _pr.data.review_status === "Manager Review")
      : (_pr.data && (_pr.data.review_status === "Not Started" || _pr.data.review_status === "Employee Review") && !_pr.viewerRole);
    prRenderPage(_pr.pages[idx].key, editable);
  };

  window.prNextPage = function() {
    if (!_pr.data) return;
    prAutoSave(_pr.pages[_pr.currentIdx].key, function() {
      if (_pr.currentIdx < _pr.pages.length - 1) {
        prShowPage(_pr.currentIdx + 1);
      }
    });
  };

  window.prPrevPage = function() {
    if (_pr.currentIdx > 0) prShowPage(_pr.currentIdx - 1);
  };

  function prAutoSave(pageKey, cb) {
    if (!_pr.data || _pr.saving) { if (cb) cb(); return; }
    if (_pr.data.review_status !== "Not Started" && _pr.data.review_status !== "Employee Review") {
      if (cb) cb(); return;
    }
    var pageData = prCollectPageData(pageKey);
    _pr.saving = true;
    var ind = document.getElementById("pr-save-ind");
    if (ind) ind.textContent = "Saving…";
    pf("save_review_page", {
      appraisal: _pr.appraisal,
      page_key: pageKey,
      page_data_json: JSON.stringify(pageData),
    }).then(function(res) {
      _pr.saving = false;
      if (ind) ind.innerHTML = "Saved <i class=ic-check></i>";
      setTimeout(function() { if (ind) ind.textContent = ""; }, 2000);
      /* Update local completed list */
      if (res && res.pages_completed) {
        _pr.data.pages_completed = res.pages_completed;
        prBuildNav();
      }
      if (cb) cb();
    }).catch(function(e) {
      _pr.saving = false;
      if (ind) ind.textContent = "Save failed";
      if (cb) cb();
    });
  }

  function prCollectPageData(key) {
    var data = {};
    var isPastObj = key === "past-objectives" || key === "past_objectives";
    var isFutureObj = key === "future-objectives" || key === "future_goals";
    if (isPastObj) {
      /* KPI self-rating + comment */
      var kpis = {};
      document.querySelectorAll("[data-pr-kpi-name]").forEach(function(el) {
        var n = el.getAttribute("data-pr-kpi-name");
        kpis[n] = kpis[n] || {};
        if (el.classList.contains("pr-kpi-rating"))  kpis[n].self_rating  = el.value;
        if (el.classList.contains("pr-kpi-comment")) kpis[n].self_comment = el.value;
      });
      /* Objective actual-progress + reflection */
      /* Reflections only. Progress is never typed into a review: it comes from
         approved facts dated inside the review period (slice 010 D, R3). */
      var objs = {};
      document.querySelectorAll("[data-pr-obj-name]").forEach(function(el) {
        var n = el.getAttribute("data-pr-obj-name");
        objs[n] = objs[n] || {};
        if (el.classList.contains("pr-obj-reflect-ta")) objs[n].reflection = el.value;
      });
      data.kpis = kpis; data.objectives = objs;
    } else if (isFutureObj) {
      var carry = {};
      document.querySelectorAll("[data-pr-carry]").forEach(function(el) {
        var n = el.getAttribute("data-pr-carry");
        carry[n] = carry[n] || {include: false, note: ""};
        if (el.type === "checkbox") carry[n].include = el.checked;
        if (el.classList.contains("pr-carry-note")) carry[n].note = el.value;
      });
      data.carry_forward = carry;
      data.new_goals = _pr.draftGoals || [];
      data.new_kpis  = _pr.draftKpis  || [];
    } else {
      document.querySelectorAll("[data-pr-field]").forEach(function(el) {
        data[el.getAttribute("data-pr-field")] = el.value;
      });
    }
    return data;
  }

  function prRenderPage(key, editable) {
    var d = _pr.data;
    if (!d) return;
    var saved = (d.page_data && d.page_data[key]) || {};
    if (key === "past-objectives" || key === "past_objectives") {
      prRenderGoalsPage(d, saved, editable);
    } else if (key === "past-dev") {
      prRenderPastDevPage(d, saved, editable);
    } else if (key === "future-objectives" || key === "future_goals") {
      prRenderFutureObjectivesPage(d, saved, editable);
    } else if (key === "future-dev") {
      prRenderFutureDevPage(d, saved, editable);
    } else if (key === "manager-feedback") {
      prRenderManagerFeedbackPlaceholder();
    } else if (key === "manager-feedback-form") {
      prRenderManagerFeedbackForm(d, editable);
    } else if (key === "manager-submit") {
      prRenderManagerSubmitPage(d, editable);
    } else if (key === "objectives-review") {
      prRenderGoalsPage(d, saved, editable, "Objectives &amp; KPIs Review");
    } else if (key === "kpis-review") {
      prRenderGoalsPage(d, saved, editable, "KPIs &amp; Metrics Review");
    } else if (key === "employee-pre-review") {
      prRenderEmployeePreReview(d, saved, editable);
    } else if (key === "employee-final-review") {
      prRenderEmployeeFinalReview(d);
    } else if (key === "summary") {
      prRenderSummary(d, editable);
    } else {
      prRenderGenericPage(key, d, saved, editable);
    }
    /* Apply custom page label to the content-area title when HR has renamed this page */
    var customLabel = d.page_settings && d.page_settings[key] && d.page_settings[key].page_label;
    if (customLabel) {
      var content = document.getElementById("pr-content");
      var titleEl = content && content.querySelector(".pr-page-title");
      if (titleEl) titleEl.textContent = customLabel;
    }
  }

  /* ── Past Objectives & KPIs ──────────────────────── */

  function prRenderGoalsPage(d, saved, editable, title) {
    var goals = d.goals || [];
    var standalone = d.standalone_kpis || [];
    /* These are the review's own copies. Their row names are the keys used
       everywhere on this page (slice 010 group D, VIS-3). */
    _riItems = {};
    riIndex(goals);
    riIndex(standalone);
    var isHier = _pr.viewMode !== "list";
    var header = "<div class=\"pr-page-title\">" + (title || "Past Objectives &amp; KPIs") + "</div>" +
      "<div class=\"pr-page-sub\">" +
        (editable
          ? "Rate yourself and comment on each item. The numbers come from approved progress and evidence dated inside the review period."
          : (_pr.viewerRole
              ? "This is the review's own copy of each item. Changing it here does not change the live record."
              : "Read-only — your review has been submitted.")) +
      "</div>" +
      riReviewNotesHtml(d) +
      "<div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:8px\">" +
        "<div class=\"pr-view-toggle\">" +
          "<button class=\"pr-vtbtn" + (isHier ? " active" : "") + "\" onclick=\"prSetView('hierarchical')\">Hierarchical</button>" +
          "<button class=\"pr-vtbtn" + (!isHier ? " active" : "") + "\" onclick=\"prSetView('list')\">List</button>" +
        "</div>" +
        "<div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">" +
          (goals.length || standalone.length
            ? "<span style=\"font-size:var(--fs-sm);color:var(--text3)\">" +
                goals.length + " objective" + (goals.length !== 1 ? "s" : "") +
                " · " + (goals.reduce(function(s,g){return s+(g.kpis||[]).length;},0) + standalone.length) + " KPIs</span>"
            : "") +
          (editable
            ? "<button class=\"btn btn-outline btn-sm\" onclick=\"prOpenObjectiveSelector()\">Add/remove Objectives</button>" +
              "<button class=\"btn btn-outline btn-sm\" onclick=\"prOpenKpiSelector()\">Add/remove KPIs</button>"
            : "") +
          /* What the manager lost when the old KPI rating row went: a first
             guess from measured attainment, now read off the review's copies. */
          (riCanRateAsManager()
            ? "<button class=\"btn btn-outline btn-sm\" onclick=\"riSuggestRatings()\">Fill empty ratings from attainment</button>"
            : "") +
        "</div>" +
      "</div>";

    if (!goals.length && !standalone.length) {
      document.getElementById("pr-content").innerHTML = header +
        "<div style=\"color:var(--text3);font-size:var(--fs-base);text-align:center;padding:40px 0\">No objectives or KPIs are in this review.</div>" +
        riRemovedHtml(d);
      return;
    }

    document.getElementById("pr-content").innerHTML = header +
      "<div id=\"pr-goals-body\"></div>" + riRemovedHtml(d);

    if (isHier) {
      prRenderHierarchicalGoals(goals, standalone, saved, editable);
    } else {
      prRenderListGoals(goals, standalone, saved, editable);
    }
  }

  function prRenderHierarchicalGoals(goals, standalone, saved, editable) {
    /* Build parent→children map so we can render the same tree the main
       Objectives view shows — child goals nested under their parent. */
    var goalMap = {};
    goals.forEach(function(g) { goalMap[g.name] = g; _prGoalStore[g.name] = g; });
    var childrenOf = {};
    goals.forEach(function(g) {
      if (g.parent_goal && goalMap[g.parent_goal]) {
        if (!childrenOf[g.parent_goal]) childrenOf[g.parent_goal] = [];
        childrenOf[g.parent_goal].push(g);
      }
    });
    var roots = goals.filter(function(g) { return !g.parent_goal || !goalMap[g.parent_goal]; });

    function renderGoalNode(g) {
      var savedObj  = (saved.objectives && saved.objectives[g.name]) || {};
      var pct       = g.progress_pct != null ? parseFloat(g.progress_pct) : 0;
      var children  = childrenOf[g.name] || [];
      var kpis      = g.kpis || [];
      var hasKids   = children.length || kpis.length;
      var org       = !g.parent_goal;
      var colour    = gpTrajColor(g.trajectory);

      /* ── Goal row (uses same .tv-row styling as main tree) ── */
      var rowHtml =
        "<div class=\"tv-row " + (org ? "tv-goal-org" : "tv-goal") + "\" style=\"margin-bottom:0\">" +
          (hasKids
            ? "<button class=\"tv-caret\" onclick=\"event.stopPropagation();prToggleObj('" + gpEsc(g.name) + "')\" title=\"Toggle\">&#9660;</button>"
            : "<span class=\"tv-caret tv-leaf\"></span>") +
          "<div class=\"tv-main\">" +
            "<div class=\"tv-name\">" + gpEsc(g.goal_name || g.name) +
              "<span class=\"tv-badge " + (org ? "tv-badge-org" : "tv-badge-obj") + "\">" + (org ? "Organisational" : "Objective") + "</span>" +
              (g.goal_type === "Development" ? "<span class=\"tv-badge\" style=\"background:var(--sky,var(--green));color:var(--surface)\">Dev</span>" : "") +
              (g.is_extra_initiative ? "<span class=\"tv-badge\" style=\"background:var(--amber);color:var(--surface)\">Stretch</span>" : "") +
              (g.company_value ? "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\">" + gpEsc(g.company_value) + "</span>" : "") +
              (g.status && g.status !== "Active" ? "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\">" + gpEsc(g.status) + "</span>" : "") +
            "</div>" +
            "<div class=\"tv-meta\">" + gpEsc(g.employee_name || "") +
              " · target " + (g.target_value || 0) + " " + gpEsc(g.unit || "") +
              " · " + (g.start_date ? gpFmtDate(g.start_date) : "?") + " – " + (g.end_date ? gpFmtDate(g.end_date) : "?") +
            "</div>" +
            riChangeNote(g) +
          "</div>" +
          "<div class=\"tv-right\">" +
            "<div class=\"tv-bar\"><div class=\"tv-bar-fill\" style=\"width:" + Math.min(100,pct) + "%;background:" + colour + "\"></div></div>" +
            "<div class=\"tv-pct\">" + Math.round(pct) + "%</div>" +
            riItemActions(g) +
          "</div>" +
        "</div>";

      /* ── Review inputs (reflection; the number comes from dated facts) ── */
      var inputsHtml =
        "<div class=\"pr-obj-body\" style=\"padding:10px 12px 8px;background:var(--surface2);border-left:3px solid " + colour + ";margin-bottom:0\">" +
          "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-bottom:6px\">" +
            "Reached " + gpEsc(pfNum(g.actual_progress, 2) + " of " + pfNum(g.target_value, 2)) +
            " " + gpEsc(g.unit || "") + " · " + gpEsc(pfNum(g.facts_count, 0)) + " approved updates counted in this review." +
            " The figure comes from approved progress and evidence, so it is not typed in here." +
          "</div>" +
          "<div class=\"pr-obj-reflect\">" +
            "<label for=\"pr-reflect-" + gpEsc(g.name) + "\">Reflection</label>" +
            "<textarea id=\"pr-reflect-" + gpEsc(g.name) + "\" class=\"pr-obj-reflect-ta\" data-pr-obj-name=\"" + gpEsc(g.name) +
              "\" placeholder=\"How did this objective go? What could be improved?\"" +
              (editable ? "" : " readonly") + ">" +
              gpEsc(savedObj.reflection || "") + "</textarea>" +
          "</div>" +
          riManagerRatingHtml(g) +
        "</div>";

      /* ── Children (KPIs + sub-objectives) ── */
      var childrenHtml = "";
      if (hasKids) {
        childrenHtml = "<div class=\"tv-children pr-obj-body\">";
        kpis.forEach(function(k) {
          var onRemove = editable ? "prRemoveKpiFromReview('" + gpEsc(k.name) + "')" : null;
          childrenHtml += prReviewKpiRow(k, saved, editable, onRemove);
        });
        children.forEach(function(child) { childrenHtml += renderGoalNode(child); });
        childrenHtml += "</div>";
      }

      return "<div class=\"pr-obj\" id=\"pr-obj-" + gpEsc(g.name) + "\" style=\"margin-bottom:8px\">" +
        rowHtml + inputsHtml + childrenHtml +
      "</div>";
    }

    var html = roots.map(renderGoalNode).join("");

    /* Standalone KPIs */
    if (standalone.length) {
      html += "<div class=\"pr-section-hdr\">Standalone KPIs</div>";
      standalone.forEach(function(k) {
        var onRemove = editable ? "prRemoveKpiFromReview('" + gpEsc(k.name) + "')" : null;
        html += prReviewKpiRow(k, saved, editable, onRemove);
      });
    }
    document.getElementById("pr-goals-body").innerHTML = html;
  }

  /* KPI row using the same .tv-row.tv-kpi style as the main tree, with
     self-rating and comment inputs embedded for the review context. */
  function prReviewKpiRow(k, saved, editable, onRemove) {
    var savedKpi = (saved.kpis && saved.kpis[k.name]) || {};
    var rating   = savedKpi.self_rating  !== undefined ? savedKpi.self_rating  : (k.self_rating  || "");
    var comment  = savedKpi.self_comment !== undefined ? savedKpi.self_comment : (k.self_comment || "");
    var att      = k.attainment_pct != null ? parseFloat(k.attainment_pct) : 0;
    var pct      = Math.max(0, Math.min(100, att));
    var colour   = pfAttColor(att);
    var kpiDateStr = [k.period_start, k.period_end].filter(Boolean).map(gpFmtDate).join(" – ");
    return "<div class=\"tv-row tv-kpi\" style=\"margin-bottom:5px;align-items:flex-start\">" +
      "<span class=\"tv-caret tv-leaf\"></span>" +
      "<div class=\"tv-main\">" +
        "<div class=\"tv-name\">" + gpEsc(k.kpi_name || k.name) +
          "<span class=\"tv-badge tv-badge-kpi\">KPI</span>" +
          (k.is_extra_initiative ? "<span class=\"tv-badge\" style=\"background:var(--amber);color:var(--surface)\">Stretch</span>" : "") +
          (k.company_value ? "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\">" + gpEsc(k.company_value) + "</span>" : "") +
        "</div>" +
        "<div class=\"tv-meta\">" + gpEsc(k.employee_name || "") +
          (k.category ? " · " + gpEsc(k.category) : "") +
          " · target " + (k.target_value || 0) + " " + gpEsc(k.unit || "") +
          " · weight " + pfNum(k.weightage) + "%" +
          (kpiDateStr ? " · " + gpEsc(kpiDateStr) : "") +
          (k.creator_name ? " · by " + gpEsc(k.creator_name) : "") +
        "</div>" +
        riChangeNote(k) +
        ((_pr.viewerRole && k.self_rating === undefined)
          ? ""
          : "<div class=\"pr-kpi-assess\" style=\"margin-top:8px\">" +
              "<div class=\"pr-kpi-comment-wrap\">" +
                "<label class=\"pr-rating-lbl\" for=\"pr-kc-" + gpEsc(k.name) + "\">" +
                  (_pr.viewerRole ? "Employee's comment" : "Your comment") + "</label>" +
                "<textarea id=\"pr-kc-" + gpEsc(k.name) + "\" class=\"pr-kpi-comment\" data-pr-kpi-name=\"" + gpEsc(k.name) +
                  "\" placeholder=\"Your comment on this KPI...\"" + (editable ? "" : " readonly") + ">" +
                  gpEsc(comment) + "</textarea></div>" +
              "<div class=\"pr-rating-wrap\">" +
                "<label class=\"pr-rating-lbl\" for=\"pr-kr-" + gpEsc(k.name) + "\">Self-rating</label>" +
                "<input id=\"pr-kr-" + gpEsc(k.name) + "\" type=\"number\" class=\"pr-rating-inp pr-kpi-rating\" data-pr-kpi-name=\"" + gpEsc(k.name) +
                "\" min=\"1\" max=\"5\" step=\"0.5\" value=\"" + gpEsc(rating+"") + "\" placeholder=\"1–5\"" +
                (editable ? "" : " readonly") + "></div>" +
            "</div>") +
        riManagerRatingHtml(k) +
      "</div>" +
      "<div class=\"tv-right\" style=\"flex-shrink:0;align-self:flex-start\">" +
        "<div class=\"tv-bar\"><div class=\"tv-bar-fill\" style=\"width:" + pct + "%;background:" + colour + "\"></div></div>" +
        "<div class=\"tv-pct\" style=\"color:" + colour + "\">" + pfNum(att) + "%</div>" +
        riItemActions(k) +
      "</div>" +
    "</div>";
  }

  function prRenderListGoals(goals, standalone, saved, editable) {
    /* Edit and Remove follow the review's stage and the person's part in it,
       not whether the self-assessment boxes are open (slice 010 D). */
    var canAct = riCanEditDefinition() || riCanRemove();
    function acts(it) {
      if (!canAct) return "";
      var html = "";
      if (riCanEditDefinition()) {
        html += "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs);padding:3px 8px\" " +
          "onclick=\"riOpenEditItem('" + gpEsc(it.name) + "')\">Edit</button> ";
      }
      if (riCanRemove()) {
        html += "<button class=\"btn btn-sm\" style=\"font-size:var(--fs-xs);padding:3px 8px;color:var(--danger,var(--red));border:1px solid var(--danger,var(--red));background:none\" " +
          "onclick=\"riOpenRemove('" + gpEsc(it.name) + "')\">Remove</button>";
      }
      return "<td style=\"white-space:nowrap\">" + html + "</td>";
    }
    var thead = "<tr><th>KPI</th><th>Objective</th><th>Target</th><th>Actual</th><th>Attainment</th><th>Period</th><th>Created by</th><th style=\"min-width:80px\">Self-Rating<br><span style=\"font-weight:400\">(1–5)</span></th><th style=\"min-width:140px\">Comment</th>" + (canAct ? "<th></th>" : "") + "</tr>";
    var rows = "";
    goals.forEach(function(g) {
      _prGoalStore[g.name] = g;
      var gPeriod = [g.start_date, g.end_date].filter(Boolean).map(gpFmtDate).join(" – ");
      (g.kpis || []).forEach(function(k) {
        var savedKpi = (saved.kpis && saved.kpis[k.name]) || {};
        var rating  = savedKpi.self_rating  !== undefined ? savedKpi.self_rating  : (k.self_rating  || "");
        var comment = savedKpi.self_comment !== undefined ? savedKpi.self_comment : (k.self_comment || "");
        var att = k.attainment_pct != null ? parseFloat(k.attainment_pct).toFixed(0) + "%" : "--";
        var color = k.attainment_pct >= 100 ? "var(--green)" : k.attainment_pct >= 70 ? "var(--amber)" : "var(--danger,var(--red))";
        var kPeriod = [k.period_start, k.period_end].filter(Boolean).map(gpFmtDate).join(" – ") || gPeriod;
        rows += "<tr>" +
          "<td style=\"font-weight:600\">" + gpEsc(k.kpi_name || k.name) + "</td>" +
          "<td style=\"color:var(--text3)\">" + gpEsc(g.goal_name || "—") + "</td>" +
          "<td>" + gpEsc((k.target_value || "--") + (k.unit ? " "+k.unit : "")) + "</td>" +
          "<td>" + gpEsc(k.actual_value || "--") + "</td>" +
          "<td style=\"font-weight:700;color:" + color + "\">" + att + "</td>" +
          "<td style=\"font-size:var(--fs-xs);color:var(--text3);white-space:nowrap\">" + gpEsc(kPeriod || "—") + "</td>" +
          "<td style=\"font-size:var(--fs-xs);color:var(--text3)\">" + gpEsc(k.creator_name || g.creator_name || "—") + "</td>" +
          "<td><input type=\"number\" class=\"pr-kpi-rating\" data-pr-kpi-name=\"" + gpEsc(k.name) +
            "\" min=\"1\" max=\"5\" step=\"0.5\" value=\"" + gpEsc(rating+"") + "\"" +
            (editable ? "" : " readonly") + "></td>" +
          "<td><textarea class=\"pr-kpi-comment\" data-pr-kpi-name=\"" + gpEsc(k.name) +
            "\" placeholder=\"Comment...\"" + (editable ? "" : " readonly") + ">" +
            gpEsc(comment) + "</textarea></td>" +
          acts(k) +
        "</tr>";
      });
    });
    standalone.forEach(function(k) {
      var savedKpi = (saved.kpis && saved.kpis[k.name]) || {};
      var rating  = savedKpi.self_rating  !== undefined ? savedKpi.self_rating  : (k.self_rating  || "");
      var comment = savedKpi.self_comment !== undefined ? savedKpi.self_comment : (k.self_comment || "");
      var att = k.attainment_pct != null ? parseFloat(k.attainment_pct).toFixed(0) + "%" : "--";
      var color = k.attainment_pct >= 100 ? "var(--green)" : k.attainment_pct >= 70 ? "var(--amber)" : "var(--danger,var(--red))";
      var kPeriod = [k.period_start, k.period_end].filter(Boolean).map(gpFmtDate).join(" – ");
      rows += "<tr>" +
        "<td style=\"font-weight:600\">" + gpEsc(k.kpi_name || k.name) + "</td>" +
        "<td style=\"color:var(--text3);font-style:italic\">Standalone</td>" +
        "<td>" + gpEsc((k.target_value || "--") + (k.unit ? " "+k.unit : "")) + "</td>" +
        "<td>" + gpEsc(k.actual_value || "--") + "</td>" +
        "<td style=\"font-weight:700;color:" + color + "\">" + att + "</td>" +
        "<td style=\"font-size:var(--fs-xs);color:var(--text3);white-space:nowrap\">" + gpEsc(kPeriod || "—") + "</td>" +
        "<td style=\"font-size:var(--fs-xs);color:var(--text3)\">" + gpEsc(k.creator_name || "—") + "</td>" +
        "<td><input type=\"number\" class=\"pr-kpi-rating\" data-pr-kpi-name=\"" + gpEsc(k.name) +
          "\" min=\"1\" max=\"5\" step=\"0.5\" value=\"" + gpEsc(rating+"") + "\"" +
          (editable ? "" : " readonly") + "></td>" +
        "<td><textarea class=\"pr-kpi-comment\" data-pr-kpi-name=\"" + gpEsc(k.name) +
          "\" placeholder=\"Comment...\"" + (editable ? "" : " readonly") + ">" +
          gpEsc(comment) + "</textarea></td>" +
        acts(k) +
      "</tr>";
    });
    document.getElementById("pr-goals-body").innerHTML =
      "<div class=\"pf-scroll\"><table class=\"pr-list-table\"><thead>" + thead + "</thead><tbody>" + rows + "</tbody></table></div>";
  }

  function prKpiRow(k, saved, editable, onRemove) {
    var savedKpi = (saved.kpis && saved.kpis[k.name]) || {};
    var rating  = savedKpi.self_rating  !== undefined ? savedKpi.self_rating  : (k.self_rating  || "");
    var comment = savedKpi.self_comment !== undefined ? savedKpi.self_comment : (k.self_comment || "");
    var att = k.attainment_pct != null ? parseFloat(k.attainment_pct) : null;
    var attStr = att != null ? att.toFixed(0) + "%" : "--";
    var attColor = att == null ? "var(--text3)" : att >= 100 ? "var(--green)" : att >= 70 ? "var(--amber)" : "var(--danger,var(--red))";
    var kpiDateStr = [k.period_start, k.period_end].filter(Boolean).map(gpFmtDate).join(" – ");
    var kpiMeta2 = [];
    if (k.creator_name) kpiMeta2.push("Created by: " + k.creator_name);
    if (kpiDateStr)     kpiMeta2.push(kpiDateStr);
    var nameRow = onRemove
      ? "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:8px\">" +
          "<div class=\"pr-kpi-name\">" + gpEsc(k.kpi_name || k.name) + "</div>" +
          "<button class=\"btn btn-sm\" style=\"font-size:var(--fs-xs);padding:2px 8px;color:var(--danger,var(--red));border:1px solid var(--danger,var(--red));background:none;flex-shrink:0\" onclick=\"" + onRemove + "\">Remove</button>" +
        "</div>"
      : "<div class=\"pr-kpi-name\">" + gpEsc(k.kpi_name || k.name) + "</div>";
    return "<div class=\"pr-kpi-item\">" +
      nameRow +
      "<div class=\"pr-kpi-meta\">" +
        "Target: <strong>" + gpEsc((k.target_value||"--") + (k.unit?" "+k.unit:"")) + "</strong>" +
        " &nbsp;·&nbsp; Actual: <strong>" + gpEsc(k.actual_value||"--") + "</strong>" +
        " &nbsp;·&nbsp; Attainment: <strong style=\"color:" + attColor + "\">" + attStr + "</strong>" +
      "</div>" +
      (kpiMeta2.length ? "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:2px\">" + gpEsc(kpiMeta2.join(" · ")) + "</div>" : "") +
      "<div class=\"pr-kpi-assess\">" +
        "<div class=\"pr-kpi-comment-wrap\"><textarea class=\"pr-kpi-comment\" data-pr-kpi-name=\"" + gpEsc(k.name) +
          "\" placeholder=\"Your comment on this KPI...\"" + (editable ? "" : " readonly") + ">" +
          gpEsc(comment) + "</textarea></div>" +
        "<div class=\"pr-rating-wrap\"><div class=\"pr-rating-lbl\">Self-Rating</div>" +
          "<input type=\"number\" class=\"pr-rating-inp pr-kpi-rating\" data-pr-kpi-name=\"" + gpEsc(k.name) +
          "\" min=\"1\" max=\"5\" step=\"0.5\" value=\"" + gpEsc(rating+"") + "\" placeholder=\"1–5\"" +
          (editable ? "" : " readonly") + "></div>" +
      "</div>" +
    "</div>";
  }

  /* ── Past Development ────────────────────────────── */

  function prRenderPastDevPage(d, saved, editable) {
    var sections = [
      {key:"achievements",     label:"Key Achievements",              placeholder:"What did you accomplish this period? Which goals or milestones are you most proud of?"},
      {key:"challenges",       label:"Challenges Faced",              placeholder:"What obstacles did you encounter? How did you address them?"},
      {key:"development_needs",label:"Development Needs",             placeholder:"Which skills or competencies would you like to strengthen? What gaps have you noticed?"},
      {key:"support_needed",   label:"Support Needed from Manager",   placeholder:"What help, coaching, or resources would you like from your manager or the organisation?"},
    ];
    var html = "<div class=\"pr-page-title\">Past Development</div>" +
      "<div class=\"pr-page-sub\">Reflect on your growth, challenges, and what you need to continue developing.</div>";
    sections.forEach(function(s) {
      html += "<div class=\"pr-stmt-wrap\">" +
        "<label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">" +
          gpEsc(s.label) + "</label>" +
        "<textarea data-pr-field=\"" + s.key + "\" placeholder=\"" + gpEsc(s.placeholder) + "\"" +
          (editable ? "" : " readonly") + " style=\"min-height:100px\">" +
          gpEsc(saved[s.key] || "") + "</textarea>" +
      "</div>";
    });
    document.getElementById("pr-content").innerHTML = html;
  }

  /* ── Future Objectives & KPIs ────────────────────── */

  function prCarryItem(g, carryData, editable, showCycleLabel) {
    _prGoalStore[g.name] = g;
    var cf  = carryData[g.name] || {};
    var pct = g.progress_pct != null ? Math.round(parseFloat(g.progress_pct)) : 0;
    var meta = pct + "% complete";
    if (g.kpis && g.kpis.length) meta += " · " + g.kpis.length + " KPI(s)";
    if (showCycleLabel && g.cycle_label) meta += " · " + g.cycle_label;
    /* This page is a plan for the next period, so there is nothing to edit or
       remove here. "Remove" used to delete the Objective itself, including one
       from an earlier cycle, which took its history with it. Unticking the box
       is the whole of "do not carry this forward" (slice 010 D, decision 19). */
    return "<div class=\"pr-carry-item\" style=\"align-items:flex-start\">" +
      "<input type=\"checkbox\" id=\"pr-carry-" + gpEsc(g.name) + "\" data-pr-carry=\"" + gpEsc(g.name) + "\"" +
        (cf.include ? " checked" : "") + (editable ? "" : " disabled") +
        " style=\"margin-top:3px;flex-shrink:0\">" +
      "<div class=\"pr-carry-label\" style=\"flex:1;min-width:0\">" +
        "<div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">" +
          "<label class=\"pr-carry-name\" for=\"pr-carry-" + gpEsc(g.name) + "\">" + gpEsc(g.goal_name || g.name) + "</label>" +
        "</div>" +
        "<div class=\"pr-carry-meta\">" + gpEsc(meta) + "</div>" +
        (editable
          ? "<textarea class=\"pr-carry-note\" aria-label=\"Note for this objective\" data-pr-carry=\"" + gpEsc(g.name) +
              "\" placeholder=\"What will you do differently or build on?\"" +
              " style=\"margin-top:6px;width:100%;min-height:48px;padding:6px 8px;border:1.5px solid var(--border2);border-radius:var(--r-sm);font-size:var(--fs-sm);font-family:inherit;resize:vertical;background:var(--surface);color:var(--text)\">" +
              gpEsc(cf.note || "") + "</textarea>"
          : (cf.note ? "<div style=\"font-size:var(--fs-sm);color:var(--text2);margin-top:4px\">" + gpEsc(cf.note) + "</div>" : "")) +
      "</div>" +
    "</div>";
  }

  function prRenderFutureObjectivesPage(d, saved, editable) {
    var goals       = d.goals || [];
    var pastGoals   = d.past_incomplete_goals || [];
    var carryData   = saved.carry_forward || {};

    /* Current-cycle goals that are not done */
    var incomplete = goals.filter(function(g) {
      return g.status !== "Completed" && g.status !== "Cancelled";
    });

    var html = "<div class=\"pr-page-title\">Future Objectives &amp; KPIs</div>" +
      "<div class=\"pr-page-sub\">Plan your objectives for the next period. " +
        (editable ? "Select goals to carry forward and add new ones." : "Read-only.") + "</div>";

    /* ── Current-cycle carry-forward ── */
    if (incomplete.length) {
      html += "<div class=\"pr-section-hdr\">Goals to Carry Forward</div>" +
        "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:10px\">" +
          "Objectives from this cycle that are still in progress. Check the ones you want to continue into the next period." +
        "</div>" +
        "<div class=\"pf-card\" style=\"padding:12px 16px;display:flex;flex-direction:column;gap:12px\">";
      incomplete.forEach(function(g) { html += prCarryItem(g, carryData, editable, false); });
      html += "</div>";
    } else {
      html += "<div class=\"pr-section-hdr\">Goals to Carry Forward</div>" +
        "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:10px\">All goals from this cycle are completed or cancelled.</div>";
    }

    /* ── Ongoing goals from previous cycles ── */
    if (pastGoals.length) {
      html += "<div class=\"pr-section-hdr\" style=\"margin-top:20px\">Ongoing Goals from Previous Cycles</div>" +
        "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:10px\">" +
          "These objectives from earlier review periods are still in progress. Select any you want to keep working on." +
        "</div>" +
        "<div class=\"pf-card\" style=\"padding:12px 16px;display:flex;flex-direction:column;gap:12px\">";
      pastGoals.forEach(function(g) { html += prCarryItem(g, carryData, editable, true); });
      html += "</div>";
    }

    /* ── Add new ── */
    var cycleName = d.cycle && (d.cycle.name || d.cycle);
    var newKpis = (d.standalone_kpis || []).filter(function(k) {
      return k.appraisal_cycle === cycleName && k.status !== "Cancelled";
    });

    html += "<div class=\"pr-section-hdr\" style=\"margin-top:20px\">Add New Objectives or KPIs</div>" +
      "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:10px\">" +
        "These are plans for the next period. They are created as live records now and do not join " +
        "the review you are filling in. A new Objective is not tagged to any cycle; for a new KPI, " +
        "choose the cycle it belongs to." +
      "</div>";

    if (editable) {
      html += "<div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px\">" +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"prOpenGoalDialogForReview()\">+ Add Objective</button>" +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"prOpenKpiDialogForReview()\">+ Add KPI</button>" +
        "</div>";
    }

    if (newKpis.length) {
      html += "<div class=\"pf-card\" style=\"padding:12px 16px;display:flex;flex-direction:column;gap:10px\">";
      newKpis.forEach(function(k) {
        html += "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:12px\">" +
          "<div>" +
            "<div style=\"font-weight:500;font-size:var(--fs-base)\">" + gpEsc(k.kpi_name) + "</div>" +
            "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:2px\">" +
              "Target: " + (k.target_value || "—") + (k.unit ? " " + gpEsc(k.unit) : "") +
              (k.category ? " &nbsp;·&nbsp; " + gpEsc(k.category) : "") +
            "</div>" +
          "</div>" +
          (editable
            ? "<div style=\"display:flex;gap:6px;flex-shrink:0\">" +
                "<button class=\"btn btn-outline btn-sm\" onclick=\"pfOpenKpiModal('review'," + gpEsc(JSON.stringify(k)) + ")\">Edit</button>" +
                "<button class=\"btn btn-outline btn-sm\" style=\"color:var(--red)\" onclick=\"prRemoveKpiFromReview(" + gpEsc(JSON.stringify(k.name)) + ")\">Remove</button>" +
              "</div>"
            : "") +
        "</div>";
      });
      html += "</div>";
    } else if (!editable) {
      html += "<div style=\"color:var(--text3);font-size:var(--fs-base)\">No new KPIs added.</div>";
    }

    document.getElementById("pr-content").innerHTML = html;
  }

  /* Open the standard goal creation dialog from within a review;
     after creation, reload review data and re-render the current page. */
  window.prOpenGoalDialogForReview = function() {
    _gpOnGoalCreated = function() {
      _gpOnGoalCreated = null;
      prRefreshCurrentPage();
    };
    /* No cycle: a plan for the next period is never tagged to the cycle under
       review (decision 19, VIS-15, code review minor 1). gpOpenCreateGoal
       leaves the hidden cycle field empty. */
    gpOpenCreateGoal();
  };

  /* Store for goal objects keyed by name — populated during rendering so
     edit buttons can look up full goal data without encoding JSON in onclick. */
  var _prGoalStore = {};

  /* Inside a review, "Edit" changes the review's own copy, never the live
     Objective (slice 010 group D, R2, decision 6). */
  window.prOpenGoalEditForReview = function(rowName) { riOpenEditItem(rowName); };

  window.prOpenKpiDialogForReview = function() {
    window._pfKpiOnSaved = function() { prRefreshCurrentPage(); };
    pfOpenKpiModal("review");
  };

  /* ── Past-objectives / KPI selector ── */

  window.prOpenObjectiveSelector = function() {
    pfSetHtml("pr-sel-list", "<div class=\"sel-empty\">Loading…</div>");
    pfSetHtml("pr-sel-title", "Add / Remove Objectives");
    pfSetHtml("pr-sel-subtitle", "");
    pfOpenModal("pr-sel-modal");
    pf("get_available_for_review", {appraisal: _pr.appraisal}).then(function(data) {
      _prShowSelectorModal("objectives", data);
    }).catch(function() {
      pfSetHtml("pr-sel-list", "<div class=\"sel-empty\">Could not load objectives.</div>");
    });
  };

  window.prOpenKpiSelector = function() {
    pfSetHtml("pr-sel-list", "<div class=\"sel-empty\">Loading…</div>");
    pfSetHtml("pr-sel-title", "Add / Remove KPIs");
    pfSetHtml("pr-sel-subtitle", "");
    pfOpenModal("pr-sel-modal");
    pf("get_available_for_review", {appraisal: _pr.appraisal}).then(function(data) {
      _prShowSelectorModal("kpis", data);
    }).catch(function() {
      pfSetHtml("pr-sel-list", "<div class=\"sel-empty\">Could not load KPIs.</div>");
    });
  };

  function _prShowSelectorModal(type, data) {
    var isObj = type === "objectives";
    var items = isObj ? (data.goals || []) : (data.kpis || []);
    var pFrom = data.period_from || "";
    var pTo   = data.period_to   || "";

    pfSetHtml("pr-sel-title", isObj ? "Add / Remove Objectives" : "Add / Remove KPIs");
    pfSetHtml("pr-sel-subtitle",
      items.length
        ? gpEsc(items.length + " " + (isObj ? "objective" : "KPI") + (items.length !== 1 ? "s" : "") +
          " found between " + pFrom + " and " + pTo)
        : "");
    pfSetHtml("pr-sel-error", "");

    if (!items.length) {
      pfSetHtml("pr-sel-list",
        "<div class=\"sel-empty\">No " + (isObj ? "objectives" : "standalone KPIs") + " found" +
        "<br>between <strong>" + gpEsc(pFrom) + "</strong> and <strong>" + gpEsc(pTo) + "</strong>." +
        "<br><span style=\"font-size:var(--fs-xs)\">Create them from the Goals section first.</span></div>");
    } else {
      var html = items.map(function(item) {
        var label = isObj ? (item.goal_name || item.name) : (item.kpi_name || item.name);
        var dFrom = isObj ? (item.start_date  || "") : (item.period_start || "");
        var dTo   = isObj ? (item.end_date    || "") : (item.period_end   || "");
        var parts = [];
        if (dFrom && dTo) parts.push(dFrom + " – " + dTo);
        if (item.status)  parts.push(item.status);
        if (item.target_value != null) parts.push("Target: " + item.target_value + (item.unit ? " " + item.unit : ""));
        if (!isObj && item.category) parts.push(item.category);
        /* Names, statuses and units come from records other people can write,
           so every one of them is escaped before it reaches the page (SEC-11). */
        return "<label class=\"sel-item\">" +
          "<input type=\"checkbox\" class=\"sel-chk\" value=\"" + gpEsc(item.name) + "\"" + (item.selected ? " checked" : "") + ">" +
          "<div class=\"sel-item-body\">" +
            "<div class=\"sel-item-name\">" + gpEsc(label) + "</div>" +
            (parts.length ? "<div class=\"sel-item-meta\">" + gpEsc(parts.join(" · ")) + "</div>" : "") +
          "</div>" +
        "</label>";
      }).join("");
      pfSetHtml("pr-sel-list", html);
    }

    var btn = document.getElementById("pr-sel-confirm");
    btn.disabled = false;
    btn.textContent = "Confirm";
    btn.onclick = function() {
      var checked = Array.from(document.querySelectorAll("#pr-sel-list .sel-chk:checked")).map(function(el) { return el.value; });
      /* Unticking takes the review's copy out. Whatever was changed for that
         item inside the review is lost, so say so first (slice 010 D, R12). */
      var dropped = items.filter(function(it) { return it.selected && checked.indexOf(it.name) < 0; });
      if (dropped.length && !confirm(
            "Take " + dropped.length + " item" + (dropped.length === 1 ? "" : "s") +
            " out of this review? Anything changed for them inside the review — target, weight, " +
            "period and your rating — will be lost. Their progress and evidence stay on the live record.")) {
        return;
      }
      btn.disabled = true; btn.textContent = "Saving…";
      var args = {appraisal: _pr.appraisal, acknowledge_removal: dropped.length ? 1 : 0};
      if (isObj) args.selected_goals_json = JSON.stringify(checked);
      else       args.selected_kpis_json  = JSON.stringify(checked);
      pf("set_review_selection", args).then(function() {
        pfCloseModal("pr-sel-modal");
        prRefreshCurrentPage();
      }).catch(function(e) {
        pfShowErr("pr-sel-error", (e && e.message) || "Error saving selection.");
        btn.disabled = false; btn.textContent = "Confirm";
      });
    };
  }

  function prRefreshCurrentPage() {
    if (!_pr.appraisal) return;
    pf("get_my_review", {appraisal: _pr.appraisal}).then(function(d) {
      _pr.data.goals                 = d.goals;
      _pr.data.standalone_kpis       = d.standalone_kpis;
      _pr.data.past_incomplete_goals = d.past_incomplete_goals;
      var key      = _pr.pages[_pr.currentIdx] && _pr.pages[_pr.currentIdx].key;
      var editable = _pr.data.review_status === "Not Started" || _pr.data.review_status === "Employee Review";
      var saved    = (_pr.data.page_data && (_pr.data.page_data[key] || {})) || {};
      var isFuture = key === "future-objectives" || key === "future_goals";
      if (isFuture) prRenderFutureObjectivesPage(_pr.data, saved, editable);
      else          prRenderGoalsPage(_pr.data, saved, editable);
    }).catch(function() {});
  }

  /* Taking an item out of a review no longer deletes the Objective or the KPI
     itself (slice 010 group D, R12). Both buttons now open the same dialog. */
  window.prRemoveGoalFromReview = function(rowName) { riOpenRemove(rowName); };
  window.prRemoveKpiFromReview  = function(rowName) { riOpenRemove(rowName); };

  /* ══════════════════════════════════════════════════════════════════
     ri* — the review's own copies (slice 010 group D, commit 11)

     Every item on a review screen is a copy that belongs to the review, not
     the live Objective or KPI. Its row name is the key everywhere here. These
     functions change the copy: its definition, its rating, whether it is in
     the review at all, and the answer to a rating question. Nothing here
     writes a live record.
     ══════════════════════════════════════════════════════════════════ */

  /* Every copy on the screen now, by row name. Filled while rendering. */
  var _riItems = {};

  window.riIndex = function(items) {
    (items || []).forEach(function(it) {
      _riItems[it.name] = it;
      (it.kpis || []).forEach(function(k) { _riItems[k.name] = k; });
    });
  };

  function riItem(rowName) { return _riItems[rowName] || null; }

  /* Who may change items, and when (decisions 6, 29). The server decides; the
     page only hides what would be refused. */
  function riCanEditDefinition() {
    var st = (_pr.data && _pr.data.review_status) || "Not Started";
    if (_pr.viewerRole) return _pr.viewerRole === "manager" && st === "Manager Review";
    return st === "Not Started" || st === "Employee Review";
  }

  function riCanRemove() {
    var st = (_pr.data && _pr.data.review_status) || "Not Started";
    if (_pr.viewerRole === "manager") return st === "Manager Review";
    if (_pr.viewerRole === "hr")      return st === "HR Review";
    return st === "Not Started" || st === "Employee Review";
  }

  function riCanRateAsManager() {
    return _pr.viewerRole === "manager" && _pr.data && _pr.data.review_status === "Manager Review";
  }

  /* A reason is required of everyone except the person whose review it is. */
  function riReasonRequired() { return !!_pr.viewerRole; }

  /* ── Change a definition inside the review (R2, decision 6) ── */

  window.riOpenEditItem = function(rowName) {
    var it = riItem(rowName);
    if (!it) return;
    pfClearErr("ri-edit-error");
    document.getElementById("ri-edit-row").value = rowName;
    document.getElementById("ri-edit-title").value  = it.title || it.goal_name || it.kpi_name || "";
    document.getElementById("ri-edit-target").value = it.target_value != null ? it.target_value : "";
    document.getElementById("ri-edit-weight").value = it.weightage != null ? it.weightage : "";
    document.getElementById("ri-edit-from").value   = it.period_start || it.start_date || "";
    document.getElementById("ri-edit-to").value     = it.period_end   || it.end_date   || "";
    pfSetHtml("ri-edit-sub", gpEsc(it.title || it.goal_name || it.kpi_name || ""));
    pfOpenModal("ri-edit-modal");
  };

  window.riSaveEditItem = function() {
    var btn = document.getElementById("ri-edit-save");
    var title = (pfVal("ri-edit-title") || "").trim();
    if (!title) { pfShowErr("ri-edit-error", "Give the item a name."); return; }
    btn.disabled = true; btn.textContent = "Saving…";
    pf("save_review_item_definition", {
      appraisal:    _pr.appraisal,
      row:          pfVal("ri-edit-row"),
      title:        title,
      target_value: pfVal("ri-edit-target"),
      weightage:    pfVal("ri-edit-weight"),
      period_start: pfVal("ri-edit-from"),
      period_end:   pfVal("ri-edit-to"),
    }).then(function() {
      pfCloseModal("ri-edit-modal");
      riReload();
    }).catch(function(e) {
      pfShowErr("ri-edit-error", (e && e.message) || "The change could not be saved.");
    }).finally(function() { btn.disabled = false; btn.textContent = "Save change"; });
  };

  /* ── Take an item out of the review (R12, decisions 9, 10, 29) ── */

  window.riOpenRemove = function(rowName) {
    var it = riItem(rowName);
    if (!it) return;
    var title = it.title || it.goal_name || it.kpi_name || "this item";
    var mine  = !_pr.viewerRole;
    var deletable = !!it.added_in_review && mine;
    pfClearErr("ri-remove-error");
    document.getElementById("ri-remove-row").value = rowName;
    document.getElementById("ri-remove-mode").value = "remove";
    pfSetHtml("ri-remove-title", "Remove “" + gpEsc(title) + "” from this review?");
    pfSetHtml("ri-remove-warning",
      "Anything changed for it inside this review — its target, weight, period and " +
      (mine ? "your rating" : "the ratings") + " — will be lost. " +
      "Its progress and evidence stay on the live record, which is not deleted." +
      (deletable
        ? "<div style=\"margin-top:8px\">This item was created inside the review. " +
          "<a href=\"#\" onclick=\"riSwitchToDelete();return false;\">Delete the Objective or KPI itself instead</a>.</div>"
        : ""));
    var req = riReasonRequired();
    pfSetHtml("ri-remove-reason-req", req ? "(required)" : "(optional)");
    document.getElementById("ri-remove-reason").value = "";
    /* "Delete instead" hides the reason box; a cancelled dialog must not leave
       it hidden for the next item (code review minor 8). */
    document.getElementById("ri-remove-reason-field").style.display = "";
    pfOpenModal("ri-remove-modal");
  };

  window.riSwitchToDelete = function() {
    document.getElementById("ri-remove-mode").value = "delete";
    pfSetHtml("ri-remove-title", "Delete this Objective or KPI?");
    pfSetHtml("ri-remove-warning",
      "This deletes the record itself, not only its place in the review. It can only be done " +
      "for something created inside this review that has no progress, evidence or rating.");
    document.getElementById("ri-remove-reason-field").style.display = "none";
  };

  window.riConfirmRemove = function() {
    var btn = document.getElementById("ri-remove-confirm");
    var row = pfVal("ri-remove-row");
    var del = pfVal("ri-remove-mode") === "delete";
    var reason = (pfVal("ri-remove-reason") || "").trim();
    if (!del && riReasonRequired() && !reason) {
      pfShowErr("ri-remove-error", "Say why this item is being removed. The employee will see the reason.");
      return;
    }
    btn.disabled = true; btn.textContent = "Working…";
    var call = del
      ? pf("delete_review_item", {appraisal: _pr.appraisal, row: row, acknowledge: 1})
      : pf("remove_review_item", {appraisal: _pr.appraisal, row: row, reason: reason, acknowledge: 1});
    call.then(function() {
      pfCloseModal("ri-remove-modal");
      document.getElementById("ri-remove-reason-field").style.display = "";
      riReload();
    }).catch(function(e) {
      pfShowErr("ri-remove-error", (e && e.message) || "The item could not be removed.");
    }).finally(function() { btn.disabled = false; btn.textContent = "Remove it"; });
  };

  /* ── Rate one item, on its copy (VIS-6, R13) ── */

  window.riSaveItemRating = function(rowName) {
    var rating  = document.getElementById("ri-r-" + rowName);
    var comment = document.getElementById("ri-c-" + rowName);
    var pot     = document.getElementById("ri-p-" + rowName);
    var msg     = document.getElementById("ri-msg-" + rowName);
    var args = {appraisal: _pr.appraisal, row: rowName,
                rating: rating ? rating.value : "", comment: comment ? comment.value : ""};
    if (pot && pot.value !== "") args.potential_rating = pot.value;
    if (msg) msg.textContent = "Saving…";
    pf("save_review_item_rating", args).then(function() {
      if (msg) { msg.textContent = "Saved"; setTimeout(function() { if (msg) msg.textContent = ""; }, 2000); }
    }).catch(function(e) {
      if (msg) msg.textContent = (e && e.message) || "Could not save this rating.";
    });
  };

  /* Fill empty manager ratings from measured attainment on the copies. */
  window.riSuggestRatings = function() {
    if (!_pr.data) return;
    pf("suggest_ratings", {employee: _pr.data.employee, cycle: _pr.data.cycle && _pr.data.cycle.name})
      .then(function(rows) {
        (rows || []).forEach(function(r) {
          var el = document.getElementById("ri-r-" + r.item);
          if (el && !el.value) el.value = r.suggested_rating;
        });
        gpShowToast("Empty ratings filled from measured attainment. Check each one, then save it.");
      }).catch(function(e) { gpShowToast((e && e.message) || "Could not suggest ratings.", "error"); });
  };

  /* ── A rating given on numbers that changed since (R7, decisions 12, 13) ── */

  /* mode is what the server said this person may do with this question in this
     view: "rater" (their own rating) or "hr" (HR answering for someone who has
     left, with a reason). Decisions 12, 34, 37. */
  window.riAnswerFlag = function(target, keep, mode) {
    var rating = "";
    if (!keep) {
      var el = document.getElementById("ri-r-" + target);
      rating = el ? el.value : "";
      if (target === "overall") {
        var ov = document.getElementById("mgr-overall-rating") || document.getElementById("hr-flag-overall-rating");
        rating = ov ? ov.value : "";
      }
      if (!rating) { gpShowToast("Choose the new rating first, then say it has changed.", "error"); return; }
    }
    var reason = "";
    if (mode === "hr") {
      reason = prompt("Why is HR answering for this rating?") || "";
      if (!reason.trim()) return;
    }
    pf("answer_rating_flag", {appraisal: _pr.appraisal, target: target, view: _pr.viewerRole,
                              keep: keep ? 1 : 0, rating: rating, reason: reason})
      .then(function() { riReload(); })
      .catch(function(e) { gpShowToast((e && e.message) || "The answer could not be saved.", "error"); });
  };

  /* ── Shared bits of markup ── */

  /* "In review · updates dated after 30 Sep 2026 don't change it" (R5).
     No review name, no rating, no link: everyone who sees the record sees it. */
  window.riReviewBadge = function(badge) {
    if (!badge || !badge.in_review) return "";
    var text = badge.updates_after
      ? "In review · updates dated after " + gpFmtDate(badge.updates_after) + " don't change it"
      : "In review";
    return "<span class=\"tv-incycle\" title=\"" + gpEsc(text) + "\">" + gpEsc(text) + "</span>";
  };

  /* What changed inside the review, in words, never colour alone. */
  function riChangeNote(it) {
    var changed = it && it.definition_changed;
    if (!changed) return "";
    var labels = {title: "name", target_value: "target", weightage: "weight",
                  period_start: "period start", period_end: "period end"};
    var parts = Object.keys(changed).map(function(f) { return labels[f] || f; });
    if (!parts.length) return "";
    return "<div style=\"font-size:var(--fs-xs);color:var(--amber);margin-top:3px\">" +
      "<i class=ic-edit></i> Changed in this review: " + gpEsc(parts.join(", ")) + "</div>";
  }

  /* A rating question on this item, for the manager and HR (R7). */
  function riFlagNote(it) {
    if (!it || !_pr.viewerRole) return "";
    var out = "";
    if (it.self_flag) {
      out += "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:3px\">" +
        "<i class=ic-info></i> The employee rated this before the numbers changed. " +
        "This is for information: it does not block the review.</div>";
    }
    if (it.manager_flag) {
      var mode = it.flag_answer === "rater" || it.flag_answer === "hr" ? it.flag_answer : "";
      out += "<div style=\"font-size:var(--fs-xs);color:var(--amber);margin-top:4px\">" +
        "<i class=ic-alert></i> This rating was given when the numbers were different. " +
        "It is now " + gpEsc(pfNum(it.actual_value, 2) + " of " + pfNum(it.target_value, 2)) + ". " +
        (mode
          ? "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs);padding:2px 8px;margin-left:6px\" " +
              "onclick=\"riAnswerFlag('" + gpEsc(it.name) + "',1,'" + mode + "')\">Keep the rating</button> " +
            "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs);padding:2px 8px\" " +
              "onclick=\"riAnswerFlag('" + gpEsc(it.name) + "',0,'" + mode + "')\">Use the rating I typed</button>"
          : "The person who gave this rating must keep or change it.") +
        "</div>";
    }
    return out;
  }

  /* The manager's rating box for one copy. */
  function riManagerRatingHtml(it) {
    if (!_pr.viewerRole) return "";
    var can = riCanRateAsManager();
    var rating = it.manager_rating != null ? it.manager_rating : "";
    var comment = it.manager_comment || "";
    var pot = it.potential_rating != null ? it.potential_rating : "";
    return "<div class=\"pr-kpi-assess\" style=\"margin-top:8px\">" +
      "<div class=\"pr-kpi-comment-wrap\">" +
        "<label class=\"pr-rating-lbl\" for=\"ri-c-" + gpEsc(it.name) + "\">Manager comment</label>" +
        "<textarea id=\"ri-c-" + gpEsc(it.name) + "\" class=\"pr-kpi-comment\" " +
          "placeholder=\"Your comment on this item…\"" + (can ? "" : " readonly") + ">" + gpEsc(comment) + "</textarea>" +
      "</div>" +
      "<div class=\"pr-rating-wrap\">" +
        "<label class=\"pr-rating-lbl\" for=\"ri-r-" + gpEsc(it.name) + "\">Manager rating</label>" +
        "<input id=\"ri-r-" + gpEsc(it.name) + "\" type=\"number\" class=\"pr-rating-inp\" min=\"1\" max=\"5\" step=\"0.5\" " +
          "value=\"" + gpEsc(rating + "") + "\" placeholder=\"1–5\"" + (can ? "" : " readonly") + ">" +
      "</div>" +
      "<div class=\"pr-rating-wrap\">" +
        "<label class=\"pr-rating-lbl\" for=\"ri-p-" + gpEsc(it.name) + "\">Potential</label>" +
        "<input id=\"ri-p-" + gpEsc(it.name) + "\" type=\"number\" class=\"pr-rating-inp\" min=\"1\" max=\"5\" step=\"0.5\" " +
          "value=\"" + gpEsc(pot + "") + "\" placeholder=\"1–5\"" + (can ? "" : " readonly") + ">" +
      "</div>" +
      (can
        ? "<div style=\"display:flex;align-items:center;gap:8px;margin-top:4px\">" +
            "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs)\" " +
              "onclick=\"riSaveItemRating('" + gpEsc(it.name) + "')\">Save rating</button>" +
            "<span id=\"ri-msg-" + gpEsc(it.name) + "\" style=\"font-size:var(--fs-xs);color:var(--text3)\"></span>" +
          "</div>"
        : "") +
      riFlagNote(it) +
      riFactsNote(it) +
    "</div>";
  }

  /* For HR only, as the server sends it: facts approved after this review's
     numbers closed (R10), and evidence with no date of its own, dated by its
     upload (decision 5). Code review minor 2. */
  function riFactsNote(it) {
    if (!it || _pr.viewerRole !== "hr") return "";
    var out = "";
    var late = it.late_facts;
    if (late && late.count) {
      out += "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:4px\">" +
        "<i class=ic-info></i> " + gpEsc(late.count + (late.count === 1 ? " update arrived" : " updates arrived")) +
        " after this review's numbers closed. With them the number would be " + gpEsc(pfNum(late.actual_with_late, 2)) +
        ". They do not change this review.</div>";
    }
    var byUpload = parseInt(it.facts_dated_by_upload || 0, 10) || 0;
    if (byUpload) {
      out += "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:4px\">" +
        "<i class=ic-info></i> " + gpEsc(byUpload + (byUpload === 1 ? " piece of evidence had" : " pieces of evidence had")) +
        " no date of its own, so it was dated by when it was uploaded.</div>";
    }
    return out;
  }

  /* Edit and Remove for one copy, shown only when the server would allow it. */
  function riItemActions(it) {
    var html = "";
    if (riCanEditDefinition()) {
      html += "<button class=\"tv-icon\" title=\"Change this item in the review\" " +
        "onclick=\"event.stopPropagation();riOpenEditItem('" + gpEsc(it.name) + "')\">" + TV_ICON.edit + "</button>";
    }
    if (riCanRemove()) {
      html += "<button class=\"tv-icon tv-danger\" title=\"Remove from this review\" " +
        "onclick=\"event.stopPropagation();riOpenRemove('" + gpEsc(it.name) + "')\">" + TV_ICON.del + "</button>";
    }
    return html ? "<div class=\"tv-acts\" style=\"opacity:1;display:flex;gap:4px\">" + html + "</div>" : "";
  }

  /* Items taken out of this review, struck through with who, when and why. */
  window.riRemovedHtml = function(d) {
    var rows = (d && d.removed_items) || [];
    if (!rows.length) return "";
    var items = rows.map(function(r) {
      var who = r.removed_by ? " by " + gpEsc(r.removed_by) : "";
      var when = r.removed_on ? " on " + gpFmtDate(r.removed_on) : "";
      return "<div style=\"padding:8px 0;border-bottom:1px solid var(--border);font-size:var(--fs-sm)\">" +
        "<span style=\"text-decoration:line-through;color:var(--text3)\">" + gpEsc(r.title || r.name) + "</span> " +
        "<span class=\"tv-badge\" style=\"background:var(--surface2);color:var(--text2)\">Removed</span>" +
        "<div style=\"color:var(--text3);margin-top:2px\">Removed" + who + when +
          (r.removal_reason ? ": " + gpEsc(r.removal_reason) : ". No reason was given.") + "</div>" +
      "</div>";
    }).join("");
    return "<div class=\"pr-section-hdr\" style=\"margin-top:20px\">Taken out of this review</div>" +
      "<div class=\"pf-card\" style=\"padding:4px 16px\">" + items + "</div>";
  };

  /* The numbers are closed; and, for HR, what cannot be finished yet. */
  window.riReviewNotesHtml = function(d) {
    var html = "";
    /* Items tagged to this cycle after the copies were taken are not added
       behind the person's back (00d section 2.4, code review minor 3). */
    var missing = parseInt((d && d.not_in_review_count) || 0, 10) || 0;
    if (missing && !_pr.viewerRole) {
      html += "<div class=\"callout\" style=\"margin-bottom:12px\">" +
        gpEsc(missing + (missing === 1 ? " item in this cycle is" : " items in this cycle are")) +
        " not in your review. Use Add/remove Objectives or Add/remove KPIs to add them if they belong here.</div>";
    }
    if (d && d.numbers_frozen) {
      html += "<div class=\"callout\" style=\"margin-bottom:12px\">The numbers in this review are closed. " +
        "Later updates to the live records do not change them.</div>";
    }
    var open = parseInt((d && d.open_blocking_flags) || 0, 10) || 0;
    if (open) {
      html += "<div class=\"callout callout-warn\" style=\"margin-bottom:12px\">" +
        gpEsc(open + (open === 1 ? " rating was" : " ratings were")) +
        " given on numbers that changed since. They must be kept or changed before this review can be completed." +
      "</div>";
    }
    return html;
  };

  /* Reload the review after a change, whichever screen is open. */
  function riReload() {
    if (_pr.viewerRole) {
      pf("get_manager_review", {appraisal: _pr.appraisal, view: _pr.viewerRole}).then(function(d) {
        _pr.data = d;
        prShowPage(_pr.currentIdx);
      }).catch(function(e) { gpShowToast((e && e.message) || "Could not reload the review.", "error"); });
    } else {
      prRefreshCurrentPage();
    }
  }

  /* ── Future Development Plan ─────────────────────── */

  function prRenderFutureDevPage(d, saved, editable) {
    var sections = [
      {key:"development_goals", label:"Development Goals for Next Period", placeholder:"What skills, behaviours, or competencies do you want to develop? What does success look like?"},
      {key:"training_needs",    label:"Training & Learning Needs",         placeholder:"What specific training, courses, or experiences would help you achieve these development goals?"},
    ];
    var html = "<div class=\"pr-page-title\">Future Development Plan</div>" +
      "<div class=\"pr-page-sub\">Set your learning and growth intentions for the next review period.</div>";
    sections.forEach(function(s) {
      html += "<div class=\"pr-stmt-wrap\">" +
        "<label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">" + gpEsc(s.label) + "</label>" +
        "<textarea data-pr-field=\"" + s.key + "\" placeholder=\"" + gpEsc(s.placeholder) + "\"" +
          (editable ? "" : " readonly") + " style=\"min-height:120px\">" +
          gpEsc(saved[s.key] || "") + "</textarea>" +
      "</div>";
    });
    document.getElementById("pr-content").innerHTML = html;
  }

  /* ── Manager Feedback (read-only placeholder for employee) ── */

  function prRenderManagerFeedbackPlaceholder() {
    document.getElementById("pr-content").innerHTML =
      "<div class=\"pr-page-title\">Manager's Feedback</div>" +
      "<div class=\"pr-page-sub\">This section is completed by your manager after you submit your self-review.</div>" +
      "<div style=\"background:var(--surface2);border:1.5px solid var(--border);border-radius:var(--r);padding:32px;text-align:center;color:var(--text3);margin-top:16px\">" +
        "<svg width=\"40\" height=\"40\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" style=\"margin-bottom:12px;opacity:.4\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75\"/></svg>" +
        "<div style=\"font-size:var(--fs-base);font-weight:600;color:var(--text2)\">Manager reviews this section</div>" +
        "<div style=\"font-size:var(--fs-base);margin-top:6px\">Once you submit your self-review, your manager will complete this section before the discussion meeting.</div>" +
      "</div>";
  }

  /* ── Manager Review: open review panel in manager mode ──── */

  /* view is the list the review is opened from: "manager" from My team's
     reviews, "hr" from the HR review list. The screen follows it, and the
     server checks the caller's right for it (decision 37). */
  window.prOpenManagerReview = function(appraisalName, employeeName, view) {
    switchPanel("pms-review");
    var content = document.getElementById("pr-content");
    if (content) content.innerHTML = "<div style=\"text-align:center;padding:40px;color:var(--text3)\">Loading review...</div>";
    document.getElementById("pr-nav").innerHTML = "";
    /* The warning belongs to one review. Clear it before loading the next,
       so a review that fails to load cannot show the last one's banner. */
    var _mp = document.getElementById("pr-missing-pages");
    if (_mp) { _mp.innerHTML = ""; _mp.style.display = "none"; }
    /* A picker answer belongs to one review only (code review M4). */
    _prEmpCache = null;
    pf("get_manager_review", {appraisal: appraisalName, view: view}).then(function(d) {
      _pr.appraisal = appraisalName;
      _pr.data = d;
      _pr.viewerRole = d.viewer_role; // "manager" or "hr": the view it was opened in
      _pr.currentIdx = 0;
      _pr.viewMode = "hierarchical";
      _pr.draftGoals = [];
      _pr.draftKpis  = [];
      /* Build page list: employee pages (read-only) + manager feedback + submit */
      var rawCfg = d.page_config || {};
      var cfgArr;
      if (Array.isArray(rawCfg)) {
        cfgArr = rawCfg;
      } else if (typeof rawCfg === "object") {
        cfgArr = Object.keys(rawCfg)
          .filter(function(k) { return rawCfg[k]; })
          .map(function(k) { return {key: k}; });
      } else { cfgArr = []; }
      var _MF_SKIP = {
        "manager-feedback": true, "manager-feedback-form": true,
        "manager-submit": true, "employee-pre-review": true, "pages": true
      };
      var pages = [];
      cfgArr.forEach(function(p) {
        if (p.enabled === false) return;
        var key = p.key || p;
        if (_MF_SKIP[key]) return;
        var meta = _PR_PAGE_META[key] || {};
        var customLabel = d.page_settings && d.page_settings[key] && d.page_settings[key].page_label;
        pages.push({key: key, label: customLabel || p.label || meta.label || key});
      });
      prShowMissingPagesWarning(d, pages.length);
      pages.push({key: "employee-pre-review", label: "Feedback for Reporting Manager"});
      pages.push({key: "manager-feedback-form", label: "Manager Feedback"});
      pages.push({key: "manager-submit", label: "Rate & Submit"});
      _pr.pages = pages;
      document.getElementById("pr-title").textContent =
        (d.viewer_role === "hr" ? "HR Review — " : "Manager Review — ") + (employeeName || d.employee_name || "");
      document.getElementById("pr-sub").textContent =
        (d.cycle && d.cycle.cycle_name ? d.cycle.cycle_name : "") +
        (d.employee_name ? " · " + d.employee_name : "");
      prUpdateStageBar(d.review_status);
      prBuildNav();
      prShowPage(0);
    }).catch(function(e) {
      if (content) content.innerHTML = "<div style=\"color:var(--danger,var(--red));padding:20px\">" + gpEsc(e.message || "Failed to load review.") + "</div>";
    });
  };

  /* ── Manager writes feedback + manages invited reviewers ──── */

  function prRenderManagerFeedbackForm(d, editable) {
    var feedback = d.manager_feedback || "";
    var internalNotes = d.manager_internal_notes || "";
    var invited = d.invited_reviewers || [];
    var reviewerRows = "";
    invited.forEach(function(r) {
      var statusCls = r.status === "Submitted" ? "color:var(--green)" : "color:var(--amber)";
      var pages = r.allowed_pages && r.allowed_pages.length ? r.allowed_pages.join(", ") : "Overall only";
      var pagesLabel = "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:2px\">Pages: " + gpEsc(pages) + "</div>";
      var commentsHtml = "";
      if (r.status === "Submitted") {
        if (r.comments) {
          commentsHtml += "<div style=\"background:var(--surface2);border-radius:var(--r-sm);padding:8px 10px;margin-top:6px;color:var(--text2);font-size:var(--fs-sm)\"><strong>Overall:</strong> " + gpEsc(r.comments) + "</div>";
        }
        var pc = r.page_comments || {};
        Object.keys(pc).forEach(function(pk) {
          if (pc[pk]) {
            commentsHtml += "<div style=\"background:var(--surface2);border-radius:var(--r-sm);padding:8px 10px;margin-top:4px;color:var(--text2);font-size:var(--fs-sm)\"><strong>" + gpEsc(pk) + ":</strong> " + gpEsc(pc[pk]) + "</div>";
          }
        });
      }
      reviewerRows += "<div style=\"padding:10px 0;border-bottom:1px solid var(--border);font-size:var(--fs-base)\">" +
        "<div style=\"display:flex;justify-content:space-between;align-items:flex-start\">" +
          "<div><strong>" + gpEsc(r.employee_name || r.employee) + "</strong>" + pagesLabel + "</div>" +
          "<span style=\"" + statusCls + ";font-size:var(--fs-sm);flex-shrink:0;margin-left:8px\">" + gpEsc(r.status) + "</span>" +
        "</div>" +
        commentsHtml +
      "</div>";
    });
    var html = "<div class=\"pr-page-title\">Manager Feedback</div>" +
      "<div class=\"pr-page-sub\">Write feedback for the employee and manage invited reviewers. Internal notes are never shown to the employee.</div>" +
      "<div class=\"pr-stmt-wrap\">" +
        "<label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Feedback for Employee</label>" +
        "<textarea id=\"mgr-feedback-ta\" placeholder=\"Write feedback for the employee…\" style=\"min-height:160px\">" + gpEsc(feedback) + "</textarea>" +
      "</div>" +
      "<div class=\"pr-stmt-wrap\" style=\"margin-top:16px\">" +
        "<label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\"><i class=ic-lock></i> Internal Notes (not shown to employee)</label>" +
        "<textarea id=\"mgr-notes-ta\" placeholder=\"Private notes for your own reference…\" style=\"min-height:100px\">" + gpEsc(internalNotes) + "</textarea>" +
      "</div>" +
      "<div style=\"margin-top:20px\">" +
        "<div style=\"font-size:var(--fs-base);font-weight:700;color:var(--text2);margin-bottom:10px\">Invited Reviewers</div>" +
        (reviewerRows || "<div style=\"color:var(--text3);font-size:var(--fs-base)\">No reviewers invited yet.</div>") +
        "<div style=\"margin-top:14px;border-top:1px solid var(--border);padding-top:14px\">" +
          "<div style=\"font-size:var(--fs-xs);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:10px\">Add Reviewers</div>" +
          "<div style=\"position:relative\" id=\"mgr-invite-wrap\">" +
            "<input type=\"text\" id=\"mgr-invite-search\" autocomplete=\"off\" placeholder=\"Search by name…\" " +
              "style=\"width:100%;padding:7px 10px;border:1.5px solid var(--border);border-radius:var(--r-sm);background:var(--surface);box-sizing:border-box\" " +
              "oninput=\"prFilterReviewerList()\" onfocus=\"prOpenReviewerList()\" onblur=\"setTimeout(prCloseReviewerList,180)\">" +
            "<input type=\"hidden\" id=\"mgr-invite-emp-id\">" +
            "<div id=\"mgr-invite-list\" style=\"display:none;position:absolute;top:calc(100% + 4px);left:0;right:0;" +
              "background:var(--surface);border:1.5px solid var(--border2);border-radius:var(--r);" +
              "box-shadow:var(--sh3);max-height:240px;overflow-y:auto;z-index:1400\"></div>" +
          "</div>" +
          prGetInvitePageOptionsHtml() +
          "<div style=\"margin-top:10px;text-align:right\">" +
            "<button class=\"btn btn-outline btn-sm\" onclick=\"prAddToPending()\">+ Add to List</button>" +
          "</div>" +
          "<div id=\"mgr-pending-list\"></div>" +
          "<div style=\"display:flex;justify-content:space-between;align-items:center;margin-top:10px\">" +
            "<div id=\"mgr-invite-msg\" style=\"font-size:var(--fs-sm)\"></div>" +
            "<button id=\"mgr-send-invites\" class=\"btn btn-primary btn-sm\" onclick=\"prSendAllInvites()\" style=\"display:none\">Send All Invites</button>" +
          "</div>" +
        "</div>" +
      "</div>" +
      "<div style=\"margin-top:16px;text-align:right\">" +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"prSaveManagerDraft()\">Save Draft</button>" +
      "</div>";
    document.getElementById("pr-content").innerHTML = html;
    var nextBtn = document.getElementById("pr-next-btn");
    if (nextBtn) nextBtn.style.display = "";
  }

  function prRenderEmployeePreReview(d, saved, editable) {
    var principles = [
      {icon: "<i class=ic-award></i>", title: "Customer Obsession",        desc: "Put the customer first in every decision and interaction."},
      {icon: "<i class=ic-bulb></i>", title: "Innovation & Disruption",   desc: "Challenge the status quo and constantly seek better ways of working."},
      {icon: "<i class=ic-handshake></i>", title: "Integrity & Trust",         desc: "Act with honesty and transparency in all that we do."},
      {icon: "<i class=ic-target></i>", title: "Ownership & Accountability",desc: "Take full responsibility for outcomes, not just actions."},
      {icon: "<i class=ic-leaf></i>", title: "Collaboration & Inclusion", desc: "Achieve more by working together and embracing diverse perspectives."},
      {icon: "<i class=ic-trend></i>", title: "Growth Mindset",            desc: "Embrace learning, welcome feedback, and pursue continuous improvement."},
      {icon: "<i class=ic-award></i>", title: "Excellence in Execution",   desc: "Deliver high-quality work with precision, care, and consistency."},
    ];
    var pHtml = principles.map(function(p) {
      return "<div style=\"display:flex;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)\">" +
        "<span style=\"font-size:var(--fs-lg);flex-shrink:0;margin-top:2px\">" + p.icon + "</span>" +
        "<div>" +
          "<div style=\"font-size:var(--fs-base);font-weight:700;color:var(--text1)\">" + gpEsc(p.title) + "</div>" +
          "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-top:3px;line-height:1.5\">" + gpEsc(p.desc) + "</div>" +
        "</div>" +
      "</div>";
    }).join("");
    var savedComments = (saved && saved.overall_comments) || "";
    var commentSection;
    if (editable) {
      commentSection =
        "<div class=\"pr-stmt-wrap\" style=\"margin-top:20px\">" +
          "<label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Your overall comments for your manager</label>" +
          "<textarea data-pr-field=\"overall_comments\" placeholder=\"Share any context you want your manager to consider — key achievements, challenges, growth areas, or anything else on your mind…\" style=\"min-height:140px\">" + gpEsc(savedComments) + "</textarea>" +
          "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:6px\">Shared with your reporting manager before they write their assessment.</div>" +
        "</div>";
    } else {
      commentSection =
        "<div style=\"margin-top:20px\">" +
          "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Employee’s overall comments</div>" +
          (savedComments
            ? "<div style=\"background:var(--surface2);border-radius:var(--r);padding:14px 16px;font-size:var(--fs-base);color:var(--text2);line-height:1.6\">" + gpEsc(savedComments) + "</div>"
            : "<div style=\"color:var(--text3);font-size:var(--fs-base);font-style:italic\">No overall comments submitted by the employee.</div>") +
        "</div>";
    }
    var html =
      "<div class=\"pr-page-title\">Feedback for Reporting Manager</div>" +
      "<div class=\"pr-page-sub\">These are the leadership principles used when assessing performance and potential. " + (editable ? "Review them, then share any context you want your manager to consider." : "The employee's overall comments are shown below.") + "</div>" +
      "<div style=\"margin-top:20px\">" +
        "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:2px\">Leadership Principles</div>" +
        "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-bottom:10px\">Read only — for context</div>" +
        "<div style=\"border:1px solid var(--border);border-radius:var(--r);padding:0 16px\">" + pHtml + "</div>" +
      "</div>" +
      commentSection;
    document.getElementById("pr-content").innerHTML = html;
  }

  /* The reviewer picker asks the server as the person types (code review M4).
     It used to load the first 50 names once, with an empty search, and filter
     them in the browser, so most of a large company could never be found, and
     a second review opened later still showed the first review's company.
     Naming the review makes the search run in the reviewed person's company
     (SEC-7). The last answer is kept only for the review it was asked for. */
  var _prEmpCache = null;
  var _prEmpTimer = null;

  window.prOpenReviewerList = function() { prFilterReviewerList(); };

  window.prFilterReviewerList = function() {
    var inp = document.getElementById("mgr-invite-search");
    var list = document.getElementById("mgr-invite-list");
    if (!inp || !list) return;
    var q = inp.value.trim();
    if (_prEmpTimer) clearTimeout(_prEmpTimer);
    if (q.length < 2) {
      list.innerHTML = "<div style=\"padding:10px 14px;font-size:var(--fs-base);color:var(--text3)\">Type at least 2 letters of a name or employee ID.</div>";
      list.style.display = "";
      return;
    }
    var forReview = _pr.appraisal;
    _prEmpTimer = setTimeout(function() {
      pf("search_employees", {query: q, appraisal: forReview}).then(function(rows) {
        /* An answer for an older search or another review is dropped. */
        if (forReview !== _pr.appraisal || inp.value.trim() !== q) return;
        _prEmpCache = {appraisal: forReview, query: q, rows: rows || []};
        prRenderReviewerMatches(list, _prEmpCache.rows);
      }).catch(function(err) {
        list.innerHTML = "<div style=\"padding:10px 14px;font-size:var(--fs-base);color:var(--text3)\">" +
          gpEsc((err && err.message) || "The search did not work. Try again.") + "</div>";
        list.style.display = "";
      });
    }, 300);
  };

  function prRenderReviewerMatches(list, matches) {
    if (!matches.length) {
      list.innerHTML = "<div style=\"padding:10px 14px;font-size:var(--fs-base);color:var(--text3)\">No employees found.</div>";
    } else {
      list.innerHTML = matches.map(function(e) {
        var meta = [e.designation, e.department].filter(Boolean).join(" · ");
        return "<div class=\"pr-rev-opt\" data-id=\"" + gpEsc(e.name) + "\" data-name=\"" + gpEsc(e.employee_name) + "\" " +
          "style=\"padding:9px 14px;border-bottom:1px solid var(--border);cursor:pointer;font-size:var(--fs-base)\">" +
          "<div style=\"font-weight:600\">" + gpEsc(e.employee_name) + "</div>" +
          (meta ? "<div style=\"font-size:var(--fs-xs);color:var(--text3);pointer-events:none\">" + gpEsc(meta) + "</div>" : "") +
          "</div>";
      }).join("");
      list.onmousedown = function(evt) {
        var row = evt.target.closest(".pr-rev-opt");
        if (row) prSelectReviewer(row.getAttribute("data-id"), row.getAttribute("data-name"));
      };
    }
    list.style.display = "";
  }

  window.prSelectReviewer = function(empId, empName) {
    var inp = document.getElementById("mgr-invite-search");
    var hidden = document.getElementById("mgr-invite-emp-id");
    var list = document.getElementById("mgr-invite-list");
    if (inp) inp.value = empName;
    if (hidden) hidden.value = empId;
    if (list) list.style.display = "none";
  };

  window.prCloseReviewerList = function() {
    var list = document.getElementById("mgr-invite-list");
    if (list) list.style.display = "none";
  };

  window.prSaveManagerDraft = function() {
    var feedback = (document.getElementById("mgr-feedback-ta") || {}).value || "";
    var notes = (document.getElementById("mgr-notes-ta") || {}).value || "";
    pf("save_manager_review", {
      appraisal: _pr.appraisal,
      manager_feedback: feedback,
      manager_internal_notes: notes,
      overall_rating: (_pr._mgr_overall_rating || 0),
      potential_rating: (_pr._mgr_potential_rating || 0),
    }).then(function() {
      if (_pr.data) {
        _pr.data.manager_feedback = feedback;
        _pr.data.manager_internal_notes = notes;
      }
      var el = document.getElementById("pr-save-ind");
      if (el) { el.innerHTML = "Draft saved <i class=ic-check></i>"; setTimeout(function() { if (el) el.innerHTML = ""; }, 2000); }
    }).catch(function(e) { alert(e.message || "Save failed."); });
  };

  function prGetInvitePageOptionsHtml() {
    var managerOnly = {"manager-feedback": 1, "manager-feedback-form": 1, "manager-submit": 1, "employee-final-review": 1, "summary": 1};
    var empPages = (_pr.pages || []).filter(function(p) { return !managerOnly[p.key]; });
    if (!empPages.length) return "";
    var chks = empPages.map(function(p) {
      return "<label style=\"display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-sm);margin-right:12px;margin-bottom:4px;cursor:pointer\">" +
        "<input type=\"checkbox\" class=\"mgr-page-chk\" value=\"" + gpEsc(p.key) + "\"> " + gpEsc(p.label) +
      "</label>";
    }).join("");
    return "<div style=\"margin-top:10px\">" +
      "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:6px\">Pages to review (leave unchecked for overall comment only):</div>" +
      "<div style=\"display:flex;flex-wrap:wrap\">" + chks + "</div>" +
    "</div>";
  }

  var _prPendingInvites = [];

  window.prAddToPending = function() {
    var hidden = document.getElementById("mgr-invite-emp-id");
    var search = document.getElementById("mgr-invite-search");
    var empId   = hidden ? hidden.value.trim() : "";
    var empName = search ? search.value.trim() : "";
    if (!empId) { alert("Please select an employee from the list first."); return; }
    if (_prPendingInvites.some(function(x) { return x.employee === empId; })) {
      alert(empName + " is already in the invite list."); return;
    }
    var chks  = document.querySelectorAll(".mgr-page-chk:checked");
    var pages = Array.prototype.map.call(chks, function(c) { return c.value; });
    _prPendingInvites.push({employee: empId, employee_name: empName, allowed_pages: pages});
    if (hidden) hidden.value = "";
    if (search) search.value = "";
    document.querySelectorAll(".mgr-page-chk").forEach(function(c) { c.checked = false; });
    prRenderPendingInvites();
  };

  function prRenderPendingInvites() {
    var el      = document.getElementById("mgr-pending-list");
    var sendBtn = document.getElementById("mgr-send-invites");
    if (!el) return;
    if (!_prPendingInvites.length) {
      el.innerHTML = "";
      if (sendBtn) sendBtn.style.display = "none";
      return;
    }
    if (sendBtn) sendBtn.style.display = "";
    var rows = _prPendingInvites.map(function(inv, idx) {
      var pageLabel = inv.allowed_pages && inv.allowed_pages.length
        ? inv.allowed_pages.join(", ")
        : "Overall comment only";
      return "<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 10px;" +
        "background:var(--surface2);border-radius:var(--r-sm);margin-top:6px;font-size:var(--fs-base)\">" +
        "<div>" +
          "<strong>" + gpEsc(inv.employee_name || inv.employee) + "</strong>" +
          "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-top:2px\">" + gpEsc(pageLabel) + "</div>" +
        "</div>" +
        "<button class=\"btn btn-outline btn-sm\" style=\"font-size:var(--fs-xs);padding:3px 10px\" data-pending-idx=\"" + idx + "\">Remove</button>" +
      "</div>";
    }).join("");
    el.innerHTML = "<div style=\"margin-top:10px;font-size:var(--fs-sm);font-weight:700;color:var(--text2);margin-bottom:4px\">To Be Invited (" + _prPendingInvites.length + ")</div>" + rows;
    el.onmousedown = function(evt) {
      var btn = evt.target.closest("[data-pending-idx]");
      if (!btn) return;
      _prPendingInvites.splice(parseInt(btn.getAttribute("data-pending-idx"), 10), 1);
      prRenderPendingInvites();
    };
  }

  window.prSendAllInvites = function() {
    if (!_prPendingInvites.length) { alert("No reviewers to invite."); return; }
    var msg     = document.getElementById("mgr-invite-msg");
    var sendBtn = document.getElementById("mgr-send-invites");
    if (msg) msg.textContent = "Inviting " + _prPendingInvites.length + " reviewer(s)...";
    if (sendBtn) sendBtn.disabled = true;
    pf("invite_reviewers_batch", {appraisal: _pr.appraisal, reviewers: JSON.stringify(_prPendingInvites)})
      .then(function(res) {
        if (_pr.data) _pr.data.invited_reviewers = res.invited || _pr.data.invited_reviewers;
        _prPendingInvites = [];
        if (msg) msg.innerHTML = "<span style=\"color:var(--green)\">Invites sent successfully.</span>";
        prRenderManagerFeedbackForm(_pr.data, true);
      }).catch(function(e) {
        if (sendBtn) sendBtn.disabled = false;
        if (msg) msg.innerHTML = "<span style=\"color:var(--danger)\">" + gpEsc(e.message || "Failed to send invites.") + "</span>";
      });
  };

  /* A question on the overall rating (R7, decisions 12, 34, 37). mode is what
     the server says this person may do in this view: "rater" (their own
     rating), "hr" (HR answering for someone who has left, with a reason) or ""
     (someone else must answer). hasPicker: the page already shows a rating
     picker with id mgr-overall-rating; otherwise a labelled box is shown. */
  window.riOverallFlagHtml = function(d, mode, hasPicker) {
    if (!d || !d.overall_rating_flag) return "";
    if (mode !== "rater" && mode !== "hr") {
      return "<div class=\"callout callout-warn\" style=\"margin-bottom:16px\">" +
        "The overall rating was given when the numbers in the review were different. " +
        "The person who gave it must keep or change it before this review can be completed.</div>";
    }
    var picker = hasPicker ? "" :
      "<div style=\"margin-top:8px\"><label for=\"hr-flag-overall-rating\" style=\"display:block;font-size:var(--fs-sm);margin-bottom:4px\">" +
        "New overall rating (1 to 5), only if you are changing it</label>" +
        "<input type=\"number\" id=\"hr-flag-overall-rating\" class=\"gp-input\" min=\"1\" max=\"5\" step=\"0.5\" style=\"width:120px\"></div>";
    return "<div class=\"callout callout-warn\" style=\"margin-bottom:16px\">" +
      "This overall rating was given when the numbers in the review were different. " +
      (hasPicker ? "Keep it, or pick a new one above and say it has changed." : "Keep it, or type a new one and say it has changed.") +
      picker +
      "<div style=\"margin-top:8px\">" +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"riAnswerFlag('overall',1,'" + mode + "')\">Keep the rating</button> " +
        "<button class=\"btn btn-outline btn-sm\" onclick=\"riAnswerFlag('overall',0,'" + mode + "')\">" +
          (hasPicker ? "Use the rating I picked" : "Use the rating I typed") + "</button>" +
      "</div>" +
    "</div>";
  };

  /* ── Manager rates + submits ──────────────────────── */

  function prRenderManagerSubmitPage(d, editable) {
    /* The HR view always gets HR's page, and the manager view the manager's,
       whatever roles the person holds (decision 37). */
    if (_pr.viewerRole === "hr") {
      prRenderHrFinalizePage(d);
      return;
    }
    /* The manager's own step is Manager Review. After it, the manager can still
       answer a question on a rating they gave, in any stage (decision 12). */
    var inManagerReview = d.review_status === "Manager Review";
    var overallMode = d.overall_flag_answer === "rater" ? "rater" : "";
    var mgfPS = (d.page_settings && d.page_settings["manager-feedback"]) || {};
    var scales = d.rating_scales || {};
    var overallScaleName   = mgfPS.overall_rating_scale   || "";
    var potentialScaleName = mgfPS.potential_rating_scale || "";
    var showPotential = mgfPS.show_potential;
    var overallScale   = overallScaleName   ? scales[overallScaleName]   : null;
    var potentialScale = potentialScaleName && showPotential ? scales[potentialScaleName] : null;
    var visChecked = d.reviewer_comments_visible ? "checked" : "";

    function ratingSelect(id, scale, currentVal) {
      if (!scale || !scale.items || !scale.items.length) return "";
      var opts = scale.items.map(function(it) {
        var sel = (parseFloat(currentVal) === parseFloat(it.value)) ? " selected" : "";
        return "<option value=\"" + gpEsc(it.value + "") + "\"" + sel + ">" +
          gpEsc(it.label) + " (" + gpEsc(it.value + "") + ")</option>";
      }).join("");
      return "<select id=\"" + id + "\" style=\"padding:7px 10px;border:1.5px solid var(--border);border-radius:var(--r-sm);background:var(--surface);min-width:220px\">" +
        "<option value=\"\">— Select —</option>" + opts + "</select>";
    }

    var overallHtml = "";
    /* The overall rating can be picked in Manager Review, and afterwards only
       to answer a question on it. */
    /* The two pickers were both labelled with the name of the rating scale.
       A tenant that uses one scale for both then saw the same words twice,
       with nothing on screen to say which question each answered. The label
       is now the question; the scale's name is a hint under it. It is also a
       real label now - tied to the picker by `for`, so a screen reader and a
       click on the words both reach the right box. */
    function ratingBlock(id, question, hint, scale, currentVal) {
      return "<div class=\"pr-stmt-wrap\" style=\"margin-bottom:16px\">" +
        "<label for=\"" + id + "\" style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:4px\">" +
          gpEsc(question) + "</label>" +
        "<div style=\"font-size:var(--fs-xs);color:var(--text3);margin-bottom:8px\">" + gpEsc(hint) + "</div>" +
        ratingSelect(id, scale, currentVal) +
      "</div>";
    }

    if (overallScale && (inManagerReview || overallMode)) {
      overallHtml = ratingBlock(
        "mgr-overall-rating",
        "Overall rating",
        "How this person performed over the cycle. Scale: " + (overallScale.scale_name || "Overall Rating"),
        overallScale, d.overall_rating);
    }

    var potentialHtml = "";
    if (potentialScale && inManagerReview) {
      potentialHtml = ratingBlock(
        "mgr-potential-rating",
        "Potential for next role",
        "How ready this person is to take on more. Scale: " + (potentialScale.scale_name || "Potential Rating"),
        potentialScale, d.potential_rating);
    }

    /* The overall rating was given on numbers that have changed since (R7,
       decision 12). It must be kept or changed before HR can complete. */
    var overallFlagHtml = riOverallFlagHtml(d, overallMode, !!overallHtml);

    var html = "<div class=\"pr-page-title\">Rate &amp; Submit</div>" +
      (inManagerReview
        ? "<div class=\"pr-page-sub\">Provide overall ratings, optionally share reviewer comments, then submit your review to the employee.</div>"
        : "<div class=\"callout\" style=\"margin-bottom:16px\">This review is now at " + gpEsc(d.review_status || "") +
            ". Your part as the manager is done" + (d.overall_rating_flag && overallMode ? ", except the rating question below." : ".") + "</div>" +
          (d.overall_rating && !overallHtml
            ? "<div style=\"margin-bottom:16px\">Overall rating: <strong>" + gpEsc(pfNum(d.overall_rating, 1)) + "</strong></div>"
            : "")) +
      overallHtml + potentialHtml + overallFlagHtml +
      (inManagerReview
        ? "<div style=\"margin-bottom:20px;display:flex;align-items:center;gap:10px\">" +
            "<input type=\"checkbox\" id=\"mgr-reviewer-visible\" " + visChecked + " style=\"width:16px;height:16px\">" +
            "<label for=\"mgr-reviewer-visible\" style=\"font-size:var(--fs-base);color:var(--text2)\">Show invited reviewer comments to employee</label>" +
          "</div>" +
          "<button class=\"btn btn-primary\" onclick=\"prSubmitManagerReview()\" style=\"width:100%\">Submit Final Review to Employee</button>" +
          "<div id=\"mgr-submit-msg\" style=\"margin-top:12px;font-size:var(--fs-base)\"></div>"
        : "");
    document.getElementById("pr-content").innerHTML = html;
    var nextBtn = document.getElementById("pr-next-btn");
    if (nextBtn) nextBtn.style.display = "none";
  }

  window.prSubmitManagerReview = function() {
    var feedback = (document.getElementById("mgr-feedback-ta") || {}).value;
    if (!feedback) {
      // Try to get from saved data
      feedback = (_pr.data && _pr.data.manager_feedback) || "";
    }
    var notes = (document.getElementById("mgr-notes-ta") || {}).value;
    if (!notes) notes = (_pr.data && _pr.data.manager_internal_notes) || "";
    var overallEl = document.getElementById("mgr-overall-rating");
    var potentialEl = document.getElementById("mgr-potential-rating");
    var visEl = document.getElementById("mgr-reviewer-visible");
    var overall = overallEl ? (parseFloat(overallEl.value) || 0) : 0;
    var potential = potentialEl ? (parseFloat(potentialEl.value) || 0) : 0;
    var vis = visEl ? (visEl.checked ? 1 : 0) : 0;
    if (!feedback) { alert("Please write feedback for the employee before submitting."); return; }
    if (overallEl && !overall) { alert("Please select an overall rating before submitting."); return; }
    if (!confirm("Submit your review to the employee? They will be notified to view and acknowledge it.")) return;
    var submitBtn = document.querySelector("[onclick=\"prSubmitManagerReview()\"]");
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Submitting..."; }
    pf("submit_manager_review", {
      appraisal: _pr.appraisal,
      manager_feedback: feedback,
      manager_internal_notes: notes,
      overall_rating: overall,
      potential_rating: potential,
      reviewer_comments_visible: vis,
    }).then(function(res) {
      if (_pr.data) _pr.data.review_status = res.review_status || "Employee Final Review";
      switchPanel("goals");
      gpShowTab("reviews");
      gpShowToast("Review submitted to employee successfully.");
      _mrLoaded = false;
      pfLoadReviews();
    }).catch(function(e) {
      if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Submit to Employee"; }
      gpShowToast(e.message || "Submission failed.", "error");
    });
  };

  /* ── HR Finalize: HR marks review as Completed ──── */

  function prRenderHrFinalizePage(d) {
    var mgfPS = (d.page_settings && d.page_settings["manager-feedback"]) || {};
    var scales = d.rating_scales || {};
    var overallScaleName   = mgfPS.overall_rating_scale   || "";
    var potentialScaleName = mgfPS.potential_rating_scale || "";

    function ratingLabel(val, scaleName) {
      if (!val) return "<span style=\"color:var(--text3)\">Not rated</span>";
      var scale = scaleName ? scales[scaleName] : null;
      if (scale && scale.items) {
        var match = scale.items.filter(function(it) { return parseFloat(it.value) === parseFloat(val); })[0];
        if (match) return "<strong>" + gpEsc(match.label) + "</strong> <span style=\"color:var(--text3)\">(" + gpEsc(String(match.value)) + ")</span>";
      }
      return "<strong>" + gpEsc(String(val)) + "</strong>";
    }

    var ratingsHtml = "";
    if (d.overall_rating) {
      ratingsHtml += "<div style=\"margin-bottom:12px\">" +
        "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:4px\">" + gpEsc((scales[overallScaleName] && scales[overallScaleName].scale_name) || "Overall Rating") + "</div>" +
        ratingLabel(d.overall_rating, overallScaleName) +
      "</div>";
    }
    if (d.potential_rating && mgfPS.show_potential) {
      ratingsHtml += "<div style=\"margin-bottom:12px\">" +
        "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:4px\">" + gpEsc((scales[potentialScaleName] && scales[potentialScaleName].scale_name) || "Potential Rating") + "</div>" +
        ratingLabel(d.potential_rating, potentialScaleName) +
      "</div>";
    }

    /* HR cannot finish while a rating is waiting for an answer (R7, SEC-23).
       Saying so here beats a refusal after the click. The person who gave a
       rating answers it: a manager from My team's reviews, HR who calibrated
       from here (decisions 12, 37). */
    var open = parseInt(d.open_blocking_flags || 0, 10) || 0;
    var blockHtml = open
      ? "<div class=\"callout callout-warn\" style=\"margin-bottom:16px\">" +
          gpEsc(open + (open === 1 ? " rating was" : " ratings were")) +
          " given on numbers that changed since. The person who gave " + (open === 1 ? "it" : "them") +
          " must keep or change " + (open === 1 ? "it" : "them") + " before this review can be completed. " +
          "Open the earlier pages of this review to see which." +
        "</div>"
      : "";

    /* In the subject's line: read only, no HR buttons (decision 34). HR's own
       buttons only while the review is in HR Review. */
    var elsewhere = !!d.hr_steps_elsewhere;
    var hrStage = d.review_status === "HR Review";
    var hrSteps = hrStage && !elsewhere;
    var overallMode = (d.overall_flag_answer === "rater" || d.overall_flag_answer === "hr") ? d.overall_flag_answer : "";
    var html = "<div class=\"pr-page-title\">" + (hrStage ? "Finalize Review" : "Review") + "</div>" +
      (elsewhere
        ? "<div class=\"callout\" style=\"margin-bottom:16px\">" + pfHrStepsElsewhereNote() + "</div>"
        : hrSteps
        ? "<div class=\"pr-page-sub\">Review the manager's assessment below, then click <strong>Finish Review</strong> to complete this appraisal. The employee will be notified.</div>" +
          blockHtml + riOverallFlagHtml(d, overallMode, false)
        : "<div class=\"pr-page-sub\">This review is " + gpEsc(d.review_status || "") + ".</div>") +
      (d.manager_feedback
        ? "<div style=\"background:var(--surface2);border:1.5px solid var(--border);border-radius:var(--r);padding:20px;margin-bottom:16px\">" +
            "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Manager Feedback</div>" +
            "<div style=\"font-size:var(--fs-base);color:var(--text);white-space:pre-wrap\">" + gpEsc(d.manager_feedback) + "</div>" +
          "</div>"
        : "") +
      (ratingsHtml ? "<div style=\"margin-bottom:20px\">" + ratingsHtml + "</div>" : "") +
      (hrSteps
        ? "<button class=\"btn btn-outline\" onclick=\"pfOpenCalibNoteModal('" + gpEsc(_pr.appraisal) + "','" +
            gpEsc(d.employee_name || d.employee || "") + "','review')\" style=\"width:100%;margin-bottom:10px\">Calibration note</button>" +
          "<button id=\"hr-finish-btn\" class=\"btn btn-primary\" onclick=\"prFinishHrReview()\" style=\"width:100%\"" +
            (open ? " disabled title=\"A rating is still waiting for an answer.\"" : "") +
            ">&#10003;&nbsp; Finish Review</button>" +
          "<div id=\"hr-finish-msg\" style=\"margin-top:12px;font-size:var(--fs-base)\"></div>"
        : "");
    document.getElementById("pr-content").innerHTML = html;
    var nextBtn = document.getElementById("pr-next-btn");
    if (nextBtn) nextBtn.style.display = "none";
  }

  window.prFinishHrReview = function() {
    if (!confirm("Mark this review as completed? The employee will be notified.")) return;
    var btn = document.getElementById("hr-finish-btn");
    if (btn) { btn.disabled = true; btn.textContent = "Finishing…"; }
    pf("advance_review_status", {appraisal: _pr.appraisal}).then(function(res) {
      if (_pr.data) _pr.data.review_status = "Completed";
      /* Finished from the HR view, so back to the HR review list (decision 37). */
      switchPanel("goals");
      gpShowTab("hr");
      gpShowToast("Review finalized — employee notified.");
      _mrLoaded = false;
      pfLoadHrCycle();
    }).catch(function(e) {
      if (btn) { btn.disabled = false; btn.textContent = "\u2713  Finish Review"; }
      gpShowToast(e.message || "Failed to finalize review.", "error");
    });
  };

  /* ── Employee Final Review: employee acknowledges ──── */

  function prRenderEmployeeFinalReview(d) {
    pf("get_employee_final_review", {appraisal: _pr.appraisal}).then(function(r) {
      var mgfPS = (r.page_settings && r.page_settings["manager-feedback"]) || {};
      var scales = r.rating_scales || {};

      function ratingLabel(val, scaleName) {
        if (!val) return "";
        var scale = scaleName ? scales[scaleName] : null;
        if (scale && scale.items) {
          var match = scale.items.filter(function(it) { return parseFloat(it.value) === parseFloat(val); })[0];
          if (match) {
            return "<span style=\"font-size:var(--fs-md);font-weight:700;color:var(--primary)\">" + gpEsc(match.label) + "</span>" +
              "<span style=\"font-size:var(--fs-sm);color:var(--text3);margin-left:6px\">(" + gpEsc(match.value + "") + ")</span>";
          }
        }
        return "<span style=\"font-size:var(--fs-md);font-weight:700\">" + pfNum(val, 1) + "</span>";
      }

      var overallScaleName   = mgfPS.overall_rating_scale   || "";
      var potentialScaleName = mgfPS.potential_rating_scale || "";
      var overallScale   = overallScaleName   ? scales[overallScaleName]   : null;
      var potentialScale = potentialScaleName ? scales[potentialScaleName] : null;

      var ratingsHtml = "";
      if (overallScale && r.overall_rating) {
        ratingsHtml += "<div><div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:6px\">" +
          gpEsc(overallScale.scale_name || "Overall Rating") + "</div>" +
          ratingLabel(r.overall_rating, overallScaleName) + "</div>";
      }
      if (potentialScale && r.potential_rating) {
        ratingsHtml += "<div><div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:6px\">" +
          gpEsc(potentialScale.scale_name || "Potential Rating") + "</div>" +
          ratingLabel(r.potential_rating, potentialScaleName) + "</div>";
      }

      var reviewerSection = "";
      if (r.reviewer_comments_visible && r.invited_reviewer_comments && r.invited_reviewer_comments.length) {
        reviewerSection = "<div style=\"margin-top:20px\">" +
          "<div style=\"font-size:var(--fs-base);font-weight:700;color:var(--text2);margin-bottom:10px\">Peer Feedback</div>";
        r.invited_reviewer_comments.forEach(function(rc) {
          reviewerSection += "<div style=\"background:var(--surface2);border:1px solid var(--border);border-radius:var(--r);padding:14px;margin-bottom:10px\">" +
            "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:6px\">" + gpEsc(rc.employee_name || "") + " · " + gpEsc(rc.submitted_on || "") + "</div>" +
            "<div style=\"font-size:var(--fs-base);color:var(--text2)\">" + gpEsc(rc.comments || "") + "</div>" +
          "</div>";
        });
        reviewerSection += "</div>";
      }

      var html = "<div class=\"pr-page-title\">Manager's Review</div>" +
        "<div class=\"pr-page-sub\">Your manager has completed their review. Please read the feedback below and acknowledge.</div>" +
        "<div style=\"background:var(--surface2);border:1.5px solid var(--border);border-radius:var(--r);padding:20px;margin-bottom:16px\">" +
          "<div style=\"font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Manager Feedback</div>" +
          "<div style=\"font-size:var(--fs-base);color:var(--text);white-space:pre-wrap\">" + gpEsc(r.manager_feedback || "(No feedback provided)") + "</div>" +
        "</div>" +
        (ratingsHtml ? "<div style=\"display:flex;gap:32px;flex-wrap:wrap;margin-bottom:16px\">" + ratingsHtml + "</div>" : "") +
        reviewerSection +
        "<div style=\"display:flex;gap:10px;margin-top:16px\">" +
          "<button class=\"btn btn-outline\" style=\"flex:1\" onclick=\"prSendBackToManager()\">&#8617; Send Back to Manager</button>" +
          "<button class=\"btn btn-primary\" style=\"flex:2\" onclick=\"prAcknowledgeReview()\">Acknowledge &amp; Continue to HR Review</button>" +
        "</div>" +
        "<div id=\"pr-ack-msg\" style=\"margin-top:10px;font-size:var(--fs-base)\"></div>";
      document.getElementById("pr-content").innerHTML = html;
      var nextBtn = document.getElementById("pr-next-btn");
      if (nextBtn) nextBtn.style.display = "none";
    }).catch(function(e) {
      document.getElementById("pr-content").innerHTML = "<div style=\"color:var(--danger,var(--red));padding:20px\">" + gpEsc(e.message || "Failed to load feedback.") + "</div>";
    });
  }

  window.prAcknowledgeReview = function() {
    if (!confirm("Acknowledge your manager's review and move to HR Review?")) return;
    var msg = document.getElementById("pr-ack-msg");
    if (msg) msg.textContent = "Processing...";
    pf("acknowledge_final_review", {appraisal: _pr.appraisal}).then(function(res) {
      if (_pr.data) _pr.data.review_status = res.review_status || "HR Review";
      prUpdateStageBar(_pr.data.review_status);
      if (msg) msg.innerHTML = "<span style=\"color:var(--green)\">Review acknowledged. Your review is now with HR.</span>";
      _mrLoaded = false;
      if (typeof pfLoadMyReviewStatus === "function") pfLoadMyReviewStatus();
    }).catch(function(e) {
      if (msg) msg.innerHTML = "<span style=\"color:var(--danger)\">" + gpEsc(e.message || "Failed to acknowledge.") + "</span>";
    });
  };

  window.prSendBackToManager = function() {
    var dlg = document.createElement("div");
    dlg.className = "gp-backdrop";
    dlg.id = "pr-sendback-dlg";
    dlg.style.cssText = "display:flex;z-index:9999";
    dlg.innerHTML =
      '<div class="gp-modal" style="max-width:480px">' +
        '<div class="gp-modal-hdr">' +
          '<div class="gp-modal-title">Send Back to Manager</div>' +
          '<button class="gp-modal-close" onclick="document.getElementById(\'pr-sendback-dlg\').remove()">&times;</button>' +
        '</div>' +
        '<div class="gp-modal-body" style="padding:20px">' +
          '<p style="font-size:var(--fs-base);color:var(--text2);margin:0 0 14px">Let your manager know what you would like them to review or amend before you acknowledge.</p>' +
          '<textarea id="pr-sendback-reason" rows="4" style="width:100%;box-sizing:border-box;resize:vertical;padding:10px;border:1px solid var(--border);border-radius:var(--r-sm);font-size:var(--fs-base);background:var(--surface);color:var(--text)" placeholder="e.g. Please revise the rating for Q2 objectives — the targets were exceeded."></textarea>' +
          '<div style="display:flex;gap:10px;margin-top:14px;justify-content:flex-end">' +
            '<button class="btn btn-outline" onclick="document.getElementById(\'pr-sendback-dlg\').remove()">Cancel</button>' +
            '<button class="btn btn-primary" id="pr-sendback-submit-btn" onclick="prConfirmSendBack()">Send Back</button>' +
          '</div>' +
          '<div id="pr-sendback-msg" style="margin-top:10px;font-size:var(--fs-base)"></div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(dlg);
    setTimeout(function() {
      var ta = document.getElementById("pr-sendback-reason");
      if (ta) ta.focus();
    }, 50);
  };

  window.prConfirmSendBack = function() {
    var reason = (document.getElementById("pr-sendback-reason") || {}).value || "";
    var msg    = document.getElementById("pr-sendback-msg");
    var btn    = document.getElementById("pr-sendback-submit-btn");
    if (btn) { btn.disabled = true; btn.textContent = "Sending..."; }
    pf("return_to_manager", {appraisal: _pr.appraisal, reason: reason}).then(function(res) {
      if (msg) msg.innerHTML = "<span style=\"color:var(--green)\">Sent. Your manager has been notified.</span>";
      setTimeout(function() {
        var dlg = document.getElementById("pr-sendback-dlg");
        if (dlg) dlg.remove();
      }, 1500);
      if (_pr.data) _pr.data.review_status = res.review_status || "Manager Review";
      prUpdateStageBar(_pr.data.review_status);
      _mrLoaded = false;
      if (typeof pfLoadMyReviewStatus === "function") pfLoadMyReviewStatus();
    }).catch(function(e) {
      if (msg) msg.innerHTML = "<span style=\"color:var(--danger)\">" + gpEsc(e.message || "Failed to send back.") + "</span>";
      if (btn) { btn.disabled = false; btn.textContent = "Send Back"; }
    });
  };

  /* ── Generic text-area page (fallback) ──────────── */

  function prRenderGenericPage(key, d, saved, editable) {
    var meta = _PR_PAGE_META[key] || {label: key};
    var prompts = {
      "strengths":  "Describe your key achievements this period.",
      "challenges": "What challenges did you face and how did you address them?",
      "development":"What skills or areas would you like to develop?",
      "support":    "What support do you need from your manager or the organisation?",
    };
    var html = "<div class=\"pr-page-title\">" + gpEsc(meta.label) + "</div>" +
      "<div class=\"pr-page-sub\">" + gpEsc(prompts[key] || "Enter your response below.") + "</div>" +
      "<div class=\"pr-stmt-wrap\"><textarea data-pr-field=\"text\" placeholder=\"Write your response here...\"" +
        (editable ? "" : " readonly") + " style=\"min-height:200px\">" +
        gpEsc(saved.text || "") + "</textarea></div>";
    document.getElementById("pr-content").innerHTML = html;
  }

  /* ── Summary & Submit ────────────────────────────── */

  function prRenderSummary(d, editable) {
    var overall = d.overall_comment || "";
    var returnNote = d.return_reason
      ? "<div class=\"callout callout-warn\" style=\"margin-bottom:16px\"><strong>Returned for revision:</strong> " + gpEsc(d.return_reason) + "</div>"
      : "";
    var statusLabel = {
      "Not Started":"Not Started","Employee Review":"In Progress",
      "Manager Review":"Submitted to Manager","HR Review":"With HR","Completed":"Completed",
    }[d.review_status] || d.review_status;
    var done = d.pages_completed ? d.pages_completed.length : 0;
    var total = _pr.pages.length - 1;
    var allDone = done >= total;
    var html = "<div class=\"pr-page-title\">Summary &amp; Submit</div>" +
      "<div class=\"pr-page-sub\">Review your responses, add an overall comment for your manager, then submit.</div>" +
      returnNote +
      "<div style=\"background:var(--surface2);border:1.5px solid var(--border);border-radius:var(--r);padding:16px;margin-bottom:16px\">" +
        "<div style=\"font-size:var(--fs-base);color:var(--text2)\"><strong>Status:</strong> " + gpEsc(statusLabel) + "</div>" +
        "<div style=\"font-size:var(--fs-sm);color:" + (allDone ? "var(--green)" : "var(--amber)") + ";margin-top:6px\">" +
          done + " of " + total + " pages completed" + (allDone ? " <i class=ic-check></i>" : " — consider completing all pages before submitting") +
        "</div>" +
      "</div>" +
      "<div class=\"pr-stmt-wrap\"><label style=\"display:block;font-size:var(--fs-sm);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:8px\">Overall Comment to Manager</label>" +
        "<textarea data-pr-field=\"overall_comment\" placeholder=\"Write an overall message to your manager — your highlights, your ask, anything you want them to know going into the discussion.\"" +
        (editable ? "" : " readonly") + " style=\"min-height:140px\">" + gpEsc(overall) + "</textarea></div>";
    if (editable) {
      html += "<button class=\"btn btn-primary\" onclick=\"prSubmitReview()\" style=\"width:100%;margin-top:8px\">Submit to Manager</button>";
    }
    document.getElementById("pr-content").innerHTML = html;
    var nextBtn = document.getElementById("pr-next-btn");
    if (nextBtn) nextBtn.style.display = "none";
  }

  window.prToggleObj = function(objName) {
    var el = document.getElementById("pr-obj-" + objName);
    if (el) el.classList.toggle("collapsed");
  };

  window.prSubmitReview = function() {
    if (!_pr.data) return;
    var commentEl = document.querySelector("[data-pr-field=\"overall_comment\"]");
    var comment = commentEl ? commentEl.value.trim() : "";
    if (!confirm("Submit your self-review to your manager? You will not be able to edit it after submission.")) return;
    var submitBtn = document.querySelector("[onclick=\"prSubmitReview()\"]");
    if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = "Submitting..."; }
    pf("submit_employee_review", {appraisal: _pr.appraisal, overall_comment: comment}).then(function(res) {
      _pr.data.review_status = res.review_status || "Manager Review";
      prUpdateStageBar(_pr.data.review_status);
      prRenderSummary(_pr.data, false);
      gpShowToast("Self-review submitted to your manager.");
      if (typeof pfLoadMyReviewStatus === "function") pfLoadMyReviewStatus();
      _mrLoaded = false;
    }).catch(function(e) {
      if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = "Submit to Manager"; }
      gpShowToast(e.message || "Submission failed.", "error");
    });
  };

  /* ── Action items (manager review) ───────────────── */

  window.pfOpenActionModal = function(appraisalId) {
    pfClearErr("pf-action-error");
    document.getElementById("pf-action-appraisal").value = appraisalId;
    document.getElementById("pf-action-desc").value = "";
    document.getElementById("pf-action-due").value = "";
    var sel = document.getElementById("pf-action-assignee");
    if (sel) sel.innerHTML = "<option value=\"\">— (none) —</option>";
    pfOpenModal("pf-action-modal");
  };

  window.pfSubmitActionItem = function() {
    var ap = document.getElementById("pf-action-appraisal").value;
    var desc = document.getElementById("pf-action-desc").value.trim();
    if (!desc) { pfShowErr("pf-action-error", "Description is required."); return; }
    pf("add_action_item", {
      appraisal: ap,
      description: desc,
      assigned_to: (document.getElementById("pf-action-assignee") || {}).value || "",
      due_date: (document.getElementById("pf-action-due") || {}).value || "",
    }).then(function() {
      pfCloseModal("pf-action-modal");
      pfLoadReviews();
    }).catch(function(e) { pfShowErr("pf-action-error", e.message); });
  };

  window.pfReturnForRevision = function(appraisalId, employeeName) {
    var reason = prompt("Return " + gpEsc(employeeName) + "'s review for revision. Reason (optional):");
    if (reason === null) return;
    pf("return_for_revision", {appraisal: appraisalId, reason: reason || ""}).then(function() {
      pfLoadReviews();
    }).catch(function(e) { alert(e.message); });
  };

  /* ── Check-ins (goal tree) ───────────────────────── */

  var _gpCheckinTraj = "";

  window.gpSetCheckinTraj = function(val) {
    _gpCheckinTraj = (_gpCheckinTraj === val) ? "" : val;   /* toggle off if same clicked again */
    document.getElementById("gp-checkin-traj-likely").classList.toggle("active", _gpCheckinTraj === "On Track");
    document.getElementById("gp-checkin-traj-unlikely").classList.toggle("active", _gpCheckinTraj === "At Risk");
  };

  window.gpOpenCheckin = function(goalId, goalName) {
    pfClearErr("gp-checkin-error");
    document.getElementById("gp-checkin-goal").value = goalId;
    document.getElementById("gp-checkin-note").value = "";
    document.getElementById("gp-checkin-pct").value = "";
    _gpCheckinTraj = "";
    document.getElementById("gp-checkin-traj-likely").classList.remove("active");
    document.getElementById("gp-checkin-traj-unlikely").classList.remove("active");
    pfSetHtml("gp-checkin-context", "<strong>" + gpEsc(goalName) + "</strong>");
    pfOpenModal("gp-checkin-modal");
  };

  window.gpSubmitCheckin = function() {
    var goalId = document.getElementById("gp-checkin-goal").value;
    var note   = document.getElementById("gp-checkin-note").value.trim();
    var pct    = document.getElementById("gp-checkin-pct").value;
    if (!note) { pfShowErr("gp-checkin-error", "A note is required."); return; }
    if (pct !== "" && (parseFloat(pct) < 0 || parseFloat(pct) > 100)) {
      pfShowErr("gp-checkin-error", "% Complete must be between 0 and 100."); return;
    }
    gpFetch("alvoraa_portal.goals_api.create_checkin", {
      goal_id: goalId, note: note, completion_pct: pct, trajectory: _gpCheckinTraj,
    }).then(function() {
      pfCloseModal("gp-checkin-modal");
      tvLoad();
    }).catch(function(e) { pfShowErr("gp-checkin-error", e.message); });
  };

  /* ── Org Settings ─────────────────────────────────── */

  window.orgLoad = function() {
    Promise.all([
      pf("get_company_values", {}),
      pf("get_leadership_principles", {}),
      pf("get_rating_scales", {}),
      window.gpFetch("alvoraa_portal.hr_api.get_org_setting", {key: "kra_link_mandatory"}),
    ]).then(function(res) {
      orgRenderValues(res[0] || []);
      orgRenderPrinciples(res[1] || []);
      rsRenderScales(res[2] || []);
      _apsRatingScales = res[2] || [];
      var kchk = document.getElementById("org-kra-mandatory");
      if (kchk) kchk.checked = (res[3] === "1" || res[3] === 1 || res[3] === true);
    }).catch(function(e) {
      pfSetHtml("org-values-body", "<div class=\"callout callout-warn\">Failed to load: " + gpEsc(e.message) + "</div>");
    });
  };

  /* ── The three review settings (slice 010 group D, decision 23) ──
     They live on HR Settings, which keeps a history of every change. Only an
     HR Manager may save them; an HR User sees them read-only, and anyone else
     never sees this screen at all. */

  window.riLoadSettings = function() {
    pf("get_review_settings", {}).then(function(s) {
      var card = document.getElementById("org-review-card");
      if (card) card.style.display = "";
      function fill(id, options, value) {
        var el = document.getElementById(id);
        if (!el) return;
        el.innerHTML = options.map(function(o) {
          return "<option value=\"" + gpEsc(o) + "\"" + (o === value ? " selected" : "") + ">" + gpEsc(o) + "</option>";
        }).join("");
        el.disabled = !s.can_edit;
      }
      fill("org-review-freeze", s.freeze_points || [], s.freeze_point);
      fill("org-review-removal", s.removal_modes || [], s.removal_mode);
      var lock = document.getElementById("org-review-lock");
      if (lock) { lock.value = s.lock_release_days; lock.disabled = !s.can_edit; }
      var save = document.getElementById("org-review-save");
      if (save) save.style.display = s.can_edit ? "" : "none";
      pfSetHtml("org-review-msg", s.can_edit ? "" :
        "<span style=\"color:var(--text3)\">Only an HR Manager can change these.</span>");
    }).catch(function() {
      /* Not HR for this site: the card simply is not there. */
      var card = document.getElementById("org-review-card");
      if (card) card.style.display = "none";
    });
  };

  window.riSaveSettings = function() {
    var btn = document.getElementById("org-review-save");
    if (btn) { btn.disabled = true; btn.textContent = "Saving…"; }
    pf("save_review_settings", {
      freeze_point:      pfVal("org-review-freeze"),
      lock_release_days: pfVal("org-review-lock"),
      removal_mode:      pfVal("org-review-removal"),
    }).then(function() {
      pfSetHtml("org-review-msg", "<span style=\"color:var(--green)\">Saved.</span>");
      setTimeout(function() { pfSetHtml("org-review-msg", ""); }, 3000);
    }).catch(function(e) {
      pfSetHtml("org-review-msg", "<span style=\"color:var(--danger,var(--red))\">" +
        gpEsc((e && e.message) || "The settings could not be saved.") + "</span>");
    }).finally(function() {
      if (btn) { btn.disabled = false; btn.textContent = "Save review settings"; }
    });
  };

  window.orgSaveKraMandatory = function(enabled) {
    window.gpFetch("alvoraa_portal.hr_api.set_org_setting", {key: "kra_link_mandatory", value: enabled ? "1" : "0"})
      .then(function() { toast(enabled ? "KRA linking is now required" : "KRA linking is now optional", "ok"); })
      .catch(function(e) { toast("Failed to save setting: " + e.message, "err"); });
  };

  /* ── Attendance rules (26 Sep 2026) ──
     Two organisation switches, off by default. The server says whether each is
     on and, when the plan cannot support one, what it still needs; the box is
     then disabled and that sentence shown. Saving goes through set_org_setting,
     which checks the same thing again - the disabled box is a courtesy. */
  var ORG_ATT_SWITCH_IDS = {
    late_rules_enabled: {box: "org-late-rules-on", needs: "org-late-rules-needs"},
    attendance_scoring_enabled: {box: "org-att-scoring-on", needs: "org-att-scoring-needs"},
  };

  window.orgLoadAttendanceRules = function() {
    var card = document.getElementById("org-attrules-card");
    window.gpFetch("alvoraa_portal.hr_api.get_attendance_rule_switches", {}).then(function(res) {
      /* A store's HR person reads the switches but cannot change them: the
         boxes are greyed out and say so, rather than flipping back on save. */
      var canEdit = !(res && res.can_edit === false);
      if (!canEdit) pfSetHtml("org-attrules-msg",
        "<span style=\"color:var(--text3)\">" +
        gpEsc(drT("Only HR with company-wide access can change these.")) + "</span>");
      ((res && res.switches) || []).forEach(function(sw) {
        var ids = ORG_ATT_SWITCH_IDS[sw.key];
        if (!ids) return;
        var box = document.getElementById(ids.box);
        if (box) { box.checked = !!sw.on; box.disabled = !canEdit || (!sw.available && !sw.on); }
        var needs = document.getElementById(ids.needs);
        if (needs) needs.textContent = sw.available ? "" :
          drT("Not available yet: your plan does not include {0}. Ask your Alvora account contact to add it.",
              [(sw.needs || []).join(", ")]);
      });
      var win = document.getElementById("org-filing-window");
      if (win) win.disabled = !canEdit;
      var onBehalf = document.getElementById("org-on-behalf-on");
      if (onBehalf) onBehalf.disabled = !canEdit;
      orgLoadOnBehalf(canEdit);
      orgLoadFilingWindow();
      if (card) card.style.display = "";
    }).catch(function() {
      /* Not HR for this site: the card simply is not there. */
      if (card) card.style.display = "none";
    });
  };

  /* ── May a manager ask on behalf, and how far back (slice 060, SEC-9a) ──
     Reworked 18 Oct 2026 into a switch and its sub-setting.

     NOTHING STORED MEANS ON. The capability already ships, so an unset tenant
     must keep exactly what it has today; only a stored "0" switches it off.
     The window box under it is disabled while the switch is off, because a
     limit on something nobody may do reads as a contradiction. */
  function orgOnBehalfApply(on, canEdit) {
    var box = document.getElementById("org-on-behalf-on");
    if (box) box.checked = !!on;
    var win = document.getElementById("org-filing-window");
    if (win) win.disabled = !canEdit || !on;
    var field = document.getElementById("org-filing-window-field");
    if (field) field.style.opacity = on ? "" : "0.55";
  }

  window.orgLoadOnBehalf = function(canEdit) {
    if (!document.getElementById("org-on-behalf-on")) return;
    window.gpFetch("alvoraa_portal.hr_api.get_org_setting", {key: "alvoraa_manager_on_behalf_enabled"})
      .then(function(v) {
        orgOnBehalfApply(String(v === null || v === undefined ? "" : v).trim() !== "0",
                         canEdit !== false);
      })
      .catch(function() { /* Not HR: the card is hidden anyway. */ });
  };

  window.orgSaveOnBehalf = function(box) {
    var on = !!box.checked;
    box.disabled = true;
    window.gpFetch("alvoraa_portal.hr_api.set_org_setting", {key: "alvoraa_manager_on_behalf_enabled", value: on ? "1" : "0"})
      .then(function() {
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--green)\">" +
          gpEsc(on ? drT("Saved. A manager can ask for a day to be fixed for the people who report to them. HR still decides.")
                   : drT("Saved. Only an employee can ask about their own day now. HR can still fix any day.")) +
          "</span>");
        orgOnBehalfApply(on, true);
      })
      .catch(function(e) {
        box.checked = !on;
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--danger,var(--red))\">" +
          gpEsc((e && e.message) || drT("The setting could not be saved. Try again, or ask your administrator.")) + "</span>");
      })
      .finally(function() { box.disabled = false; });
  };

  /* The sub-setting. Working days, counted on the employee's own holiday list.
     The server checks the same number again on the manager's path, so this box
     is where HR sets it, not where it is enforced.

     EMPTY MEANS NO LIMIT, and it is the default (Surbhi, 18 Oct 2026). Empty
     and 0 are opposite answers here - 0 is today only - so the box is left
     empty rather than filled in with a number nobody chose. */
  window.orgLoadFilingWindow = function() {
    var box = document.getElementById("org-filing-window");
    if (!box) return;
    window.gpFetch("alvoraa_portal.hr_api.get_org_setting", {key: "alvoraa_manager_filing_window_days"})
      .then(function(v) {
        var raw = (v === null || v === undefined) ? "" : String(v).trim();
        var n = parseInt(raw, 10);
        box.value = (raw === "" || isNaN(n)) ? "" : n;
      })
      .catch(function() { /* Not HR: the card is hidden anyway. */ });
  };

  window.orgSaveFilingWindow = function(box) {
    var raw = String(box.value === null || box.value === undefined ? "" : box.value).trim();
    var n = parseInt(raw, 10);
    if (raw !== "" && (isNaN(n) || n < 0 || n > 30)) {
      pfSetHtml("org-attrules-msg", "<span style=\"color:var(--danger,var(--red))\">" +
        gpEsc(drT("Give a whole number of working days between 0 and 30, or leave it empty for no limit.")) + "</span>");
      orgLoadFilingWindow();
      return;
    }
    box.disabled = true;
    window.gpFetch("alvoraa_portal.hr_api.set_org_setting", {key: "alvoraa_manager_filing_window_days", value: raw === "" ? "" : String(n)})
      .then(function() {
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--green)\">" +
          gpEsc(raw === "" ? drT("Saved. There is no limit: a manager can ask about any past day.")
                : n === 0 ? drT("Saved. A manager can now ask about today only; HR can still fix any day.")
                          : drT("Saved. A manager can now ask about the last {0} working days; HR can still fix any day.", [n])) +
          "</span>");
      })
      .catch(function(e) {
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--danger,var(--red))\">" +
          gpEsc((e && e.message) || drT("The setting could not be saved. Try again, or ask your administrator.")) + "</span>");
      })
      .finally(function() { box.disabled = false; orgLoadFilingWindow(); });
  };

  window.orgSaveAttendanceSwitch = function(key, box) {
    var on = !!box.checked;
    box.disabled = true;
    window.gpFetch("alvoraa_portal.hr_api.set_org_setting", {key: key, value: on ? "1" : "0"})
      .then(function() {
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--green)\">" +
          gpEsc(on ? drT("Switched on. It applies from now; nothing earlier is changed.")
                   : drT("Switched off. Nothing new is deducted or scored; records already made are kept.")) +
          "</span>");
        /* Other screens read the switch from the feature list. */
        if (window._features) window._features[key === "late_rules_enabled" ? "org_late_rules" : "org_attendance_scoring"] = on;
      })
      .catch(function(e) {
        box.checked = !on;
        pfSetHtml("org-attrules-msg", "<span style=\"color:var(--danger,var(--red))\">" +
          gpEsc((e && e.message) || drT("The setting could not be saved. Try again, or ask your administrator.")) + "</span>");
      })
      .finally(function() { orgLoadAttendanceRules(); });
  };

  window.orgRenderValues = function(values) {
    if (!values.length) {
      pfSetHtml("org-values-body", "<div class=\"empty-state\"><div class=\"empty-state-text\">No company values defined yet. Click + Add Value to create the first one.</div></div>");
      return;
    }
    var rows = values.map(function(v) {
      var data = gpEsc(JSON.stringify(v));
      return "<tr>" +
        "<td style=\"width:36px;font-size:var(--fs-lg);text-align:center\">" + gpEsc(v.icon_emoji || "") + "</td>" +
        "<td style=\"font-weight:600\">" + gpEsc(v.value_name) + "</td>" +
        "<td style=\"color:var(--text2);font-size:var(--fs-base)\">" + gpEsc(v.description || "") + "</td>" +
        "<td style=\"white-space:nowrap;text-align:right\">" +
          "<button class=\"btn btn-outline btn-sm\" style=\"margin-right:4px\" onclick=\"orgOpenValueModal(" + data + ")\">Edit</button>" +
          "<button class=\"btn btn-outline btn-sm\" style=\"color:var(--red)\" onclick=\"orgDeleteValue(" + gpEsc(JSON.stringify(v.name)) + ")\">Delete</button>" +
        "</td></tr>";
    }).join("");
    pfSetHtml("org-values-body",
      "<div style=\"overflow-x:auto\"><table class=\"pf-table\" style=\"width:100%\">" +
      "<thead><tr><th></th><th>Name</th><th>Description</th><th></th></tr></thead>" +
      "<tbody>" + rows + "</tbody></table></div>"
    );
  };

  window.orgRenderPrinciples = function(principles) {
    if (!principles.length) {
      pfSetHtml("org-principles-body", "<div class=\"empty-state\"><div class=\"empty-state-text\">No leadership principles defined yet. Click + Add Principle to create the first one.</div></div>");
      return;
    }
    var rows = principles.map(function(p) {
      var data = gpEsc(JSON.stringify(p));
      var behaviours = (p.expected_behaviours || "").split("\n").filter(Boolean)
        .map(function(b) { return "<li>" + gpEsc(b.trim()) + "</li>"; }).join("");
      return "<tr>" +
        "<td style=\"font-weight:600;min-width:140px\">" + gpEsc(p.principle_name) + "</td>" +
        "<td style=\"color:var(--text2);font-size:var(--fs-base)\">" + gpEsc(p.description || "") + "</td>" +
        "<td style=\"font-size:var(--fs-sm);color:var(--text2)\">" + (behaviours ? "<ul style=\"margin:0;padding-left:16px\">" + behaviours + "</ul>" : "—") + "</td>" +
        "<td style=\"white-space:nowrap;text-align:right\">" +
          "<button class=\"btn btn-outline btn-sm\" style=\"margin-right:4px\" onclick=\"pfOpenPrincipleModal(" + data + ")\">Edit</button>" +
          "<button class=\"btn btn-outline btn-sm\" style=\"color:var(--red)\" onclick=\"orgDeletePrinciple(" + gpEsc(JSON.stringify(p.name)) + ")\">Delete</button>" +
        "</td></tr>";
    }).join("");
    pfSetHtml("org-principles-body",
      "<div style=\"overflow-x:auto\"><table class=\"pf-table\" style=\"width:100%\">" +
      "<thead><tr><th>Principle</th><th>Description</th><th>Expected Behaviours</th><th></th></tr></thead>" +
      "<tbody>" + rows + "</tbody></table></div>"
    );
  };

  window.orgOpenValueModal = function(existing) {
    if (typeof existing === "string") { try { existing = JSON.parse(existing); } catch(e) { existing = null; } }
    pfClearErr("pf-value-error");
    document.getElementById("pf-val-name").value = (existing && existing.name) || "";
    document.getElementById("pf-val-value-name").value = (existing && existing.value_name) || "";
    document.getElementById("pf-val-emoji").value = (existing && existing.icon_emoji) || "";
    document.getElementById("pf-val-desc").value = (existing && existing.description) || "";
    pfOpenModal("pf-value-modal");
  };

  window.orgDeleteValue = function(name) {
    if (!confirm("Delete this company value? This cannot be undone.")) return;
    pf("delete_company_value", {name: name}).then(function() {
      var cvSel = document.getElementById("gp-c-company-value");
      if (cvSel) delete cvSel.dataset.loaded;
      orgLoad();
    }).catch(function(e) { alert("Error: " + e.message); });
  };

  window.orgDeletePrinciple = function(name) {
    if (!confirm("Delete this leadership principle?")) return;
    pf("delete_leadership_principle", {name: name}).then(function() {
      orgLoad();
    }).catch(function(e) { alert("Error: " + e.message); });
  };

  window.pfSubmitValue = function() {
    var valName = document.getElementById("pf-val-value-name").value.trim();
    if (!valName) { pfShowErr("pf-value-error", "Value name is required."); return; }
    pf("save_company_value", {
      value_name: valName,
      icon_emoji: document.getElementById("pf-val-emoji").value.trim(),
      description: document.getElementById("pf-val-desc").value.trim(),
      name: document.getElementById("pf-val-name").value || null,
    }).then(function(r) {
      pfCloseModal("pf-value-modal");
      var cvSel = document.getElementById("gp-c-company-value");
      if (cvSel) delete cvSel.dataset.loaded;
      orgLoad();
    }).catch(function(e) { pfShowErr("pf-value-error", e.message); });
  };

  /* kept for legacy callers from HR Setup tab */
  window.pfOpenValueModal = function() { orgOpenValueModal(null); };

  /* ── Rating Scales (Org Settings) ───────────────── */

  var _apsRatingScales = [];  /* shared cache used by setup page too */

  function rsRenderScales(scales) {
    var el = document.getElementById("org-scales-body");
    if (!el) return;
    if (!scales.length) {
      el.innerHTML = '<div class="empty-state"><div class="empty-state-text">No rating scales defined. Click + Add Scale to create one.</div></div>';
      return;
    }
    var rows = scales.map(function(s) {
      var chips = (s.items || []).map(function(it) {
        return '<span class="rs-chip" title="' + gpEsc(it.label) + '">' + gpEsc(it.label) + ' = ' + it.value + '</span>';
      }).join('');
      return '<tr>' +
        '<td style="font-weight:600;white-space:nowrap">' + gpEsc(s.scale_name) + (s.is_default ? ' <span style="font-size:var(--fs-xs);background:var(--primary);color:var(--surface);border-radius:var(--r-sm);padding:1px 6px;margin-left:4px">Default</span>' : '') + '</td>' +
        '<td><div class="rs-scale-items">' + chips + '</div></td>' +
        '<td style="white-space:nowrap;text-align:right">' +
          '<button class="btn btn-outline btn-sm" style="margin-right:4px" onclick="rsOpenModal(' + gpEsc(JSON.stringify(s)) + ')">Edit</button>' +
          '<button class="btn btn-outline btn-sm" style="color:var(--red,var(--red))" onclick="rsDelete(' + gpEsc(JSON.stringify(s.name)) + ')">Delete</button>' +
        '</td></tr>';
    }).join('');
    el.innerHTML = '<div style="overflow-x:auto"><table class="rs-table"><thead><tr><th>Scale</th><th>Points</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>';
  }

  window.rsOpenModal = function(existing) {
    if (typeof existing === "string") { try { existing = JSON.parse(existing); } catch(e) { existing = null; } }
    pfClearErr("rs-error");
    document.getElementById("rs-modal-title").textContent = existing ? "Edit Rating Scale" : "New Rating Scale";
    document.getElementById("rs-existing-name").value = (existing && existing.name) || "";
    document.getElementById("rs-name").value = (existing && existing.scale_name) || "";
    document.getElementById("rs-desc").value = (existing && existing.description) || "";
    var itemsEl = document.getElementById("rs-items");
    itemsEl.innerHTML = "";
    var pts = (existing && existing.items) || [{label:"",value:""}];
    pts.forEach(function(it) { rsAddPoint(it); });
    pfOpenModal("rs-modal");
  };

  window.rsAddPoint = function(pt) {
    var el = document.getElementById("rs-items");
    var row = document.createElement("div");
    row.style.cssText = "display:flex;gap:6px;align-items:center";
    row.innerHTML =
      '<input class="gp-input rs-pt-label" placeholder="Label (e.g. Exceptional)" style="flex:2;height:34px;padding:6px 10px" value="' + gpEsc((pt && pt.label) || "") + '">' +
      '<input class="gp-input rs-pt-value" placeholder="Value" type="number" step="0.1" style="flex:1;height:34px;padding:6px 8px" value="' + ((pt && pt.value != null) ? pt.value : "") + '">' +
      '<input class="gp-input rs-pt-color" type="color" style="width:36px;height:34px;padding:2px 4px;flex-shrink:0" value="' + gpEsc((pt && pt.color) || "var(--primary)") + '">' +
      '<button onclick="this.parentNode.remove()" style="background:none;border:none;color:var(--text3);cursor:pointer;font-size:var(--fs-lg);line-height:1;flex-shrink:0" title="Remove">×</button>';
    el.appendChild(row);
  };

  window.rsSubmit = function() {
    pfClearErr("rs-error");
    var name = document.getElementById("rs-name").value.trim();
    if (!name) { pfShowErr("rs-error", "Scale name is required."); return; }
    var rows = document.getElementById("rs-items").querySelectorAll("div");
    var items = [];
    var ok = true;
    rows.forEach(function(r) {
      var lbl = r.querySelector(".rs-pt-label");
      var val = r.querySelector(".rs-pt-value");
      var col = r.querySelector(".rs-pt-color");
      if (!lbl || !val) return;
      if (!lbl.value.trim()) { ok = false; return; }
      items.push({label: lbl.value.trim(), value: parseFloat(val.value||0), color: col ? col.value : ""});
    });
    if (!ok || !items.length) { pfShowErr("rs-error", "Each point needs a label and a value."); return; }
    var existing = document.getElementById("rs-existing-name").value || null;
    pf("save_rating_scale", {scale_name: name, items: JSON.stringify(items), existing_name: existing})
      .then(function() {
        pfCloseModal("rs-modal");
        pf("get_rating_scales", {}).then(function(scales) {
          _apsRatingScales = scales || [];
          rsRenderScales(_apsRatingScales);
        });
      }).catch(function(e) { pfShowErr("rs-error", e.message); });
  };

  window.rsDelete = function(name) {
    if (!confirm("Delete the rating scale '" + name + "'? This cannot be undone.")) return;
    pf("delete_rating_scale", {name: name}).then(function() {
      pf("get_rating_scales", {}).then(function(scales) {
        _apsRatingScales = scales || [];
        rsRenderScales(_apsRatingScales);
      });
    }).catch(function(e) { alert("Error: " + e.message); });
  };

  /* ── Appraisal Setup Full Page ───────────────────── */

  var _APS_PAGES = {
    "past-objectives":  {label: "Past Objectives & KPIs",      icon: "<i class=ic-target></i>"},
    "past-dev":         {label: "Past Development Goals",       icon: "<i class=ic-trend></i>"},
    "future-objectives":{label: "Future Objectives & KPIs",     icon: "<i class=ic-award></i>"},
    "future-dev":       {label: "Future Development Goals",     icon: "<i class=ic-leaf></i>"},
    "manager-feedback": {label: "Manager's Feedback",           icon: "<i class=ic-message></i>"},
  };

  /* "How the score is built": the weights the cycle's final score formula is
     built from. Attendance only counts when the tenant has that feature and
     HR switches it on for the cycle. */
  function apsDefaultScoring() {
    return {include_attendance: 0, goal_weight: 50, feedback_weight: 30, attendance_weight: 20,
            reliability_weight: 60, punctuality_weight: 40, deduction_penalty: 0.25,
            count_paid_leave_as_absent: 0, when_no_data: "Use the average of the other parts",
            exempt_grades: []};
  }
  function apsScoringSold() {
    /* An Organisation Settings switch since 26 Sep 2026, not a plan feature:
       HR turns "Attendance in appraisal score" on for the whole company. */
    var f = window._features || {};
    return !!f.org_attendance_scoring;
  }
  function apsShowScoringNav() {
    var el = document.getElementById("apsn-scoring");
    if (el) el.style.display = apsScoringSold() ? "" : "none";
  }

  var _aps = {
    item: "cycle-details",
    addedPages: [],
    pageSettings: {},
    empFields: {designation:true,department:true,years_of_service:true,reports_to:true},
    empAll: [], empFilterOpts: null,
    cycleDetail: {name:"",desc:"",start:"",end:""},
    existingCycle: null,
    scoring: apsDefaultScoring(),
  };

  window.apsOpenSetup = function(cycleId) {
    /* Reset for a new cycle */
    _aps = {
      item:"cycle-details", addedPages:[], pageSettings:{},
      empFields:{designation:true,department:true,years_of_service:true,reports_to:true},
      empAll:[], empFilterOpts:null,
      cycleDetail:{name:"",desc:"",start:"",end:""},
      existingCycle: cycleId || null,
      scoring: apsDefaultScoring(),
    };
    /* Load rating scales so they're available in page settings */
    if (!_apsRatingScales.length) {
      pf("get_rating_scales", {}).then(function(s) { _apsRatingScales = s || []; });
    }
    /* An existing cycle brings its own scoring settings */
    if (cycleId) {
      pf("get_cycle_config", {cycle: cycleId}).then(function(cfg) {
        var sc = (cfg && cfg.scoring) || {};
        if (sc.goal_weight || sc.feedback_weight || sc.attendance_weight) {
          _aps.scoring = Object.assign(apsDefaultScoring(), sc);
          if (_aps.item === "scoring") apsShowItem("scoring");
        }
      }).catch(function() {});
    }
    switchPanel("appraisal-setup");
    apsRenderLeftNav();
    apsShowScoringNav();
    apsShowItem("cycle-details");
  };

  /* ── New Cycle choice dialog ────────────────────────── */

  window.pfOpenNewCycleDialog = function() {
    pfSetHtml("pf-new-cycle-modal-title", "New Review Cycle");
    pfShowNewCycleChoices();
    pfOpenModal("pf-new-cycle-modal");
  };

  window.pfShowNewCycleChoices = function pfShowNewCycleChoices() {
    pfSetHtml("pf-new-cycle-modal-body",
      '<p style="font-size:var(--fs-base);color:var(--text2);margin:0 0 20px">How would you like to set up this cycle?</p>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">' +
        '<button class="aps-choice-card" onclick="pfCloseModal(\'pf-new-cycle-modal\');apsOpenSetup()">' +
          '<div class="aps-choice-icon">' +
            '<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18M8 14h.01M12 14h.01M16 14h.01M8 17h.01M12 17h.01"/></svg>' +
          '</div>' +
          '<div class="aps-choice-title">Build from Scratch</div>' +
          '<div class="aps-choice-desc">Set up a new review cycle with custom pages, fields, and settings.</div>' +
        '</button>' +
        '<button class="aps-choice-card" onclick="pfShowNewCycleTemplates()">' +
          '<div class="aps-choice-icon">' +
            '<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="8" y1="13" x2="16" y2="13"/><line x1="8" y1="17" x2="16" y2="17"/></svg>' +
          '</div>' +
          '<div class="aps-choice-title">Use a Template</div>' +
          '<div class="aps-choice-desc">Start from a saved review template to reuse your preferred setup.</div>' +
        '</button>' +
      '</div>'
    );
  };

  window.pfShowNewCycleTemplates = function() {
    pfSetHtml("pf-new-cycle-modal-title", "Choose a Template");
    pfSetHtml("pf-new-cycle-modal-body", '<div style="text-align:center;padding:24px;color:var(--text3);font-size:var(--fs-base)">Loading templates…</div>');
    pf("list_cycle_templates", {}).then(function(templates) {
      if (!templates || !templates.length) {
        pfSetHtml("pf-new-cycle-modal-body",
          '<div style="text-align:center;padding:32px 16px">' +
            '<div style="font-size:var(--fs-2xl);margin-bottom:10px"><i class=ic-clipboard></i></div>' +
            '<div style="font-size:var(--fs-base);font-weight:600;color:var(--text1);margin-bottom:6px">No templates yet</div>' +
            '<div style="font-size:var(--fs-sm);color:var(--text3);margin-bottom:18px">Set up a cycle and click "Save as Template" to create one.</div>' +
            '<button class="btn btn-outline btn-sm" onclick="pfShowNewCycleChoices()">← Back</button>' +
          '</div>'
        );
        return;
      }
      var rows = templates.map(function(t) {
        var pageCount = Object.keys(t.page_config || {}).length;
        var savedAt = t.saved_at ? t.saved_at.split(" ")[0] : "";
        return '<div class="aps-tpl-row">' +
          '<div class="aps-tpl-info">' +
            '<div class="aps-tpl-name">' + gpEsc(t.name) + '</div>' +
            '<div class="aps-tpl-meta">' + pageCount + ' page' + (pageCount !== 1 ? 's' : '') +
              (savedAt ? ' · saved ' + gpEsc(savedAt) : '') + '</div>' +
          '</div>' +
          '<div style="display:flex;gap:6px">' +
            '<button class="btn btn-primary btn-sm" onclick="pfCloseModal(\'pf-new-cycle-modal\');apsOpenSetupFromTemplate(' + JSON.stringify(JSON.stringify(t)) + ')">Use</button>' +
            '<button class="btn btn-outline btn-sm" style="color:var(--danger,var(--red));border-color:var(--danger,var(--red))" onclick="pfDeleteCycleTemplate(' + JSON.stringify(t.name) + ',this)">Delete</button>' +
          '</div>' +
        '</div>';
      }).join('');
      pfSetHtml("pf-new-cycle-modal-body",
        '<button class="btn btn-outline btn-sm" style="margin-bottom:14px" onclick="pfShowNewCycleChoices()">← Back</button>' +
        '<div class="aps-tpl-list">' + rows + '</div>'
      );
    }).catch(function(e) {
      pfSetHtml("pf-new-cycle-modal-body",
        '<div style="color:var(--danger);padding:12px">' + gpEsc((e && e.message) || "Failed to load templates.") + '</div>' +
        '<button class="btn btn-outline btn-sm" style="margin-top:8px" onclick="pfShowNewCycleChoices()">← Back</button>'
      );
    });
  };

  window.pfDeleteCycleTemplate = function(name, btn) {
    if (!confirm('Delete template "' + name + '"? This cannot be undone.')) return;
    if (btn) btn.disabled = true;
    pf("delete_cycle_template", {template_name: name})
      .then(function() { pfShowNewCycleTemplates(); })
      .catch(function(e) { alert(e.message || "Could not delete template."); if (btn) btn.disabled = false; });
  };

  window.apsOpenSetupFromTemplate = function(templateJson) {
    var t = typeof templateJson === "string" ? JSON.parse(templateJson) : templateJson;
    /* addedPages = keys of page_config that are true, in _APS_PAGES order */
    var pageOrder = Object.keys(_APS_PAGES);
    var pageCfg = t.page_config || {};
    var addedPages = pageOrder.filter(function(k) { return pageCfg[k]; });
    _aps = {
      item: "cycle-details",
      addedPages: addedPages,
      pageSettings: t.page_settings || {},
      empFields: t.employee_fields || {designation:true,department:true,years_of_service:true,reports_to:true},
      empAll: [], empFilterOpts: null,
      cycleDetail: {name:"",desc:"",start:"",end:""},
      existingCycle: null,
      scoring: Object.assign(apsDefaultScoring(), t.scoring || {}),
    };
    if (!_apsRatingScales.length) {
      pf("get_rating_scales", {}).then(function(s) { _apsRatingScales = s || []; });
    }
    switchPanel("appraisal-setup");
    apsRenderLeftNav();
    apsShowScoringNav();
    apsShowItem("cycle-details");
  };

  window.apsSaveAsTemplate = function() {
    apsSaveCurrent();
    /* Collect what's been configured so far */
    var pageCfg = {};
    _aps.addedPages.forEach(function(k) { pageCfg[k] = true; });
    if (!_aps.addedPages.length) {
      pfShowErr("aps-header-error", "Add at least one appraisal page before saving a template.");
      return;
    }
    var name = (window.prompt('Template name (e.g. "Standard H2 Review"):') || "").trim();
    if (!name) return;
    pf("save_cycle_template", {
      template_name:  name,
      page_config:    JSON.stringify(pageCfg),
      page_settings:  JSON.stringify(_aps.pageSettings),
      employee_fields: JSON.stringify(_aps.empFields),
    }).then(function() {
      if (window.frappe && frappe.show_alert) frappe.show_alert({message: 'Template "' + name + '" saved.', indicator: "green"}, 4);
    }).catch(function(e) {
      pfShowErr("aps-header-error", e.message || "Could not save template.");
    });
  };

  /* Save values from whatever panel is currently open */
  function apsSaveCurrent() {
    var cur = _aps.item;
    if (cur === "cycle-details") {
      _aps.cycleDetail = {
        name:  (document.getElementById("aps-cy-name")  || {}).value || "",
        desc:  (document.getElementById("aps-cy-desc")  || {}).value || "",
        start: (document.getElementById("aps-cy-start") || {}).value || "",
        end:   (document.getElementById("aps-cy-end")   || {}).value || "",
      };
    } else if (cur === "emp-fields") {
      var fields = {};
      ["designation","department","branch","grade","joining_date","years_of_service","reports_to","employment_type"]
        .forEach(function(f) {
          var el = document.getElementById("aps-wf-" + f);
          if (el) fields[f] = el.checked;
        });
      _aps.empFields = fields;
    } else if (cur === "scoring") {
      _aps.scoring = apsCollectScoring();
    } else if (_APS_PAGES[cur]) {
      var ps = {};
      document.querySelectorAll("[data-aps-key]").forEach(function(el) {
        var k = el.dataset.apsKey;
        if (el.type === "checkbox") ps[k] = el.checked;
        else ps[k] = el.value;
      });
      _aps.pageSettings[cur] = ps;
    }
  }

  /* Navigate left nav */
  window.apsShowItem = function(key) {
    apsSaveCurrent();
    _aps.item = key;
    /* Update active states */
    document.querySelectorAll(".aps-nav-item, .aps-page-chip").forEach(function(el) {
      el.classList.remove("active");
    });
    var navEl = document.getElementById("apsn-" + key);
    if (navEl) navEl.classList.add("active");
    /* Render right panel */
    var panel = document.getElementById("aps-settings-panel");
    if (!panel) return;
    if (key === "cycle-details")   panel.innerHTML = apsHtmlCycleDetails();
    else if (key === "emp-fields") panel.innerHTML = apsHtmlEmpFields();
    else if (key === "scoring")    { panel.innerHTML = apsHtmlScoring(); apsScoringRefresh(); }
    else if (key === "select-emps"){ panel.innerHTML = apsHtmlSelectEmps(); apsInitEmpFilter(); }
    else if (_APS_PAGES[key])      panel.innerHTML = apsHtmlPageSettings(key);
    /* Update cycle subtitle */
    var sub = document.getElementById("aps-cycle-subtitle");
    if (sub && _aps.cycleDetail.name) sub.textContent = _aps.cycleDetail.name;
  };

  /* ── Right-panel HTML builders ──────────────────── */

  function apsHtmlCycleDetails() {
    var d = _aps.cycleDetail;
    return '<div class="aps-s-title">Cycle Details</div>' +
      '<div class="aps-s-sub">Set the name and timeline for this performance review cycle.</div>' +
      '<div class="gp-field">' +
        '<div class="gp-label">Cycle Name *</div>' +
        '<input class="gp-input" id="aps-cy-name" placeholder="e.g. H2 2026 Performance Review" value="' + gpEsc(d.name) + '">' +
      '</div>' +
      '<div class="gp-field">' +
        '<div class="gp-label">Description</div>' +
        '<textarea class="gp-input" id="aps-cy-desc" rows="3" placeholder="Brief overview — purpose and scope of this cycle.">' + gpEsc(d.desc) + '</textarea>' +
      '</div>' +
      '<div class="gp-row2">' +
        '<div class="gp-field"><div class="gp-label">Start Date *</div><input class="gp-input" id="aps-cy-start" type="date" value="' + gpEsc(d.start) + '"></div>' +
        '<div class="gp-field"><div class="gp-label">End Date *</div><input class="gp-input" id="aps-cy-end" type="date" value="' + gpEsc(d.end) + '"></div>' +
      '</div>';
  }

  function apsHtmlScoring() {
    var sc = _aps.scoring || apsDefaultScoring();
    function slider(k, lbl, hint) {
      return '<div class="aps-toggle-row" style="align-items:flex-start">' +
        '<div class="aps-toggle-text" style="flex:1"><div class="aps-toggle-lbl">' + lbl + '</div>' +
        '<div class="aps-toggle-hint">' + hint + '</div>' +
        '<input type="range" min="0" max="100" step="5" id="aps-sc-' + k + '" value="' + gpEsc(String(sc[k] || 0)) + '" oninput="apsScoringRefresh()" style="width:100%;margin-top:6px"></div>' +
        '<div style="width:56px;text-align:right;font-weight:700;font-size:var(--fs-md)" id="aps-sc-' + k + '-val">' + gpEsc(String(sc[k] || 0)) + '%</div>' +
      '</div>';
    }
    function num(k, lbl, hint, step) {
      return '<div class="gp-field"><div class="gp-label">' + lbl + '</div>' +
        '<input class="gp-input" type="number" step="' + step + '" min="0" id="aps-sc-' + k + '" value="' + gpEsc(String(sc[k] == null ? "" : sc[k])) + '" oninput="apsScoringRefresh()" style="height:34px;padding:6px 10px">' +
        (hint ? '<div class="gp-hint">' + hint + '</div>' : '') + '</div>';
    }
    var grades = (_aps.empFilterOpts && _aps.empFilterOpts.grades) || [];
    var gradeHtml = grades.length
      ? grades.map(function(g) {
          var on = (sc.exempt_grades || []).indexOf(g) !== -1;
          return '<label style="display:inline-flex;align-items:center;gap:6px;margin:0 14px 6px 0;font-size:var(--fs-base)">' +
            '<input type="checkbox" class="aps-sc-grade" value="' + gpEsc(g) + '"' + (on ? ' checked' : '') + '> ' + gpEsc(g) + '</label>';
        }).join('')
      : '<div style="font-size:var(--fs-sm);color:var(--text3)" id="aps-sc-grades-empty">Loading grades…</div>';
    return '<div class="aps-s-title">How the Score Is Built</div>' +
      '<div class="aps-s-sub">Each appraisal\'s final score is a weighted mix of three parts. Move the sliders so they add up to 100.</div>' +
      '<div class="aps-toggle-row">' +
        '<div class="aps-toggle-text"><div class="aps-toggle-lbl">Include attendance</div>' +
        '<div class="aps-toggle-hint">Score regularity and punctuality from the attendance records in the cycle window. Off means the score is targets and manager feedback only.</div></div>' +
        '<label class="aps-sw"><input type="checkbox" id="aps-sc-include"' + (sc.include_attendance ? ' checked' : '') + ' onchange="apsScoringRefresh()"><span class="aps-sw-slider"></span></label>' +
      '</div>' +
      '<div class="aps-section-lbl">Weights</div>' +
      slider("goal_weight", "Targets", "KPI and goal ratings given by the manager") +
      slider("feedback_weight", "Manager feedback", "Ratings against the feedback criteria (core values, customer handling, teamwork)") +
      '<div id="aps-sc-att-block">' + slider("attendance_weight", "Attendance", "Regularity and punctuality, with the late-coming rule\'s deductions") + '</div>' +
      '<div id="aps-sc-total" style="font-size:var(--fs-base);font-weight:600;margin:6px 0 4px"></div>' +
      '<div id="aps-sc-formula" style="font-size:var(--fs-sm);color:var(--text3);font-family:monospace;margin-bottom:12px"></div>' +
      '<details id="aps-sc-advanced" style="margin-top:8px"><summary style="cursor:pointer;font-size:var(--fs-base);font-weight:600">Advanced: how the attendance score is worked out</summary>' +
        '<div style="padding:10px 0 0">' +
        '<div class="gp-row2">' +
          num("reliability_weight", "Reliability share (%)", "Days present against days scheduled. Approved paid leave does not count against the employee.", "5") +
          num("punctuality_weight", "Punctuality share (%)", "Days on time against days present. The two shares add up to 100.", "5") +
        '</div>' +
        '<div class="gp-row2">' +
          num("deduction_penalty", "Penalty per deducted day", "Score points taken off for each day the late-coming rule deducted (0.25 = a quarter point).", "0.05") +
          '<div class="gp-field"><div class="gp-label">When there is no attendance data</div>' +
            '<select class="gp-input" id="aps-sc-when_no_data" style="height:34px;padding:6px 8px">' +
              ["Use the average of the other parts", "Give full marks"].map(function(o) {
                return '<option value="' + o + '"' + (sc.when_no_data === o ? ' selected' : '') + '>' + o + '</option>';
              }).join('') +
            '</select></div>' +
        '</div>' +
        '<div class="aps-toggle-row">' +
          '<div class="aps-toggle-text"><div class="aps-toggle-lbl">Count paid leave as absent</div>' +
          '<div class="aps-toggle-hint">Normally approved leave does not lower the score.</div></div>' +
          '<label class="aps-sw"><input type="checkbox" id="aps-sc-count_paid_leave_as_absent"' + (sc.count_paid_leave_as_absent ? ' checked' : '') + '><span class="aps-sw-slider"></span></label>' +
        '</div>' +
        '<div class="gp-label" style="margin-top:8px">Exempt grades (full marks for attendance)</div>' +
        '<div id="aps-sc-grades">' + gradeHtml + '</div>' +
        '</div></details>';
  }

  window.apsScoringRefresh = function() {
    var inc = document.getElementById("aps-sc-include");
    if (!inc) return;
    var on = inc.checked;
    var attBlock = document.getElementById("aps-sc-att-block");
    var adv = document.getElementById("aps-sc-advanced");
    if (attBlock) attBlock.style.display = on ? "" : "none";
    if (adv) adv.style.display = on ? "" : "none";
    var keys = on ? ["goal_weight","feedback_weight","attendance_weight"] : ["goal_weight","feedback_weight"];
    var total = 0, w = {};
    keys.forEach(function(k) {
      var el = document.getElementById("aps-sc-" + k);
      var v = el ? parseFloat(el.value || 0) : 0;
      w[k] = v; total += v;
      var lbl = document.getElementById("aps-sc-" + k + "-val");
      if (lbl) lbl.textContent = v + "%";
    });
    var totEl = document.getElementById("aps-sc-total");
    if (totEl) {
      var ok = Math.abs(total - 100) < 0.01;
      totEl.style.color = ok ? "var(--green)" : "var(--amber)";
      totEl.textContent = "Total " + total + "%" + (ok ? "" : " — must be 100");
    }
    var fEl = document.getElementById("aps-sc-formula");
    if (fEl) {
      fEl.textContent = on
        ? "final = targets × " + (w.goal_weight / 100) + " + manager feedback × " + (w.feedback_weight / 100) + " + attendance × " + (w.attendance_weight / 100)
        : (w.feedback_weight > 0 && Math.abs(w.goal_weight + w.feedback_weight - 100) < 0.01
            ? "final = targets × " + (w.goal_weight / 100) + " + manager feedback × " + (w.feedback_weight / 100)
            : "final = targets score");
    }
    /* grades arrive with the employee-filter options */
    if (document.getElementById("aps-sc-grades-empty") && !_aps.empFilterOpts) {
      pf("get_wizard_filter_options").then(function(opts) {
        _aps.empFilterOpts = opts;
        if (_aps.item === "scoring") { _aps.scoring = apsCollectScoring(); apsShowItem("scoring"); }
      });
    }
  };

  function apsCollectScoring() {
    var sc = Object.assign({}, _aps.scoring || apsDefaultScoring());
    function val(k, dflt) {
      var el = document.getElementById("aps-sc-" + k);
      if (!el) return dflt;
      var v = parseFloat(el.value);
      return isNaN(v) ? dflt : v;
    }
    var inc = document.getElementById("aps-sc-include");
    if (!inc) return sc;
    sc.include_attendance = inc.checked ? 1 : 0;
    sc.goal_weight = val("goal_weight", sc.goal_weight);
    sc.feedback_weight = val("feedback_weight", sc.feedback_weight);
    sc.attendance_weight = val("attendance_weight", sc.attendance_weight);
    sc.reliability_weight = val("reliability_weight", sc.reliability_weight);
    sc.punctuality_weight = val("punctuality_weight", sc.punctuality_weight);
    sc.deduction_penalty = val("deduction_penalty", sc.deduction_penalty);
    var paid = document.getElementById("aps-sc-count_paid_leave_as_absent");
    sc.count_paid_leave_as_absent = paid && paid.checked ? 1 : 0;
    var when = document.getElementById("aps-sc-when_no_data");
    if (when) sc.when_no_data = when.value;
    var grades = [];
    document.querySelectorAll(".aps-sc-grade:checked").forEach(function(el) { grades.push(el.value); });
    if (document.querySelector(".aps-sc-grade")) sc.exempt_grades = grades;
    return sc;
  }

  function apsScoringProblem() {
    var sc = _aps.scoring || apsDefaultScoring();
    if (!apsScoringSold()) return "";
    if (sc.include_attendance) {
      var total = (sc.goal_weight || 0) + (sc.feedback_weight || 0) + (sc.attendance_weight || 0);
      if (Math.abs(total - 100) > 0.01) return "The targets, manager feedback and attendance weights add up to " + total + "%. They must add up to 100.";
      if ((sc.reliability_weight || 0) + (sc.punctuality_weight || 0) <= 0) return "Give reliability or punctuality a share above zero.";
    }
    return "";
  }

  function apsHtmlEmpFields() {
    var ef = _aps.empFields || {};
    function chk(k,lbl,hint) {
      return '<div class="aps-toggle-row">' +
        '<div class="aps-toggle-text"><div class="aps-toggle-lbl">' + lbl + '</div>' +
        (hint ? '<div class="aps-toggle-hint">' + hint + '</div>' : '') +
        '</div>' +
        '<label class="aps-sw"><input type="checkbox" id="aps-wf-' + k + '"' + (ef[k] ? ' checked' : '') + '><span class="aps-sw-slider"></span></label>' +
      '</div>';
    }
    return '<div class="aps-s-title">Employee Profile Fields</div>' +
      '<div class="aps-s-sub">Choose which employee details appear at the top of each appraisal form.</div>' +
      chk("designation",    "Designation",          "Job title / role of the employee") +
      chk("department",     "Department",            "Team or business unit") +
      chk("branch",         "Branch / Location",     "Office or geographical location") +
      chk("grade",          "Grade / Level",         "Salary band or seniority level") +
      chk("joining_date",   "Date of Joining",       "") +
      chk("years_of_service","Years of Service",     "Calculated automatically from joining date") +
      chk("reports_to",     "Reporting Manager",     "Direct line manager") +
      chk("employment_type","Employment Type",       "Permanent, contract, intern, etc.");
  }

  function apsHtmlSelectEmps() {
    return '<div class="aps-s-title">Select Employees</div>' +
      '<div class="aps-s-sub">Filter active employees and select who to include in this cycle. An appraisal will be created for each selected person.</div>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">' +
        '<div><div class="gp-label" style="margin-bottom:4px">Department</div>' +
        '<select class="gp-input" id="aps-f-dept" style="height:34px;padding:6px 8px" onchange="apsEmpFetch()"><option value="">All Departments</option></select></div>' +
        '<div><div class="gp-label" style="margin-bottom:4px">Manager</div>' +
        '<select class="gp-input" id="aps-f-mgr" style="height:34px;padding:6px 8px" onchange="apsEmpFetch()"><option value="">All Managers</option></select></div>' +
        '<div><div class="gp-label" style="margin-bottom:4px">Designation</div>' +
        '<select class="gp-input" id="aps-f-desig" style="height:34px;padding:6px 8px" onchange="apsEmpFetch()"><option value="">All Designations</option></select></div>' +
        '<div><div class="gp-label" style="margin-bottom:4px">Date of Joining</div>' +
        '<div style="display:flex;gap:4px;align-items:center">' +
        '<input type="date" class="gp-input" id="aps-f-join-from" style="height:34px;padding:6px 8px;flex:1" onchange="apsEmpFetch()">' +
        '<span style="font-size:var(--fs-xs);color:var(--text3)">–</span>' +
        '<input type="date" class="gp-input" id="aps-f-join-to" style="height:34px;padding:6px 8px;flex:1" onchange="apsEmpFetch()"></div></div>' +
      '</div>' +
      '<div style="display:flex;gap:6px;align-items:center;margin-bottom:10px">' +
        '<input class="gp-input" id="aps-emp-search" placeholder="Search by name…" style="flex:1;height:34px;padding:6px 10px" oninput="apsRenderEmpList()">' +
        '<span id="aps-emp-loading" style="font-size:var(--fs-sm);color:var(--text3);display:none">Loading…</span>' +
      '</div>' +
      '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">' +
        '<div style="font-size:var(--fs-sm);color:var(--text3)"><span id="aps-sel-count">0</span> of <span id="aps-emp-count">0</span> selected</div>' +
        '<div style="display:flex;gap:10px">' +
          '<button class="btn" style="font-size:var(--fs-sm);padding:2px 10px;background:none;border:1px solid var(--border);border-radius:var(--r-sm)" onclick="apsToggleAll(true)">Select All</button>' +
          '<button class="btn" style="font-size:var(--fs-sm);padding:2px 10px;background:none;border:1px solid var(--border);border-radius:var(--r-sm)" onclick="apsToggleAll(false)">Deselect All</button>' +
        '</div>' +
      '</div>' +
      '<div id="aps-emp-list" style="border:1px solid var(--border);border-radius:var(--r-sm);max-height:320px;overflow-y:auto">' +
        '<div class="empty-state" style="padding:24px"><div class="empty-state-text">Loading employees…</div></div>' +
      '</div>';
  }

  function apsHtmlPageSettings(key) {
    var def = _APS_PAGES[key];
    if (!def) return "";
    var ps = _aps.pageSettings[key] || {};
    var scaleOpts = _apsRatingScales.map(function(s) {
      return '<option value="' + gpEsc(s.name) + '"' + (ps.rating_scale === s.name ? ' selected' : '') + '>' + gpEsc(s.scale_name) + '</option>';
    }).join('');

    function toggle(k, lbl, hint, dflt) {
      var checked = ps[k] !== undefined ? ps[k] : dflt;
      return '<div class="aps-toggle-row">' +
        '<div class="aps-toggle-text"><div class="aps-toggle-lbl">' + lbl + '</div>' +
        (hint ? '<div class="aps-toggle-hint">' + hint + '</div>' : '') +
        '</div>' +
        '<label class="aps-sw"><input type="checkbox" data-aps-key="' + k + '"' + (checked ? ' checked' : '') + '><span class="aps-sw-slider"></span></label>' +
      '</div>';
    }
    function dateField(k, lbl, dflt) {
      return '<div class="gp-field" style="flex:1"><div class="gp-label">' + lbl + '</div>' +
        '<input class="gp-input" type="date" data-aps-key="' + k + '" value="' + gpEsc(ps[k] || dflt || '') + '" style="height:34px;padding:6px 10px"></div>';
    }
    function scaleFieldFor(key, label) {
      if (!_apsRatingScales.length) return '<div style="font-size:var(--fs-sm);color:var(--text3);margin-top:6px">No rating scales defined — add one in Org Settings first.</div>';
      var opts = _apsRatingScales.map(function(s) {
        return '<option value="' + gpEsc(s.name) + '"' + (ps[key] === s.name ? ' selected' : '') + '>' + gpEsc(s.scale_name) + '</option>';
      }).join('');
      return '<div class="gp-field"><div class="gp-label">' + label + '</div>' +
        '<select class="gp-input" data-aps-key="' + key + '" style="height:34px;padding:6px 8px"><option value="">— No scale (rating not shown) —</option>' + opts + '</select></div>';
    }

    var cycleDates = _aps.cycleDetail;
    var html = '<div class="aps-s-title">' + def.icon + ' ' + gpEsc(def.label) + '</div>' +
      '<div class="aps-s-sub">Configure what is shown and measured in this section of the appraisal form.</div>' +
      '<div class="gp-field" style="margin-top:16px">' +
        '<div class="gp-label">Page Name</div>' +
        '<input class="gp-input" type="text" data-aps-key="page_label" placeholder="' + gpEsc(def.label) + '" value="' + gpEsc(ps.page_label || '') + '">' +
        '<div class="gp-hint">How this section is labelled in the employee\'s appraisal form. Leave blank to use the default name.</div>' +
      '</div>';

    if (key === "past-objectives") {
      html += '<div class="aps-section-lbl">Review Period</div>' +
        '<div class="gp-row2">' + dateField("period_from","From",cycleDates.start) + dateField("period_to","To",cycleDates.end) + '</div>' +
        '<div class="aps-section-lbl">Ratings</div>' +
        toggle("self_rating", "Employee Self-Rating", "Allow each employee to rate their own performance on each objective", true) +
        toggle("manager_rating", "Manager Rating", "Allow the manager to rate each objective individually", true) +
        toggle("overall_manager_rating", "Overall Manager Rating", "Collect one summary rating from the manager for the whole section", true) +
        scaleFieldFor("objectives_rating_scale", "Rating Scale for Objectives & KPIs");
    } else if (key === "past-dev") {
      html += '<div class="aps-section-lbl">Review Period</div>' +
        '<div class="gp-row2">' + dateField("period_from","From",cycleDates.start) + dateField("period_to","To",cycleDates.end) + '</div>' +
        '<div class="aps-section-lbl">Assessment</div>' +
        toggle("self_comments", "Employee Self-Assessment", "Allow employees to write a reflection on each development goal", true) +
        toggle("manager_comments", "Manager Comments", "Allow the manager to add comments on each development goal", true);
    } else if (key === "future-objectives") {
      html += '<div class="aps-section-lbl">Target Period</div>' +
        '<div class="gp-row2">' + dateField("period_from","From","") + dateField("period_to","To","") + '</div>' +
        '<div class="aps-section-lbl">Target Setting</div>' +
        toggle("employee_targets", "Employee-Proposed Targets", "Let employees draft their own performance targets for next period", true) +
        toggle("manager_approval", "Manager Approval Required", "Manager must approve proposed targets before they are finalised", false);
    } else if (key === "future-dev") {
      html += '<div class="aps-section-lbl">Development Period</div>' +
        '<div class="gp-row2">' + dateField("period_from","From","") + dateField("period_to","To","") + '</div>' +
        '<div class="aps-section-lbl">Options</div>' +
        toggle("employee_goals", "Employee-Defined Goals", "Let employees set their own development goals for the next period", true) +
        toggle("manager_input", "Manager Input", "Allow managers to add recommended development areas", true);
    } else if (key === "manager-feedback") {
      html += '<div class="aps-section-lbl">Sections to Include</div>' +
        toggle("show_strengths", "Strengths", "Manager describes what the employee does well", true) +
        toggle("show_dev_areas", "Development Areas", "Manager identifies areas for growth", true) +
        toggle("show_action_plan", "Action Plan", "Agreed next steps and support needed", true) +
        '<div class="aps-section-lbl">Overall Rating</div>' +
        toggle("show_overall_rating", "Enable Overall Rating", "Manager gives a single overall rating using the chosen scale", true) +
        scaleFieldFor("overall_rating_scale", "Rating Scale for Overall Rating") +
        '<div class="aps-section-lbl">Potential Rating</div>' +
        toggle("show_potential", "Enable Potential Rating", "Manager gives a separate rating for employee potential using the chosen scale", false) +
        scaleFieldFor("potential_rating_scale", "Rating Scale for Potential Rating");
    }
    return html;
  }

  /* ── Employee filter (Select Employees panel) ────── */

  function apsInitEmpFilter() {
    if (_aps.empFilterOpts) {
      apsPopulateEmpDropdowns(_aps.empFilterOpts);
      apsEmpFetch();
      return;
    }
    var loadEl = document.getElementById("aps-emp-loading");
    if (loadEl) loadEl.style.display = "";
    pf("get_wizard_filter_options").then(function(opts) {
      _aps.empFilterOpts = opts;
      if (loadEl) loadEl.style.display = "none";
      apsPopulateEmpDropdowns(opts);
      apsEmpFetch();
    }).catch(function(e) {
      if (loadEl) loadEl.style.display = "none";
    });
  }

  function apsPopulateEmpDropdowns(opts) {
    function fill(id, items, valFn, lblFn) {
      var sel = document.getElementById(id);
      if (!sel || sel.options.length > 1) return;
      (items || []).forEach(function(it) { sel.add(new Option(lblFn(it), valFn(it))); });
    }
    fill("aps-f-dept",  opts.departments  || [], function(d){return d;}, function(d){return d;});
    fill("aps-f-mgr",   opts.managers     || [], function(m){return m.name;}, function(m){return m.employee_name;});
    fill("aps-f-desig", opts.designations || [], function(d){return d;}, function(d){return d;});
  }

  window.apsEmpFetch = function() {
    var loadEl = document.getElementById("aps-emp-loading");
    if (loadEl) loadEl.style.display = "";
    var params = {};
    var dept  = (document.getElementById("aps-f-dept")      || {}).value;
    var mgr   = (document.getElementById("aps-f-mgr")       || {}).value;
    var desig = (document.getElementById("aps-f-desig")     || {}).value;
    var jFrom = (document.getElementById("aps-f-join-from") || {}).value;
    var jTo   = (document.getElementById("aps-f-join-to")   || {}).value;
    if (dept)  params.department   = dept;
    if (mgr)   params.manager      = mgr;
    if (desig) params.designation  = desig;
    if (jFrom) params.joining_from = jFrom;
    if (jTo)   params.joining_to   = jTo;
    pf("get_filterable_employees", params).then(function(emps) {
      if (loadEl) loadEl.style.display = "none";
      var prev = {};
      _aps.empAll.forEach(function(e) { if (e._checked) prev[e.name] = true; });
      _aps.empAll = emps.map(function(e) { e._checked = !!prev[e.name]; return e; });
      apsRenderEmpList();
    }).catch(function() { if (loadEl) loadEl.style.display = "none"; });
  };

  window.apsRenderEmpList = function() {
    var q = ((document.getElementById("aps-emp-search") || {}).value || "").toLowerCase();
    var listEl = document.getElementById("aps-emp-list");
    if (!listEl) return;
    var vis = _aps.empAll.filter(function(e) {
      return !q || (e.employee_name||"").toLowerCase().indexOf(q) > -1
                || (e.designation||"").toLowerCase().indexOf(q) > -1;
    });
    if (!vis.length) {
      listEl.innerHTML = '<div class="empty-state" style="padding:24px"><div class="empty-state-text">No employees match the current filters.</div></div>';
    } else {
      listEl.innerHTML = vis.map(function(e) {
        return '<label class="wiz-emp-row" onclick="apsToggleEmp(event,\'' + gpEsc(e.name) + '\')">' +
          '<input type="checkbox"' + (e._checked ? ' checked' : '') + ' onclick="event.stopPropagation();apsToggleEmp(null,\'' + gpEsc(e.name) + '\')" data-empid="' + gpEsc(e.name) + '">' +
          '<div><div class="wiz-emp-name">' + gpEsc(e.employee_name || e.name) + '</div>' +
          '<div class="wiz-emp-meta">' + [e.designation, e.department, e.reports_to_name ? 'Reports to: ' + e.reports_to_name : ''].filter(Boolean).join(' · ') + '</div>' +
          '</div></label>';
      }).join('');
    }
    var sel = _aps.empAll.filter(function(e) { return e._checked; }).length;
    var cntEl = document.getElementById("aps-sel-count"); if (cntEl) cntEl.textContent = sel;
    var totEl = document.getElementById("aps-emp-count"); if (totEl) totEl.textContent = _aps.empAll.length;
    var badge = document.getElementById("aps-emp-badge");
    if (badge) { badge.textContent = sel; badge.style.display = sel ? "" : "none"; }
  };

  window.apsToggleEmp = function(evt, id) {
    if (evt) evt.preventDefault();
    var emp = _aps.empAll.find(function(e) { return e.name === id; });
    if (emp) emp._checked = !emp._checked;
    apsRenderEmpList();
  };

  window.apsToggleAll = function(val) {
    _aps.empAll.forEach(function(e) { e._checked = val; });
    apsRenderEmpList();
  };

  /* ── Add-page left-nav ──────────────────────────── */

  var _apsPageMenu = null;

  window.apsTogglePageMenu = function(evt) {
    if (evt) { evt.stopPropagation(); }
    if (_apsPageMenu) { _apsPageMenu.remove(); _apsPageMenu = null; return; }
    var menu = document.createElement("div");
    menu.className = "aps-page-menu";
    var added = {};
    _aps.addedPages.forEach(function(k) { added[k] = true; });
    Object.keys(_APS_PAGES).forEach(function(k) {
      var item = document.createElement("div");
      item.className = "aps-page-menu-item" + (added[k] ? " aps-added" : "");
      item.innerHTML = _APS_PAGES[k].icon + " " + gpEsc(_APS_PAGES[k].label) + (added[k] ? " <span style='margin-left:auto;font-size:var(--fs-xs);color:var(--text3)'>Added</span>" : "");
      if (!added[k]) {
        item.onclick = function() { apsAddPage(k); _apsPageMenu.remove(); _apsPageMenu = null; };
      }
      menu.appendChild(item);
    });
    /* position near the button */
    var btn = evt ? evt.currentTarget : document.querySelector(".aps-add-page-btn");
    if (btn) {
      var r = btn.getBoundingClientRect();
      menu.style.top  = (r.bottom + 4) + "px";
      menu.style.left = r.left + "px";
    }
    document.body.appendChild(menu);
    _apsPageMenu = menu;
    /* close on outside click */
    setTimeout(function() {
      document.addEventListener("click", function _close() {
        if (_apsPageMenu) { _apsPageMenu.remove(); _apsPageMenu = null; }
        document.removeEventListener("click", _close);
      }, {once: true});
    }, 10);
  };

  function apsAddPage(key) {
    if (_aps.addedPages.indexOf(key) === -1) {
      _aps.addedPages.push(key);
    }
    apsRenderLeftNav();
    apsShowItem(key);
  }

  window.apsRemovePage = function(key) {
    _aps.addedPages = _aps.addedPages.filter(function(k) { return k !== key; });
    delete _aps.pageSettings[key];
    apsRenderLeftNav();
    apsShowItem("cycle-details");
  };

  function apsRenderLeftNav() {
    var listEl = document.getElementById("aps-page-list");
    if (!listEl) return;
    if (!_aps.addedPages.length) {
      listEl.innerHTML = '<div style="padding:8px 16px;font-size:var(--fs-sm);color:var(--text3);font-style:italic">No pages added yet</div>';
      return;
    }
    listEl.innerHTML = _aps.addedPages.map(function(k) {
      var def = _APS_PAGES[k] || {label: k, icon: "<i class=ic-file></i>"};
      var navLabel = (_aps.pageSettings[k] && _aps.pageSettings[k].page_label) || def.label;
      var isActive = _aps.item === k;
      return '<div class="aps-page-chip' + (isActive ? ' active' : '') + '" id="apsn-' + k + '" onclick="apsShowItem(\'' + k + '\')">' +
        '<span style="font-size:var(--fs-base)">' + def.icon + '</span>' +
        '<span style="flex:1;font-size:var(--fs-base);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + gpEsc(navLabel) + '</span>' +
        '<button class="aps-page-chip-del" onclick="event.stopPropagation();apsRemovePage(\'' + k + '\')" title="Remove">×</button>' +
      '</div>';
    }).join('');
  }

  /* ── Launch / Save ──────────────────────────────── */

  window.apsLaunch = function(launch) {
    apsSaveCurrent();
    /* Validate */
    var cd = _aps.cycleDetail;
    if (!cd.name) {
      apsShowItem("cycle-details");
      pfShowErr("aps-header-error", "Cycle name is required.");
      return;
    }
    if (!cd.start || !cd.end) {
      apsShowItem("cycle-details");
      pfShowErr("aps-header-error", "Start and end dates are required.");
      return;
    }
    if (cd.start >= cd.end) {
      apsShowItem("cycle-details");
      pfShowErr("aps-header-error", "End date must be after start date.");
      return;
    }
    if (!_aps.addedPages.length) {
      pfShowErr("aps-header-error", "Add at least one appraisal page before launching.");
      return;
    }
    var scoringProblem = apsScoringProblem();
    if (scoringProblem) {
      apsShowItem("scoring");
      pfShowErr("aps-header-error", scoringProblem);
      return;
    }
    var selected = _aps.empAll.filter(function(e) { return e._checked; }).map(function(e) { return e.name; });
    if (launch && !selected.length) {
      apsShowItem("select-emps");
      pfShowErr("aps-header-error", "Select at least one employee to include.");
      return;
    }
    pfClearErr("aps-header-error");
    var btn = document.getElementById("aps-launch-btn");
    if (btn) { btn.disabled = true; btn.textContent = launch ? "Launching…" : "Saving…"; }

    /* Build page_config (which pages are included) */
    var pageCfg = {};
    _aps.addedPages.forEach(function(k) { pageCfg[k] = true; });

    pf("save_cycle_wizard", {
      cycle_name:         cd.name,
      start_date:         cd.start,
      end_date:           cd.end,
      description:        cd.desc,
      employee_fields:    JSON.stringify(_aps.empFields),
      page_config:        JSON.stringify(pageCfg),
      page_settings:      JSON.stringify(_aps.pageSettings),
      selected_employees: JSON.stringify(selected),
      existing_cycle:     _aps.existingCycle || null,
      scoring:            apsScoringSold() ? JSON.stringify(_aps.scoring) : null,
    }).then(function(r) {
      _aps.existingCycle = r.name;
      if (btn) { btn.disabled = false; btn.textContent = "Launch Cycle"; }
      var msg = r.message || (launch ? "Cycle launched." : "Draft saved.");
      if (window.frappe && frappe.show_alert) frappe.show_alert({message: msg, indicator: "green"}, 5);
      if (launch) {
        switchPanel("goals");
        gpShowTab("hr");
        pf("get_performance_context").then(function(ctx) { _pfCtx = ctx; pfFillCycleSelects(); pfLoadHr(true); });
      }
    }).catch(function(e) {
      if (btn) { btn.disabled = false; btn.textContent = launch ? "Launch Cycle" : "Save Draft"; }
      pfShowErr("aps-header-error", e.message);
    });
  };

  /* ── Upward feedback (employee) ──────────────────── */

  var _upwardManagerId = "", _upwardCycle = "";

  window.pfOpenUpwardModal = function() {
    var ctx = _gpCtx;
    if (!ctx || !ctx.cycle) { alert("No active appraisal cycle found."); return; }
    var mgr = ctx.reports_to;
    if (!mgr) { alert("No manager found on your employee record."); return; }
    _upwardManagerId = mgr;
    _upwardCycle = ctx.cycle.name;
    pfClearErr("pf-upward-error");
    document.getElementById("pf-upward-about").value = mgr;
    document.getElementById("pf-upward-cycle").value = _upwardCycle;
    document.getElementById("pf-upward-rating").value = "";
    document.getElementById("pf-upward-comments").value = "";
    pfSetHtml("pf-upward-context",
      "<strong>Feedback about:</strong> " + gpEsc(ctx.reports_to_name || mgr) +
      "<br><small>Cycle: " + gpEsc(_upwardCycle) + "</small>");
    // Load leadership principles as prompts
    pf("get_leadership_principles", {}).then(function(ps) {
      var html = "";
      (ps || []).forEach(function(p) {
        html += "<div style=\"margin-bottom:8px\">" +
          "<div style=\"font-size:var(--fs-base);font-weight:600;color:var(--text1)\">" + gpEsc(p.principle_name) + "</div>" +
          (p.description ? "<div style=\"font-size:var(--fs-sm);color:var(--text3);margin-bottom:4px\">" + gpEsc(p.description) + "</div>" : "") +
          "</div>";
      });
      if (!html) html = "<p style=\"font-size:var(--fs-sm);color:var(--text3)\">Leadership principles not yet configured by HR.</p>";
      pfSetHtml("pf-upward-principles", html);
    }).catch(function() {});
    pfOpenModal("pf-upward-modal");
  };

  window.pfSubmitUpwardFeedback = function() {
    var about = document.getElementById("pf-upward-about").value;
    var cycle = document.getElementById("pf-upward-cycle").value;
    var rating = document.getElementById("pf-upward-rating").value;
    var comments = document.getElementById("pf-upward-comments").value.trim();
    if (!rating) { pfShowErr("pf-upward-error", "Overall rating is required."); return; }
    var ratingNum = parseFloat(rating);
    if (isNaN(ratingNum) || ratingNum < 0 || ratingNum > 5) {
      pfShowErr("pf-upward-error", "Rating must be between 0 and 5."); return;
    }
    gpFetch("alvoraa_portal.goals_api.submit_upward_feedback", {
      about_employee: about, cycle: cycle,
      rating: ratingNum, comments: comments,
    }).then(function() {
      pfCloseModal("pf-upward-modal");
      pfSetHtml("gp-upward-status", "<span style=\"color:var(--green)\"><i class=ic-check></i> Feedback submitted. Thank you.</span>");
    }).catch(function(e) { pfShowErr("pf-upward-error", e.message); });
  };

  /* ── Additional reviewer (manager view) ──────────── */

  window.pfOpenReviewerModal = function(kpiId, kpiName) {
    pfClearErr("pf-reviewer-error");
    document.getElementById("pf-reviewer-kpi").value = kpiId;
    document.getElementById("pf-reviewer-emp").value = "";
    document.getElementById("pf-reviewer-role").value = "";
    pfSetHtml("pf-reviewer-context",
      "<strong>KPI:</strong> " + gpEsc(kpiName));
    pfOpenModal("pf-reviewer-modal");
  };

  window.pfSubmitAdditionalReviewer = function() {
    var kpi = document.getElementById("pf-reviewer-kpi").value;
    var emp = document.getElementById("pf-reviewer-emp").value.trim();
    var role = document.getElementById("pf-reviewer-role").value.trim();
    if (!emp) { pfShowErr("pf-reviewer-error", "Employee ID is required."); return; }
    pf("add_additional_reviewer", {kpi: kpi, reviewer: emp, reviewer_role: role})
      .then(function(r) {
        pfCloseModal("pf-reviewer-modal");
        pfSetHtml("pf-hr-msg", pfAlert("ok", r.message || "Reviewer added."));
      }).catch(function(e) { pfShowErr("pf-reviewer-error", e.message); });
  };

  /* ── Leadership principles (HR admin) ───────────── */

  window.pfOpenPrincipleModal = function(existing) {
    if (typeof existing === "string") { try { existing = JSON.parse(existing); } catch(e) { existing = null; } }
    pfClearErr("pf-principle-error");
    document.getElementById("pf-principle-name").value = (existing && existing.name) || "";
    document.getElementById("pf-principle-title").value = (existing && existing.principle_name) || "";
    document.getElementById("pf-principle-desc").value = (existing && existing.description) || "";
    document.getElementById("pf-principle-behaviours").value = (existing && existing.expected_behaviours) || "";
    pfOpenModal("pf-principle-modal");
  };

  window.pfSubmitPrinciple = function() {
    var title = document.getElementById("pf-principle-title").value.trim();
    if (!title) { pfShowErr("pf-principle-error", "Principle name is required."); return; }
    pf("save_leadership_principle", {
      principle_name: title,
      description: document.getElementById("pf-principle-desc").value.trim(),
      expected_behaviours: document.getElementById("pf-principle-behaviours").value.trim(),
      name: document.getElementById("pf-principle-name").value || null,
    }).then(function(r) {
      pfCloseModal("pf-principle-modal");
      orgLoad();
    }).catch(function(e) { pfShowErr("pf-principle-error", e.message); });
  };

  /* ── Calibration note (HR Setup) ─────────────────── */

  /* HR's calibration note, from the HR review list or HR's Finalize page (rehearsal
     F3). The box shows the note already saved, which these same HR people can
     read in the desk; the server checks them again (decisions 34 and 35). from
     is "review" when opened inside the review, so that screen reloads. */
  window.pfOpenCalibNoteModal = function(appraisal, employeeName, from) {
    var modal = document.getElementById("pf-calib-note-modal");
    var text = document.getElementById("pf-calib-note-text");
    document.getElementById("pf-calib-note-context").textContent = "Employee: " + employeeName;
    text.value = "";
    text.disabled = true;
    document.getElementById("pf-calib-rating").value = "";
    modal.dataset.appraisal = appraisal;
    modal.dataset.from = from || "list";
    pfClearErr("pf-calib-note-error");
    pfOpenModal("pf-calib-note-modal");
    pf("get_calibration_note", {appraisal: appraisal}).then(function(r) {
      if (modal.dataset.appraisal !== appraisal) return;
      text.value = (r && r.calibration_notes) || "";
      text.disabled = false;
    }).catch(function(e) {
      text.disabled = false;
      pfShowErr("pf-calib-note-error", (e && e.message) || "The saved note could not be loaded.");
    });
  };

  window.pfSubmitCalibNote = function() {
    var ap = document.getElementById("pf-calib-note-modal").dataset.appraisal;
    var notes = document.getElementById("pf-calib-note-text").value.trim();
    var ratingRaw = document.getElementById("pf-calib-rating").value.trim();
    var ratingNum = ratingRaw ? parseFloat(ratingRaw) : null;
    if (!notes) { pfShowErr("pf-calib-note-error", "Notes are required."); return; }
    if (ratingNum != null && (ratingNum < 0 || ratingNum > 5)) {
      pfShowErr("pf-calib-note-error", "Rating must be between 0 and 5."); return;
    }
    pf("save_calibration_note", {appraisal: ap, calibration_notes: notes, calibrated_rating: ratingNum})
      .then(function(r) {
        var from = document.getElementById("pf-calib-note-modal").dataset.from;
        pfCloseModal("pf-calib-note-modal");
        if (from === "review" && _pr.appraisal === ap) {
          gpShowToast(r.message || "Note saved.");
          riReload();
        } else {
          pfSetHtml("pf-hr-msg", pfAlert("ok", r.message || "Note saved."));
          pfLoadHrCycle();
        }
      }).catch(function(e) { pfShowErr("pf-calib-note-error", e.message); });
  };

  /* ── CSV export (HR Setup) ───────────────────────── */

  window.pfExportCycleCsv = function() {
    var cycle = pfVal("pf-hr-cycle");
    if (!cycle) { pfSetHtml("pf-hr-msg", pfAlert("err", "Pick a cycle first.")); return; }
    pfSetHtml("pf-hr-msg", pfAlert("warn", "Generating export…"));
    pf("export_cycle_kpis_csv", {cycle: cycle}).then(function(r) {
      var blob = new Blob([r.csv], {type: "text/csv"});
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = "kpis-" + (cycle || "export").replace(/\s+/g, "-") + ".csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      pfSetHtml("pf-hr-msg", pfAlert("ok", "Downloaded."));
    }).catch(function(e) { pfSetHtml("pf-hr-msg", pfAlert("err", e.message)); });
  };

}());

/* ── Sidebar collapse ───────────────────────────── */
function initSbCollapse() {
  var pinned = localStorage.getItem("sb-pinned") === "1";
  if (!pinned) document.body.classList.add("sb-collapsed");
  var btn = document.getElementById("sb-pin-btn");
  if (btn) btn.title = pinned ? "Unpin sidebar" : "Pin sidebar open";
}
window.toggleSbPin = function() {
  var collapsed = document.body.classList.toggle("sb-collapsed");
  var pinned = !collapsed;
  localStorage.setItem("sb-pinned", pinned ? "1" : "0");
  var btn = document.getElementById("sb-pin-btn");
  if (btn) btn.title = pinned ? "Unpin sidebar" : "Pin sidebar open";
};

/* ── Boot ────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", function() {
  initSbCollapse();
  startClock();
  loadPortalContext();
  loadHome();
  loadAvailableFeatures();
});
